import random
import time
import uuid
from enum import Enum
from typing import List, Dict, Tuple, Optional, Any

# Base classes for the Team_Treasure_Hunt game simulation

class Direction(Enum):
    UP = 0
    DOWN = 1
    LEFT = 2
    RIGHT = 3

class Position:
    def __init__(self, x: float, y: float):
        self.x = x
        self.y = y

    def __str__(self):
        return f"Position(x={round(self.x, 2)}, y={round(self.y, 2)})"

class CharacterAbility(Enum):
    STRENGTH = "Strength"
    AGILITY = "Agility"
    INTELLIGENCE = "Intelligence"
    STEALTH = "Stealth"

class Player:
    def __init__(self, name: str, team: str, ability: CharacterAbility, position: Position = Position(0.0, 0.0)):
        self.id = str(uuid.uuid4())
        self.name = name
        self.team = team
        self.ability = ability
        self.position = position
        self.treasures_collected = 0
        self.is_active = True

    def move(self, direction: Direction):
        if not self.is_active:
            return
        if direction == Direction.UP:
            self.position.y += 1
        elif direction == Direction.DOWN:
            self.position.y -= 1
        elif direction == Direction.LEFT:
            self.position.x -= 1
        elif direction == Direction.RIGHT:
            self.position.x += 1

    def collect_treasure(self):
        if self.is_active:
            self.treasures_collected += 1

    def use_ability(self, environment):
        if self.ability == CharacterAbility.STRENGTH:
            environment.remove_obstacle()
        elif self.ability == CharacterAbility.AGILITY:
            environment.navigate_space()
        elif self.ability == CharacterAbility.INTELLIGENCE:
            environment.solve_puzzle()
        elif self.ability == CharacterAbility.STEALTH:
            environment.bypass_trap()

    def __str__(self):
        return f"Player(id={self.id}, name='{self.name}', team='{self.team}', ability='{self.ability.value}', treasures={self.treasures_collected}, active={self.is_active})"

class Environment:
    def __init__(self, name: str, difficulty: int):
        self.name = name
        self.difficulty = difficulty
        self.obstacle_present = random.random() < 0.5
        self.puzzle_present = random.random() < 0.5
        self.trap_present = random.random() < 0.5

    def remove_obstacle(self):
        if self.obstacle_present:
            self.obstacle_present = False

    def navigate_space(self):
        if self.puzzle_present:
            return True
        return False

    def solve_puzzle(self):
        return random.random() < self.difficulty / 10

    def bypass_trap(self):
        if self.trap_present:
            self.trap_present = False

    def is_clear(self):
        return not self.obstacle_present and not self.puzzle_present and not self.trap_present

    def __str__(self):
        return f"Environment(name='{self.name}', difficulty={self.difficulty}, obstacle={self.obstacle_present}, puzzle={self.puzzle_present}, trap={self.trap_present})"

class Game:
    def __init__(self):
        self.teams: Dict[str, List[Player]] = {}
        self.environments: List[Environment] = []
        self.current_environment_index = 0
        self.treasures_collected_per_team: Dict[str, int] = {}
        self.start_time = time.time()

    def add_player_to_team(self, name: str, team: str, ability: CharacterAbility):
        if team not in self.teams:
            self.teams[team] = []
            self.treasures_collected_per_team[team] = 0
        if len(self.teams[team]) >= 4:
            print(f"Team {team} is already full.")
            return
        player = Player(name, team, ability)
        self.teams[team].append(player)

    def create_environment(self, name: str, difficulty: int):
        self.environments.append(Environment(name, difficulty))

    def next_environment(self):
        if self.current_environment_index + 1 < len(self.environments):
            self.current_environment_index += 1
            print(f"Moving to the next environment: {self.environments[self.current_environment_index].name}")
        else:
            print("Final treasure chamber reached!")

    def process_player_actions(self):
        current_environment = self.environments[self.current_environment_index]
        for team in self.teams.values():
            for player in team:
                if not player.is_active:
                    continue
                player.move(random.choice(list(Direction)))
                player.use_ability(current_environment)
                if random.random() < 0.3:
                    player.collect_treasure()
                    self.treasures_collected_per_team[player.team] += 1

    def end_game(self):
        elapsed_time = time.time() - self.start_time
        print(f"Game Over! Teams reached the final treasure chamber in {elapsed_time:.2f} seconds.")
        for team, score in self.treasures_collected_per_team.items():
            print(f"Team {team} collected {score} treasures.")
        # Determine winner
        winner = max(self.treasures_collected_per_team, key=self.treasures_collected_per_team.get)
        print(f"Winner: Team {winner}!")

    def run_game(self):
        print("Starting Team Treasure Hunt...")
        while self.current_environment_index < len(self.environments):
            current_environment = self.environments[self.current_environment_index]
            print(f"Team_Treasure_Hunt - Environment: {current_environment.name}, Difficulty: {current_environment.difficulty}")

            # Simulate player actions
            self.process_player_actions()

            # Check if environment is clear
            if current_environment.is_clear():
                self.next_environment()
            else:
                print(f"Team still needs to clear the environment: {current_environment.name}")
            time.sleep(1)  # Simulate time between actions
        self.end_game()

