import math
from enum import Enum
from abc import ABC, abstractmethod

class Direction(Enum):
    UP = 0
    DOWN = 1
    LEFT = 2
    RIGHT = 3

class WeaponType(Enum):
    RANGED = 0
    MELEE = 1
    SUPPORT = 2

class Team(Enum):
