class Position:
    """Represents a position in the arena with x and y coordinates."""
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def distance_to(self, other_position):
        """Calculate the distance to another position."""
        return math.sqrt((self.x - other_position.x)**2 + (self.y - other_position.y)**2)

class Arena:
    """Represents the battle arena with dimensions and environmental features."""
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.power_ups = []
        self.hazards = []

    def add_power_up(self, power_up):
        """Add a power-up to the arena."""
        self.power_ups.append(power_up)

    def add_hazard(self, hazard):
        """Add a hazard to the arena."""
        self.hazards.append(hazard)

    def get_power_ups_in_proximity(self, position, radius):
        """Get all power-ups within a certain radius of a given position."""
        return [pu for pu in self.power_ups if position.distance_to(pu.position) <= radius]

    def get_hazards_in_proximity(self, position, radius):
        """Get all hazards within a certain radius of a given position."""
        return [h for h in self.hazards if position.distance_to(h.position) <= radius]

class Weapon(ABC):
    """Abstract base class for all weapons in the arena."""
    def __init__(self, weapon_type, damage, range):
        self.weapon_type = weapon_type
        self.damage = damage
        self.range = range

    @abstractmethod
    def use(self, user, target):
        pass

class RangedWeapon(Weapon):
    """Represents a ranged weapon that can attack enemies from a distance."""
    def __init__(self, name, damage, range, accuracy):
        super().__init__(WeaponType.RANGED, damage, range)
        self.name = name
        self.accuracy = accuracy  # Accuracy as a decimal (0.0 to 1.0)

    def use(self, user, target):
        """Attempt to attack a target with this ranged weapon."""
        if user.position.distance_to(target.position) <= self.range:
            if random.random() <= self.accuracy:
                target.take_damage(self.damage)
                print(f"{user.name} hit {target.name} with {self.name} for {self.damage} damage!")
            else:
                print(f"{user.name} missed {target.name} with {self.name}!")
        else:
            print(f"{user.name} is too far away to use {self.name} on {target.name}!")

