        self.team = team
        self.health = 100
        self.weapon_type = weapon_type
        self.role = role
        self.experience = 0
        self.score = 0
        self.position = (0, 0)
        self.state = State.ALIVE
        self.weapon_damage = {
            WeaponType.RANGED: random.randint(15, 30),
            WeaponType.MELEE: random.randint(20, 40)
        }

    def attack(self, target):
        if self.state == State.ALIVE:
            damage = self.weapon_damage[self.weapon_type]
            target.health -= damage
            self.score += 1
            print(f"{self.name} attacks {target.name} for {damage} damage!")
            if target.health <= 0:
                self.score += 5
                target.state = State.INACTIVE
                print(f"{target.name} has been defeated!")

    def heal(self, ally):
        if self.role == Role.SUPPORT and self.state == State.ALIVE:
            heal_amount = random.randint(10, 25)
            ally.health = min(ally.health + heal_amount, 100)
            print(f"{self.name} heals {ally.name} for {heal_amount} health!")

    def move_towards(self, target_position):
        # Simple movement logic
        if self.state == State.ALIVE:
            dx = target_position[0] - self.position[0]
            dy = target_position[1] - self.position[1]
            step = random.choice((1, -1)) if abs(dx) > abs(dy) else random.choice((1, -1))
            self.position = (self.position[0] + (step if dx > 0 else -step), self.position[1] + (step if dy > 0 else -step))

    def update_experience(self, amount=1):
        self.experience += amount
        if self.experience >= 10:
            self.experience = 0
            self.weapon_damage[self.weapon_type] += random.randint(5, 10)
            print(f"{self.name} leveled up! Weapon damage increased.")

