        objectives = [ObjectiveType.CAPTURE_FLAG, ObjectiveType.DEFEND_BASE, ObjectiveType.ESCORT_PAYLOAD]
        for team in self.team_manager.teams:
            if self.team_manager.teams[team]:
                objective = random.choice(objectives)
                self.objective_manager.add_objective(objective)
                self.team_manager.assign_objective(team, objective)

    def start_round(self):
        print(f"\n--- Round {self.current_round} Started ---")
        self.round_start_time = time.time()
        self.assign_random_objectives()
        while time.time() - self.round_start_time < self.round_duration:
            self.run_tick()

        self.end_round()

    def run_tick(self):
        # Simulate robot actions
        for team in self.team_manager.teams.values():
            for robot in team:
                if robot.state == State.ALIVE:
                    if robot.role == Role.ATTACKER:
                        target = self.get_random_opponent(robot)
                        if target:
                            robot.attack(target)
                    elif robot.role == Role.SUPPORT:
                        ally = self.get_random_teammate(robot)
                        if ally:
                            robot.heal(ally)
                    elif robot.role == Role.TANK:
                        robot.move_towards(self.get_objective_position(robot.team))
                    elif robot.role == Role.SCAV:
                        robot.collect_resource()

        # Adaptive difficulty update
        self.adjust_difficulty()

    def get_random_opponent(self, robot):
        for team in self.team_manager.teams.values():
            if team != robot.team:
                for r in team:
                    if r.state == State.ALIVE:
                        return r
        return None

    def get_random_teammate(self, robot):
        for r in self.team_manager.teams[robot.team]:
            if r != robot and r.state == State.ALIVE:
                return r
        return None

    def get_objective_position(self, team):
        if self.team_manager.team_objective[team] == ObjectiveType.CAPTURE_FLAG:
            return (10, 10)
        elif self.team_manager.team_objective[team] == ObjectiveType.DEFEND_BASE:
            return (0, 0)
        elif self.team_manager.team_objective[team] == ObjectiveType.ESCORT_PAYLOAD:
            return (20, 20)
        return (0, 0)

    def adjust_difficulty(self):
        # Adjust based on robot performance
        for team in self.team_manager.teams.values():
            for robot in team:
                if robot.score > 20:
                    robot.update_experience()

        # Update team scores based on objectives
        for objective in self.objective_manager.completed_objectives:
            if objective == ObjectiveType.CAPTURE_FLAG:
                self.team_manager.update_team_score(objective.team, 10)
            elif objective == ObjectiveType.DEFEND_BASE:
                self.team_manager.update_team_score(objective.team, 5)
            elif objective == ObjectiveType.ESCORT_PAYLOAD:
                self.team_manager.update_team_score(objective.team, 15)

    def end_round(self):
        print(f"--- Round {self.current_round} Ended ---")
        self.current_round += 1
        self.reset_robots()
        if self.current_round > self.max_rounds:
            self.end_game()

    def reset_robots(self):
        for team in self.team_manager.teams.values():
            for robot in team:
