            self.health += 20
        elif self.power_up == PowerUp.SPEED_BOOST:
            pass
        elif self.power_up == PowerUp.REPAIR_KIT:
            self.health = 100
        elif self.power_up == PowerUp.EMP_PULSE:
            pass

    def use_weapon(self, target_robot):
        if self.weapon == Weapon.LASER_RIFLE:
            damage = random.randint(10, 20)
        elif self.weapon == Weapon.PLASMA_PULSE:
            damage = random.randint(5, 30)
        elif self.weapon == Weapon.ELECTRIC_SWORD:
