class Game:
    def __init__(self, game_type, max_players, scoring_rules):
        self.game_type = game_type
        self.max_players = max_players
        self.scoring_rules = scoring_rules
        self.teams = []
        self.robots = []
        self.current_turn = 0
        self.turn_order = []
        self.scoreboard = {}
        self.game_started = False
        self.game_ended = False

    def create_team(self, team_name, members):
        team = Team(team_name)
        for member in members:
            self.robots.append(Robot(member, team))
        self.teams.append(team)

    def start_game(self):
        self.game_started = True
        self.turn_order = self.robots.copy()
        random.shuffle(self.turn_order)
        self._start_turn_timer()

    def _start_turn_timer(self):
        def turn_cycle():
            while self.current_turn < len(self.turn_order) and not self.game_ended:
                current_robot = self.turn_order[self.current_turn]
                print(f"--- Turn {self.current_turn + 1} ---")
                print(f"It's {current_robot.name}'s turn.")

                # Simulate robot actions
                action = random.choice(["attack", "defend", "use_power_up"])
                if action == "attack":
                    target = random.choice([r for r in self.robots if r != current_robot])
                    current_robot.use_weapon(target)
                elif action == "defend":
                    pass
                elif action == "use_power_up":
                    current_robot.apply_power_up()

                # Update scores
                self._update_score(current_robot)

                # Notify next turn
                self._notify_next_turn()

                self.current_turn += 1
                time.sleep(2)  # Simulate time between turns

            self.end_game()

        threading.Thread(target=turn_cycle, daemon=True).start()

