class User:
    def __init__(self, user_id: str, name: str):
        self.user_id: str = user_id
        self.name: str = name
        self.expenses: Dict[str, float] = defaultdict(float)

    def add_expense(self, category: str, amount: float):
        if amount < 0:
            raise ValueError("Expense amount cannot be negative.")
        self.expenses[category] += round(amount, 2)

    def get_total_expenses(self) -> float:
        return sum(self.expenses.values())

    def get_expenses(self) -> Dict[str, float]:
        return dict(self.expenses)


class BudgetCategory:
    def __init__(self, name: str, limit: float):
        self.name: str = name
        self.limit: float = round(limit, 2)
        self.used: float = 0.0

    def add_usage(self, amount: float):
        if amount < 0:
            raise ValueError("Usage amount cannot be negative.")
        self.used += round(amount, 2)
        if self.used > self.limit:
            print(f"Warning: Budget for {self.name} has been exceeded by ${self.used - self.limit:.2f}")

    def get_remaining(self) -> float:
        return self.limit - self.used

    def set_limit(self, new_limit: float):
        self.limit = round(new_limit, 2)


class BudgetOptimizer:
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.budget_categories: Dict[str, BudgetCategory] = {}

    def add_user(self, user_id: str, name: str):
        if user_id in self.users:
            raise ValueError(f"User {user_id} already exists.")
        self.users[user_id] = User(user_id, name)

    def get_user(self, user_id: str) -> User:
        if user_id not in self.users:
            raise KeyError(f"User {user_id} not found.")
        return self.users[user_id]

    def add_expense(self, user_id: str, category: str, amount: float):
        user = self.get_user(user_id)
        user.add_expense(category, amount)
        if category not in self.budget_categories:
            raise ValueError(f"Category {category} not found in budget categories.")
        self.budget_categories[category].add_usage(amount)

    def add_budget_category(self, name: str, limit: float):
        if name in self.budget_categories:
            raise ValueError(f"Category {name} already exists.")
        self.budget_categories[name] = BudgetCategory(name, limit)

    def get_budget_status(self) -> Dict[str, Dict]:
        return {
            category: {
                "limit": cat.limit,
                "used": cat.used,
                "remaining": cat.get_remaining()
            }
            for category, cat in self.budget_categories.items()
        }

    def optimize_budget(self) -> List[Dict]:
        suggestions = []
        for category, cat in self.budget_categories.items():
            if cat.used > cat.limit:
                over_spent = cat.used - cat.limit
                suggestions.append({
                    "category": category,
                    "over_spent": over_spent,
                    "suggestion": f"Reduce spending or adjust budget for {category} by ${over_spent:.2f}."
                })
        return suggestions

    def get_user_contribution(self, user_id: str) -> Dict[str, float]:
        user = self.get_user(user_id)
        return user.get_expenses()

    def get_group_summary(self) -> Dict:
        total_expenses = 0.0
        category_usage = defaultdict(float)

        for user in self.users.values():
            for category, amount in user.expenses.items():
                category_usage[category] += amount
                total_expenses += amount

