class CombatRobot(Robot):
    """Robot specialized for combat actions"""
    def decide_action(self):
        """Combat robot AI decision making"""
        # Simple combat AI: attack nearest enemy or move towards them
        nearest_enemy = self.find_nearest_enemy()

        if nearest_enemy and self.position.distance_to(nearest_enemy.position) <= self.weapon.range:
            damage = self.weapon.use() * self.damage_multiplier
            nearest_enemy.take_damage(damage)
            print(f"{Color.OKGREEN}{self.name} attacks {nearest_enemy.name} for {damage} damage!{Color.ENDC}")

            # Record this action in memory
            self.memory.append({
                "action": {"type": "attack", "target": nearest_enemy.name, "weapon": self.weapon},
                "result": damage
            })
        else:
            # If no enemy in range, move towards nearest enemy
            if nearest_enemy:
                direction = self.calculate_direction_to(nearest_enemy.position)
                self.move(direction)

    def find_nearest_enemy(self):
        """Find the nearest enemy robot"""
        enemies = [robot for robot in self.arena.robots if robot.team != self.team]
        if enemies:
            return min(enemies, key=lambda r: r.position.distance_to(self.position))
        return None

    def calculate_direction_to(self, target_position):
        """Calculate direction to move towards a target position"""
        dx = target_position.x - self.position.x
        dy = target_position.y - self.position.y

        if abs(dx) > abs(dy):
            return Direction.RIGHT if dx > 0 else Direction.LEFT
        else:
            return Direction.DOWN if dy > 0 else Direction.UP

    def move(self, direction):
        """Move the robot in the specified direction"""
        if direction == Direction.UP:
            self.position.y -= self.speed
        elif direction == Direction.DOWN:
            self.position.y += self.speed
        elif direction == Direction.LEFT:
            self.position.x -= self.speed
        elif direction == Direction.RIGHT:
