        self.completed = False

    def check_completion(self, robots):
        """Check if the objective is completed"""
        if self.objective_type == ArenaObjective.CAPTURE_FLAG:
            # Check if a robot from a different team is in the zone
            if any(robot.team != self.team and robot.position.distance_to(self.position) <= 2 for robot in robots):
                self.completed = True
                print(f"{Color.BOLD}{Color.GREEN}Team {self.team.name} captured the enemy flag!{Color.ENDC}")
                self.arena.update_scores()
        elif self.objective_type == ArenaObjective.DEFEND_BASE:
