            if any(robot.team != self.team and robot.position.distance_to(self.position) <= 5 for robot in robots):
                self.completed = False
                print(f"{Color.BOLD}{Color.RED}Team {self.team.name} base is under attack!{Color.ENDC}")
        elif self.objective_type == ArenaObjective.ESCORT_PAYLOAD:
            # Check if a teammate is successfully escorting the payload
            if any(robot.team == self.team and robot.objective == self.objective_type for robot in robots):
                self.completed = True
