    def spawn_objectives(self):
        """Spawn objectives in the arena"""
        objective_types = [ArenaObjective.CAPTURE_FLAG, ArenaObjective.DEFEND_BASE, ArenaObjective.ESCORT_PAYLOAD, ArenaObjective.DOMINATE_ZONE]

        for team in Team:
            # Create objectives for each team
            objective_type = random.choice(objective_types)
            position = Position(random.uniform(0, self.width), random.uniform(0, self.height))

            if objective_type == ArenaObjective.CAPTURE_FLAG:
                # Create multiple flags for different teams
                for other_team in Team:
                    if other_team != team:
                        self.objectives.append(ObjectiveZone(position, objective_type, other_team))
