        for objective in self.objectives:
            if objective.completed and not hasattr(objective, "scored"):
                # Add points for completed objective
                self.scores[objective.team.name] += 100
                objective.scored = True
                print(f"{Color.OKCYAN}Team {objective.team.name} scored 100 points!{Color.ENDC}")

    def check_hazards(self):
