        for hazard in self.hazards:
            for robot in self.robots:
                if robot.position.distance_to(hazard.position) <= 3:
                    hazard.apply_effect(robot)

    def run_simulation(self, duration=60):
        """Run the simulation for the specified duration (in seconds)"""
        print(f"{Color.BOLD}{Color.MAGENTA}CyberArena Simulation Starting!{Color.ENDC}")
