        while time.time() < end_time:
            # Update objectives
            for objective in self.objectives:
                objective.check_completion(self.robots)

            # Check if any robots are in hazardous areas
            self.check_hazards()

            # Let all robots take their turn
            for robot in self.robots:
                robot.decide_action()
                robot.learn()  # Learn from the action

                # Adjust difficulty based on performance
                self.adjust_difficulty(robot)

            # Update the arena state
            self.update_scores()

