class Direction(Enum):
    """Possible movement directions"""
    UP = 1
    DOWN = 2
    LEFT = 3
    RIGHT = 4
    STATIONARY = 5

class WeaponType(Enum):
    """Types of weapons available to robots"""
    LASER = 1
    PLASMA = 2
    MELEE = 3
    MISSILE = 4
    NONE = 5

class PowerUpType(Enum):
    """Types of power-ups available in the arena"""
    SHIELD = 1
