    CAPTURE_FLAG = 1
    DEFEND_BASE = 2
    ESCORT_PAYLOAD = 3
    DOMINATE_ZONE = 4

class Position:
    """Represents a position in the arena"""
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def distance_to(self, other_position):
        """Calculate distance to another position"""
        return math.sqrt((self.x - other_position.x)**2 + (self.y - other_position.y)**2)

class Weapon:
    """Base class for all weapons"""
    def __init__(self, name, damage, range, fire_rate, ammo):
        self.name = name
        self.damage = damage
        self.range = range
        self.fire_rate = fire_rate  # attacks per second
        self.ammo = ammo

    def use(self):
        """Use the weapon (consume ammo and return damage)"""
        if self.ammo > 0:
            self.ammo -= 1
            return self.damage
        return 0

class Laser(Weapon):
    """Laser weapon class"""
    def __init__(self):
        super().__init__("Laser", 20, 100, 2.0, float('inf'))

class Plasma(Weapon):
    """Plasma weapon class"""
    def __init__(self):
        super().__init__("Plasma", 35, 80, 1.0, 50)

class Melee(Weapon):
    """Melee weapon class"""
    def __init__(self):
        super().__init__("Melee", 40, 1.5, 0.5, float('inf'))

class Missile(Weapon):
    """Missile weapon class"""
    def __init__(self):
        super().__init__("Missile", 50, 150, 0.3, 10)

class PowerUp:
    """Base class for all power-ups"""
    def __init__(self, power_type, duration):
        self.power_type = power_type
        self.duration = duration

    @abstractmethod
    def apply(self, robot):
        """Apply the power-up effect to a robot"""
        pass

class ShieldPowerUp(PowerUp):
    """Power-up that grants a shield"""
    def __init__(self):
        super().__init__(PowerUpType.SHIELD, 10)

    def apply(self, robot):
        robot.shield = min(robot.max_shield, robot.shield + 50)
        print(f"{Color.OKGREEN}{robot.name} picked up a shield power-up!{Color.ENDC}")

class SpeedBoostPowerUp(PowerUp):
    """Power-up that boosts speed"""
    def __init__(self):
        super().__init__(PowerUpType.SPEED_BOOST, 8)

    def apply(self, robot):
        robot.speed = min(robot.max_speed, robot.speed + 2)
        print(f"{Color.OKGREEN}{robot.name} got a speed boost!{Color.ENDC}")

class RepairKitPowerUp(PowerUp):
    """Power-up that repairs health"""
    def __init__(self):
        super().__init__(PowerUpType.REPAIR_KIT, 0)

    def apply(self, robot):
        robot.health = min(robot.max_health, robot.health + 25)
        print(f"{Color.OKGREEN}{robot.name} used a repair kit!{Color.ENDC}")

class TeamShieldPowerUp(PowerUp):
    """Power-up that grants a shield to the whole team"""
    def __init__(self):
        super().__init__(PowerUpType.TEAM_SHIELD, 10)

    def apply(self, robot):
        for team_robot in robot.arena.robots:
            if team_robot.team == robot.team:
                team_robot.shield = min(team_robot.max_shield, team_robot.shield + 30)
        print(f"{Color.OKGREEN}Team {robot.team.name} got a team shield power-up!{Color.ENDC}")

