class Robot(ABC):
    """Base class for all robots in the arena"""
    def __init__(self, name, team, position, arena):
        self.name = name
        self.team = team
        self.position = position
        self.arena = arena
        self.health = 100
        self.max_health = 100
        self.shield = 0
        self.max_shield = 50
        self.speed = 2.0
        self.max_speed = 5.0
        self.damage_multiplier = 1.0
        self.weapon = None
        self.power_ups = []
        self.objective = None

        # AI related attributes
        self.memory = []  # stores experiences for learning
        self.performance = 0  # tracks overall performance

        # Initialize with a random weapon
        self.select_weapon()

    @abstractmethod
    def decide_action(self):
        """Determine the robot's next action based on its AI"""
        pass

    def select_weapon(self):
        """Randomly select a weapon for the robot"""
        weapon_options = [Laser(), Plasma(), Melee(), Missile()]
        self.weapon = random.choice(weapon_options)
        print(f"{Color.OKBLUE}{self.name} equipped with {self.weapon.name}{Color.ENDC}")

    def take_damage(self, damage):
        """Handle taking damage (applying to shield first, then health)"""
        if self.shield > 0:
            if damage >= self.shield:
                self.shield = 0
                damage -= self.shield
            else:
                self.shield -= damage
                damage = 0

        if damage > 0:
            self.health -= damage
            print(f"{Color.FAIL}{self.name} took {damage} damage!{Color.ENDC}")

        if self.health <= 0:
            self.die()

    def die(self):
        """Handle the robot's death"""
        print(f"{Color.BOLD}{Color.RED}{self.name} has been destroyed!{Color.ENDC}")
