        def remove_power_up():
            time.sleep(power_up.duration)
            if power_up.power_type == PowerUpType.SPEED_BOOST:
                self.speed = min(self.max_speed, self.speed - 2)
            elif power_up.power_type == PowerUpType.DAMAGE_BOOST:
                self.damage_multiplier = min(1.0, self.damage_multiplier - 0.5)

        threading.Thread(target=remove_power_up).start()

