                self.completed = True
                print(f"{Color.BOLD}{Color.GREEN}Team {self.team.name} successfully escorted the payload!{Color.ENDC}")
                self.arena.update_scores()
        elif self.objective_type == ArenaObjective.DOMINATE_ZONE:
            # Check if the team dominates the zone
            if sum(robot.team == self.team for robot in robots) > sum(robot.team != self.team for robot in robots):
                self.completed = True
                print(f"{Color.BOLD}{Color.GREEN}Team {self.team.name} dominates the zone!{Color.ENDC}")
