        """Spawn power-ups in the arena"""
        power_up_types = [ShieldPowerUp, SpeedBoostPowerUp, RepairKitPowerUp, TeamShieldPowerUp, DamageBoostPowerUp]

        for _ in range(10):
            power_up_type = random.choice(power_up_types)
