            print(f"{Color.FAIL}Spawned {hazard_type().__class__.__name__} at ({position.x}, {position.y}){Color.ENDC}")

    def spawn_objectives(self):
        """Spawn objectives in the arena"""
        objective_types = [ArenaObjective.CAPTURE_FLAG, ArenaObjective.DEFEND_BASE, ArenaObjective.ESCORT_PAYLOAD, ArenaObjective.DOMINATE_ZONE]

        for team in Team:
            # Create objectives for each team
            objective_type = random.choice(objective_types)
            position = Position(random.uniform(0, self.width), random.uniform(0, self.height))

            if objective_type == ArenaObjective.CAPTURE_FLAG:
                # Create multiple flags for different teams
                for other_team in Team:
                    if other_team != team:
                        self.objectives.append(ObjectiveZone(position, objective_type, other_team))
            else:
                self.objectives.append(ObjectiveZone(position, objective_type, team))

    def update_scores(self):
        """Update the scores based on objectives completed"""
        for objective in self.objectives:
            if objective.completed and not hasattr(objective, "scored"):
                # Add points for completed objective
                self.scores[objective.team.name] += 100
                objective.scored = True
                print(f"{Color.OKCYAN}Team {objective.team.name} scored 100 points!{Color.ENDC}")

    def check_hazards(self):
        """Check if any robots are in hazardous areas"""
        for hazard in self.hazards:
            for robot in self.robots:
                if robot.position.distance_to(hazard.position) <= 3:
                    hazard.apply_effect(robot)

    def run_simulation(self, duration=60):
        """Run the simulation for the specified duration (in seconds)"""
        print(f"{Color.BOLD}{Color.MAGENTA}CyberArena Simulation Starting!{Color.ENDC}")
        print(f"{Color.BOLD}{Color.CYAN}Simulation will run for {duration} seconds{Color.ENDC}")

        for team in Team:
            print(f"{Color.BOLD}{Color.GREEN}Team {team.name} robots:")
            for robot in [r for r in self.robots if r.team == team]:
                print(f"  - {robot.name}")

        end_time = time.time() + duration

        while time.time() < end_time:
            # Update objectives
            for objective in self.objectives:
                objective.check_completion(self.robots)

            # Check if any robots are in hazardous areas
            self.check_hazards()

            # Let all robots take their turn
            for robot in self.robots:
                robot.decide_action()
                robot.learn()  # Learn from the action

                # Adjust difficulty based on performance
                self.adjust_difficulty(robot)

            # Update the arena state
            self.update_scores()

            # Print status every 5 seconds
            if (time.time() % 5) < 0.1:
                self.print_status()

            # Wait for a short time between steps
            time.sleep(0.1)

        print(f"{Color.BOLD}{Color.YELLOW}Simulation Complete!{Color.ENDC}")
        self.print_final_scores()

    def adjust_difficulty(self, robot):
        """Adjust the difficulty based on robot performance"""
        # Increase difficulty if robot is performing too well
        if robot.performance > 80:
            if random.random() < 0.1:  # 10% chance to spawn new hazard
                hazard_types = [ToxicCloud, Lava]
                hazard_type = random.choice(hazard_types)
                position = Position(random.uniform(0, self.width), random.uniform(0, self.height))
                self.hazards.append(hazard_type())
                self.hazards[-1].position = position
                print(f"{Color.FAIL}Increased difficulty: Spawned {hazard_type().__class__.__name__}{Color.ENDC}")

        # Decrease difficulty if robot is struggling
        if robot.performance < 20:
            if random.random() < 0.1:  # 10% chance to remove a hazard
                if self.hazards:
                    removed_hazard = self.hazards.pop()
                    print(f"{Color.OKGREEN}Decreased difficulty: Removed {removed_hazard.name}{Color.ENDC}")

    def print_status(self):
        """Print current status of the arena"""
        print(f"{Color.BOLD}{Color.CYAN}--- Arena Status ---{Color.ENDC}")
        print(f"Time elapsed: {time.time() % 60:.1f} seconds")
        print(f"Active Robots: {len(self.robots)}")
        print(f"Remaining Power-ups: {len(self.power_ups)}")
        print(f"Active Hazards: {len(self.hazards)}")
        print(f"Active Objectives: {len([o for o in self.objectives if not o.completed])}")
        print(f"Current Scores: {self.scores}")
        print(f"---------------------{Color.ENDC}")

    def print_final_scores(self):
        """Print the final scores of the simulation"""
        print(f"{Color.BOLD}{Color.YELLOW}--- Final Scores ---{Color.ENDC}")
        for team, score in self.scores.items():
            print(f"Team {team}: {score} points")

        # Determine the winning team
        winner = max(self.scores.items(), key=lambda x: x[1])
        print(f"{Color.BOLD}{Color.GREEN}Winner: Team {winner[0]} with {winner[1]} points!{Color.ENDC}")

