# User Management and Authentication Module

class User:
    """Represents a user profile with authentication and permissions."""

    def __init__(self, username, password, email):
        self.username = username
        self.password = password  # In a real app, use hashing (e.g., bcrypt)
        self.email = email
        self.shared_budgets = []  # Budgets the user is part of
        self.permission_level = 'EDITOR'  # Default permission

    def create_budget(self, name, members=[]):
        """User creates a new shared budget."""
        new_budget = Budget(name)
        new_budget.add_members(members)
        return new_budget

    def assign_permission(self, budget, user, permission):
        """Assign access level to a user in a shared budget."""
        if permission in ['VIEWER', 'EDITOR']:
            budget.update_user_permissions(user, permission)

# Shared Budget Module

class Budget:
    """Represents a shared budget with income, expenses, and goals."""

    def __init__(self, name):
        self.name = name
        self.members = []  # Users in this budget
        self.incomes = []  # Income records
        self.expenses = []  # Expense records
        self.goals = []  # Budget goals
        self.notifications = []  # Notifications for this budget

    def add_members(self, users):
        """Add users to this budget."""
        for user in users:
            self.members.append(user)
            user.shared_budgets.append(self)

    def update_user_permissions(self, user, permission):
        """Update a user's access level in this budget."""
        for member in self.members:
            if member.username == user.username:
                user.permission_level = permission

    def add_income(self, amount, category='Uncategorized'):
        self.incomes.append({'amount': amount, 'category': category})

    def add_expense(self, amount, category='Uncategorized', user=None):
        self.expenses.append({'amount': amount, 'category': category, 'user': user.username})

    def calculate_total(self):
        total_income = sum([income['amount'] for income in self.incomes])
        total_expense = sum([expense['amount'] for expense in self.expenses])
        return {'income': total_income, 'expense': total_expense, 'balance': total_income - total_expense}

    def track_progress(self):
        """Track progress toward budget goals."""
        for goal in self.goals:
            progress = self.calculate_total()['balance'] / goal['target_amount']
            if progress >= 1.0:
                self.notifications.append(f"{goal['name']} goal achieved!")

# Dashboard Module

class Dashboard:
    """Represents the shared dashboard view for each budget."""

    def __init__(self, budget):
        self.budget = budget
        self.visualization = Visualization()

