            arena.play_sound_effect("heal_sound")
            arena.add_visual_effect("heal_glow", teammate.position)
            self.last_action_time = time.time()

    def find_nearby_entities(self, arena, entity_type, health_threshold=0):
        """Find nearby entities of a specific type"""
        result = []
        for entity in arena.robots + arena.objectives:
            if entity_type == 'enemy' and entity.team != self.team and entity.health > health_threshold:
                result.append(entity)
            elif entity_type == 'teammate' and entity.team == self.team and entity.health > health_threshold and entity != self:
                result.append(entity)

        # Sort by distance from this robot
        result.sort(key=lambda x: self.distance_to(x))
        return result

    def find_team_base(self, arena):
        """Find the team's base position"""
        for objective in arena.objectives:
            if objective.objective_type == 'Defend Base' and objective.team == self.team:
