        self.power_ups.append(power_up)

    def add_hazard(self, hazard):
        """Add a hazard to the arena"""
        self.hazards.append(hazard)

    def log_event(self, message):
        """Add an event to the log"""
        self.log.append((time.time(), message))

    def play_sound_effect(self, sound_name):
        """Add a sound effect to play"""
        self.sound_effects.append(sound_name)

    def add_visual_effect(self, effect_name, position):
        """Add a visual effect to display"""
        self.visual_effects.append((effect_name, position, time.time()))

    def schedule_action(self, function, delay):
        """Schedule an action to occur after delay seconds"""
        threading.Timer(delay, function, args=[self]).start()

    def is_valid_position(self, position):
        """Check if a position is within arena bounds and not occupied"""
        x, y = position
        if 0 <= x < self.width and 0 <= y < self.height:
            # Check for collisions with other robots
            for robot in self.robots:
                if robot.position == position:
                    return False
            return True
        return False

    def update(self):
        """Update the arena state"""
        self.timer += 1

        # Update all robots
        for robot in self.robots:
            robot.update(self)
            # Apply status effects
            for effect in list(robot.status_effects):
                if effect == StatusEffect.BURNING:
                    robot.take_damage(5, self)
                    if random.random() < 0.5:
                        self.schedule_action(robot.burn_damage, 1)

            # Remove expired effects
            if StatusEffect.SLOWED in robot.status_effects and self.timer % 10 == 0:
                robot.remove_status_effect(StatusEffect.SLOWED)

            if StatusEffect.STUNNED in robot.status_effects and self.timer % 5 == 0:
                robot.remove_status_effect(StatusEffect.STUNNED)

            if StatusEffect.EMP in robot.status_effects and self.timer % 5 == 0:
                robot.remove_status_effect(StatusEffect.EMP)

            if StatusEffect.FROZEN in robot.status_effects and self.timer % 10 == 0:
                robot.remove_status_effect(StatusEffect.FROZEN)

            if StatusEffect.BURNING in robot.status_effects and self.timer % 10 == 0:
                robot.remove_status_effect(StatusEffect.BURNING)

        # Update objectives
        for objective in self.objectives:
            objective.update(self)

        # Check for power-up pickups
        for power_up in list(self.power_ups):
            for robot in self.robots:
                if robot.position == power_up.position:
                    power_up.apply_effect(robot, self)
                    self.power_ups.remove(power_up)
                    break

        # Apply hazard effects
        for hazard in self.hazards:
            for robot in self.robots:
                if robot.position == hazard.position:
                    hazard.apply_effect(robot, self)

        # Apply adaptive difficulty
        self.update_difficulty()

        # Clean up expired visual effects
        self.visual_effects = [v for v in self.visual_effects if time.time() - v[2] < 2]

        # Check for win condition
        if self.check_win_condition():
            self.end_arena()

    def update_difficulty(self):
        """Update the difficulty based on team performance"""
        red_strength = sum(robot.health for robot in self.robots if robot.team == 'Red')
        blue_strength = sum(robot.health for robot in self.robots if robot.team == 'Blue')

        if red_strength > blue_strength * 1.5 and self.difficulty_level < 5:
            self.difficulty_level += 1
            self.log_event("Increasing difficulty level to " + str(self.difficulty_level))

        elif blue_strength > red_strength * 1.5 and self.difficulty_level > 1:
