# Combat system
class CombatSystem:
    def __init__(self):
        self.battlefield = {}
        self.combat_log = []

    def add_robot(self, robot, position):
        """Add a robot to the battlefield"""
        self.battlefield[position] = robot
        robot.position = position

    def remove_robot(self, robot):
        """Remove a robot from the battlefield"""
        positions = [pos for pos, r in self.battlefield.items() if r == robot]
        for pos in positions:
            del self.battlefield[pos]

    def handle_combat(self):
        """Handle real-time combat actions"""
        active_robots = list(self.battlefield.values())
        for robot in active_robots:
            if robot.health <= 0:
                self.remove_robot(robot)
                continue

            # Find nearby enemies
            nearby_enemies = []
            for pos, enemy in self.battlefield.items():
                if enemy.team != robot.team and self.distance(robot.position, pos) <= robot.attack_range:
                    nearby_enemies.append(enemy)

            if nearby_enemies:
                # Choose a random target
                target = random.choice(nearby_enemies)
                robot.attack(target)
                self.combat_log.append(f"{robot.name} attacked {target.name}")
            else:
                # Move to a random position if no enemies nearby
                new_pos = (robot.position[0] + random.randint(-2, 2),
                          robot.position[1] + random.randint(-2, 2))
                robot.move(new_pos)

    def distance(self, pos1, pos2):
        """Calculate distance between two positions"""
        return ((pos1[0] - pos2[0])**2 + (pos1[1] - pos2[1])**2)**0.5

