        """Create a power-up at a specific position"""
        self.active_power_ups.append({
            "type": power_up_type,
            "position": position,
            "duration": 20  # seconds
        })
        print(f"{power_up_type.value} power-up created at position {position}")

    def update_power_ups(self, robots):
        """Update power-up status and apply effects to robots"""
        for power_up in self.active_power_ups.copy():
            # Decrease duration
            power_up["duration"] -= 1

            # Check if any robot is near the power-up
            for robot in robots:
                if self.distance(robot.position, power_up["position"]) < 2:
                    robot.use_power_up(power_up["type"])
                    self.active_power_ups.remove(power_up)
                    print(f"{robot.name} collected {power_up['type'].value}")
                    break

            # Remove expired power-ups
            if power_up["duration"] <= 0:
                self.active_power_ups.remove(power_up)
                print(f"{power_up['type'].value} power-up expired")

    def distance(self, pos1, pos2):
        return ((pos1[0] - pos2[0])**2 + (pos1[1] - pos2[1])**2)**0.5

