# solution.py

import datetime
import json
from typing import Dict, List, Optional
import uuid
import random
from dataclasses import dataclass
from collections import defaultdict
import matplotlib.pyplot as plt
from flask import Flask, request, jsonify, session
from flask_cors import CORS

app = Flask(__name__)
app.secret_key = "super-secret-key"
CORS(app)

# In-memory database for demo purposes
users_db: Dict[str, Dict] = {}
budgets_db: Dict[str, Dict] = {}
roles_db: Dict[str, Dict] = {}
messages_db: Dict[str, List[Dict]] = {}

# Roles with permissions
ROLES = {
    "admin": ["create", "edit", "delete", "view"],
    "user": ["view", "edit"]
}

# Dataclasses for better typing
@dataclass
class User:
    user_id: str
    username: str
    email: str
    password: str

@dataclass
class Budget:
    budget_id: str
    name: str
    users: List[str]  # user_ids
    income: Dict[str, float]  # category -> amount
    expenses: Dict[str, float]  # category -> amount
    goals: Dict[str, Dict]  # goal_name -> {"target": float, "current": float, "deadline": str}
    feedback: List[str]

@dataclass
class Message:
    id: str
    budget_id: str
    sender: str
    content: str
    timestamp: str

# Helper functions
def create_user(username: str, email: str, password: str) -> Dict:
    user_id = str(uuid.uuid4())
    users_db[user_id] = {
        "username": username,
        "email": email,
        "password": password
    }
    return {"user_id": user_id}

def create_budget(name: str, user_ids: List[str]) -> Dict:
    budget_id = str(uuid.uuid4())
    budgets_db[budget_id] = {
        "name": name,
        "users": user_ids,
        "income": {},
        "expenses": {},
        "goals": {},
        "feedback": []
    }
    for user_id in user_ids:
        messages_db.setdefault(user_id, [])
    return {"budget_id": budget_id}

def add_income(budget_id: str, category: str, amount: float, user_id: str):
    if user_id not in budgets_db[budget_id]["users"]:
        return {"success": False, "message": "User not part of this budget."}
    budgets_db[budget_id]["income"][category] = budgets_db[budget_id]["income"].get(category, 0) + amount
    generate_feedback(budget_id)
    return {"success": True}

def add_expense(budget_id: str, category: str, amount: float, user_id: str):
    if user_id not in budgets_db[budget_id]["users"]:
        return {"success": False, "message": "User not part of this budget."}
    budgets_db[budget_id]["expenses"][category] = budgets_db[budget_id]["expenses"].get(category, 0) + amount
    generate_feedback(budget_id)
    return {"success": True}

def set_goal(budget_id: str, goal_name: str, target: float, deadline: str, user_id: str):
    if user_id not in budgets_db[budget_id]["users"]:
        return {"success": False, "message": "User not part of this budget."}
    budgets_db[budget_id]["goals"][goal_name] = {
        "target": target,
        "current": 0.0,
        "deadline": deadline
    }
    return {"success": True}

def generate_feedback(budget_id: str):
    budget = budgets_db[budget_id]
    feedback = []

    total_income = sum(budget["income"].values())
    total_expenses = sum(budget["expenses"].values())

    if total_expenses > total_income:
        feedback.append("Your expenses exceed income. Consider reducing expenses or increasing income.")

    for category, amount in budget["expenses"].items():
        if amount > total_income * 0.15:  # 15% threshold
            feedback.append(f"Be cautious with {category}: it's consuming a large portion of your budget.")

    for goal, data in budget["goals"].items():
        progress = data["current"] / data["target"] * 100 if data["target"] > 0 else 0
        if progress < 20:
            feedback.append(f"Goal '{goal}' is only at {progress:.1f}% progress. Consider increasing contributions.")

    budget["feedback"] = feedback

@app.route('/create_user', methods=['POST'])
def create_user_route():
    data = request.json
    result = create_user(data['username'], data['email'], data['password'])
    return jsonify(result)

@app.route('/create_budget', methods=['POST'])
def create_budget_route():
    data = request.json
    result = create_budget(data['name'], data['user_ids'])
    return jsonify(result)

@app.route('/add_income', methods=['POST'])
def add_income_route():
    data = request.json
    result = add_income(data['budget_id'], data['category'], data['amount'], data['user_id'])
    return jsonify(result)

@app.route('/add_expense', methods=['POST'])
def add_expense_route():
    data = request.json
    result = add_expense(data['budget_id'], data['category'], data['amount'], data['user_id'])
    return jsonify(result)

@app.route('/set_goal', methods=['POST'])
def set_goal_route():
    data = request.json
    result = set_goal(data['budget_id'], data['goal_name'], data['target'], data['deadline'], data['user_id'])
    return jsonify(result)

@app.route('/get_budget', methods=['GET'])
def get_budget():
    budget_id = request.args.get('budget_id')
    return jsonify(budgets_db.get(budget_id, {}))

@app.route('/get_feedback', methods=['GET'])
def get_feedback():
    budget_id = request.args.get('budget_id')
    return jsonify(budgets_db.get(budget_id, {}).get('feedback', []))

@app.route('/send_message', methods=['POST'])
def send_message_route():
    data = request.json
    message = Message(
        id=str(uuid.uuid4()),
        budget_id=data['budget_id'],
        sender=data['sender'],
        content=data['content'],
        timestamp=str(datetime.datetime.now())
    )
    if budgets_db.get(data['budget_id']):
        messages_db.setdefault(data['sender'], []).append(message.__dict__)
        return jsonify({"success": True})
    return jsonify({"success": False, "message": "Budget not found"})

@app.route('/get_messages', methods=['GET'])
def get_messages_route():
    user_id = request.args.get('user_id')
    return jsonify(messages_db.get(user_id, []))

@app.route('/plot_budget', methods=['GET'])
def plot_budget_route():
    budget_id = request.args.get('budget_id')
    budget = budgets_db.get(budget_id, {})
    income = budget.get('income', {})
    expenses = budget.get('expenses', {})

    # Create pie chart
    labels = list(expenses.keys())
    sizes = list(expenses.values())

    plt.figure(figsize=(8, 6))
    plt.pie(sizes, labels=labels, autopct='%1.1f%%', startangle=140)
    plt.title('Expense Breakdown')
    plt.savefig('static/expense_pie.png')
    plt.close()

    return jsonify({"image": "expense_pie.png"})

if __name__ == "__main__":
