        """Record the results of a battle for analysis"""
        self.battle_history.append(battle_results)

    def analyze_patterns(self):
        """Analyze battle patterns to improve strategies"""
        if not self.battle_history:
            return

        # Simple pattern recognition
        for battle in self.battle_history[-5:]:  # Only look at recent battles
            for robot_name, stats in battle.items():
                if robot_name not in self.strategy_patterns:
                    self.strategy_patterns[robot_name] = {"wins": 0, "losses": 0, "preferred_weapons": {}}

                if stats["result"] == "win":
                    self.strategy_patterns[robot_name]["wins"] += 1
                    # Track preferred weapons
                    weapon = stats["last_weapon"]
                    if weapon in self.strategy_patterns[robot_name]["preferred_weapons"]:
                        self.strategy_patterns[robot_name]["preferred_weapons"][weapon] += 1
                    else:
                        self.strategy_patterns[robot_name]["preferred_weapons"][weapon] = 1
                else:
                    self.strategy_patterns[robot_name]["losses"] += 1

    def suggest_improvements(self, robot):
        """Suggest strategy improvements based on analysis"""
        if robot.name not in self.strategy_patterns:
            return "No data available for this robot"

        patterns = self.strategy_patterns[robot.name]
        suggestions = []

        if patterns["wins"] < patterns["losses"]:
            suggestions.append("Your win rate is low. Consider adjusting your strategy.")

        # Suggest preferred weapons based on success
        if patterns["preferred_weapons"]:
            best_weapon = max(patterns["preferred_weapons"], key=patterns["preferred_weapons"].get)
            suggestions.append(f"Consider using {best_weapon.value} more often as it has shown success.")

        return suggestions

