import random
import math
from abc import ABC, abstractmethod
from enum import Enum
import time


class Team(Enum):
    RED = 1
    BLUE = 2

class Position:
    """Represents a 2D position in the arena."""
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def distance(self, other):
        """Calculate the distance between this position and another."""
        return math.sqrt((self.x - other.x) ** 2 + (self.y - other.y) ** 2)

    def __repr__(self):
        return f"Position(x={self.x}, y={self.y})"

class Weapon(Enum):
    """Available weapons for robots in the arena."""
    LASER = 1
    MISSILE = 2
    PLASMA = 3

class Robot(ABC):
    """Abstract base class for all robots in the arena."""
    def __init__(self, name, team, position, weapon):
        self.name = name
        self.team = team
        self.position = position
        self.weapon = weapon
        self.health = 100

    @abstractmethod
    def move(self, new_position):
        """Abstract method to move the robot to a new position."""
        pass

    @abstractmethod
    def attack(self, target):
        """Abstract method to attack a target robot."""
        pass

    def take_damage(self, amount):
        """Reduce the robot's health by the given amount."""
        self.health -= amount
        if self.health < 0:
            self.health = 0

    def is_alive(self):
        """Check if the robot is still alive (health > 0)."""
        return self.health > 0

    def __repr__(self):
        return f"Robot(name={self.name}, team={self.team.name}, position={self.position}, health={self.health}, weapon={self.weapon.name})"

class Arena:
    """Represents the battle arena where robots fight."""
    def __init__(self, width=100, height=100):
        self.width = width
        self.height = height
        self.robots = []

    def add_robot(self, robot):
        """Add a robot to the arena if its position is within the arena boundaries."""
        if 0 <= robot.position.x <= self.width and 0 <= robot.position.y <= self.height:
            self.robots.append(robot)
        else:
            raise ValueError(f"Robot {robot.name} is outside the arena boundaries.")

    def remove_robot(self, robot):
        """Remove a robot from the arena."""
        if robot in self.robots:
            self.robots.remove(robot)

    def get_alive_robots(self):
        """Get a list of all alive robots in the arena."""
        return [robot for robot in self.robots if robot.is_alive()]

    def simulate_turn(self):
        """Simulate one turn of the battle: robots move and attack."""
        # Move all robots first
        for robot in self.robots:
            robot.move(Position(random.randint(0, self.width), random.randint(0, self.height)))

        # Then attack
        for robot in self.robots:
            if robot.is_alive():
                # Find a target from the opposing team
                potential_targets = [r for r in self.robots if r.team != robot.team and r.is_alive()]
                if potential_targets:
                    target = random.choice(potential_targets)
                    robot.attack(target)

    def __repr__(self):
        return f"Arena(width={self.width}, height={self.height}, robots={self.robots})"

class BattleSimulator:
    """Simulates a battle between robots in an arena."""
    def __init__(self, arena, max_turns=10):
        self.arena = arena
        self.max_turns = max_turns
        self.turn_count = 0

    def run_simulation(self):
        """Run the battle simulation until one team wins or max turns are reached."""
        while self.turn_count < self.max_turns and any(robot.is_alive() for robot in self.arena.robots):
            print(f"\n--- Turn {self.turn_count + 1} ---")
            self.arena.simulate_turn()
            self.turn_count += 1
            self.display_status()

        # Determine the winner
        red_robots = [robot for robot in self.arena.robots if robot.team == Team.RED and robot.is_alive()]
        blue_robots = [robot for robot in self.arena.robots if robot.team == Team.BLUE and robot.is_alive()]

        if red_robots and not blue_robots:
            print("\nRed team wins!")
        elif blue_robots and not red_robots:
            print("\nBlue team wins!")
        else:
            print("\nIt's a draw!")

    def display_status(self):
        """Display the current status of all robots in the arena."""
        for robot in self.arena.robots:
            print(robot)

    def __repr__(self):
        return f"BattleSimulator(arena={self.arena}, max_turns={self.max_turns}, turn_count={self.turn_count})"


