    def update_score(self, points: int) -> None:
        """Updates the team's score."""
        self.score += points

    def get_score(self) -> int:
        """Returns the team's current score."""
        return self.score

    def get_robots(self) -> List[Robot]:
        """Returns the list of robots in the team."""
        return self.robots

    def serialize(self) -> Dict:
        """Converts the team to a dictionary for serialization."""
        return {
            "name": self.name,
            "color": self.color,
            "score": self.score,
            "robots": [r.serialize() for r in self.robots]
        }

    def __repr__(self) -> str:
        return f"Team({self.name}, Score: {self.score}, Robots: {len(self.robots)})"


class Objective:
    """Represents a team-based objective in the CyberArena."""

    def __init__(self, name: str, description: str, 
                 completion_reward: int, difficulty: float):
