        for objective in self.objectives:
            # Check if objective is completed
            if objective.is_completed():
                # Award completion reward to the team
                for team in self.teams:
                    if team.objectives and objective in team.objectives:
                        team.update_score(objective.completion_reward)
                        self.scoreboard[team.name] = team.get_score()
