            if power_up.should_spawn(current_time):
                power_up.activate(current_time)

        # Update hazards
        for hazard in self.hazards:
            # Check if hazard should activate
            if not hazard.is_active(current_time) and random.random() < 0.1:
                hazard.activate(current_time)

        # Check for power-up collection
        for robot in self.robots:
            if robot.is_alive:
                for power_up in self.power_ups:
                    if power_up.is_active(current_time) and \
                       robot.position.distance_to(power_up.position) <= 5:
                        robot.collect_power_up(power_up, current_time)

        # Check for robot deaths and update scores
        for team in self.teams:
            alive_robots = sum(1 for r in team.get_robots() if r.is_alive)
            if alive_robots == 0:
                # Team has lost all robots, update score
                team.update_score(-100)  # Penalize for losing all robots
                self.scoreboard[team.name] = team.get_score()

        # Update elapsed time
        self.time_elapsed = current_time - self.start_time

    def get_scoreboard(self) -> Dict:
        """Returns the current scoreboard."""
        return self.scoreboard

    def get_winning_team(self) -> Team:
        """Returns the winning team based on score."""
        if not self.teams:
