        super().__init__(name, team, position)
        self.set_role(Role.MEDIC)

    def take_action(self, arena):
        """Medic's decision making: heal injured teammates"""
        injured_teammates = [r for r in arena.robots if r.team == self.team and r.health < 100 and r.is_alive()]

        if injured_teammates:
            # Find the most injured teammate
            target = min(injured_teammates, key=lambda r: r.health)

            if self.position.distance_to(target.position) < 15:
                # Heal the teammate
                heal_amount = min(10, 100 - target.health)
                target.health += heal_amount
                print(f"{self.name} healed {target.name} for {heal_amount} health!")
                self.add_experience(5)  # Gain experience for healing
        else:
            # No injured teammates, move to a random position
            self._move_to_random_position()

    def _move_to_random_position(self):
        """Move to a random position in the arena"""
        new_x = random.uniform(0, 100)
        new_y = random.uniform(0, 100)
        move_dir = Vector2(new_x - self.position.x, new_y - self.position.y)
        move_dir = move_dir / max(1, move_dir.distance_to(Vector2(0,0))) * 3  # Normalize and limit speed
        self.position = self.position + move_dir


class Scout(Robot):
    """Reconnaissance role for gathering information"""
    def __init__(self, name, team, position):
        super().__init__(name, team, position)
        self.set_role(Role.SCOUT)
        self.last_seen_enemies = {}

    def take_action(self, arena):
        """Scout's decision making: gather intel and report"""
        # Look for enemies
        for robot in arena.robots:
            if robot.team != self.team and robot.is_alive():
                distance = self.position.distance_to(robot.position)
                if distance < 50:
                    # Report enemy location to the team
                    print(f"{self.name} spotted an enemy at {robot.position}!")
                    self.last_seen_enemies[robot.name] = robot.position

        # If no enemies seen, move to a random position
        if not self.last_seen_enemies or random.random() < 0.3:
            self._move_to_random_position()

    def _move_to_random_position(self):
        """Move to a random position in the arena"""
        new_x = random.uniform(0, arena.width)
        new_y = random.uniform(0, arena.height)
        move_dir = Vector2(new_x - self.position.x, new_y - self.position.y)
        move_dir = move_dir / max(1, move_dir.distance_to(Vector2(0,0))) * 4  # Normalize and limit speed
        self.position = self.position + move_dir


# =============
# Game Objectives
# =============

class Objective:
    """Base class for game objectives"""
    def __init__(self, description, team_reward=True):
        self.description = description
        self.team_reward = team_reward

    @abstractmethod
    def is_complete(self, arena):
        """Check if the objective is completed"""
        pass


class CaptureFlagObjective(Objective):
    """Objective to capture an enemy flag"""
    def __init__(self, flag_position):
        super().__init__("Capture the enemy flag", team_reward=True)
        self.flag_position = flag_position
        self.flag_captured = False

    def is_complete(self, arena):
        """Check if the objective is completed"""
        for robot in arena.robots:
            if robot.team == Team.RED and robot.position.distance_to(self.flag_position) < 5:
                self.flag_captured = True
                return True
        return False


class DefendBaseObjective(Objective):
    """Objective to defend a base position"""
    def __init__(self, base_position):
        super().__init__("Defend the base from enemy attacks", team_reward=True)
        self.base_position = base_position
        self.base_destroyed = False

    def is_complete(self, arena):
        """Check if the objective is completed"""
        # Objective is completed if base is not destroyed for the duration
        for robot in arena.robots:
            if robot.team != Team.BLUE and robot.position.distance_to(self.base_position) < 10:
                # Enemy is too close to the base
                return False
        return True


class EscortPayloadObjective(Objective):
    """Objective to escort a payload to its destination"""
    def __init__(self, payload_position, destination_position):
        super().__init__("Escort the payload to its destination", team_reward=True)
        self.payload_position = payload_position
        self.destination_position = destination_position
        self.payload_delivered = False

    def is_complete(self, arena):
        """Check if the objective is completed"""
        for robot in arena.robots:
            if robot.team == Team.BLUE and robot.position.distance_to(self.payload_position) < 5:
                # A blue team robot is carrying the payload
                if self.payload_position.distance_to(self.destination_position) < 5:
                    self.payload_delivered = True
                    return True
        return False


