class PowerUp:
    """Base class for power-ups"""
    def __init__(self, name, position, duration=10):
        self.name = name
        self.position = position
        self.duration = duration
        self.is_active = True
        self.activation_time = time.time()

    def update(self, arena):
        """Update power-up state"""
        if time.time() - self.activation_time > self.duration:
            self.is_active = False
            print(f"{self.name} power-up has expired.")

    def apply_effect(self, robot):
        """Apply the power-up effect to a robot"""
        pass


class HealthPack(PowerUp):
    """Power-up that restores health"""
    def __init__(self, position):
        super().__init__("Health Pack", position)

    def apply_effect(self, robot):
        """Restore health to the robot"""
        heal_amount = min(50, 100 - robot.health)
        robot.health += heal_amount
        print(f"{robot.name} used a Health Pack and gained {heal_amount} health!")


class SpeedBoost(PowerUp):
    """Power-up that increases movement speed"""
    def __init__(self, position):
        super().__init__("Speed Boost", position)

    def apply_effect(self, robot):
        """Increase the robot's movement speed temporarily"""
        robot._speed_multiplier = 1.5
        print(f"{robot.name} activated a Speed Boost!")


class ArmorBoost(PowerUp):
    """Power-up that increases armor/defense"""
    def __init__(self, position):
        super().__init__("Armor Boost", position)

    def apply_effect(self, robot):
        """Increase the robot's defense temporarily"""
        robot._armor_multiplier = 2
        print(f"{robot.name} activated an Armor Boost!")


class EnvironmentalHazard:
    """Base class for environmental hazards"""
    def __init__(self, name, position, radius, duration):
        self.name = name
        self.position = position
        self.radius = radius
        self.duration = duration
        self.is_active = True
        self.activation_time = time.time()

    def update(self, arena):
        """Update hazard state"""
        if time.time() - self.activation_time > self.duration:
            self.is_active = False
            print(f"{self.name} hazard has expired.")

    def affect_robots(self, arena):
        """Apply the hazard effect to robots in range"""
        for robot in arena.robots:
            if robot.is_alive() and self.position.distance_to(robot.position) <= self.radius:
                self._apply_damage(robot)

    @abstractmethod
    def _apply_damage(self, robot):
        """Apply damage to a robot affected by the hazard"""
        pass


class ToxicWaste(EnvironmentalHazard):
    """Environmental hazard that deals continuous damage"""
    def __init__(self, position):
        super().__init__("Toxic Waste", position, radius=15, duration=60)

    def _apply_damage(self, robot):
        """Deal continuous damage to affected robots"""
        damage = 2
        robot.health -= damage
        print(f"{robot.name} is taking {damage} damage from toxic waste!")


class EMPZone(EnvironmentalHazard):
    """Environmental hazard that disables weapons"""
    def __init__(self, position):
        super().__init__("EMP Zone", position, radius=20, duration=30)

    def _apply_damage(self, robot):
        """Disable robot's weapon temporarily"""
        if hasattr(robot, 'weapon') and robot.weapon:
            robot._weapon_disabled = True
            print(f"{robot.name}'s weapon was disabled by the EMP zone!")


