    """Power-up that restores health"""
    def __init__(self, position):
        super().__init__("Health Pack", position)

    def apply_effect(self, robot):
        """Restore health to the robot"""
        heal_amount = min(50, 100 - robot.health)
        robot.health += heal_amount
        print(f"{robot.name} used a Health Pack and gained {heal_amount} health!")


