import pandas as pd
import os
import json
from abc import ABC, abstractmethod

# ---------------------------
# DataFlowCoordinator System
# ---------------------------

class DataFlowStage:

    def __init__(self, name):
        self.name = name
        self.success = False
        self.message = """"

    @abstractmethod
    def execute(self, data):
        pass

    def is_successful(self):
        return self.success

# ---------------------------
# Data Ingestion Module
# ---------------------------

class DataIngestion(DataFlowStage):

    def __init__(self):
        super().__init__("Data Ingestion")
        self.supported_formats = ["csv", "xlsx", "db"]

    def execute(self, source, format):
        if format not in self.supported_formats:
            self.success = False
            self.message = f"Format {format} is not supported. Supported formats: {', '.join(self.supported_formats)}" 
            return None

        try:
            if format == "csv":
                data = pd.read_csv(source)
            elif format == "xlsx":
                data = pd.read_excel(source)
            elif format == "db":
                # Dummy DB ingestion
                data = pd.DataFrame(columns=["id", "name", "value"])
                data = data.append({"id": 1, "name": "Example", "value": "data"}, ignore_index=True)

            self.success = True
            self.message = f"{format.upper()} file ingested successfully." 
            return data
        except Exception as e:
            self.success = False
            self.message = f"Error during data ingestion: {str(e)}"
            return None

# ---------------------------
# Data Validation Module
# ---------------------------

class DataValidation(DataFlowStage):

    def __init__(self):
        super().__init__("Data Validation")

    def execute(self, data):
        if data is None or data.empty:
            self.success = False
            self.message = "Data is empty or not provided. Validation failed."
            return None

        try:
            # Check for completeness
            if data.isnull().values.any():
                self.message += "\n- Warning: Missing values found in the data." 

            # Check for consistency (e.g., data types)
            if not all(isinstance(val, (int, float, str)) for col in data.columns for val in data[col].values):
                self.message += "\n- Warning: Inconsistent data types found." 

            # Check for validity (e.g., numeric ranges or required fields)
            for col in data.columns:
                if data[col].dtype != "object" and (data[col].min() < 0):
                    self.message += f"\n- Warning: Negative values found in column {col}."

            self.success = True
            self.message += "\nData is valid and ready for transformation."
            return data
        except Exception as e:
            self.success = False
            self.message = f"Error during data validation: {str(e)}"
            return None

# ---------------------------
# Data Transformation Module
# ---------------------------

class DataTransformation(DataFlowStage):

    def __init__(self):
        super().__init__("Data Transformation")

    def execute(self, data):
        if data is None or not self.success:
            self.success = False
            self.message = "Data is invalid or not provided. Transformation failed."
            return None

        try:
            # Example transformation: Remove duplicates
            data = data.drop_duplicates()
            self.message += "\n- Removed duplicate rows."

            # Example transformation: Rearranged columns (alphabetically)
            data = data.reindex(sorted(data.columns), axis=1)
            self.message += "\n- Reordered columns alphabetically."

            # Example transformation: Change data type of a column to string
            data["id"] = data["id"].astype(str)
            self.message += "\n- Changed 'id' column to string type."

            self.success = True
            self.message += "\nData transformation completed successfully."
            return data
        except Exception as e:
            self.success = False
            self.message = f"Error during data transformation: {str(e)}"
            return None

# ---------------------------
# Data Export Module
# ---------------------------

class DataExport(DataFlowStage):

    def __init__(self):
        super().__init__("Data Export")
        self.supported_formats = ["csv", "xlsx", "db"]

    def execute(self, data, output_path, format):
        if data is None or not self.success:
            self.success = False
            self.message = "Data is invalid or not provided. Export failed."
            return None

        if format not in self.supported_formats:
            self.success = False
            self.message = f"Format {format} is not supported. Supported formats: {', '.join(self.supported_formats)}"
            return None

        try:
            if format == "csv":
                data.to_csv(output_path, index=False)
            elif format == "xlsx":
                data.to_excel(output_path, index=False)
            elif format == "db":
                # Dummy export to database
                pass

            self.success = True
            self.message = f"Data exported successfully in {format.upper()} format to {output_path}."
            return output_path
        except Exception as e:
            self.success = False
            self.message = f"Error during data export: {str(e)}"
            return None

# ---------------------------
# DataFlowCoordinator Orchestrator
# ---------------------------

class DataFlowCoordinator:

    def __init__(self):
        self.stages = {
            "ingestion": DataIngestion(),
            "validation": DataValidation(),
            "transformation": DataTransformation(),
            "export": DataExport()
        }

    def run_pipeline(self, source, source_format, output_path, output_format):
        data = self.stages["ingestion"].execute(source, source_format)
        if self.stages["ingestion"].is_successful():
            print(f"[INFO] {self.stages["ingestion"].message}")
            data = self.stages["validation"].execute(data)
            if self.stages["validation"].is_successful():
                print(f"[INFO] {self.stages["validation"].message}")
                data = self.stages["transformation"].execute(data)
                if self.stages["transformation"].is_successful():
                    print(f"[INFO] {self.stages["transformation"].message}")
                    self.stages["export"].execute(data, output_path, output_format)
                    if self.stages["export"].is_successful():
                        print(f"[INFO] {self.stages["export"].message}")
                    else:
                        print(f"[ERROR] {self.stages["export"].message}")
                else:
                    print(f"[ERROR] {self.stages["transformation"].message}")
            else:
                print(f"[ERROR] {self.stages["validation"].message}")
        else:
            print(f"[ERROR] {self.stages["ingestion"].message}")

# ---------------------------
# Example Usage
# ---------------------------

