        """Abstract method to ingest data from a source."""
        pass

class CSVIngestor(DataIngestor):
    def ingest_data(self, source_path: str) -> pd.DataFrame:
        if not os.path.exists(source_path):
            raise FileNotFoundError(f"CSV file not found at {source_path}")
        try:
            return pd.read_csv(source_path)
        except Exception as e:
            raise RuntimeError(f"Error reading CSV file: {e}") from e

