        if not os.path.exists(source_path):
            raise FileNotFoundError(f"Excel file not found at {source_path}")
        try:
            return pd.read_excel(source_path)
        except Exception as e:
            raise RuntimeError(f"Error reading Excel file: {e}") from e

class DatabaseIngestor(DataIngestor):
    def ingest_data(self, source_path: str) -> pd.DataFrame:
        # Placeholder for actual database connection logic
