# =============================
# Data Validation Module
# =============================

class DataValidator:
    def validate_data(self, data: pd.DataFrame, schema: Dict[str, Dict[str, Any]]) -> pd.DataFrame:
        """Validates the data based on the provided schema."""
        for col, rules in schema.items():
            if col not in data.columns:
                raise DataValidationError(f"Missing required column: {col}")

            if 'required' in rules and rules['required'] and data[col].isnull().any():
                raise DataValidationError(f"Column {col} contains missing values.")

            if 'data_type' in rules:
                expected_type = rules['data_type']
                if not pd.api.types.is_dtype_equal(data[col].dtype, pd.api.types.pandas_dtype(expected_type)):
                    raise DataValidationError(f"Column {col} has incorrect data type. Expected {expected_type}, got {data[col].dtype}")

            if 'unique' in rules and rules['unique'] and not data[col].is_unique:
                raise DataValidationError(f"Column {col} contains duplicate values.")

            if 'min' in rules:
                if (data[col] < rules['min']).any():
                    raise DataValidationError(f"Column {col} contains values below the minimum {rules['min']}.")

            if 'max' in rules:
                if (data[col] > rules['max']).any():
                    raise DataValidationError(f"Column {col} contains values above the maximum {rules['max']}.")

        return data

# =============================
# Data Transformation Module
# =============================

class DataTransformer:
    def apply_transformations(self, data: pd.DataFrame, transformations: List[Dict[str, Any]]) -> pd.DataFrame:
        """Applies transformation rules to the data."""
        for rule in transformations:
            if rule['operation'] == 'rename_column':
                data.rename(columns={rule['from']: rule['to']}, inplace=True)
            elif rule['operation'] == 'drop_column':
                data.drop(columns=[rule['column']], inplace=True)
            elif rule['operation'] == 'reorder_columns':
                data = data[rule['columns_order']]
            elif rule['operation'] == 'change_data_type':
                data[rule['column']] = data[rule['column']].astype(rule['data_type'])
            elif rule['operation'] == 'filter_rows':
                condition = rule['condition']
                data = data.query(condition)
            elif rule['operation'] == 'map_values':
                data[rule['column']] = data[rule['column']].map(rule['mapping'])
            elif rule['operation'] == 'fillna':
                data[rule['column']].fillna(rule['value'], inplace=True)
            elif rule['operation'] == 'remove_duplicates':
                data.drop_duplicates(subset=[rule['column']], inplace=True)
            elif rule['operation'] == 'merge_columns':
                data[rule['new_column_name']] = data[rule['columns']].apply(lambda row: ", ".join(row.values.astype(str)), axis=1)
            else:
                raise DataTransformationError(f"Unsupported transformation operation: {rule['operation']}")
        return data

# =============================
# Data Export Module
# =============================

class DataExporter(ABC):
    @abstractmethod
    def export_data(self, data: pd.DataFrame, output_path: str) -> str:
        """Abstract method to export data."""
        pass

class CSVExporter(DataExporter):
    def export_data(self, data: pd.DataFrame, output_path: str) -> str:
        try:
            data.to_csv(output_path, index=False)
            return f"Data successfully exported to CSV at {output_path}"
        except Exception as e:
            raise DataExportError(f"Error exporting CSV file: {e}") from e

class ExcelExporter(DataExporter):
    def export_data(self, data: pd.DataFrame, output_path: str) -> str:
        try:
            data.to_excel(output_path, index=False)
            return f"Data successfully exported to Excel at {output_path}"
        except Exception as e:
            raise DataExportError(f"Error exporting Excel file: {e}") from e

