MAX_HEALTH = 100
MAX_ENERGY = 200
ATTACK_COOLDOWN = 1.0  # seconds
MOVE_SPEED = 5.0  # units per second
VISION_RADIUS = 300  # units
TEAM_COLORS = ["red", "blue", "green", "yellow", "purple"]
WEAPON_TYPES = ["rifle", "laser", "plasma", "melee", "rocket"]
POWER_UP_TYPES = ["health", "shield", "speed", "energy", "damage_boost"]
HAZARD_TYPES = ["lava", "acid_pit", "electric_grid", "landmine", "explosive_barrel"]

# Define data classes for game entities
@dataclass
class Entity:
    id: str
    x: float
    y: float
    health: float
    energy: float
    team_color: str
    weapon_type: str

    def move(self, dx: float, dy: float, delta_time: float):
        self.x += dx * MOVE_SPEED * delta_time
        self.y += dy * MOVE_SPEED * delta_time

    def attack(self, target: "Entity", delta_time: float):
        if self.energy >= 10 and time.time() - self.last_attack_time >= ATTACK_COOLDOWN:
            damage = random.uniform(10, 20)
            target.health = max(0, target.health - damage)
            self.energy -= 10
            self.last_attack_time = time.time()

@dataclass
class PowerUp:
    id: str
    x: float
    y: float
    power_up_type: str

@dataclass
class Hazard:
    id: str
    x: float
    y: float
    hazard_type: str
    active: bool

@dataclass
class GameState:
    time: float
    entities: List[Entity]
    power_ups: List[PowerUp]
    hazards: List[Hazard]

# Game state management
@dataclass
class GameEngine:
    state: GameState

    def update(self, delta_time: float):
        # Move all entities
        for entity in self.state.entities:
            # Move entity (for simplicity, random movement)
            dx = random.uniform(-1, 1)
            dy = random.uniform(-1, 1)
            entity.move(dx, dy, delta_time)

            # Check for health regeneration
            if entity.health < MAX_HEALTH:
                entity.health = min(MAX_HEALTH, entity.health + 0.5 * delta_time)

            # Check for energy regeneration
            if entity.energy < MAX_ENERGY:
                entity.energy = min(MAX_ENERGY, entity.energy + 1.0 * delta_time)

            # Check for power ups
            for power_up in self.state.power_ups:
                if self._is_in_range(entity.x, entity.y, power_up.x, power_up.y, 10):
                    self._apply_power_up(entity, power_up)

            # Check for hazards
            for hazard in self.state.hazards:
                if self._is_in_range(entity.x, entity.y, hazard.x, hazard.y, 10) and hazard.active:
                    self._apply_hazard(entity, hazard)

    def _is_in_range(self, x1: float, y1: float, x2: float, y2: float, range: float):
        return np.sqrt((x1 - x2)**2 + (y1 - y2)**2) <= range

    def _apply_power_up(self, entity: Entity, power_up: PowerUp):
        if power_up.power_up_type == "health":
            entity.health = min(MAX_HEALTH, entity.health + 20)
        elif power_up.power_up_type == "shield":
            entity.health = min(MAX_HEALTH, entity.health + 30)
        elif power_up.power_up_type == "speed":
            entity.speed = min(15.0, entity.speed + 5.0)
        elif power_up.power_up_type == "energy":
            entity.energy = min(MAX_ENERGY, entity.energy + 30)
        elif power_up.power_up_type == "damage_boost":
            entity.damage = min(30.0, entity.damage + 10.0)

    def _apply_hazard(self, entity: Entity, hazard: Hazard):
        if hazard.hazard_type == "lava":
            entity.health = max(0, entity.health - 10 * entity.speed * 0.1)
        elif hazard.hazard_type == "acid_pit":
            entity.health = max(0, entity.health - 8 * entity.speed * 0.1)
        elif hazard.hazard_type == "electric_grid":
            entity.energy = max(0, entity.energy - 15 * entity.speed * 0.1)
        elif hazard.hazard_type == "landmine":
            if random.random() < 0.5:
                entity.health = max(0, entity.health - 40)
                hazard.active = False
        elif hazard.hazard_type == "explosive_barrel":
            if random.random() < 0.5:
                entity.health = max(0, entity.health - 50)
                hazard.active = False

# Simulation functions
def create_initial_game_state():
    entities = [
        Entity(id=str(uuid.uuid4()), x=random.uniform(0, SCREEN_WIDTH), y=random.uniform(0, SCREEN_HEIGHT), 
               health=MAX_HEALTH, energy=MAX_ENERGY, team_color=TEAM_COLORS[i % len(TEAM_COLORS)], 
               weapon_type=WEAPON_TYPES[i % len(WEAPON_TYPES)]) 
        for i in range(10)
    ]

    power_ups = [
        PowerUp(id=str(uuid.uuid4()), x=random.uniform(0, SCREEN_WIDTH), y=random.uniform(0, SCREEN_HEIGHT), 
                power_up_type=POWER_UP_TYPES[i % len(POWER_UP_TYPES)])
        for i in range(5)
    ]

    hazards = [
        Hazard(id=str(uuid.uuid4()), x=random.uniform(0, SCREEN_WIDTH), y=random.uniform(0, SCREEN_HEIGHT), 
               hazard_type=HAZARD_TYPES[i % len(HAZARD_TYPES)], active=True)
        for i in range(3)
    ]

    return GameState(time=0.0, entities=entities, power_ups=power_ups, hazards=hazards)

# Example usage
def main():
    game_state = create_initial_game_state()
    game_engine = GameEngine(state=game_state)

    # Simulate for 10 seconds
    simulation_time = 10.0
    start_time = time.time()
    elapsed_time = 0.0

    while elapsed_time < simulation_time:
        delta_time = 0.1  # 100ms per frame
        game_engine.update(delta_time)
        elapsed_time += delta_time

        # Print some metrics every second
        if time.time() - start_time >= 1.0:
            print(f"Time: {elapsed_time:.2f}s")
            for entity in game_engine.state.entities:
                print(f"Entity {entity.id} - Health: {entity.health:.1f}, Energy: {entity.energy:.1f}")
            start_time = time.time()

if __name__ == "__main__":
    main()"
}
