            ammo=random.randint(10, 50),
            max_ammo=random.randint(10, 50)
        )

    def move(self, target_position, speed=5.0):
        self.state = RobotState.MOVING
        dx = target_position.x - self.position.x
        dy = target_position.y - self.position.y
        distance = (dx**2 + dy**2)**0.5
        if distance > 0:
            self.velocity.dx = dx / distance * speed
            self.velocity.dy = dy / distance * speed
        else:
            self.velocity.dx = 0.0
            self.velocity.dy = 0.0
            self.state = RobotState.IDLE

