# User Registration and Authentication
@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')

    if not username or not password:
        return jsonify({"error": "Username and password are required"}), 400

    existing_user = mongo.db.users.find_one({"username": username})
    if existing_user:
        return jsonify({"error": "Username already exists"}), 400

    hashed_password = bcrypt.generate_password_hash(password).decode('utf-8')
    mongo.db.users.insert_one({"username": username, "password": hashed_password})
    return jsonify({"message": "User registered successfully"}), 201

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')

    user = mongo.db.users.find_one({"username": username})
    if not user or not bcrypt.check_password_hash(user['password'], password):
        return jsonify({"error": "Invalid username or password"}), 401

    session['user_id'] = str(user['_id'])
    return jsonify({"message": "Login successful", "user_id": str(user['_id'])}), 200

# Story Creation and Editing
@app.route('/create_story', methods=['POST'])
def create_story():
    if 'user_id' not in session:
        return jsonify({"error": "Authentication required"}), 401

    data = request.get_json()
    title = data.get('title')
    author_id = session['user_id']
    content = data.get('content', '')
    created_at = datetime.utcnow()

    story_id = mongo.db.stories.insert_one({
        "title": title,
        "author_id": author_id,
        "content": content,
        "history": [{"version": 1, "content": content, "timestamp": created_at}],
        "collaborators": [author_id],
        "created_at": created_at
    }).inserted_id

    return jsonify({"story_id": str(story_id), "message": "Story created"}), 201

@app.route('/get_story/<story_id>', methods=['GET'])
def get_story(story_id):
    story = mongo.db.stories.find_one({"_id": story_id})
    if not story:
        return jsonify({"error": "Story not found"}), 404

    return jsonify({
        "title": story['title'],
        "content": story['content'],
        "history": story['history'],
        "collaborators": story['collaborators']
    }), 200

# Real-Time Collaboration
@socketio.on('join_story')
def join_story(data):
    story_id = data.get('story_id')
    username = data.get('username')
    user_id = session.get('user_id')

    if not user_id:
        return

    story = mongo.db.stories.find_one({"_id": story_id})
    if not story or user_id not in story['collaborators']:
        return

    emit('story_content', {"content": story['content']}, room=story_id)
    emit('user_joined', {"username": username}, room=story_id)

@socketio.on('edit_story')
def edit_story(data):
    story_id = data.get('story_id')
    new_content = data.get('content')
    user_id = session.get('user_id')

    if not user_id:
        return

    story = mongo.db.stories.find_one({"_id": story_id})
    if not story or user_id not in story['collaborators']:
        return

    version = len(story['history']) + 1
    updated_at = datetime.utcnow()

    mongo.db.stories.update_one(
        {"_id": story_id},
        {
            "$set": {
                "content": new_content,
                "last_edited_at": updated_at
            },
            "$push": {
                "history": {
                    "version": version,
                    "content": new_content,
                    "timestamp": updated_at,
                    "user_id": user_id
                }
            }
        }
    )

    emit('update_content', {"content": new_content, "version": version, "user_id": user_id}, room=story_id)

# Version Control
@app.route('/get_story_version/<story_id>/<version>', methods=['GET'])
def get_story_version(story_id, version):
    story = mongo.db.stories.find_one({"_id": story_id})
    if not story:
        return jsonify({"error": "Story not found"}), 404
    try:
        version = int(version)
        for v in story['history']:
            if v['version'] == version:
                return jsonify({"content": v['content'], "timestamp": v['timestamp']})
        return jsonify({"error": "Version not found"}), 404
    except ValueError:
        return jsonify({"error": "Invalid version number"}), 400

# Community Gallery
@app.route('/gallery', methods=['GET'])
def gallery():
    stories = list(mongo.db.stories.find())
    formatted_stories = []
    for story in stories:
        if 'last_edited_at' in story:
            formatted_stories.append({
                "title": story['title'],
                "author_id": story['author_id'],
                "last_edited_at": story['last_edited_at'],
                "views": story.get('views', 0),
                "ratings": story.get('ratings', [])
            })
    return jsonify(formatted_stories), 200

@app.route('/rate_story/<story_id>', methods=['POST'])
def rate_story(story_id):
    data = request.get_json()
    rating = data.get('rating')
    user_id = session.get('user_id')

    if not user_id:
        return jsonify({"error": "Authentication required"}), 401

    if not (1 <= rating <= 5):
        return jsonify({"error": "Rating must be between 1 and 5"}), 400

    mongo.db.stories.update_one(
        {"_id": story_id},
        {"$push": {"ratings": {"user_id": user_id, "score": rating}}}
    )
    return jsonify({"message": "Story rated successfully"}), 200

