class CollaborativeStoryBuilder:
    def __init__(self):
        self.users = {}  # Dictionary of user_id -> User
        self.stories = {}  # Dictionary of story_id -> Story
        self.notifications = []  # List of notifications

    # 1. User Registration and Authentication
    def register_user(self, username: str, email: str, password: str) -> str:
        user_id = str(uuid.uuid4())
        self.users[user_id] = User(user_id, username, email, password)
        return user_id

