    def _create_version(self, story_id: str, version_number: int) -> Dict:
        return {
            'version_number': version_number,
            'timestamp': datetime.datetime.now(),
            'story_id': story_id,
            'content': self._get_story_content(story_id)
        }

    def _update_version(self, story_id: str) -> None:
        story = self.stories[story_id]
        latest_version = story.version_history[-1]['version_number']
        new_version = latest_version + 1
        story.version_history.append(self._create_version(story_id, new_version))

    def _get_story_content(self, story_id: str) -> str:
        story = self.stories[story_id]
        content = [f"Chapter {i+1}: {chapter.title}\n{chapter.content}\n\n" 
                   for i, chapter in enumerate(story.chapters)]
        return ''.join(content)

