    def move_to(self, new_pos: "Position", speed: float = 1.0) -> None:
        """Move robot towards a new position with given speed."""
        diff_x = new_pos.x - self.x
        diff_y = new_pos.y - self.y
        diff_z = new_pos.z - self.z
        distance = (diff_x**2 + diff_y**2 + diff_z**2)**0.5
        if distance > 0:
            move_factor = min(speed, distance)
            self.x += (diff_x / distance) * move_factor
            self.y += (diff_y / distance) * move_factor
            self.z += (diff_z / distance) * move_factor

    def distance_to(self, other: "Position") -> float:
        """Calculate Euclidean distance between positions."""
        return ((self.x - other.x)**2 + 
