class Vector2:
    """Represents a 2D vector for position, velocity, and other spatial calculations."""

    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vector2(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag > 0:
            return Vector2(self.x / mag, self.y / mag)
        return Vector2(0, 0)

    def distance_to(self, other):
        return ((self.x - other.x)**2 + (self.y - other.y)**2) ** 0.5

    def __repr__(self):
        return f"({self.x:.2f}, {self.y:.2f})"


class Weapon:
    """Base class for all weapons used by robots in CyberArena."""

    def __init__(self, name, damage, attack_speed, range):
        self.name = name
        self.damage = damage
        self.attack_speed = attack_speed  # attacks per second
        self.range = range  # maximum effective distance

    def calculate_damage(self, target_distance):
        """Calculate damage based on distance to target (diminishing effect for ranged weapons)."""
        if target_distance <= self.range:
            if target_distance == 0:
                return self.damage
            else:
                # Reduce damage based on distance from target
                return self.damage * (1 - (target_distance / self.range))
        else:
            return 0  # Out of range


