class FamilyMember:
    """Represents a family member's profile and progress."""

    def __init__(self, name: str):
        self.name = name
        self.assigned_quests = []
        self.completed_quests = []

    def assign_quest(self, quest):
        self.assigned_quests.append(quest)

    def complete_stage(self, quest_name: str, stage_index: int):
        for quest in self.assigned_quests:
            if quest['name'] == quest_name and stage_index < len(quest['stages']):
                quest['stages'][stage_index]['completed'] = True
                quest['stages'][stage_index]['completed_at'] = datetime.now().isoformat()
                if stage_index == len(quest['stages']) - 1:
                    self.completed_quests.append(quest)

    def get_progress(self):
        return {
            'name': self.name,
            'assigned_quests': self.assigned_quests,
            'completed_quests': self.completed_quests
        }

class QuestManager:
    """Manages quest assignment and progress tracking."""

    def __init__(self):
        self.family_members = []
        self.quests = []

    def add_family_member(self, member: FamilyMember):
        self.family_members.append(member)

    def assign_quest_to_member(self, member_name: str, quest):
        for member in self.family_members:
            if member.name == member_name:
                member.assign_quest(quest)
                return True
        return False

    def track_progress(self, member_name: str):
        for member in self.family_members:
            if member.name == member_name:
                return member.get_progress()
        return None

    def notify_next_stage(self, member_name: str, quest_name: str, stage_index: int):
