        """Update the entire arena state by the given time step"""
        self.time_elapsed += delta_time

        # Update all robots
        for robot in self.robots:
            if robot.is_alive():
                # Update strategy based on experience
                robot.update_strategy()

                # Update power-ups
                robot.update_power_ups(delta_time)

                # Apply hazard damage if robot is in a hazard area
                for hazard_data in self.hazards:
                    if hazard_data["active"]:
                        distance = np.linalg.norm(robot.position - hazard_data["position"])
                        if distance < 5.0:  # Within hazard range
                            robot.receive_damage(hazard_data["hazard"].apply_damage(robot))

        # Handle objective progress
        if self.objective:
            self._update_objective(delta_time)

        # Update power-up durations
        for power_up_data in self.power_ups[:]:
            power_up_data["time_remaining"] -= delta_time
            if power_up_data["time_remaining"] <= 0:
                self.power_ups.remove(power_up_data)  # Remove expired power-ups

