                self._update_experience(attack_success=False)

    def _calculate_attack_chance(self, distance):
        """Calculate the probability of a successful attack"""
        if distance > self.weapon.range:
            return 0.05  # Low chance for out-of-range attack
        elif distance < 1.0:  # Very close range
            return 0.95
        else:
            return 0.7  # Base chance for in-range attacks

    def _get_accuracy_bonus(self):
        """Calculate accuracy bonus based on robot's experience and role"""
        if self.role == RobotRole.ASSAULT:
            return int(self.experience * 0.1)
        elif self.role == RobotRole.SUPPORT:
            return int(self.experience * 0.05)
        return int(self.experience * 0.08)

    def _apply_damage_to_target(self, damage, target):
        """Apply damage to a target robot"""
        if target.shield > 0:
            shield_damage = min(damage, target.shield)
            damage -= shield_damage
            target.shield -= shield_damage

        armor_damage = min(damage, target.armor)
        damage -= armor_damage
        target.armor -= armor_damage

        if damage > 0:
            target.health -= damage

    def _update_experience(self, attack_success):
        """Update robot's experience based on attack outcome"""
        if attack_success:
            self.experience += 5
        else:
            self.experience += 1  # Still gain some experience from failed attacks

    def update_strategy(self):
        """Update strategy based on current situation and experience"""
        if self.experience > 100 and self.role == RobotRole.ASSAULT:
            self.strategy = "flanking"
        elif self.experience > 50 and self.role == RobotRole.SUPPORT:
            self.strategy = "healing"
        elif self.experience > 80 and self.role == RobotRole.TANK:
            self.strategy = "frontline"
        else:
            self.strategy = "default"

    def apply_power_up(self, power_up):
        """Apply a power-up to the robot"""
        self.power_ups.append(power_up)
        power_up.apply_effect(self)

    def remove_power_up(self, power_up):
        """Remove a power-up from the robot"""
        if power_up in self.power_ups:
            self.power_ups.remove(power_up)
            power_up.remove_effect(self)

    def update_power_ups(self, delta_time):
        """Update power-up durations and remove expired ones"""
        for power_up in self.power_ups[:]:
            power_up.duration -= delta_time
            if power_up.duration <= 0:
                self.remove_power_up(power_up)

    def receive_damage(self, damage):
        """Receive damage from an external source (like hazards)"""
        if self.shield > 0:
            shield_damage = min(damage, self.shield)
            damage -= shield_damage
            self.shield -= shield_damage

        armor_damage = min(damage, self.armor)
        damage -= armor_damage
        self.armor -= armor_damage

        if damage > 0:
            self.health -= damage

    def is_alive(self):
        """Check if the robot is still operational"""
        return self.health > 0

class CyberArena:
    def __init__(self, width=100.0, height=100.0):
        self.width = width
        self.height = height
        self.robots = []
        self.power_ups = []
        self.hazards = []
        self.objective = None
        self.score = {Team.RED: 0, Team.BLUE: 0}
        self.time_elapsed = 0.0
        self.difficulty_level = 1  # Starting difficulty level

    def add_robot(self, robot):
        """Add a robot to the arena"""
        self.robots.append(robot)

    def add_power_up(self, power_up, position):
        """Add a power-up to the arena at a specific position"""
        self.power_ups.append({"power_up": power_up, "position": np.array(position), "time_remaining": 30.0})

    def add_hazard(self, hazard, position):
        """Add a hazard to the arena at a specific position"""
        self.hazards.append({"hazard": hazard, "position": np.array(position), "active": True})

    def set_objective(self, objective_type, target_position):
        """Set the current objective for the battle"""
        self.objective = {
            "type": objective_type,
            "target_position": np.array(target_position),
            "progress": 0.0,
            "owner": None
        }

    def update(self, delta_time):
        """Update the entire arena state by the given time step"""
        self.time_elapsed += delta_time

        # Update all robots
        for robot in self.robots:
            if robot.is_alive():
                # Update strategy based on experience
                robot.update_strategy()

                # Update power-ups
                robot.update_power_ups(delta_time)

                # Apply hazard damage if robot is in a hazard area
                for hazard_data in self.hazards:
                    if hazard_data["active"]:
                        distance = np.linalg.norm(robot.position - hazard_data["position"])
                        if distance < 5.0:  # Within hazard range
                            robot.receive_damage(hazard_data["hazard"].apply_damage(robot))

        # Handle objective progress
        if self.objective:
            self._update_objective(delta_time)

        # Update power-up durations
        for power_up_data in self.power_ups[:]:
            power_up_data["time_remaining"] -= delta_time
            if power_up_data["time_remaining"] <= 0:
                self.power_ups.remove(power_up_data)  # Remove expired power-ups

        # Adjust difficulty based on performance
        self._adjust_difficulty()

    def _update_objective(self, delta_time):
        """Update progress toward the current objective"""
        if self.objective["type"] == ObjectiveType.CAPTURE_FLAG:
            # For each robot on the correct team near the target
            for robot in self.robots:
                if robot.team == Team.RED and self.objective["owner"] != Team.RED:
                    distance = np.linalg.norm(robot.position - self.objective["target_position"])
                    if distance < 5.0:
                        self.objective["progress"] += 0.1 * delta_time
                        if self.objective["progress"] >= 1.0:
                            self._complete_objective(Team.RED)
                elif robot.team == Team.BLUE and self.objective["owner"] != Team.BLUE:
                    distance = np.linalg.norm(robot.position - self.objective["target_position"])
                    if distance < 5.0:
                        self.objective["progress"] += 0.1 * delta_time
                        if self.objective["progress"] >= 1.0:
                            self._complete_objective(Team.BLUE)

    def _complete_objective(self, winning_team):
        """Handle the completion of an objective"""
        self.score[winning_team] += 100  # Score points for completing objective
        self.objective["owner"] = winning_team
        self.objective["progress"] = 1.0

        # Trigger visual/audio feedback
        self._trigger_feedback(winning_team)

        # Reset objective after a while
        self._schedule_objective_reset()

    def _trigger_feedback(self, winning_team):
        """Trigger visual and audio feedback for objective completion"""
        # In a real implementation, this would trigger actual visual and audio effects
        print(f"🎯 Objective completed by {winning_team.value} team!")

    def _schedule_objective_reset(self):
        """Schedule the objective to reset after a certain time"""
        pass  # Would be implemented with actual timing in a game engine

    def _adjust_difficulty(self):
        """Adjust the difficulty based on the robots' performance"""
        # Calculate average performance
        living_robots = [robot for robot in self.robots if robot.is_alive()]
        if not living_robots:
            return

        avg_health = sum(robot.health for robot in living_robots) / len(living_robots)
        avg_energy = sum(robot.energy for robot in living_robots) / len(living_robots)

        # Adjust difficulty based on performance
        if avg_health > 80 and avg_energy > 80:
            # Robots are performing well, increase difficulty
            self.difficulty_level += 1
            self._increase_ai_difficulty()
            self._add_more_hazards()
        elif avg_health < 30 or avg_energy < 20:
            # Robots are struggling, decrease difficulty
            self.difficulty_level = max(1, self.difficulty_level - 1)
            self._decrease_ai_difficulty()
            self._remove_hazards()

    def _increase_ai_difficulty(self):
        """Increase AI difficulty by making robots more aggressive and accurate"""
        for robot in self.robots:
            if robot.is_alive():
                robot.attack_speed *= 1.1
                robot.weapon.base_damage = int(robot.weapon.base_damage * 1.1)

    def _decrease_ai_difficulty(self):
        """Decrease AI difficulty by making robots less aggressive and accurate"""
        for robot in self.robots:
            if robot.is_alive():
                robot.attack_speed /= 1.1
                robot.weapon.base_damage = int(robot.weapon.base_damage / 1.1)

    def _add_more_hazards(self):
        """Add more hazards to increase challenge"""
        if self.difficulty_level % 2 == 0:
            for _ in range(2):
                hazard = Hazard("Lava", 5)
                position = np.array([random.uniform(5.0, self.width - 5.0), random.uniform(5.0, self.height - 5.0)])
                self.add_hazard(hazard, position)

    def _remove_hazards(self):
        """Remove some hazards to decrease challenge"""
        if len(self.hazards) > 2:
            # Remove half of the hazards
            remaining_hazards = self.hazards[:len(self.hazards)//2]
            self.hazards = remaining_hazards

    def get_robot_by_name(self, name):
        """Find a robot by name"""
        for robot in self.robots:
            if robot.name == name:
                return robot
        return None

    def get_team_score(self, team):
        """Get the current score for a team"""
        return self.score.get(team, 0)

