# CyberArena - A futuristic multi-agent battle arena simulation

import random
import time
from enum import Enum
import numpy as np
from collections import deque

class Team(Enum):
    RED = "Red"
    BLUE = "Blue"

class WeaponType(Enum):
    LASER = "Laser"
    PLASMA = "Plasma"
    KINETIC = "Kinetic"
    SHOCK = "Shock"

class RobotRole(Enum):
    TANK = "Tank"
    ASSAULT = "Assault"
    SUPPORT = "Support"
    SABOTEUR = "Saboteur"

class ObjectiveType(Enum):
    CAPTURE_FLAG = "Capture Flag"
    DEFEND_BASE = "Defend Base"
    ESCORT_PAYLOAD = "Escort Payload"

class Weapon:
    def __init__(self, weapon_type, damage, range, energy_cost):
        self.type = weapon_type
        self.base_damage = damage
        self.range = range  # In meters
        self.energy_cost = energy_cost  # Energy units per shot

    def calculate_damage(self, distance, accuracy_bonus=0):
        """Calculate damage based on distance and accuracy bonus"""
        if distance > self.range:
            return 0  # Out of range
        # Adjust damage based on distance (higher damage at close range)
        distance_factor = 1 - (distance / self.range)
        return int(self.base_damage * distance_factor) + accuracy_bonus

class PowerUp:
    def __init__(self, power_type, duration):
        self.type = power_type
        self.duration = duration  # In seconds

    def apply_effect(self, robot):
        """Apply the power-up effect to the robot"""
        if self.type == "Shield":
            robot.shield = 100
