# ========================
# BASE CLASSES AND ENUMS
# ========================

class Team(Enum):
    RED = "Red Team"
    BLUE = "Blue Team"
    NEUTRAL = "Neutral"

class WeaponType(Enum):
    RANGED = "Ranged"
