    score_increment: int = 100
    adaptive_difficulty_threshold: float = 0.7  # win rate threshold for difficulty adjustment

# ========================
# WEAPON CLASS
# ========================

class Weapon:
    def __init__(self, name: str, weapon_type: WeaponType, damage: float, 
                 special_effect: Optional[Dict] = None):
        self.name = name
        self.type = weapon_type
        self.damage = damage
        self.special_effect = special_effect or {}

    def __str__(self):
        return self.name

# ========================
# ROBOT CLASS
# ========================

class Robot:
    def __init__(self, name: str, team: Team, position: Tuple[float, float], 
                 health: float = 100.0, speed: float = 5.0, 
                 weapon: Optional[Weapon] = None):
        self.id = str(uuid.uuid4())
        self.name = name
        self.team = team
        self.position = np.array(position, dtype=float)
        self.health = health
        self.max_health = health
        self.speed = speed
        self.weapon = weapon
        self.status = RobotStatus.ACTIVE
        self.cooldown_timer = 0.0
        self.power_ups = {}  # {PowerUp: end_time}
        self.objective = None  # current objective
        self.objective_progress = 0.0
        self.score = 0
        self.battle_history = []  # list of battle outcomes
        self.strategy = {}  # learned strategy parameters
        self.last_action_time = time.time()

    def move(self, target_position: Tuple[float, float], dt: float):
        """Move robot towards target position with smooth interpolation"""
        if self.status != RobotStatus.ACTIVE:
            return
        direction = np.array(target_position) - self.position
        distance = np.linalg.norm(direction)
        if distance > 0:
            direction = direction / distance
            self.position += direction * self.speed * dt
            if distance < 0.1:  # close enough to target
                self.position = np.array(target_position)
                return True
        return False

    def attack(self, target: "Robot", game_config: GameConfig) -> bool:
        """Attempt to attack a target robot"""
        if self.status != RobotStatus.ACTIVE or self.cooldown_timer > 0:
            return False

        distance = np.linalg.norm(self.position - target.position)

        if self.weapon.type == WeaponType.MELEE and distance > game_config.melee_range:
            return False  # out of melee range

        if self.weapon.type == WeaponType.RANGED and distance < game_config.melee_range:
            adjusted_damage = self.weapon.damage * game_config.ranged_damage_multiplier
        else:
            adjusted_damage = self.weapon.damage

        # Apply power-up modifiers
        if PowerUp.DAMAGE_AMPLIFIER in self.power_ups:
            adjusted_damage *= 1.5

        # Apply shield defense
        if PowerUp.SHIELD in target.power_ups:
            adjusted_damage *= 0.5

        # Apply the damage
        target.health -= adjusted_damage
        if target.health <= 0:
            target.status = RobotStatus.DESTROYED
            self.score += game_config.score_increment

        # Record the battle
        self.battle_history.append({
            'target': target.id,
            'damage': adjusted_damage,
            'success': target.health <= 0
        })

        # Set cooldown
        self.cooldown_timer = game_config.weapon_cooldown
        return True

    def use_power_up(self, power_up: PowerUp, game_config: GameConfig):
        """Activate a power-up effect"""
        if power_up not in self.power_ups:
            return False
        end_time = self.power_ups[power_up]
        if time.time() < end_time:
            # Apply effect
            if power_up == PowerUp.SHIELD:
                self.health = min(self.health + 20, self.max_health)
            elif power_up == PowerUp.SPEED_BOOST:
                self.speed *= 1.5
                self.power_ups[power_up] = time.time() + game_config.power_up_duration
            elif power_up == PowerUp.DAMAGE_AMPLIFIER:
                pass  # already applied in attack
            elif power_up == PowerUp.TEAM_HEAL:
                # Heal nearby team members
                for robot in get_nearby_robots(self, team=self.team):
                    robot.health = min(robot.health + 15, robot.max_health)
        return True

    def apply_power_ups(self):
        """Apply active power-up effects"""
        current_time = time.time()
        power_ups_to_remove = []
        for power_up, end_time in self.power_ups.items():
            if current_time >= end_time:
                power_ups_to_remove.append(power_up)
            else:
                # Apply ongoing effects
                if power_up == PowerUp.SPEED_BOOST:
                    self.speed = self.speed * 0.8 + 2.0  # gradual decay
                elif power_up == PowerUp.DAMAGE_AMPLIFIER:
                    pass  # already applied in attack
        for power_up in power_ups_to_remove:
            del self.power_ups[power_up]

    def recharge(self, game_config: GameConfig):
        """Recharge after being destroyed"""
        if self.status == RobotStatus.DESTROYED:
            if time.time() - self.last_action_time > game_config.recharging_time:
                self.status = RobotStatus.ACTIVE
                self.health = self.max_health
                self.position = self.get_default_spawn_position()

    def get_default_spawn_position(self) -> Tuple[float, float]:
        """Get default spawn position based on team"""
        if self.team == Team.RED:
            return (10, 10)
        elif self.team == Team.BLUE:
            return (90, 90)
        else:  # Neutral
            return (50, 50)

    def update(self, dt: float, game_config: GameConfig):
        """Update robot state"""
        # Apply power-up effects
        self.apply_power_ups()

        # Update cooldown timer
        if self.cooldown_timer > 0:
            self.cooldown_timer -= dt

        # Recharge if necessary
        self.recharge(game_config)

# ========================
