# ========================

class TeamManager:
    def __init__(self, game_config: GameConfig):
        self.teams = {Team.RED: [], Team.BLUE: []}
        self.config = game_config
        self.team_scores = {Team.RED: 0, Team.BLUE: 0}
        self.team_objectives = {}  # {Team: Objective}
        self.difficulty_level = 1.0  # 1.0 = normal, <1.0 = easier, >1.0 = harder

    def add_robot(self, robot: Robot):
        """Add a robot to its team"""
        if robot.team in [Team.RED, Team.BLUE]:
            self.teams[robot.team].append(robot)

    def assign_objectives(self):
        """Assign objectives to teams based on game mode"""
        for team in [Team.RED, Team.BLUE]:
            if self.team_objectives.get(team) is None:
                # Randomly assign an objective
                objectives = list(Objective)
                self.team_objectives[team] = random.choice(objectives)
                # Set robot roles based on objective
                self.assign_robot_roles(team)

    def assign_robot_roles(self, team: Team):
        """Assign specific roles to robots based on team objective"""
        if self.team_objectives[team] == Objective.CAPTURE_FLAG:
            # Assign a flag carrier and scouts
            for i, robot in enumerate(self.teams[team]):
                if i == 0:
                    robot.objective = "Carry Flag"
                else:
                    robot.objective = "Scout"
        elif self.team_objectives[team] == Objective.DEFEND_BASE:
            # Assign guards and support
            for i, robot in enumerate(self.teams[team]):
                if i < 2:
                    robot.objective = "Guard Base"
                else:
                    robot.objective = "Support"
        elif self.team_objectives[team] == Objective.ESCEORT_PAYLOAD:
            # Assign a leader and assistants
            for i, robot in enumerate(self.teams[team]):
                if i == 0:
                    robot.objective = "Lead Escort"
                else:
                    robot.objective = "Follow Escort"

    def update_team_ai(self, game_config: GameConfig):
        """Update team AI based on current game state"""
        # Adaptive difficulty adjustment
        red_win_rate = self.calculate_win_rate(Team.RED)
        blue_win_rate = self.calculate_win_rate(Team.BLUE)

        # Adjust difficulty if necessary
        if red_win_rate > game_config.adaptive_difficulty_threshold:
            self.difficulty_level = min(1.5, self.difficulty_level + 0.1)
        elif red_win_rate < (1 - game_config.adaptive_difficulty_threshold):
            self.difficulty_level = max(0.5, self.difficulty_level - 0.1)

        if blue_win_rate > game_config.adaptive_difficulty_threshold:
            self.difficulty_level = min(1.5, self.difficulty_level + 0.1)
        elif blue_win_rate < (1 - game_config.adaptive_difficulty_threshold):
            self.difficulty_level = max(0.5, self.difficulty_level - 0.1)

        # Update team strategies based on battle history
        for team in [Team.RED, Team.BLUE]:
            team_robots = self.teams[team]
            if team_robots:
                # Calculate average battle effectiveness
                total_damage = sum(len(r.battle_history) for r in team_robots)
                total_actions = sum(1 for r in team_robots for b in r.battle_history if b['success'])

                if total_actions > 0:
                    effectiveness = total_actions / total_damage
                    # Update team strategy based on effectiveness
                    if effectiveness > 0.7:
                        # Emphasize offensive strategy
                        for robot in team_robots:
                            robot.strategy = {"aggressiveness": 0.8}
                    else:
                        # Emphasize defensive strategy
                        for robot in team_robots:
                            robot.strategy = {"defensiveness": 0.8}

    def calculate_win_rate(self, team: Team) -> float:
        """Calculate win rate for a team based on battle history"""
        total_battles = 0
        successful_battles = 0

        for robot in self.teams[team]:
            for battle in robot.battle_history:
                total_battles += 1
                if battle['success']:
                    successful_battles += 1

        return successful_battles / total_battles if total_battles > 0 else 0.5

    def update_team_scores(self):
        """Update team scores based on robot scores"""
        for team in [Team.RED, Team.BLUE]:
            self.team_scores[team] = sum(robot.score for robot in self.teams[team])

# ========================
# ARENA AND ENVIRONMENT
# ========================

class Arena:
    def __init__(self, game_config: GameConfig):
        self.game_config = game_config
        self.robots = []
        self.power_ups = []  # list of active power-ups
        self.hazards = []  # list of active hazards
        self.team_manager = TeamManager(game_config)
        self.game_time = 0.0
        self.battle_events = []  # list of battle events for replay
        self.objective_status = {}  # {Objective: status}

    def add_robot(self, robot: Robot):
        """Add a robot to the arena"""
        self.robots.append(robot)
        self.team_manager.add_robot(robot)

    def add_power_up(self, power_up: PowerUp, position: Tuple[float, float], duration: float):
        """Add a power-up to the arena"""
        self.power_ups.append({
            'type': power_up,
            'position': np.array(position, dtype=float),
            'duration': duration,
            'end_time': time.time() + duration
        })

    def add_hazard(self, hazard: Hazard, position: Tuple[float, float], duration: float):
        """Add a hazard to the arena"""
        self.hazards.append({
            'type': hazard,
            'position': np.array(position, dtype=float),
            'duration': duration,
            'end_time': time.time() + duration
        })

    def check_power_ups(self):
        """Check for available power-ups and apply them to robots"""
        current_time = time.time()
        power_ups_to_remove = []
        for power_up in self.power_ups:
            if current_time >= power_up['end_time']:
                power_ups_to_remove.append(power_up)
                continue

            # Check if any robot is near the power-up
            for robot in self.robots:
                distance = np.linalg.norm(robot.position - power_up['position'])
                if distance < 3.0:  # pickup range
                    robot.power_ups[power_up['type']] = power_up['end_time']
                    power_ups_to_remove.append(power_up)
                    break
        for power_up in power_ups_to_remove:
            self.power_ups.remove(power_up)

    def check_hazards(self):
        """Check for hazards and apply their effects"""
        current_time = time.time()
        hazards_to_remove = []
        for hazard in self.hazards:
            if current_time >= hazard['end_time']:
                hazards_to_remove.append(hazard)
                continue

            # Apply hazard effect to robots in range
            for robot in self.robots:
                distance = np.linalg.norm(robot.position - hazard['position'])
                if distance < 5.0 and hazard['type'] == Hazard.LASER_GRID:
                    robot.health -= 5
                    if robot.health <= 0:
                        robot.status = RobotStatus.DESTROYED
                elif distance < 3.0 and hazard['type'] in [Hazard.TRIPWIRE, Hazard.EMP_ZONE]:
                    robot.speed = max(robot.speed * 0.5, 1.0)  # reduce speed
        for hazard in hazards_to_remove:
            self.hazards.remove(hazard)

    def update(self, dt: float):
        """Update the arena state"""
        self.game_time += dt

        # Update all robots
        for robot in self.robots:
            robot.update(dt, self.game_config)

        # Check for power-ups and hazards
        self.check_power_ups()
        self.check_hazards()

        # Update team AI and strategies
        self.team_manager.update_team_ai(self.game_config)

        # Update team scores
        self.team_manager.update_team_scores()

        # Record battle events
        for robot in self.robots:
            if robot.battle_history:
                self.battle_events.append({
                    'robot': robot.id,
                    'timestamp': time.time(),
                    'action': "Attack",
                    'target': robot.battle_history[-1]['target'],
                    'damage': robot.battle_history[-1]['damage'],
                    'success': robot.battle_history[-1]['success']
                })

        # Check for objective completion
        self.check_objective_completion()

    def check_objective_completion(self):
        """Check if any team has completed their objective"""
        for team in [Team.RED, Team.BLUE]:
            objective = self.team_manager.team_objectives.get(team)
            if objective == Objective.CAPTURE_FLAG:
                # Check if any robot has captured the flag
                flag_position = np.array((50, 50))  # flag position
                for robot in self.teams[team]:
                    distance = np.linalg.norm(robot.position - flag_position)
                    if distance < 2.0:
                        # Objective completed
                        self.team_manager.team_scores[team] += self.game_config.score_increment
                        self.objective_status[objective] = "Completed"
                        self.spawn_power_ups()
                        break
            elif objective == Objective.DEFEND_BASE:
                # Check if base is under attack
                base_position = np.array((10, 10) if team == Team.RED else (90, 90))
                for robot in self.teams[team]:
                    distance = np.linalg.norm(robot.position - base_position)
                    if distance > 10.0:
                        # Base is under threat
                        self.objective_status[objective] = "Threatened"
                # Check if base is destroyed
                if self.objective_status.get(objective) == "Threatened" and len(self.team_manager.teams[team]) < 2:
                    self.objective_status[objective] = "Failed"
            elif objective == Objective.ESCORT_PAYLOAD:
                # Check if payload is being escorted to destination
                payload_position = np.array((90, 10) if team == Team.RED else (10, 90))
                for robot in self.teams[team]:
                    if robot.objective == "Lead Escort":
                        distance = np.linalg.norm(robot.position - payload_position)
