                            # Objective completed
                            self.team_manager.team_scores[team] += self.game_config.score_increment
                            self.objective_status[objective] = "Completed"
                            self.spawn_power_ups()
                            break

    def spawn_power_ups(self):
        """Randomly spawn new power-ups after an objective is completed"""
        power_ups_to_spawn = random.choices(list(PowerUp), k=min(3, self.game_config.max_robots_per_team))
        for power_up in power_ups_to_spawn:
