            y = random.uniform(0, self.game_config.arena_size[1])
            self.add_power_up(power_up, (x, y), self.game_config.power_up_duration)

    def get_game_state(self) -> dict:
        """Return current game state as a dictionary"""
        return {
            "robots": [r.__dict__ for r in self.robots],
            "team_scores": self.team_manager.team_scores,
