        for team in [Team.RED, Team.BLUE]:
            team_robots = self.teams[team]
            if team_robots:
                # Calculate average battle effectiveness
                total_damage = sum(len(r.battle_history) for r in team_robots)
                total_actions = sum(1 for r in team_robots for b in r.battle_history if b['success'])

                if total_actions > 0:
                    effectiveness = total_actions / total_damage
                    # Update team strategy based on effectiveness
                    if effectiveness > 0.7:
