class GameEngine:
    def __init__(self, game_config: GameConfig):
        self.game_config = game_config
        self.arena = Arena(game_config)
        self.is_running = False
        self.thread = None
        self.update_rate = 0.016  # ~60 FPS
        self.last_update_time = time.time()

    def start(self):
        """Start the game simulation"""
        if self.is_running:
            return

        # Create initial teams and robots
        self.create_robots()
        self.arena.team_manager.assign_objectives()

        # Add some initial power-ups and hazards
        self.spawn_initial_power_ups()
        self.spawn_initial_hazards()

        # Start the game loop thread
        self.is_running = True
        self.thread = threading.Thread(target=self.game_loop)
        self.thread.start()

    def stop(self):
        """Stop the game simulation"""
        if not self.is_running:
            return
        self.is_running = False
        self.thread.join()

    def create_robots(self):
        """Create and add robots to the arena"""
        # Create red team robots
        for i in range(self.game_config.max_robots_per_team):
            name = f"Red Bot {i+1}"
            weapon = Weapon(f"Red WP{i+1}", WeaponType.RANGED, 20.0)
            robot = Robot(name, Team.RED, (10 + i*5, 10), weapon=weapon)
            self.arena.add_robot(robot)

        # Create blue team robots
        for i in range(self.game_config.max_robots_per_team):
            name = f"Blue Bot {i+1}"
            weapon = Weapon(f"Blue WP{i+1}", WeaponType.MELEE, 15.0)
            robot = Robot(name, Team.BLUE, (90 - i*5, 90), weapon=weapon)
            self.arena.add_robot(robot)

    def spawn_initial_power_ups(self):
        """Spawn initial power-ups in the arena"""
        for power_up in PowerUp:
            x = random.uniform(0, self.game_config.arena_size[0])
            y = random.uniform(0, self.game_config.arena_size[1])
            self.arena.add_power_up(power_up, (x, y), self.game_config.power_up_duration)

    def spawn_initial_hazards(self):
        """Spawn initial hazards in the arena"""
        for hazard in Hazard:
            x = random.uniform(0, self.game_config.arena_size[0])
            y = random.uniform(0, self.game_config.arena_size[1])
            self.arena.add_hazard(hazard, (x, y), self.game_config.power_up_duration)

    def game_loop(self):
        """Main game loop"""
        while self.is_running:
            current_time = time.time()
            dt = current_time - self.last_update_time
            self.last_update_time = current_time

            if dt > 0:
                self.arena.update(dt)

            # Check for end conditions (score limit or time limit)
            if self.arena.team_manager.team_scores[Team.RED] >= 1000 or \
               self.arena.team_manager.team_scores[Team.BLUE] >= 1000 or \
               self.arena.game_time >= 600:  # 10 minutes
                self.is_running = False

            time.sleep(self.update_rate)

    def get_game_state(self) -> dict:
        """Get current game state"""
        return self.arena.get_game_state()

    def get_team_scores(self) -> dict:
        """Get current team scores"""
        return self.arena.team_manager.team_scores

    def get_battle_events(self, count: int = 100) -> List[dict]:
        """Get recent battle events"""
        return self.arena.battle_events[-count:]

