        for robot in self.robots:
            if robot.battle_history:
                self.battle_events.append({
                    'robot': robot.id,
                    'timestamp': time.time(),
                    'action': "Attack",
                    'target': robot.battle_history[-1]['target'],
                    'damage': robot.battle_history[-1]['damage'],
                    'success': robot.battle_history[-1]['success']
                })

        # Check for objective completion
        self.check_objective_completion()

    def check_objective_completion(self):
        """Check if any team has completed their objective"""
        for team in [Team.RED, Team.BLUE]:
