from dataclasses import dataclass
from datetime import datetime, timedelta
from typing import List, Dict, Optional
import uuid
import json
import threading
import time
import smtplib
from email.mime.text import MIMEText
from email.mime.multipart import MIMEMultipart


# =============================
# USER AUTHENTICATION
# =============================
class User:
    def __init__(self, user_id: str, name: str, email: str, password: str):
        self.user_id = user_id
        self.name = name
        self.email = email
        self.password = password
        self.groups = []

    def create_group(self, group_name: str, objective: str, target_amount: float, deadline: datetime):
        group = Group(group_id=str(uuid.uuid4()), name=group_name, objective=objective,
                      target_amount=target_amount, deadline=deadline, created_by=self)
        self.groups.append(group)
        return group

    def join_group(self, group):
        if self not in group.members:
            group.add_member(self)
            self.groups.append(group)


# =============================
# GROUP AND GOAL MANAGEMENT
# =============================
class Group:
    def __init__(self, group_id: str, name: str, objective: str, target_amount: float, deadline: datetime, created_by: User):
        self.group_id = group_id
        self.name = name
        self.objective = objective
        self.target_amount = target_amount
        self.deadline = deadline
        self.created_by = created_by
        self.members: List[User] = [created_by]
        self.contributions: Dict[str, float] = {created_by.user_id: 0}
        self.milestones: List[float] = []
        self.notifications = []

    def add_member(self, user: User):
        self.members.append(user)
        self.contributions[user.user_id] = 0

    def add_contribution(self, user_id: str, amount: float):
        if user_id in self.contributions:
            self.contributions[user_id] += amount
        else:
            raise ValueError("User not a member of this group.")

    def add_milestone(self, milestone_amount: float):
        self.milestones.append(milestone_amount)
        self.milestones.sort()

    def check_progress(self):
        total_contributed = sum(self.contributions.values())
        return {
            "total_contributed": total_contributed,
            "target_amount": self.target_amount,
            "progress_percentage": (total_contributed / self.target_amount) * 100 if self.target_amount > 0 else 0,
            "remaining_amount": self.target_amount - total_contributed
        }

    def set_notification(self, message: str):
        self.notifications.append({"message": message, "timestamp": datetime.now()})


# =============================
# NOTIFICATION SYSTEM
# =============================
class NotificationService:
    def __init__(self):
        self.notifications = []

    def send_email(self, email: str, subject: str, body: str):
        try:
            msg = MIMEMultipart()
            msg["From"] = "financialcollaborator@example.com"
            msg["To"] = email
            msg["Subject"] = subject
            msg.attach(MIMEText(body, "plain"))

            # Simulate sending email
            print(f"Email sent to {email}: {subject}")
            self.notifications.append({"email": email, "subject": subject, "body": body})
        except Exception as e:
            print(f"Error sending email to {email}: {e}")

    def alert_milestone(self, group: Group, milestone: float):
        total = sum(group.contributions.values())
        if total >= milestone:
            for member in group.members:
                self.send_email(member.email, "Milestone Reached!", f"The group '{group.name}' has reached a milestone of ${milestone}!")

    def alert_deadline(self, group: Group):
        now = datetime.now()
        if now >= group.deadline:
            for member in group.members:
                self.send_email(member.email, "Deadline Alert!", f"The deadline for the group '{group.name}' is due today!")

    def alert_budget_deviation(self, group: Group):
        total_contributed = sum(group.contributions.values())
        if total_contributed > group.target_amount:
            for member in group.members:
                self.send_email(member.email, "Budget Deviation Alert!", f"The group '{group.name}' has exceeded the target amount of ${group.target_amount}!")


# =============================
# CHAT FEATURE
# =============================
class ChatMessage:
    def __init__(self, message_id: str, sender_id: str, content: str, timestamp: datetime):
        self.message_id = message_id
        self.sender_id = sender_id
        self.content = content
        self.timestamp = timestamp


class ChatService:
    def __init__(self):
        self.messages: Dict[str, List[ChatMessage]] = {}

    def send_message(self, group_id: str, user_id: str, content: str):
        if group_id not in self.messages:
            self.messages[group_id] = []
        message_id = str(uuid.uuid4())
        message = ChatMessage(message_id, user_id, content, datetime.now())
        self.messages[group_id].append(message)
        print(f"User {user_id} sent a message to group {group_id}.")

    def get_messages(self, group_id: str) -> List[ChatMessage]:
        return self.messages.get(group_id, [])


