        self.users: Dict[str, User] = {}
        self.groups: Dict[str, Group] = {}
        self.notification_service = NotificationService()
        self.chat_service = ChatService()
        self._start_notification_timer()

    def create_user(self, name: str, email: str, password: str) -> User:
        if email in [user.email for user in self.users.values()]:
            raise ValueError("User with this email already exists.")
        user_id = str(uuid.uuid4())
        user = User(user_id, name, email, password)
        self.users[user_id] = user
        return user

    def get_user(self, user_id: str) -> Optional[User]:
        return self.users.get(user_id)

    def get_group(self, group_id: str) -> Optional[Group]:
        return self.groups.get(group_id)

    def create_group(self, user: User, group_name: str, objective: str, target_amount: float, deadline: datetime) -> Group:
        group = user.create_group(group_name, objective, target_amount, deadline)
        self.groups[group.group_id] = group
        return group

    def add_milestone(self, group_id: str, milestone_amount: float):
        group = self.get_group(group_id)
        if group:
            group.add_milestone(milestone_amount)
        else:
            raise ValueError("Group not found.")

    def add_contribution(self, group_id: str, user_id: str, amount: float):
        group = self.get_group(group_id)
        if group:
            group.add_contribution(user_id, amount)
            # Check for milestones
            for milestone in group.milestones:
                if sum(group.contributions.values()) >= milestone:
                    self.notification_service.alert_milestone(group, milestone)
            # Check for budget deviations
            self.notification_service.alert_budget_deviation(group)
        else:
            raise ValueError("Group not found.")

    def send_message(self, group_id: str, user_id: str, content: str):
        self.chat_service.send_message(group_id, user_id, content)

    def get_messages(self, group_id: str) -> List[ChatMessage]:
        return self.chat_service.get_messages(group_id)

    def _start_notification_timer(self):
        def check_notifications():
            while True:
                for group_id, group in self.groups.items():
                    group = self.groups[group_id]
                    self.notification_service.alert_deadline(group)
                time.sleep(86400)  # Check every 24 hours

        timer_thread = threading.Thread(target=check_notifications, daemon=True)
        timer_thread.start()


