        self.name = name
        self.type = weapon_type
        self.damage = damage
        self.range = range
        self.cooldown = cooldown
        self.last_used = 0

    def is_ready(self):
        return time.time() - self.last_used >= self.cooldown

    def use(self):
        if self.is_ready():
            self.last_used = time.time()
            return self.damage
        return 0

class PowerUp(Enum):
    SPEED_BOOST = "Speed Boost"
    DAMAGE_AMPLIFIER = "Damage Amplifier"
    SHIELD = "Shield"
    INVISIBILITY = "Invisibility"
    HEAL = "Heal"

class Hazard(Enum):
    FIRE_FIELD = "Fire Field"
    POISON_CLOUD = "Poison Cloud"
    ELECTRICAL_ZONE = "Electrical Zone"

