        self.power_ups = []
        self.experience = 0
        self.strategy = defaultdict(int)

    def assign_weapon(self, weapon):
        self.weapon = weapon

    def move(self, new_position):
        if not self.invisible and not self.shield > 0:
            self.position = new_position

    def attack(self, target_robot):
        if self.weapon and self.weapon.is_ready():
            damage = self.weapon.use()
            damage *= (1 + 0.2 * self.damage)  # Apply damage modifier
            damage = max(0, damage)  # Ensure damage is not negative

            if target_robot.shield > 0:
                target_robot.shield -= damage
                if target_robot.shield < 0:
                    target_robot.health += target_robot.shield  # Carry over damage if shield breaks
                    target_robot.shield = 0
            else:
                target_robot.health -= damage

            self.update_strategy("attack")

            return damage
        return 0

    def use_power_up(self, power_up):
        if power_up in self.power_ups:
            if power_up == PowerUp.SPEED_BOOST:
                self.speed *= 1.5
                self.power_ups.remove(power_up)
                self.update_strategy("speed_boost")
            elif power_up == PowerUp.DAMAGE_AMPLIFIER:
                self.damage *= 1.5
                self.power_ups.remove(power_up)
                self.update_strategy("damage_amplifier")
            elif power_up == PowerUp.SHIELD:
