            elif power_up == PowerUp.INVISIBLE:
                self.invisible = True
                self.power_ups.remove(power_up)
                self.update_strategy("invisibility")
            elif power_up == PowerUp.HEAL:
                self.health = min(100, self.health + 20)
                self.power_ups.remove(power_up)
                self.update_strategy("heal")

    def is_alive(self):
        return self.health > 0

    def update_strategy(self, action):
