    def learn_from_battle(self, enemy_actions):
        # Simple learning: increase strategy for actions that counter enemy actions
        if "attack" in enemy_actions:
            self.strategy["defend"] += 1
        elif "move" in enemy_actions:
            self.strategy["chase"] += 1

        # Normalize strategy weights
