WEAPON_TYPES = ["laser", "plasma", "melee", "missile"]
POWER_UP_TYPES = ["speed_boost", "shield", "heal", "invisibility"]
OBJECTIVE_TYPES = ["capture_flag", "defend_base", "escort_payload"]

# --- Base Class for Game Entity ---
class Entity:
    def __init__(self, name: str, position: Tuple[float, float]):
        self.name = name
        self.position = np.array(position, dtype=float)
        self.velocity = np.array([0.0, 0.0], dtype=float)
        self.health = MAX_HEALTH

    def update_position(self, new_position: Tuple[float, float]):
        self.position = np.array(new_position, dtype=float)

    def take_damage(self, damage: float):
        self.health -= damage
        if self.health < 0:
            self.health = 0

    def is_alive(self):
        return self.health > 0

# --- Robot Class with AI Controller and Team Assignment ---
class Robot(Entity):
    class Role(Enum):
        ATTACKER = "attacker"
        DEFENDER = "defender"
        SUPPORT = "support"
        SCOUT = "scout"

    def __init__(self, name: str, team: int, role: Role):
        super().__init__(name, (random.uniform(0, 100), random.uniform(0, 100)))
        self.team = team
        self.role = role
        self.weapon = random.choice(WEAPON_TYPES)
        self.power_ups = []
        self.action_points = 100
        self.experience = 0
        self.combat_log = []

    def assign_weapon(self, weapon_type: str):
        self.weapon = weapon_type

    def assign_power_up(self, power_up_type: str):
        self.power_ups.append(power_up_type)

    def use_power_up(self, power_up_type: str):
        if power_up_type in self.power_ups:
            self.power_ups.remove(power_up_type)
            return True
        return False

    def move_towards(self, target_position: Tuple[float, float], speed: float = 2.0):
        if not self.is_alive():
            return
        direction = np.array(target_position) - self.position
        distance = np.linalg.norm(direction)
        if distance > 0:
            direction = direction / distance
        self.velocity = direction * speed
        self.position += self.velocity
        self.action_points -= 1

    def attack(self, target: "Robot", weapon: str):
        if not self.is_alive() or not target.is_alive():
            return
        if weapon not in WEAPON_TYPES:
            return
        if self.weapon == weapon:
            damage = random.uniform(5, 20)  # Random damage based on weapon
            target.take_damage(damage)
            self.combat_log.append(f"{self.name} attacked {target.name} with {weapon}, dealt {damage:.1f} damage")
            self.action_points -= 5

    def learn_strategy(self):
        # Simple strategy learning logic
        if self.role == self.Role.ATTACKER:
            self.experience += 5
        elif self.role == self.Role.DEFENDER:
            self.experience += 3
        elif self.role == self.Role.SUPPORT:
            self.experience += 4
        elif self.role == self.Role.SCOUT:
            self.experience += 6

# --- Objective Class for Team-Based Tasks ---
class Objective(Entity):
    def __init__(self, name: str, position: Tuple[float, float], objective_type: str):
        super().__init__(name, position)
        self.objective_type = objective_type
        self.team_capturing = None
        self.is_complete = False

    def capture(self, team: int):
        self.team_capturing = team
        self.is_complete = True

    def reset(self):
        self.team_capturing = None
        self.is_complete = False

# --- Game Environment with Combat and Objectives ---
class CyberArena:
    def __init__(self):
        self.robots: List[Robot] = []
        self.objectives: List[Objective] = []
        self.power_ups: List[Tuple[Tuple[float, float], str]] = []
        self.time_elapsed = 0.0
        self.scores = {0: 0, 1: 0}

        self._initialize_robots()
        self._initialize_objectives()
        self._initialize_power_ups()

    def _initialize_robots(self):
        for team in range(TEAM_COUNT):
            for i in range(TEAM_SIZE):
                role = random.choice(list(Robot.Role))
