        self.set_difficulty(self.difficulty)

    def set_difficulty(self, difficulty_level):
        """Adjust game difficulty based on the specified level"""
        self.difficulty = difficulty_level
        if difficulty_level == "easy":
            # Easy difficulty: robots are less aggressive and have less damage
            for robot in self.robots:
                robot.skills["attack"] = 0.6
                robot.attack_speed = 0.8
        elif difficulty_level == "medium":
            # Medium difficulty: balanced settings
            for robot in self.robots:
                robot.skills["attack"] = 0.8
                robot.attack_speed = 1.0
        elif difficulty_level == "hard":
            # Hard difficulty: robots are more aggressive and have more damage
            for robot in self.robots:
                robot.skills["attack"] = 1.0
                robot.attack_speed = 1.2
        elif difficulty_level == "expert":
            # Expert difficulty: robots are very aggressive and have high damage
            for robot in self.robots:
                robot.skills["attack"] = 1.2
                robot.attack_speed = 1.5

    def update_difficulty(self):
        """Adjust difficulty based on current game state"""
        # Calculate overall game balance
        team_strengths = [sum(robot.skills.values()) for robot in self.robots]
        team_strengths = [sum(team_strengths[i::TEAM_COUNT]) for i in range(TEAM_COUNT)]

        # If one team is significantly stronger, increase difficulty for that team
        if abs(team_strengths[0] - team_strengths[1]) > 10:
            if team_strengths[0] > team_strengths[1]:
                self.set_difficulty(max(DIFFICULTY_LEVELS, key=DIFFICULTY_LEVELS.index(DIFFICULTY_LEVELS[-1])))
