# Power-up class
class PowerUp:
    def __init__(self, power_type):
        self.type = power_type
        self.position = np.array([random.uniform(0, SCREEN_WIDTH), random.uniform(0, SCREEN_HEIGHT)])
        self.active = True
        self.effects = {
            "health_boost": {"health": 30},
            "speed_boost": {"speed": 1.5},
            "damage_boost": {"damage": 1.5},
            "invisibility": {"invisibility": True}
        }

    def apply_effect(self, robot):
        """Apply the power-up effect to a robot"""
        if not self.active:
            return False

        if self.type in self.effects:
            for effect, value in self.effects[self.type].items():
                if effect == "health":
                    robot.health = min(MAX_HEALTH, robot.health + value)
                elif effect == "speed":
                    robot.speed *= value
                elif effect == "damage":
                    robot.attack_speed *= value
                elif effect == "invisibility":
                    robot.invisible = value

        self.deactivate()

    def deactivate(self):
        """Deactivate the power-up"""
        self.active = False
        # Schedule the power-up to reactivate after some time
        threading.Timer(10.0, self.reactivate).start()

    def reactivate(self):
        """Reactivate the power-up after a cooldown period"""
        self.active = True
        self.position = np.array([random.uniform(0, SCREEN_WIDTH), random.uniform(0, SCREEN_HEIGHT)])

