# Arena Class - Main simulation environment
class Arena:
    def __init__(self):
        self.robots = []  # List of all robots in the arena
        self.teams = []  # List of teams
        self.items = []  # List of power-ups and items
        self.hazards = []  # List of environmental hazards
        self.objectives = []  # List of objectives
        self.running = True  # Simulation status
        self.round_time = 300  # Time for a round in seconds
        self.timer = 0  # Current time in the round
        self.difficulty = 1.0  # Difficulty level (1.0 = normal)
        self.terrain = np.random.choice(['Grass', 'Metal', 'Concrete', 'Sand'], size=(10,10))

    def add_robot(self, robot):
        """Add a robot to the arena"""
        self.robots.append(robot)

    def add_item(self, item):
        """Add an item to the arena"""
        self.items.append(item)

    def add_hazard(self, hazard):
        """Add a hazard to the arena"""
        self.hazards.append(hazard)

    def add_objective(self, objective):
        """Add an objective to the arena"""
        self.objectives.append(objective)

    def start(self):
        """Start the simulation"""
        print("CyberArena simulation starting...")
        self.timer = 0

        # Assign roles to teams
        for team in self.teams:
            team.assign_roles()

        # Start the main simulation loop
        simulation_thread = threading.Thread(target=self.simulation_loop)
        simulation_thread.start()

    def simulation_loop(self):
        """Main simulation loop"""
        while self.running and self.timer < self.round_time:
            # Update time
            self.timer += 1
            time.sleep(1)  # Simulate 1 second

            # Process each robot's action
            for robot in self.robots:
                if robot.health > 0:
                    action = robot.choose_action(self)
                    #print(f"{robot.name} ({robot.team.name}) chose action: {action}")

            # Check for objective completions
            for objective in self.objectives:
                if objective.completed:
                    # Award points to the team
                    objective.team.update_score(100)
                    print(f"{objective.team.name} completed objective: {objective.description}")

            # Check for winning conditions
            for team in self.teams:
                if team.check_winning_condition():
                    print(f"{team.name} has won the battle!")
                    self.end()

            # Update difficulty based on team performance
            self.update_difficulty()

            # Apply hazard effects
            for hazard in self.hazards:
                hazard.apply_effect(self)

            # Apply item effects
            for item in self.items:
                item.apply_effect(self)

        # End of round
        if self.timer >= self.round_time:
            print("Round time has expired!")
            self.end()

    def update_difficulty(self):
        """Adjust difficulty based on team performance"""
        # Calculate team performance
        team_performance = sum(team.score for team in self.teams) / len(self.teams)

        # Adjust difficulty based on performance
        if team_performance > 80:
            self.difficulty = max(1.0, self.difficulty * 0.95)  # Reduce difficulty
            print("Lowering difficulty as teams are performing well...")
        elif team_performance < 40:
            self.difficulty = min(2.0, self.difficulty * 1.05)  # Increase difficulty
            print("Increasing difficulty as teams need more challenge...")
        else:
            # Maintain current difficulty
            self.difficulty = self.difficulty

    def end(self):
        """End the simulation"""
        self.running = False
        # Print final scores
        for team in self.teams:
            print(f"{team.name} Final Score: {team.score}")
        print("Simulation ended.")

