                if power_up_name == "Speed Boost":
                    self.speed /= 1.5
                elif power_up_name == "Shield":
                    self.max_health -= 50
                    if self.health > self.max_health:
                        self.health = self.max_health
                elif power_up_name == "Double Damage":
