                break

    def take_damage(self, amount: float):
        """Take damage from an attack or hazard."""
        if self.state == State.DEAD:
            return
        if self.health > 0:
            self.health -= amount
            if self.health <= 0:
                self.health = 0
                self.state = State.DEAD

    def heal(self, amount: float):
        """Heal the robot."""
        if self.state == State.DEAD:
            return
        self.health = min(self.max_health, self.health + amount)

    def move_towards(self, target: Tuple[float, float], speed: Optional[float] = None):
        """Move the robot towards a target location."""
        if self.state == State.DEAD:
            return
        self.state = State.MOVING
        speed = speed or self.speed
        dx, dy = target[0] - self.position[0], target[1] - self.position[1]
        distance = math.hypot(dx, dy)
        if distance > 0:
            move_factor = speed / distance
            new_position = (
                self.position[0] + dx * move_factor,
                self.position[1] + dy * move_factor
            )
            self.position = new_position

    def attack(self, target: "Robot", weapon: Optional[Weapon] = None):
        """Attack another robot with a specific weapon."""
        if self.state == State.DEAD:
