@dataclass
class Arena:
    name: str
    size: Tuple[float, float] = (100, 100)
    teams: List[str] = field(default_factory=lambda: TEAM_COLORS[:2])
    robots: List[Robot] = field(default_factory=list)
    objectives: List[Objective] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    current_time: float = 0
    difficulty: Difficulty = Difficulty.MEDIUM
    score_multiplier: float = 1.0

    def add_robot(self, robot: Robot):
        """Add a robot to the arena."""
        if robot.team not in self.teams:
            raise ValueError(f"Team {robot.team} is not valid")
        self.robots.append(robot)

    def add_objective(self, objective: Objective):
        """Add an objective to the arena."""
        self.objectives.append(objective)

    def add_hazard(self, hazard: Hazard):
        """Add a hazard to the arena."""
        self.hazards.append(hazard)

    def add_power_up(self, power_up: PowerUp):
        """Add a power-up to the arena."""
        self.power_ups.append(power_up)

    def update(self, dt: float):
        """Update the arena with the given time delta."""
        self.current_time += dt

        # Update all robots
        for robot in self.robots:
            if robot.state == State.DEAD:
                continue

            # Apply power-ups
            for power_up in robot.power_ups:
                if power_up.timer >= power_up.duration:
                    robot.remove_power_up(power_up.name)
                else:
                    power_up.timer += dt

            # Check for hazards affecting the robot
            for hazard in self.hazards:
                if hazard.active:
                    distance = robot.distance_to(hazard.location)
                    if distance <= hazard.radius:
                        robot.take_damage(hazard.damage_per_second * dt)

            # Update robot state based on objectives
            if self.objectives:
                for objective in self.objectives:
                    if objective.team == robot.team and not objective.captured:
                        robot.move_towards(objective.location)
                        if robot.distance_to(objective.location) < 2:
                            objective.captured = True
                            robot.score += 100 * self.score_multiplier
                            # Add visual and audio feedback for objective capture

            # Update robot state based on nearby enemies
            enemy_robots = [r for r in self.robots if r.team != robot.team]
            if enemy_robots:
                closest_enemy = min(enemy_robots, key=lambda r: robot.distance_to(r))
                if robot.role == Role.ATTACKER:
                    if robot.distance_to(closest_enemy) > robot.weapon.range:
                        robot.move_towards(closest_enemy.position)
                    else:
                        robot.attack(closest_enemy)
                elif robot.role == Role.DEFENDER:
                    if robot.distance_to(closest_enemy) < 10:
                        robot.attack(closest_enemy)
                    else:
                        robot.move_towards(robot.team_objective().location)
                elif robot.role == Role.SCOUT:
                    # Implement scouting behavior
                    pass
                elif robot.role == Role.SUPPORT:
                    # Implement support behavior (healing, buffing)
                    pass

        # Update adaptive difficulty
        self.update_adaptive_difficulty()

        # Update power-up appearances
        if random.random() < 0.05:  # 5% chance per update
            power_up = random.choice(POWER_UPS)
            power_up_obj = PowerUp(power_up, "Effect", 10)
            self.add_power_up(power_up_obj)

    def team_objective(self, team: str) -> Optional[Objective]:
        """Find the objective for a specific team."""
        for objective in self.objectives:
            if objective.team == team:
                return objective
        return None

    def update_adaptive_difficulty(self):
        """Adjust difficulty based on robot performance."""
        total_health = sum(robot.health for robot in self.robots)
        dead_robots = sum(1 for robot in self.robots if robot.state == State.DEAD)

        if total_health / len(self.robots) < 30 and dead_robots < len(self.robots) / 2:
            # Robots are struggling - reduce difficulty
            if self.difficulty != Difficulty.EASY:
                self.difficulty = Difficulty(self.difficulty.value - 1)
                self.score_multiplier *= 0.9
                for robot in self.robots:
                    robot.speed *= 1.1
        elif dead_robots > len(self.robots) / 2:
            # Robots are dying too quickly - increase difficulty
            if self.difficulty != Difficulty.LEGENDARY:
                self.difficulty = Difficulty(self.difficulty.value + 1)
                self.score_multiplier *= 1.1
                for robot in self.robots:
                    robot.speed *= 0.9

    def get_leaderboards(self) -> Dict[str, float]:
        """Return the current leaderboard based on scores."""
        leaders = {}
        for team in self.teams:
            team_score = sum(robot.score for robot in self.robots if robot.team == team)
            leaders[team] = team_score
        return dict(sorted(leaders.items(), key=lambda item: item[1], reverse=True))

