    def simulate(self):
        """Run the simulation for the full duration."""
        while self.current_time < self.total_time:
            delta_time = min(self.time_step, self.total_time - self.current_time)
            self.arena.update(delta_time)
            self.current_time += delta_time
            self.update_visuals()
            time.sleep(self.time_step / 10)  # Control simulation speed

    def update_visuals(self):
        """Update visual and audio effects (simulated)."""
        # In a real implementation, this would update the graphics and sound
        # Here we just print some status to simulate the updates
        if self.current_time % 1 == 0:  # Print status every second
            self.print_status()
            self.play_sound_effect("arena_background")

    def print_status(self):
