        print(f"\nTime: {self.current_time:.1f}s")
        for team, score in self.arena.get_leaderboards().items():
            print(f"{team} Team Score: {score:.0f}")
        for robot in self.arena.robots:
            if robot.state != State.DEAD:
                print(f"{robot.name} ({robot.team} Team): {robot.health:.0f} HP, {robot.state.value}, at {robot.position}")
