        self.robots = []  # List of all robots in the arena
        self.objectives = objectives  # List of objectives to complete
        self.powerups = powerups  # List of power-ups available
        self.bullets = []  # List of active bullets
        self.scoreboard = defaultdict(int)
        self.running = True

        # Initialize robots for each team
        for team_name, robot_configs in initial_robots.items():
            for i, config in enumerate(robot_configs):
                robot_type = RobotType(config["type"])
                robot = Robot(f"{team_name}_Robot_{i+1}", team_name, robot_type)
                self.robots.append(robot)
                self.teams[team_name].append(robot)

    def add_powerup(self, powerup):
        """Add a new power-up to the arena."""
        self.powerups.append(powerup)

    def remove_powerup(self, powerup):
        """Remove a power-up from the arena."""
        self.powerups.remove(powerup)

    def spawn_bullets(self):
        """Spawn bullets for ranged attacks."""
        for robot in self.robots:
            # For simplicity, assume robots only attack the nearest enemy
            enemies = [r for r in self.robots if r.team != robot.team and r.is_alive()]
            if enemies:
                nearest_enemy = min(enemies, key=lambda e: math.hypot(robot.position[0] - e.position[0], robot.position[1] - e.position[1]))
                if robot.robot_type != RobotType.HEALER and robot.weapon.weapon_type in [WeaponType.PISTOL, WeaponType.RIFLE, WeaponType.SHOTGUN, WeaponType.LASER]:
                    # Only shoot if the weapon is a ranged weapon
                    bullet = Bullet(robot, nearest_enemy, robot.weapon)
                    self.bullets.append(bullet)

    def update_bullets(self):
        """Update the position of bullets and check for collisions."""
        for bullet in self.bullets[:]:
            bullet.move()
            if bullet.is_out_of_bounds():
                self.bullets.remove(bullet)
            elif bullet.hit_target():
                bullet.target.health = max(0, bullet.target.health - bullet.weapon.damage)
                bullet.target.score -= 1  # Deduct points for being hit
                bullet.shooter.score += 2  # Award points for successful hit
                self.bullets.remove(bullet)

    def update_status_effects(self):
        """Update status effects for all robots."""
        for robot in self.robots:
            robot.update_status_effects()

    def check_powerups(self):
        """Check if any robot is near a power-up and apply it."""
        for powerup in self.powerups[:]:
            for robot in self.robots:
                distance = math.hypot(powerup.position[0] - robot.position[0], powerup.position[1] - robot.position[1])
                if distance <= 50:  # Assume a 50-unit radius for power-up collection
                    powerup.apply(robot)
                    self.powerups.remove(powerup)
                    break

    def update_objectives(self):
        """Update objectives based on progress."""
        for objective in self.objectives:
            if not objective.completed:
                if objective.objective_type == ObjectiveType.CAPTURE_FLAG:
                    # For simplicity, assume flag is captured when a robot reaches the position
                    for robot in self.robots:
                        distance = math.hypot(robot.position[0] - objective.position[0], robot.position[1] - objective.position[1])
                        if distance <= 20 and robot.team == objective.target:
                            objective.completed = True
                            robot.score += 5  # Award points for completing the objective
                            break
                elif objective.objective_type == ObjectiveType.DESTROY_ENEMY:
                    # Assume objective is complete when all enemy robots are destroyed
                    if all(robot.team != objective.target or not robot.is_alive() for robot in self.robots):
                        objective.completed = True
                        for robot in self.robots:
                            if robot.team == objective.target:
                                robot.score += 5  # Award points for completing the objective
                elif objective.objective_type == ObjectiveType.ESCORT_PAYLOAD:
                    # Assume objective is complete when a robot reaches the target position
                    for robot in self.robots:
                        if robot.team == objective.target:
                            distance = math.hypot(robot.position[0] - objective.position[0], robot.position[1] - objective.position[1])
                            if distance <= 20:
                                objective.completed = True
                                robot.score += 5  # Award points for completing the objective
                                break

    def update_scoreboard(self):
        """Update the scoreboard with robot scores."""
        self.scoreboard.clear()
        for robot in self.robots:
            self.scoreboard[robot.robot_id] += robot.score

    def update(self):
        """Update the CyberArena state."""
        self.spawn_bullets()
        self.update_bullets()
        self.update_status_effects()
        self.check_powerups()
        self.update_objectives()
        self.update_scoreboard()

    def run(self):
        """Run the CyberArena simulation."""
        print("CyberArena simulation started!")
        try:
            while self.running:
                self.update()
                time.sleep(ACTION_INTERVAL)
                self._print_status()
        except KeyboardInterrupt:
            print("\nSimulation stopped by user.")
            self.running = False
            self._print_final_results()

    def _print_status(self):
        """Print the current status of the simulation to the console."""
        alive_robots = [robot for robot in self.robots if robot.is_all()]
        print(f"Alive Robots: {len(alive_robots)}")
        print(f"Active Bullets: {len(self.bullets)}")
        print(f"Active Power-Ups: {len(self.powerups)}")
        print(f"Objectives Completed: {sum(obj.completed for obj in self.objectives)}")
        print(f"Scoreboard: {self.scoreboard}")
        print("-" * 50)

    def _print_final_results(self):
        """Print the final results of the simulation."""
        print("\nFinal Results:")
        print(f"Total Alive Robots: {sum(robot.is_all() for robot in self.robots)}")
        print(f"Completed Objectives: {sum(obj.completed for obj in self.objectives)}")
