        self.reload_time = reload_time
        self.cooldown = 0  # Current cooldown timer

    def is_ready(self) -> bool:
        return self.cooldown <= 0

    def update(self, dt: float):
        if self.cooldown > 0:
            self.cooldown -= dt

    def use(self):
        if self.is_ready():
            self.cooldown = self.reload_time
            return True
        return False

    def describe(self) -> str:
        return f"{self.name} ({self.type.value}): Damage={self.damage}, Range={self.range}, Reload={self.reload_time}"

# Base class for all power-ups
class PowerUp:
    def __init__(self, name: str, duration: float, effect: Callable[[Robot], None]):
        self.name = name
        self.duration = duration
        self.effect = effect

    def apply(self, robot: 'Robot'):
        self.effect(robot)

    def describe(self) -> str:
        return f"{self.name}: Duration={self.duration}"

# Base class for all environmental hazards
class Hazard:
    def __init__(self, name: str, damage_per_second: float, duration: float, area_of_effect: float):
        self.name = name
        self.damage_per_second = damage_per_second
        self.duration = duration
        self.area_of_effect = area_of_effect
        self.remaining_time = duration

    def update(self, dt: float):
        self.remaining_time -= dt
        if self.remaining_time <= 0:
            self.remaining_time = 0

    def is_active(self) -> bool:
        return self.remaining_time > 0

    def describe(self) -> str:
        return f"{self.name}: Damage/Sec={self.damage_per_second}, Duration={self.duration}, AoE={self.area_of_effect}"

# Abstract base class for all game agents
class Agent(ABC):
    def __init__(self, position: Position, speed: float):
        self.position = position
        self.speed = speed
        self.velocity: Velocity = (0, 0)
        self.health = 100.0
        self.is_alive = True

    @abstractmethod
    def update(self, dt: float):
        pass

    def move_towards(self, target: Position, dt: float):
        dx, dy = target[0] - self.position[0], target[1] - self.position[1]
        distance = (dx**2 + dy**2)**0.5
        if distance > 0:
            self.velocity = (dx / distance * self.speed, dy / distance * self.speed)
        else:
            self.velocity = (0, 0)
        self.position = (self.position[0] + self.velocity[0] * dt,
                         self.position[1] + self.velocity[1] * dt)

    def take_damage(self, amount: float):
        if self.health > 0:
            self.health -= amount
            if self.health <= 0:
                self.is_alive = False

    def render(self, surface):
        pass

# Robot class representing AI-controlled agents in the arena
class Robot(Agent):
    def __init__(self, name: str, position: Position, team: TeamColor, role: Role, weapons: List[Weapon], speed: float):
        super().__init__(position, speed)
        self.name = name
        self.team = team
        self.role = role
        self.weapons = weapons
        self.current_weapon_index = 0
        self.score = 0  # Score for this robot
        self.objective_progress = 0  # Progress toward current objective
        self.memory = []  # Memory for learning from previous battles
        self.skills = {}  # Dictionary to store skill proficiency
        self.current_power_up: Optional[PowerUp] = None
        self.power_up_timer = 0

    @property
    def current_weapon(self) -> Weapon:
        return self.weapons[self.current_weapon_index]

    def switch_next_weapon(self):
        self.current_weapon_index = (self.current_weapon_index + 1) % len(self.weapons)

    def attack(self, target: 'Robot', dt: float) -> bool:
        if self.current_weapon.is_ready():
            if self.distance_to(target) <= self.current_weapon.range:
                target.take_damage(self.current_weapon.damage)
                self.current_weapon.use()
                return True
        return False

    def distance_to(self, other: 'Robot') -> float:
        dx = self.position[0] - other.position[0]
        dy = self.position[1] - other.position[1]
        return (dx**2 + dy**2)**0.5

    def use_power_up(self, power_up: PowerUp):
        self.current_power_up = power_up
        self.power_up_timer = power_up.duration
        power_up.apply(self)

    def update(self, dt: float):
        super().update(dt)
        self.current_weapon.update(dt)

        if self.current_power_up and self.power_up_timer > 0:
            self.power_up_timer -= dt
            if self.power_up_timer <= 0:
                self.current_power_up = None

    def learn_from_battle(self, opponent: 'Robot', result: str):
        """
        Store battle experience for future learning
        result: 'win', 'loss', or 'draw'
        """
        self.memory.append({
            'opponent': opponent.name,
            'opponent_role': opponent.role,
            'weapons_used': [w.name for w in self.weapons],
            'result': result,
            'time': time.time()
        })

    def calculate_score(self, team: 'Team'):
        """
        Calculate and update score based on various factors
        """
        # Base score for being alive
        base_score = int(100 if self.is_alive else 0)

        # Bonus for objective progress
        objective_bonus = int(self.objective_progress * 50)

        # Bonus for team contributions
        team_contribution = int(self.score * 0.2)

        # Total score
        self.score = base_score + objective_bonus + team_contribution

        # Also update team score
        if self in team.members:
            team.score += self.score

    def render(self, surface):
        # Draw robot as a colored circle
        if self.team == TeamColor.RED:
            color = (255, 0, 0)
        elif self.team == TeamColor.BLUE:
            color = (0, 0, 255)
        elif self.team == TeamColor.GREEN:
            color = (0, 255, 0)
        else:  # Yellow
            color = (255, 255, 0)

        pygame.draw.circle(surface, color, (int(self.position[0]), int(self.position[1])), 10)

        # Draw health bar
        pygame.draw.rect(surface, (255, 0, 0), (int(self.position[0]) - 10, int(self.position[1]) - 20, 20, 5))
        pygame.draw.rect(surface, (0, 255, 0), (int(self.position[0]) - 10, int(self.position[1]) - 20, 
                                               int(20 * (self.health / 100)), 5))

    def describe(self) -> str:
        return f"{self.name} ({self.team.value}, {self.role.value}): Health={self.health:.1f}, Score={self.score}"

# Team class representing a group of robots working together
class Team:
    def __init__(self, name: str, color: TeamColor, objective: Objective):
        self.name = name
        self.color = color
        self.objective = objective
        self.members: List[Robot] = []
        self.score = 0
        self.base_position: Position = (200, 200) if color == TeamColor.RED else (600, 600)
        self.flag_position: Position = (self.base_position[0] + 50, self.base_position[1])
        self.payload_position: Position = (400, 300)
        self.defended_area: Position = (self.base_position[0] - 100, self.base_position[1] - 100, 200, 200)
        self.objective_progress = 0

    def add_member(self, robot: Robot):
        self.members.append(robot)

    def update(self, dt: float):
        # Update all members
        for robot in self.members:
            robot.update(dt)

        # Update objective progress
        if self.objective == Objective.CAPTURE_FLAG:
            self.objective_progress = min(1.0, self.objective_progress + dt * 0.1)
        elif self.objective == Objective.ESCORT_PAYLOAD:
            payload_distance = self._calculate_payload_distance()
            self.objective_progress = max(0.0, 1.0 - payload_distance / 800)

    def _calculate_payload_distance(self) -> float:
        # Calculate the average distance from all team members to the payload
        total_distance = 0
        for robot in self.members:
            if robot.is_alive:
                dx = robot.position[0] - self.payload_position[0]
                dy = robot.position[1] - self.payload_position[1]
                total_distance += (dx**2 + dy**2)**0.5
        return total_distance / len(self.members) if self.members else 0

    def render(self, surface):
        # Draw team base
        pygame.draw.rect(surface, self.color.value_to_rgb(), 
                        (self.base_position[0] - 50, self.base_position[1] - 50, 100, 100), 2)

        # Draw objective marker
        if self.objective == Objective.CAPTURE_FLAG:
            pygame.draw.rect(surface, (255, 255, 255), 
                            (self.flag_position[0] - 5, self.flag_position[1] - 20, 10, 40))
        elif self.objective == Objective.ESCORT_PAYLOAD:
            pygame.draw.circle(surface, (255, 255, 0), 
                              (int(self.payload_position[0]), int(self.payload_position[1])), 15, 2)

        # Draw team members
        for robot in self.members:
            robot.render(surface)

    def calculate_scores(self):
        for robot in self.members:
            robot.calculate_score(self)

    def describe(self) -> str:
        return f"{self.name} ({self.color.value}): Objective={self.objective.value}, Score={self.score}, Members={len(self.members)}"

# Extend enum to include RGB values for rendering
class TeamColor(Enum):
    RED = "Red", (255, 0, 0)
    BLUE = "Blue", (0, 0, 255)
    GREEN = "Green", (0, 255, 0)
    YELLOW = "Yellow", (255, 255, 0)

    def value_to_rgb(self) -> Tuple[int, int, int]:
        return self.value[1]

# Arena class representing the game environment
class Arena:
    def __init__(self, teams: List[Team], hazards: List[Hazard]):
        self.teams = teams
        self.hazards = hazards
        self.time_elapsed = 0
        self.round_number = 1
        self.winning_team: Optional[Team] = None
        self.battle_log: List[Dict] = []

    def update(self, dt: float):
        self.time_elapsed += dt

        # Update all teams
        for team in self.teams:
            team.update(dt)

        # Update all hazards
        for hazard in self.hazards:
            hazard.update(dt)
            if hazard.is_active():
                # Apply hazard damage to robots in the area of effect
                for team in self.teams:
                    for robot in team.members:
                        if robot.is_alive:
                            distance = ((robot.position[0] - hazard.area_of_effect[0])**2 + 
                                       (robot.position[1] - hazard.area_of_effect[1])**2)**0.5
                            if distance <= hazard.area_of_effect[2]:
                                robot.take_damage(hazard.damage_per_second * dt)

        # Check for objective completion
        self._check_objective_completion()

        # Check for win condition
        self._check_win_condition()

    def _check_objective_completion(self):
        for team in self.teams:
            if team.objective == Objective.CAPTURE_FLAG:
                if team.objective_progress >= 0.9:
                    # Team has captured the flag
                    self._log_event(f"{team.name} has captured the flag!")
                    team.score += 500
            elif team.objective == Objective.ESCORT_PAYLOAD:
                if team.objective_progress >= 0.9:
                    # Team has successfully escorted the payload
                    self._log_event(f"{team.name} has successfully escorted the payload!")
                    team.score += 500
            elif team.objective == Objective.DEFEND_BASE:
                # For defending base, check if other teams have attacked
                for other_team in self.teams:
                    if other_team != team:
                        other_distance = ((team.base_position[0] - other_team.base_position[0])**2 +
                                         (team.base_position[1] - other_team.base_position[1])**2)**0.5
                        if other_distance < 150:
                            team.score += 100
                            break

    def _check_win_condition(self):
        # Simple win condition: first team to 1000 points wins
        for team in self.teams:
            if team.score >= 1000 and self.winning_team is None:
                self.winning_team = team
                self._log_event(f"{team.name} has won the battle!")
                # Reset scores for next round
                for t in self.teams:
                    t.score = 0

    def _log_event(self, event: str):
        self.battle_log.append({"time": self.time_elapsed, "event": event})

    def render(self, surface):
        # Draw background
        surface.fill((30, 30, 30))  # Dark gray background

        # Draw hazards
        for hazard in self.hazards:
            if hazard.is_active():
                hazard_surface = pygame.Surface((hazard.area_of_effect[2]*2, hazard.area_of_effect[2]*2), 
                                              pygame.SRCALPHA)
                pygame.draw.circle(hazard_surface, (255, 0, 0, 100), 
                                 (hazard.area_of_effect[2], hazard.area_of_effect[2]), 
                                 hazard.area_of_effect[2])
                surface.blit(hazard_surface, 
                            (hazard.area_of_effect[0] - hazard.area_of_effect[2], 
                             hazard.area_of_effect[1] - hazard.area_of_effect[2]))

        # Draw teams and their members
        for team in self.teams:
            team.render(surface)

        # Draw UI elements
        self._draw_ui(surface)

        # Update display
        pygame.display.flip()

    def _draw_ui(self, surface):
        # Draw score display
        font = pygame.font.SysFont(None, 24)
        y_offset = 10

        # Display round number and time
        round_text = font.render(f"Round: {self.round_number} | Time: {self.time_elapsed:.1f}s", True, (255, 255, 255))
        surface.blit(round_text, (10, y_offset))
        y_offset += 30

        # Display team scores
        for team in self.teams:
            score_text = font.render(f"{team.name} Score: {team.score}", True, team.color.value_to_rgb())
            surface.blit(score_text, (10, y_offset))
            y_offset += 30

        # Display winning team
        if self.winning_team:
            win_text = font.render(f"{self.winning_team.name} has won the battle!", True, (255, 255, 0))
            surface.blit(win_text, (WIDTH/2 - 150, HEIGHT - 40))

        # Display objectives
        y_offset = HEIGHT - 150
        for team in self.teams:
            obj_text = font.render(f"{team.name} Objective: {team.objective.value}", True, team.color.value_to_rgb())
            surface.blit(obj_text, (10, y_offset))
            y_offset += 30

    def run_battle(self, duration: float = 300.0):
        """Run a battle for the specified duration in seconds"""
        start_time = time.time()
        while time.time() - start_time < duration and self.winning_team is None:
            dt = clock.tick(60) / 1000  # Convert to seconds
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    return

            self.update(dt)
            self.render(screen)

            # Check if all robots are dead
            if all(not robot.is_alive for team in self.teams for robot in team.members):
                self._log_event("All robots are dead - draw!")
                break

        # After battle
        self._post_battle_analysis()
        self.round_number += 1
        self.winning_team = None

    def _post_battle_analysis(self):
        """Analyze the battle and provide feedback for learning"""
        for team in self.teams:
            for robot in team.members:
                # Calculate performance metrics
                survival_rate = robot.health / 100 if robot.is_alive else 0
                objective_contribution = robot.objective_progress / team.objective_progress if team.objective_progress > 0 else 0

                # Update skill proficiency
                if robot.role == Role.ATTACKER:
                    robot.skills['attack'] = robot.skills.get('attack', 0) + survival_rate * objective_contribution
                elif robot.role == Role.SUPPORT:
                    robot.skills['support'] = robot.skills.get('support', 0) + survival_rate * objective_contribution
                elif robot.role == Role.TANK:
                    robot.skills['defense'] = robot.skills.get('defense', 0) + survival_rate * objective_contribution
                elif robot.role == Role.UTIL:
                    robot.skills['utility'] = robot.skills.get('utility', 0) + survival_rate * objective_contribution

                # Store battle experience
                if team.score > 0:
                    robot.learn_from_battle(None, 'win')
                else:
                    robot.learn_from_battle(None, 'loss')

    def adapt_difficulty(self):
        """Adjust difficulty based on team performance"""
        total_score = sum(team.score for team in self.teams)

        if total_score < 500:  # Easy
            for team in self.teams:
                for robot in team.members:
                    # Increase robot speed
                    robot.speed = min(10.0, robot.speed * 1.2)
                    # Increase damage of weapons
                    for weapon in robot.weapons:
                        weapon.damage *= 1.2
        elif total_score > 1500:  # Hard
            for team in self.teams:
                for robot in team.members:
                    # Decrease robot speed
                    robot.speed = max(2.0, robot.speed * 0.8)
                    # Decrease damage of weapons
                    for weapon in robot.weapons:
                        weapon.damage *= 0.8
        else:  # Normal difficulty
            # Reset to default values
            for team in self.teams:
                for robot in team.members:
                    robot.speed = 5.0
                    for weapon in robot.weapons:
                        weapon.damage = {
                            WeaponType.LASER: 25,
                            WeaponType.MISSILE: 40,
                            WeaponType.SWORD: 30,
                            WeaponType.SHIELD: 0
                        }[weapon.type]

# Create CyberArena environment
def create_arena() -> Arena:
    # Create teams
    red_team = Team("Red Team", TeamColor.RED, Objective.CAPTURE_FLAG)
    blue_team = Team("Blue Team", TeamColor.BLUE, Objective.DEFEND_BASE)

    # Create robots for Red Team
    red_laser = Weapon("Laser Gun", WeaponType.LASER, 25, 300, 0.5)
    red_missile = Weapon("Plasma Missile", WeaponType.MISSILE, 40, 500, 1.2)
    red_robot1 = Robot("Red Alpha", (100, 100), TeamColor.RED, Role.ATTACKER, [red_laser, red_missile], 5.0)
    red_sword = Weapon("Energy Blade", WeaponType.SWORD, 30, 1.5, 0.8)
    red_robot2 = Robot("Red Beta", (120, 120), TeamColor.RED, Role.TANK, [red_sword], 4.0)
    red_team.add_member(red_robot1)
    red_team.add_member(red_robot2)

    # Create robots for Blue Team
    blue_laser = Weapon("Railgun", WeaponType.LASER, 30, 400, 0.6)
    blue_shield = Weapon("Energy Shield", WeaponType.SHIELD, 0, 0, 1.5)
    blue_robot1 = Robot("Blue Gamma", (700, 500), TeamColor.BLUE, Role.SUPPORT, [blue_laser, blue_shield], 4.5)
    blue_missile = Weapon("Railgun Missile", WeaponType.MISSILE, 35, 450, 1.0)
    blue_robot2 = Robot("Blue Delta", (680, 480), TeamColor.BLUE, Role.UTIL, [blue_missile], 4.0)
    blue_team.add_member(blue_robot1)
    blue_team.add_member(blue_robot2)

    # Create hazards
    hazard1 = Hazard("Lava Trap", 10.0, 10.0, (400, 300, 50))
    hazard2 = Hazard("Electric Storm", 5.0, 5.0, (200, 200, 30))

    # Create and return arena
    return Arena([red_team, blue_team], [hazard1, hazard2])

# Main function to run the CyberArena simulation
def main():
    # Create the CyberArena
    arena = create_arena()

    # Run multiple rounds to allow learning and adaptation
    for _ in range(3):  # Run 3 rounds
        print(f"\n{'='*50}")
        print(f"Starting Round {arena.round_number}")
        print(f"{'='*50}")

        # Print team descriptions
        for team in arena.teams:
            print(team.describe())

        # Run the battle
        arena.run_battle(duration=30.0)  # 30 seconds per round

        # Print results
        print(f"\n{'-'*50}")
        print(f"Results of Round {arena.round_number}")
        print(f"{'-'*50}")

        for team in arena.teams:
            print(f"\n{team.name} Team Results:")
            print(f"Score: {team.score}")
            for robot in team.members:
                print(f"{robot.name}:")
                print(f"  Health: {robot.health:.1f}")
                print(f"  Score: {robot.score}")
                print(f"  Objective Progress: {robot.objective_progress:.2f}")
                print(f"  Skills: {robot.skills}")
                print(f"  Current Weapon: {robot.current_weapon.describe()}")
                print(f"  Power-Up: {robot.current_power_up.name if robot.current_power_up else 'None'}")

        # Adapt difficulty for next round
        arena.adapt_difficulty()

    # Print final results
    print(f"\n{'='*50}")
    print("Final Results")
    print(f"{'='*50}")

    for team in arena.teams:
        print(f"\n{team.name} Team Final Stats:")
        print(f"Total Score: {team.score}")
        for robot in team.members:
            print(f"{robot.name}:")
            print(f"  Final Health: {robot.health:.1f}")
            print(f"  Final Score: {robot.score}")
            print(f"  Learned from {len(robot.memory)} battles")
            if robot.memory:
                print(f"  Last Battle: {robot.memory[-1]}")
            print(f"  Skills: {robot.skills}")

    print("\nBattle Log:")
    for entry in arena.battle_log:
        print(f"{entry['time']:.1f}s: {entry['event']}")

