class Position:
    """Represents a 2D position in the game world."""
    def __init__(self, x: float = 0.0, y: float = 0.0):
        self.x = x
        self.y = y

    def distance_to(self, other: "Position") -> float:
        """Calculate the Euclidean distance to another position."""
        return ((self.x - other.x)**2 + (self.y - other.y)**2)**0.5

    def __str__(self) -> str:
        return f"Position(x={self.x:.2f}, y={self.y:.2f})"

    def __repr__(self) -> str:
        return self.__str__()

class Weapon:
    """Base class for all weapon types in the game."""
    def __init__(self, weapon_type: WeaponType, damage: float, range: float, cooldown: float):
        self.weapon_type = weapon_type
        self.damage = damage
        self.range = range
        self.cooldown = cooldown
        self.last_used = 0.0  # Time since last use

    def is_ready(self, current_time: float) -> bool:
        """Check if the weapon is ready for use."""
        return (current_time - self.last_used) >= self.cooldown

    def use(self, current_time: float):
        """Mark the weapon as used and record the time."""
        if self.is_ready(current_time):
            self.last_used = current_time

    def __str__(self) -> str:
        return f"Weapon(type={self.weapon_type.value}, damage={self.damage}, range={self.range}, cooldown={self.cooldown})"

class Powerup:
    """Base class for all power-up types in the game."""
    def __init__(self, powerup_type: PowerupType, duration: float, strength: float):
        self.powerup_type = powerup_type
        self.duration = duration
        self.strength = strength
        self.activation_time = 0.0

    def is_active(self, current_time: float) -> bool:
        """Check if the power-up is active."""
        return (current_time - self.activation_time) < self.duration

    def activate(self, current_time: float):
        """Activate the power-up and record the time."""
        self.activation_time = current_time

    def __str__(self) -> str:
        return f"Powerup(type={self.powerup_type.value}, duration={self.duration}, strength={self.strength})"

class Hazard:
    """Base class for all environmental hazards."""
    def __init__(self, hazard_type: HazardType, radius: float, effect_duration: float):
        self.hazard_type = hazard_type
        self.radius = radius
        self.effect_duration = effect_duration
        self.activation_time = 0.0

    def is_active(self, current_time: float) -> bool:
        """Check if the hazard is active."""
        return (current_time - self.activation_time) < self.effect_duration

    def activate(self, current_time: float):
        """Activate the hazard and record the time."""
        self.activation_time = current_time

    def __str__(self) -> str:
        return f"Hazard(type={self.hazard_type.value}, radius={self.radius}, duration={self.effect_duration})"

class Robot:
    """Base class for all AI-controlled robots in the game."""
    def __init__(self, name: str, team: Team, position: Position, speed: float, health: float):
        self.name = name
        self.team = team
        self.position = position
        self.speed = speed
        self.health = health
        self.max_health = health
        self.weapons: List[Weapon] = []
        self.powerups: List[Powerup] = []
        self.active_powerups: Dict[PowerupType, Powerup] = {}
        self.hazards: List[Hazard] = []
        self.score = 0
        self.last_action_time = 0.0
        self.action_cooldown = 0.5  # Seconds
        self.role = self.assign_role()  # Assign a dynamic role

    def assign_role(self) -> str:
        """Assign a dynamic role based on team and robot type."""
        return random.choice(["Scout", "Support", "Tank", "Offense"]) if random.random() < 0.8 else "Utility"

    def is_alive(self) -> bool:
        """Check if the robot is alive."""
        return self.health > 0

    def move_towards(self, target_position: Position, delta_time: float) -> None:
        """Move the robot towards the target position."""
        if not self.is_ready_for_action(delta_time):
            return

        distance = self.position.distance_to(target_position)
        if distance > 0:
            direction_x = (target_position.x - self.position.x) / distance
            direction_y = (target_position.y - self.position.y) / distance
            self.position.x += direction_x * self.speed * delta_time
            self.position.y += direction_y * self.speed * delta_time
            self.last_action_time = time.time()

    def is_ready_for_action(self, delta_time: float) -> bool:
        """Check if the robot is ready to perform an action."""
        return (time.time() - self.last_action_time) >= self.action_cooldown

    def take_damage(self, amount: float) -> None:
        """Reduce robot health by the given amount, considering any active power-ups."""
        active_shield = self.active_powerups.get(PowerupType.SHIELD)
        if active_shield and self.is_powerup_active(PowerupType.SHIELD):
            shield_strength = active_shield.strength
            if shield_strength >= amount:
                # Shield absorbs all damage
                return
            else:
                # Shield absorbs partial damage
                self.health -= (amount - shield_strength)
                active_shield.strength = 0  # Deplete the shield
        else:
            self.health -= amount

        # Apply poison effect if on poison hazard
        if any(hazard.hazard_type == HazardType.POISON_POOL and hazard.is_active(time.time()) for hazard in self.hazards):
            self.health -= 1.0 * delta_time  # Continuous damage over time

        # Ensure health doesn't go below 0
        if self.health < 0:
            self.health = 0

    def heal(self, amount: float) -> None:
        """Heal the robot by the given amount."""
        self.health = min(self.max_health, self.health + amount)

    def apply_powerup(self, powerup: Powerup) -> None:
        """Apply a powerup to the robot."""
        if powerup.powerup_type in self.active_powerups:
            existing = self.active_powerups[powerup.powerup_type]
            # Update duration and strength if powerup is already active
            existing.duration = max(existing.duration, powerup.duration)
            existing.strength = max(existing.strength, powerup.strength)
            existing.activation_time = powerup.activation_time
        else:
            self.active_powerups[powerup.powerup_type] = powerup

    def is_powerup_active(self, powerup_type: PowerupType) -> bool:
        """Check if a specific powerup is active."""
        if powerup_type not in self.active_powerups:
            return False
        powerup = self.active_powerups[powerup_type]
        return powerup.is_active(time.time())

    def use_weapon(self, weapon_type: WeaponType, target_position: Position, delta_time: float) -> None:
        """Use a weapon if available and not on cooldown."""
        if not self.is_ready_for_action(delta_time):
            return

        for weapon in self.weapons:
            if weapon.weapon_type == weapon_type and weapon.is_ready(time.time()):
                # Calculate damage based on distance to target
                distance = self.position.distance_to(target_position)
                # Apply weapon range check
                if distance <= weapon.range:
                    # Apply damage modifier if damage amplifier is active
                    damage_amp = self.active_powerups.get(PowerupType.DAMAGE_AMPLIFIER)
                    if damage_amp and self.is_powerup_active(PowerupType.DAMAGE_AMPLIFIER):
                        weapon_damage = weapon.damage * (1 + damage_amp.strength)
                    else:
                        weapon_damage = weapon.damage

                    # Apply weapon-specific effects
                    if weapon.weapon_type == WeaponType.FLAMETHROWER:
                        # Create fire hazard at target location
                        fire_hazard = Hazard(HazardType.FIRE_RING, 2.0, 5.0)
                        fire_hazard.activate(time.time())
                        self.hazards.append(fire_hazard)

                    # Use the weapon
                    weapon.use(time.time())
                    self.last_action_time = time.time()
                    return

    def update(self, delta_time: float) -> None:
        """Update the robot's state over time."""
        # Update active powerups
        active_powerups_to_remove = []
        for powerup_type, powerup in self.active_powerups.items():
            if not powerup.is_active(time.time()):
                active_powerups_to_remove.append(powerup_type)
        for powerup_type in active_powerups_to_remove:
            del self.active_powerups[powerup_type]

        # Update hazards
        active_hazards_to_remove = []
        for hazard in self.hazards:
            if not hazard.is_active(time.time()):
                active_hazards_to_remove.append(hazard)
        for hazard in active_hazards_to_remove:
            self.hazards.remove(hazard)

    def __str__(self) -> str:
        return f"Robot(name={self.name}, team={self.team.value}, health={self.health:.2f}, position={self.position}, role={self.role})"

    def __repr__(self) -> str:
        return self.__str__()

class AIController(ABC):
    """Abstract base class for AI controllers that manage robot behavior."""
    def __init__(self, robot: Robot):
        self.robot = robot

    @abstractmethod
    def decide_action(self, arena: "CyberArena", delta_time: float) -> None:
        """Abstract method for the AI to decide an action."""
        pass

class BasicAIController(AIController):
    """A simple AI controller for basic robot behavior."""
    def decide_action(self, arena: "CyberArena", delta_time: float) -> None:
        """Decide an action for the robot based on its role and the current game state."""
        if not self.robot.is_alive():
            return

        # Check for nearby enemies
        nearby_enemies = [robot for robot in arena.get_all_robots() if 
                          robot.team != self.robot.team and 
                          self.robot.position.distance_to(robot.position) < 15.0]

        # Check for nearby power-ups
        nearby_powerups = [powerup for powerup in arena.get_all_powerups() if 
                           self.robot.position.distance_to(powerup.position) < 10.0]

        # Check for objectives
        objectives = arena.get_objectives()

        # Make decisions based on role
        if self.robot.role == "Scout":
            # Scouts should move quickly to objectives and gather information
            if objectives:
                target_position = objectives[0].position
                self.robot.move_towards(target_position, delta_time)
            elif nearby_powerups:
                # Move towards the nearest power-up
                nearest_powerup = min(nearby_powerups, 
                                     key=lambda p: self.robot.position.distance_to(p.position))
                self.robot.move_towards(nearest_powerup.position, delta_time)

        elif self.robot.role == "Support":
            # Supports should assist teammates
            if nearby_enemies:
                # Attack the nearest enemy
                nearest_enemy = min(nearby_enemies,
                                  key=lambda r: self.robot.position.distance_to(r.position))
                if self.robot.position.distance_to(nearest_enemy.position) <= 10.0:
                    self.robot.use_weapon(WeaponType.PLASMA, nearest_enemy.position, delta_time)
            else:
                # Follow a teammate
                if arena.team_robots[self.robot.team]:
                    teammate = random.choice(arena.team_robots[self.robot.team])
                    self.robot.move_towards(teammate.position, delta_time)

        elif self.robot.role == "Tank":
            # Tanks should stay in the back and protect teammates
            if nearby_enemies:
                # Attack the nearest enemy
                nearest_enemy = min(nearby_enemies,
                                  key=lambda r: self.robot.position.distance_to(r.position))
                if self.robot.position.distance_to(nearest_enemy.position) <= 15.0:
                    self.robot.use_weapon(WeaponType.SHOCKWAVE, nearest_enemy.position, delta_time)
            else:
                # Move to the center of the team
                if arena.team_robots[self.robot.team]:
                    center_x = sum(robot.position.x for robot in arena.team_robots[self.robot.team]) / len(arena.team_robots[self.robot.team])
                    center_y = sum(robot.position.y for robot in arena.team_robots[self.robot.team]) / len(arena.team_robots[self.robot.team])
                    self.robot.move_towards(Position(center_x, center_y), delta_time)

        elif self.robot.role == "Offense":
            # Offense should attack enemies and objectives
            if objectives:
                # Move towards the objective
                objective = objectives[0]
                self.robot.move_towards(objective.position, delta_time)
                # Attack any enemies near the objective
                for enemy in nearby_enemies:
                    if objective.position.distance_to(enemy.position) < 5.0:
                        if self.robot.position.distance_to(enemy.position) <= 10.0:
                            self.robot.use_weapon(WeaponType.LASER, enemy.position, delta_time)

            elif nearby_enemies:
                # Attack the nearest enemy
                nearest_enemy = min(nearby_enemies,
                                  key=lambda r: self.robot.position.distance_to(r.position))
                if self.robot.position.distance_to(nearest_enemy.position) <= 10.0:
                    self.robot.use_weapon(WeaponType.MISSILE, nearest_enemy.position, delta_time)

        elif self.robot.role == "Utility":
            # Utility robots should use abilities strategically
            if nearby_powerups:
                # Move towards the nearest power-up
                nearest_powerup = min(nearby_powerups,
                                    key=lambda p: self.robot.position.distance_to(p.position))
                self.robot.move_towards(nearest_powerup.position, delta_time)
                if self.robot.position.distance_to(nearest_powerup.position) < 1.0:
                    # Apply the power-up
                    self.robot.apply_powerup(Powerup(nearest_powerup.powerup_type, 10.0, 0.5))

            elif nearby_enemies:
                # Attack the nearest enemy
                nearest_enemy = min(nearby_enemies,
                                  key=lambda r: self.robot.position.distance_to(r.position))
                if self.robot.position.distance_to(nearest_enemy.position) <= 15.0:
                    self.robot.use_weapon(WeaponType.ICE_BLASTER, nearest_enemy.position, delta_time)

class Objective:
    """Base class for all objectives in the game."""
    def __init__(self, name: str, position: Position, team: Optional[Team] = None):
        self.name = name
        self.position = position
        self.team = team  # Team that controls this objective
        self.health = 100.0  # Health for objectives that can be destroyed
        self.max_health = 100.0
        self.active = True  # Whether the objective is active
        self.completed = False  # Whether the objective is completed

    def is_capturable(self) -> bool:
        """Check if the objective can be captured."""
        return self.team is None

    def capture(self, capturing_team: Team) -> None:
        """Capture the objective for the given team."""
        if self.is_capturable() and self.active:
            self.team = capturing_team
            self.completed = True
            # Optional: Add visual/audio feedback for capture

    def take_damage(self, amount: float) -> None:
        """Reduce the objective's health by the given amount."""
        if not self.active:
            return
        self.health -= amount
        if self.health <= 0:
            self.health = 0
            self.active = False
            self.completed = True
            # Optional: Add visual/audio feedback for destruction

    def __str__(self) -> str:
        return f"Objective(name={self.name}, position={self.position}, team={self.team.value if self.team else 'Neutral'}, health={self.health:.2f}, active={self.active}, completed={self.completed})"

    def __repr__(self) -> str:
        return self.__str__()

class CyberArena:
    """Main class for the CyberArena game simulation."""
    def __init__(self, width: float = 100.0, height: float = 100.0):
        self.width = width
        self.height = height
        self.robots: List[Robot] = []
        self.powerups: List[Powerup] = []
        self.hazards: List[Hazard] = []
        self.objectives: List[Objective] = []
        self.team_robots: Dict[Team, List[Robot]] = {team: [] for team in Team}
        self.score: Dict[Team, float] = {team: 0 for team in Team}
        self.last_update_time = time.time()
        self.difficulty_level = 1.0  # Base difficulty level (1.0 = normal)
        self.learning_rate = 0.1  # Rate at which AI learns from previous battles

    def add_robot(self, robot: Robot, controller_class: type = BasicAIController) -> None:
        """Add a robot to the game with an AI controller."""
        controller = controller_class(robot)
        robot.controller = controller
        self.robots.append(robot)
        self.team_robots[robot.team].append(robot)

    def add_powerup(self, powerup: Powerup, position: Position) -> None:
        """Add a powerup to the game at the specified position."""
        powerup.position = position
        self.powerups.append(powerup)

    def add_hazard(self, hazard: Hazard, position: Position) -> None:
        """Add a hazard to the game at the specified position."""
        hazard.position = position
        self.hazards.append(hazard)

    def add_objective(self, objective: Objective) -> None:
        """Add an objective to the game."""
        self.objectives.append(objective)

    def get_all_robots(self) -> List[Robot]:
        """Get all robots in the game."""
        return self.robots

    def get_all_powerups(self) -> List[Powerup]:
        """Get all powerups in the game."""
        return self.powerups

    def get_objectives(self) -> List[Objective]:
        """Get all objectives in the game."""
        return self.objectives

    def get_robots_by_team(self, team: Team) -> List[Robot]:
        """Get all robots on the specified team."""
        return self.team_robots[team]

    def get_robots_in_team(self, robot: Robot) -> List[Robot]:
        """Get all robots in the same team as the given robot."""
        return self.team_robots[robot.team]

    def get_opponents(self, robot: Robot) -> List[Robot]:
        """Get all robots on opposing teams."""
        opponents = []
        for team in Team:
            if team != robot.team:
                opponents.extend(self.team_robots[team])
        return opponents

    def update(self, delta_time: float) -> None:
        """Update the game state for all objects."""
        # Update all robots
        for robot in self.robots:
            robot.update(delta_time)
            # Check for hazards affecting the robot
            for hazard in self.hazards:
                if robot.position.distance_to(hazard.position) <= hazard.radius and hazard.is_active(time.time()):
                    if hazard.hazard_type == HazardType.ELECTRIC_FLOOR:
                        robot.take_damage(0.5 * delta_time)
                    elif hazard.hazard_type == HazardType.POISON_POOL:
                        robot.take_damage(1.0 * delta_time)
                    elif hazard.hazard_type == HazardType.MAGNETIC_FIELD:
                        # Attract robot towards hazard center
                        direction_x = (hazard.position.x - robot.position.x)
                        direction_y = (hazard.position.y - robot.position.y)
                        robot.position.x += direction_x * 0.1 * delta_time
                        robot.position.y += direction_y * 0.1 * delta_time
                    elif hazard.hazard_type == HazardType.GRAVITY_WELL:
                        # Slow robot movement
                        robot.speed *= 0.5
                    elif hazard.hazard_type == HazardType.FIRE_RING:
                        robot.take_damage(2.0 * delta_time)

        # Update all objectives
        for objective in self.objectives:
            if not objective.active:
                continue

            # Check if any robot is near the objective
            nearby_robots = [robot for robot in self.robots if 
                            robot.position.distance_to(objective.position) < 5.0 and 
                            robot.is_alive()]

            if nearby_robots and objective.is_capturable():
                # Capture the objective for the team of the nearest robot
                nearest_robot = min(nearby_robots, 
                                  key=lambda r: robot.position.distance_to(objective.position))
                objective.capture(nearest_robot.team)
                # Optional: Add visual/audio feedback for capture
                # Award points for capturing
                self.score[nearest_robot.team] += 10
                # Update difficulty based on objective capture
                self.update_difficulty()

        # Update all hazards
        for hazard in self.hazards:
            if not hazard.is_active(time.time()):
                self.hazards.remove(hazard)

        # Update AI behavior
        for robot in self.robots:
            if robot.is_alive():
                robot.controller.decide_action(self, delta_time)

        # Check for completed objectives
        if all(obj.completed for obj in self.objectives):
            self.end_game()

    def update_difficulty(self) -> None:
        """Adjust the difficulty based on the current game state."""
        # Calculate team performance
        team_performance = {team: 0 for team in Team}
        for team in Team:
            if len(self.team_robots[team]) > 0:
                # Calculate score per robot
                team_performance[team] = self.score[team] / len(self.team_robots[team])

        # Find the best and worst performing teams
        best_team = max(team_performance, key=team_performance.get)
        worst_team = min(team_performance, key=team_performance.get)

        # Adjust difficulty for each team
        if team_performance[best_team] > 100:  # If best team is performing too well
            # Increase difficulty for best team
            for robot in self.team_robots[best_team]:
                robot.speed *= 1.1  # Make robots move faster
                robot.health *= 0.9  # Reduce health
            # Add more hazards in the best team's area
            for _ in range(2):
                hazard = Hazard(HazardType.ELECTRIC_FLOOR, 5.0, 10.0)
                hazard.position = Position(random.uniform(20, 80), random.uniform(20, 80))
                self.hazards.append(hazard)

        elif team_performance[best_team] < 50 and team_performance[best_team] > 0:  # If best team is struggling
            # Decrease difficulty for best team
            for robot in self.team_robots[best_team]:
                robot.speed *= 0.9  # Make robots move slower
                robot.health *= 1.1  # Increase health
            # Remove some hazards in the best team's area
            electric_hazards = [h for h in self.hazards if h.hazard_type == HazardType.ELECTRIC_FLOOR]
            for hazard in electric_hazards[:2]:  # Remove up to 2 hazards
                self.hazards.remove(hazard)

        # If a team is significantly behind, give them some power-ups
        if team_performance[best_team] > 150 and team_performance[best_team] - team_performance[worst_team] > 100:
            for robot in self.team_robots[worst_team]:
                shield_powerup = Powerup(PowerupType.SHIELD, 10.0, 0.8)
                shield_powerup.activation_time = time.time()
                robot.apply_powerup(shield_powerup)

    def end_game(self) -> None:
        """Handle the end of the game."""
        print("Game Over!")
        # Calculate final scores
        for team in Team:
            print(f"{team.value} Team Score: {self.score[team]:.2f}")

        # Determine the winning team
        winning_team = max(self.score, key=self.score.get)
        print(f"Winning Team: {winning_team.value}")
        # Apply learning updates to AI controllers
        for robot in self.robots:
            # Adjust AI learning rate based on team performance
            if team_success[robot.team] > 1.0:
                robot.controller.learning_rate = min(robot.controller.learning_rate + 0.05, 0.3)
            else:
                robot.controller.learning_rate = max(robot.controller.learning_rate - 0.05, 0.1)

            # Adjust individual robot strategy based on performance
            if robot_performance[robot.name]['damage_dealt'] > 15.0:
                # Robot is effective in combat
                robot.role = 'Offense'
                robot.speed *= 1.1
                robot.health *= 0.95
            elif robot_performance[robot.name]['objectives_contributed'] > 2:
                # Robot is good at objectives
                robot.role = 'Scout'
                robot.speed *= 1.2
                robot.health *= 0.9
            elif robot_performance[robot.name]['team_assists'] > 1:
                # Robot is a good team player
                robot.role = 'Support'
                robot.speed *= 0.95
                robot.health *= 1.05
            else:
                # Default or balanced role
                robot.role = 'Tank'
                robot.speed *= 0.9
                robot.health *= 1.1

            # Record lessons for future use
            if hasattr(robot.controller, 'record_lesson'):
                robot.controller.record_lesson(robot_performance[robot.name])

        # Provide feedback for AI learning
        self.update_ai_learning()

