class Objective:
    """Base class for all objectives in the game."""
    def __init__(self, name: str, position: Position, team: Optional[Team] = None):
        self.name = name
        self.position = position
        self.team = team  # Team that controls this objective
        self.health = 100.0  # Health for objectives that can be destroyed
        self.max_health = 100.0
        self.active = True  # Whether the objective is active
        self.completed = False  # Whether the objective is completed

    def is_capturable(self) -> bool:
        """Check if the objective can be captured."""
        return self.team is None

    def capture(self, capturing_team: Team) -> None:
        """Capture the objective for the given team."""
        if self.is_capturable() and self.active:
            self.team = capturing_team
            self.completed = True
            # Optional: Add visual/audio feedback for capture

    def take_damage(self, amount: float) -> None:
        """Reduce the objective's health by the given amount."""
        if not self.active:
            return
        self.health -= amount
        if self.health <= 0:
            self.health = 0
            self.active = False
            self.completed = True
            # Optional: Add visual/audio feedback for destruction

    def __str__(self) -> str:
        return f"Objective(name={self.name}, position={self.position}, team={self.team.value if self.team else 'Neutral'}, health={self.health:.2f}, active={self.active}, completed={self.completed})"

    def __repr__(self) -> str:
        return self.__str__()

