    def update_buffs(self):
        current_time = time.time()
        expired_buffs = []
        for buff, end_time in self.buffs_timer.items():
            if current_time > end_time:
                expired_buffs.append(buff)

        for buff in expired_buffs:
            self.buffs.remove(buff)
            del self.buffs_timer[buff]
            print(f"{self.name}'s {buff.value} buff has expired.")

    def calculate_team_contribution(self, team):
        # Calculate this robot's contribution to the team based on score and objective progress
        return self.score / sum(robot.score for robot in team.robots) if sum(robot.score for robot in team.robots) > 0 else 0

