# Class representing an objective
class Objective:
    def __init__(self, objective_type, position):
        self.objective_type = objective_type
        self.position = position
        self.is_complete = False

    def complete(self):
        self.is_complete = True
        print(f"Objective {self.objective_type.value} completed!")

# Class representing a power-up
class PowerUp:
    def __init__(self, power_up_type, position):
        self.power_up_type = power_up_type
        self.position = position
        self.is_active = True

    def activate(self, robot):
        if self.is_active:
            robot.apply_buff(self.power_up_type)
            self.is_active = False
            print(f"{robot.name} activated {self.power_up_type.value} power-up at position {self.position}")

# Class representing an environmental hazard
class Hazard:
    def __init__(self, hazard_type, position):
        self.hazard_type = hazard_type
        self.position = position
        self.is_active = True

    def trigger(self, robot):
        if self.is_active:
            # Apply effects based on hazard type
            if self.hazard_type == HazardType.LAND_MINE:
                robot.take_damage(30)
                print(f"{robot.name} triggered a land mine at {self.position} and took 30 damage!")
            elif self.hazard_type == HazardType.ELECTRIC_FIELD:
                robot.take_damage(15)
                print(f"{robot.name} was struck by an electric field at {self.position} and took 15 damage!")
            elif self.hazard_type == HazardType.ICE_PATCH:
                robot.speed = max(robot.speed * 0.5, 0.1)  # Reduce speed by 50%
                print(f"{robot.name} stepped on an ice patch at {self.position} and is now moving slower!")

# Class representing a team
class Team:
    def __init__(self, name):
        self.name = name
        self.robots = []
        self.score = 0
        self.wins = 0

    def add_robot(self, robot):
        self.robots.append(robot)

    def update(self, environment):
        for robot in self.robots:
            if robot.is_active:
                robot.update(environment)
                robot.update_buffs()

    def complete_objective(self):
        self.score += 100
        self.wins += 1
        print(f"Team {self.name} has completed an objective! Score: {self.score}, Wins: {self.wins}")

# Class representing a battle arena
class BattleArena:
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.teams = []
        self.robots = []
        self.objective = None
        self.power_ups = []
        self.hazards = []
        self.combat_log = []

    def add_team(self, team):
        self.teams.append(team)
        for robot in team.robots:
            self.robots.append(robot)

    def add_objective(self, objective):
        self.objective = objective

    def add_power_up(self, power_up):
        self.power_ups.append(power_up)

    def add_hazard(self, hazard):
        self.hazards.append(hazard)

    def is_in_combat(self, robot):
        # Check if there are any active opponents nearby
        for enemy in self.robots:
            if enemy.team != robot.team and enemy.is_active:
                distance = np.linalg.norm(robot.position - enemy.position)
                if distance < 10:  # Combat range
                    return True
        return False

    def get_closest_opponent(self, robot):
        closest_opponent = None
        min_distance = float('inf')
        for enemy in self.robots:
            if enemy.team != robot.team and enemy.is_active:
                distance = np.linalg.norm(robot.position - enemy.position)
                if distance < min_distance:
                    min_distance = distance
                    closest_opponent = enemy
        return closest_opponent

    def has_objective(self):
        return self.objective is not None and not self.objective.is_complete

    def get_objective_position(self):
        if self.objective:
            return self.objective.position
        return None

    def update(self):
        # Update all teams
        for team in self.teams:
            team.update(self)

        # Check for power-up interactions
        for power_up in self.power_ups:
            if power_up.is_active:
                for robot in self.robots:
                    if robot.is_active and np.linalg.norm(robot.position - power_up.position) < 1.0:
                        power_up.activate(robot)
                        break

        # Check for hazard interactions
        for hazard in self.hazards:
            if hazard.is_active:
                for robot in self.robots:
                    if robot.is_active and np.linalg.norm(robot.position - hazard.position) < 1.5:
                        hazard.trigger(robot)
                        break

        # Check if objective is completed
        if self.objective and not self.objective.is_complete:
            for robot in self.robots:
                if robot.is_active and np.linalg.norm(robot.position - self.objective.position) < 2.0:
                    self.objective.complete()
                    for team in self.teams:
                        if robot in team.robots:
                            team.complete_objective()
                    break

        # Update scores based on teamwork
        self.update_team_scores()

    def update_team_scores(self):
        for team in self.teams:
            total_contribution = 0
            for robot in team.robots:
                if robot.is_active:
                    contribution = robot.calculate_team_contribution(team)
                    total_contribution += contribution
                    robot.score += int(contribution * 10)  # Add score based on contribution

            # Add bonus for teamwork
            team.score += int(total_contribution * 50)
            print(f"Team {team.name} score updated: {team.score}")

# Class for adaptive difficulty system
class AdaptiveDifficulty:
    def __init__(self, arena):
        self.arena = arena
        self.difficulty_level = 1  # Start at level 1
        self.max_difficulty = 5  # Maximum difficulty level

    def update_difficulty(self):
        # Calculate performance metrics
        total_health = sum(robot.health for robot in self.arena.robots)
        avg_health = total_health / len(self.arena.robots) if self.arena.robots else 0
        survival_rate = sum(1 for robot in self.arena.robots if robot.is_active) / len(self.arena.robots)

        # Adjust difficulty based on performance
        if avg_health > 75 and survival_rate > 0.7:
            # Easy - increase difficulty
            self.difficulty_level = min(self.difficulty_level + 1, self.max_difficulty)
            print(f"Difficulty increased to level {self.difficulty_level}")
            self._increase_difficulty()
        elif avg_health < 40 or survival_rate < 0.3:
            # Hard - decrease difficulty
            self.difficulty_level = max(self.difficulty_level - 1, 1)
            print(f"Difficulty decreased to level {self.difficulty_level}")
            self._decrease_difficulty()

    def _increase_difficulty(self):
        # Increase enemy strength, add more hazards, etc.
        for robot in self.arena.robots:
            if robot.team == "AI":
                robot.health += 10
                robot.speed += 0.2
                if robot.weapon == WeaponType.PLASMA:
                    robot.buffs.append(PowerUpType.DAMAGE_BOOST)

        # Add more hazards
        for _ in range(2):
            hazard_type = random.choice(list(HazardType))
            position = np.random.rand(2) * [self.arena.width, self.arena.height]
            self.arena.add_hazard(Hazard(hazard_type, position))

    def _decrease_difficulty(self):
        # Decrease enemy strength, remove some hazards, etc.
        for robot in self.arena.robots:
            if robot.team == "AI":
                robot.health -= 10
                robot.speed = max(robot.speed - 0.2, 0.5)
                if PowerUpType.DAMAGE_BOOST in robot.buffs:
                    robot.buffs.remove(PowerUpType.DAMAGE_BOOST)

        # Remove some hazards
        if len(self.arena.hazards) > 2:
            for _ in range(2):
                self.arena.hazards.pop()

# Class for learning and strategy adaptation
class LearningSystem:
    def __init__(self, arena):
        self.arena = arena
        self.memory = {}  # Store experiences and strategies

    def learn(self):
        # Analyze recent battles and update strategies
        for robot in self.arena.robots:
            if robot.is_active:
                # Store robot's performance
                self._store_experience(robot)
                # Update strategies based on performance
                self._update_strategies(robot)

    def _store_experience(self, robot):
        # Store the robot's recent actions and outcomes
        experience = {
            "position": robot.position.copy(),
            "health": robot.health,
            "score": robot.score,
            "buffs": robot.buffs.copy(),
            "last_action": robot.last_action if hasattr(robot, "last_action") else "none"
        }
        self.memory[robot.name] = experience

    def _update_strategies(self, robot):
        # Update robot's strategy based on past experiences
        if robot.name in self.memory:
            previous_experience = self.memory[robot.name]

            # Example of strategy adaptation:
            # If robot took too much damage, try to find cover
            if robot.health < previous_experience["health"] - 20:
                print(f"{robot.name} learned to find cover after taking significant damage.")
                robot.last_action = "find cover"

            # If robot's score improved, reinforce the strategy
            if robot.score > previous_experience["score"]:
                print(f"{robot.name} learned to continue current strategy as it improves score.")
                robot.last_action = previous_experience["last_action"]

# Main simulation class
class CyberArena:
    def __init__(self, width, height, duration=60):
        self.arena = BattleArena(width, height)
        self.duration = duration  # in seconds
        self.start_time = None
        self.difficulty_system = AdaptiveDifficulty(self.arena)
        self.learning_system = LearningSystem(self.arena)

    def setup(self):
        # Create teams
        team1 = Team("Team Alpha")
        robot1 = Robot("Alpha-1", "Team Alpha", RobotType.WARRIOR)
        robot2 = Robot("Alpha-2", "Team Alpha", RobotType.TANK)
        robot3 = Robot("Alpha-3", "Team Alpha", RobotType.SUPPORT)
        robot4 = Robot("Alpha-4", "Team Alpha", RobotType.SCOUT)
        team1.add_robot(robot1)
        team1.add_robot(robot2)
        team1.add_robot(robot3)
        team1.add_robot(robot4)

        team2 = Team("Team Omega")
        robot5 = Robot("Omega-1", "Team Omega", RobotType.WARRIOR)
