        power_up_positions = [
            np.array([20, 20]),
            np.array([80, 20]),
            np.array([20, 80]),
            np.array([80, 80])
        ]

        for position in power_up_positions:
            power_up_type = random.choice(list(PowerUpType))
            self.arena.add_power_up(PowerUp(power_up_type, position))

        # Add hazards
        hazard_positions = [
            np.array([30, 30]),
