            np.array([70, 70])
        ]

        for position in hazard_positions:
            hazard_type = random.choice(list(HazardType))
            self.arena.add_hazard(Hazard(hazard_type, position))

        # Initialize robot positions
        team1_positions = [
            np.array([10, 10]),
            np.array([10, 90]),
            np.array([90, 10]),
            np.array([90, 90])
        ]

        for i, robot in enumerate(team1.robots):
            robot.position = team1_positions[i]

        team2_positions = [
            np.array([10, 50]),
            np.array([90, 50]),
            np.array([50, 10]),
