        ]

        for i, robot in enumerate(team2.robots):
            robot.position = team2_positions[i]

        print("CyberArena initialized with:")
        print(f"- {len(team1.robots)} robots in Team Alpha")
        print(f"- {len(team2.robots)} robots in Team Omega")
        print(f"- {len(self.arena.power_ups)} power-ups")
        print(f"- {len(self.arena.hazards)} hazards")
        print(f"- Objective: {self.arena.objective.objective_type.value}")

    def run(self):
        self.start_time = time.time()
        print(f"CyberArena battle started! Duration: {self.duration} seconds")

        while time.time() - self.start_time < self.duration:
            # Update the arena
            self.arena.update()

            # Adjust difficulty
            self.difficulty_system.update_difficulty()

            # Learn and adapt strategies
            self.learning_system.learn()

            # Display current status
            self.display_status()

            # Add some delay to simulate real-time aspect
            time.sleep(0.1)

        print("CyberArena battle ended!")
        self.display_results()

