# Class representing an objective
class Objective:
    def __init__(self, objective_type, position):
        self.objective_type = objective_type
        self.position = position
        self.is_complete = False

    def complete(self):
        self.is_complete = True
        print(f"Objective {self.objective_type.value} completed!")

# Class representing a power-up
class PowerUp:
    def __init__(self, power_up_type, position):
        self.power_up_type = power_up_type
        self.position = position
        self.is_active = True

    def activate(self, robot):
        if self.is_active:
            robot.apply_buff(self.power_up_type)
            self.is_active = False
            print(f"{robot.name} activated {self.power_up_type.value} power-up at position {self.position}")

# Class representing an environmental hazard
class Hazard:
    def __init__(self, hazard_type, position):
        self.hazard_type = hazard_type
        self.position = position
        self.is_active = True

    def trigger(self, robot):
        if self.is_active:
            # Apply effects based on hazard type
            if self.hazard_type == HazardType.LAND_MINE:
                robot.take_damage(30)
                print(f"{robot.name} triggered a land mine at {self.position} and took 30 damage!")
            elif self.hazard_type == HazardType.ELECTRIC_FIELD:
                robot.take_damage(15)
                print(f"{robot.name} was struck by an electric field at {self.position} and took 15 damage!")
            elif self.hazard_type == HazardType.ICE_PATCH:
                robot.speed = max(robot.speed * 0.5, 0.1)  # Reduce speed by 50%
                print(f"{robot.name} stepped on an ice patch at {self.position} and is now moving slower!")

