# Concrete objective class - Flag Capture
class FlagCapture(Objective):
    def __init__(self, name, position, flag_position):
        super().__init__(name, position)
        self.flag_position = np.array(flag_position)
        self.carried_by = None

    def check_completion(self, robots):
        """Flag Capture objective is completed when a robot from the opposing team returns to base with the flag"""
        for robot in robots:
            if robot.position[0] <= 0 and self.carried_by and self.carried_by.team != robot.team:
                self.completed = True
                return f"{self.name} objective completed by {self.carried_by.name} from team {self.carried_by.team}"
        return ""

# Concrete objective class - Base Defense
class BaseDefense(Objective):
