        self.base_position = np.array(base_position)
        self.base_health = 100

    def check_completion(self, robots):
        """Base Defense objective is completed when the base is destroyed by the opposing team"""
        for robot in robots:
            distance = np.linalg.norm(robot.position - self.base_position)
            if distance < 2 and robot.weapon and robot.weapon.weapon_type == WeaponType.PLASMA_RIFLE:
