# Adaptive difficulty system class
class AdaptiveDifficulty:
    def __init__(self, robots, difficulty_factor=1.0):
        self.robots = robots
        self.difficulty_factor = difficulty_factor
        self.performance_metrics = {}

    def update_difficulty(self):
        """Adjust difficulty based on robot performance"""
        for robot in self.robots:
            self.performance_metrics[robot.name] = {
                "accuracy": random.uniform(0.7, 0.95),  # Simulated accuracy
                "survival": robot.health / robot.__class__.__init__.__defaults__[2],  # Health ratio
                "energy_efficiency": robot.energy / robot.__class__.__init__.__defaults__[3]  # Energy ratio
            }

        # Adjust difficulty factor based on average performance
        average_performance = np.mean([
            self.performance_metrics[robot.name]["accuracy"] * 0.4 +
            self.performance_metrics[robot.name]["survival"] * 0.3 +
            self.performance_metrics[robot.name]["energy_efficiency"] * 0.3
            for robot in self.robots
        ])

        if average_performance > 0.8:
            self.difficulty_factor *= 1.1  # Increase difficulty if performance is high
        elif average_performance < 0.5:
            self.difficulty_factor *= 0.9  # Decrease difficulty if performance is low

        return f"Difficulty factor updated to {self.difficulty_factor:.2f}"

    def apply_difficulty(self):
        """Apply difficulty changes to robot attributes"""
        for robot in self.robots:
            # Increase enemy damage and health based on difficulty factor
            if robot.team != self.robots[0].team:  # Assuming first robot is player's team
                robot.health += 10 * self.difficulty_factor
                robot.energy += 5 * self.difficulty_factor
                if robot.weapon:
                    robot.weapon.damage += 5 * self.difficulty_factor
            # Adjust movement speed for all robots
            robot.movement_speed += 0.5 * self.difficulty_factor
        return f"Applied difficulty changes with factor {self.difficulty_factor:.2f}"

# Power-up class with different types and effects
class PowerUp:
    def __init__(self, position, power_up_type):
        self.position = np.array(position)
        self.power_up_type = power_up_type
        self.active = True

    def apply_effect(self, robot):
        """Apply the power-up effect to a robot"""
        if not self.active:
            return f"Power-up {self.power_up_type.value} is already used"

        if self.power_up_type == "HEALTH_BOOST":
            robot.health += 30
            return f"{robot.name} used Health Boost - Health increased to {robot.health}"
        elif self.power_up_type == "ENERGY_REFILL":
            robot.energy = min(robot.energy + 50, robot.__class__.__init__.__defaults__[3])
            return f"{robot.name} used Energy Refill - Energy increased to {robot.energy}"
        elif self.power_up_type == "SPEED_BOOST":
            robot.movement_speed += 3
            return f"{robot.name} used Speed Boost - Movement speed increased to {robot.movement_speed}"
        elif self.power_up_type == "INVISIBILITY":
            robot.invisible = True
            return f"{robot.name} used Invisibility - Became invisible to enemies"
        elif self.power_up_type == "REPAIR_KIT":
            robot.health = min(robot.health + 20, robot.__class__.__init__.__defaults__[2])
            return f"{robot.name} used Repair Kit - Health increased to {robot.health}"
        else:
            return f"Unknown power-up type: {self.power_up_type.value}"

    def reset(self):
        """Reset the power-up for reuse"""
        self.active = True
        return f"Power-up {self.power_up_type.value} reset"

# Environmental hazard class with different types and effects
class Hazard:
    def __init__(self, position, hazard_type):
        self.position = np.array(position)
        self.hazard_type = hazard_type
        self.active = True

    def apply_effect(self, robot):
        """Apply the hazard effect to a robot"""
        if not self.active:
            return f"Hazard {self.hazard_type.value} is already active"

        if self.hazard_type == "LAVA":
            robot.health -= 10
            return f"{robot.name} was damaged by lava - Health decreased to {robot.health}"
        elif self.hazard_type == "ELECTRIC_FLOOR":
            robot.energy -= 20
            return f"{robot.name} lost energy to the electric floor - Energy decreased to {robot.energy}"
        elif self.hazard_type == "TOXIC_CLOUD":
            robot.health -= 5
            robot.energy -= 5
            return f"{robot.name} was affected by toxic cloud - Health: {robot.health}, Energy: {robot.energy}"
        elif self.hazard_type == "GRAVITY_WELL":
            robot.movement_speed -= 2
            return f"{robot.name} is affected by gravity well - Movement speed decreased to {robot.movement_speed}"
        else:
            return f"Unknown hazard type: {self.hazard_type.value}"

    def reset(self):
        """Reset the hazard for reuse"""
        self.active = True
        return f"Hazard {self.hazard_type.value} reset"

