            team_a_robots = [robot for robot in self.robots if robot.team == "Team A"]
            team_b_robots = [robot for robot in self.robots if robot.team == "Team B"]

            if not team_a_robots:
                self.battle_log.append("Team A has been eliminated! Team B wins!")
                break
            elif not team_b_robots:
                self.battle_log.append("Team B has been eliminated! Team A wins!")
                break

        self.battle_log.append("\nSimulation complete!")
        self.battle_log.append(f"Final Score: {self.score}")
        self.battle_log.append(f"Winning team: {max(self.score, key=self.score.get)}")
        self.battle_log.append(f"Total rounds played: {self.round_number}")
        self.battle_log.append(f"Number of surviving robots: {len(self.robots)}")

        return self.battle_log

