from abc import ABC, abstractmethod

class Vector2:
    """Represents a 2D vector for position and movement calculations."""

    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vector2(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2(self.x / scalar, self.y / scalar)

    def length(self):
        """Returns the magnitude of the vector."""
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        """Returns a unit vector in the same direction."""
        length = self.length()
        if length == 0:
            return Vector2(0, 0)
        return Vector2(self.x / length, self.y / length)

    def distance_to(self, other):
        """Returns the distance between this vector and another vector."""
        return (self - other).length()


class Weapon:
    """Abstract base class for all types of weapons in the arena."""

    def __init__(self, name, damage, range, cool_down):
        self.name = name
        self.damage = damage
        self.range = range  # For ranged weapons; melee is typically short range
        self.cool_down = cool_down  # Time between uses
        self.last_used = -float('inf')  # Last time the weapon was used

    @abstractmethod
    def use(self, user, target):
        """Abstract method to be implemented by subclasses to define how the weapon is used."""
        pass

    def is_ready(self):
        """Check if the weapon is ready to be used based on its cool-down."""
        return time.time() - self.last_used >= self.cool_down


class RangedWeapon(Weapon):
    """Represents a weapon that can attack from a distance."""

    def __init__(self, name, damage, range, cool_down, ammo=100):
        super().__init__(name, damage, range, cool_down)
        self.ammo = ammo  # Ammo capacity for ranged weapons

    def use(self, user, target):
        """Fire a projectile at the target if within range and ammo is available."""
        if not self.is_ready():
            print(f"{user.name}'s {self.name} is on cool-down.")
            return

        if self.ammo <= 0:
            print(f"{user.name}'s {self.name} is out of ammo.")
            return

        distance = user.position.distance_to(target.position)
        if distance > self.range:
            print(f"{user.name}'s {self.name} is out of range.")
            return

        # Attack logic
