class Robot:
    """Represents an AI-controlled robot in the CyberArena."""

    def __init__(self, name, team, position):
        self.name = name
        self.team = team
        self.position = position
        self.health = 100
        self.max_health = 100
        self.weapon = None
        self.power_ups = []
        self.skills = []
        self.arena = None  # Reference to the arena
        self.strategy = "basic"  # Strategy: basic, aggressive, defensive, etc.

    def set_arena(self, arena):
        """Assign the arena this robot belongs to."""
        self.arena = arena

    def set_weapon(self, weapon):
        """Assign a weapon to the robot."""
        self.weapon = weapon

    def take_damage(self, amount):
        """Reduce the robot's health when attacked."""
        self.health -= amount
        if self.health <= 0:
            print(f"{self.name} has been destroyed!")
            self.arena.remove_robot(self)
            return True
        return False

    def heal(self, amount):
        """Increase the robot's health up to the max limit."""
        self.health = min(self.max_health, self.health + amount)

    def move_towards(self, target_position, speed=1.0):
        """Move the robot towards a target position at a certain speed."""
        direction = (target_position - self.position).normalize()
        self.position += direction * speed

    def choose_target(self, enemies):
        """Choose a target based on strategy and proximity."""
        if not enemies:
            return None
        if self.strategy == "aggressive":
            return random.choice(enemies)  # Attack a random enemy
        elif self.strategy == "defensive":
            # Target the closest enemy
            return min(enemies, key=lambda e: self.position.distance_to(e.position))
        elif self.strategy == "support":
            # Support strategy (no direct combat)
            return None
        else:
            # Basic strategy: choose a random enemy
            return random.choice(enemies)

    def use_power_up(self, power_up_index):
        """Use a specific power-up from the robot's inventory."""
        if power_up_index < len(self.power_ups):
            power_up = self.power_ups.pop(power_up_index)
            power_up.activate(self)

    def update(self):
        """Update the robot's behavior and strategy in real-time."""
        if self.strategy in ["aggressive", "basic"]:
            enemies = [robot for robot in self.arena.robots if robot.team != self.team]
            target = self.choose_target(enemies)
            if target:
                if self.weapon and self.weapon.is_ready():
                    self.weapon.use(self, target)
                else:
                    self.move_towards(target.position, speed=0.5)
        elif self.strategy == "defensive":
            allies = [robot for robot in self.arena.robots if robot.team == self.team]
            # Stay near allies
            if allies:
                center_position = Vector2(sum(robot.position.x for robot in allies) / len(allies),
                                          sum(robot.position.y for robot in allies) / len(allies))
                self.move_towards(center_position, speed=0.3)
        elif self.strategy == "support":
            pass  # Support robot may have other tasks like healing or buffing allies


class PowerUp:
