class FlagCaptureObjective(Objective):
    """Objective for capturing a flag in the arena."""

    def __init__(self, name, position, team):
        super().__init__(name, position)
        self.team = team
        self.carried_by = None  # Robot carrying the flag

    def check_completion(self, arena):
        """Check if the flag is carried to the enemy team's base."""
        if self.carried_by and self.carried_by.team != self.team:
