        # Feedback loop: improve strategies based on performance
        for team in self.teams:
            team_score = team.score
            if team_score > 500:
                # Increase robot skill and strategy complexity
                for robot in team.robots:
                    robot.strategy = "aggressive"
                    robot.weapon = RangedWeapon("Plasma Cannon", 30, 25, 2.0)
