    DEFEND_BASE = 2
    ESCORT_PAYLOAD = 3
    DESTROY_TURRET = 4

# Base class for all weapons in the game
class Weapon:
    def __init__(self, weapon_type, damage, energy_cost):
        self.weapon_type = weapon_type  # "ranged" or "melee"
        self.damage = damage
        self.energy_cost = energy_cost
        self.cooldown = 0  # Seconds between attacks

    def use(self, robot):
        """Simulate using the weapon by the robot."""
        if robot.energy >= self.energy_cost:
            robot.energy -= self.energy_cost
            return self.damage
        return 0  # Not enough energy to use the weapon

# Ranged weapon with different properties
class RangedWeapon(Weapon):
    def __init__(self, damage, energy_cost):
        super().__init__("ranged", damage, energy_cost)
        self.range = 200  # Attack range for ranged weapons
        self.accuracy = 0.8  # Accuracy chance (0.0 to 1.0)

    def use(self, robot, target):
        """Simulate using a ranged weapon on a target."""
        if robot.energy >= self.energy_cost and robot.calculate_distance(target) <= self.range:
            robot.energy -= self.energy_cost
            if random.random() < self.accuracy:
                return self.damage
            return 0  # Missed the shot
        return 0  # Not enough energy or out of range

# Melee weapon with different properties
class MeleeWeapon(Weapon):
    def __init__(self, damage, energy_cost):
        super().__init__("melee", damage, energy_cost)
        self.critical_hit_chance = 0.2  # Chance for a critical hit

    def use(self, robot, target):
        """Simulate using a melee weapon on a target."""
        if robot.energy >= self.energy_cost and robot.calculate_distance(target) <= COMBAT_RADIUS:
            robot.energy -= self.energy_cost
            if random.random() < self.critical_hit_chance:
                return int(self.damage * 1.5)  # Critical hit
            return self.damage
        return 0  # Not enough energy or out of melee range

# Base class for all robots in the CyberArena
class Robot:
    def __init__(self, name, team, role):
        self.name = name
        self.team = team  # Team color ("red", "blue", "green", "yellow")
        self.health = MAX_HEALTH
        self.energy = MAX_ENERGY
        self.position = (random.randint(0, SCREEN_WIDTH), random.randint(0, SCREEN_HEIGHT))
        self.weapon = random.choice([RangedWeapon(20, 10), MeleeWeapon(30, 5)])
        self.role = role  # RobotRole enum (ATTACKER, DEFENDER, SUPPORT, RECON)
        self.objective = None  # Current objective (Objective enum)
        self.learning_data = []  # Data for learning and adaptation

    def calculate_distance(self, other):
        """Calculate distance between this robot and another robot or point."""
        if isinstance(other, Robot):
            return math.hypot(self.position[0] - other.position[0], self.position[1] - other.position[1])
        else:
            return math.hypot(self.position[0] - other[0], self.position[1] - other[1])

    def move_toward(self, target_position):
        """Move robot toward a target position."""
        # Simple movement logic - more sophisticated could be implemented
        x, y = self.position
        tx, ty = target_position
        if x < tx:
            x += 5
        elif x > tx:
            x -= 5
        if y < ty:
            y += 5
        elif y > ty:
            y -= 5
        self.position = (x, y)

    def attack(self, target):
        """Attack another robot."""
        if self.weapon.weapon_type == "ranged":
            return self.weapon.use(self, target)
        else:  # Melee weapon
            return self.weapon.use(self, target)

    def heal(self, amount):
        """Heal the robot by a given amount."""
        self.health = min(MAX_HEALTH, self.health + amount)

    def receive_damage(self, amount):
        """Receive damage from an attack."""
        self.health = max(0, self.health - amount)
        if self.health <= 0:
            self.die()

    def die(self):
        """Handle robot death."""
        print(f"{self.name} has died!")
        # Reset position and health for next round
        self.health = MAX_HEALTH
        self.energy = MAX_ENERGY
        self.position = (random.randint(0, SCREEN_WIDTH), random.randint(0, SCREEN_HEIGHT))

    def learn_from_battle(self, battle_results):
        """Collect data from battle for future adaptation."""
        self.learning_data.append(battle_results)
        # Simple adaptation rule: switch to a different weapon type if consistently failing
        if random.random() < 0.2:  # 20% chance to adapt
            if self.weapon.weapon_type == "ranged":
                self.weapon = MeleeWeapon(30, 5)
            else:
                self.weapon = RangedWeapon(20, 10)

# Class for representing teams in the CyberArena
class Team:
    def __init__(self, team_color):
        self.team_color = team_color
        self.robots = []
        self.score = 0
        self.objective = None  # Current team objective (Objective enum)

    def add_robot(self, robot):
        """Add a robot to this team."""
        self.robots.append(robot)

    def update_score(self, points):
        """Update the team score by adding points."""
        self.score += points

    def reset(self):
        """Reset the team for the next round."""
        for robot in self.robots:
            robot.health = MAX_HEALTH
            robot.energy = MAX_ENERGY
            robot.position = (random.randint(0, SCREEN_WIDTH), random.randint(0, SCREEN_HEIGHT))

# Class for managing the CyberArena simulation
class CyberArena:
    def __init__(self, teams):
        self.teams = teams
        self.round_number = 1
        self.game_over = False
        self.time_limit = 300  # 5 minutes per round
        self.power_ups = []  # List of active power-ups
        self.hazards = []  # List of active hazards

    def start(self):
        """Start the CyberArena simulation."""
        print("Welcome to CyberArena!")
        self.assign_initial_objectives()
        while not self.game_over:
            self.run_round()
            self.round_number += 1
            self.assign_new_objectives()
            self.reset_teams()
            print(f"\nRound {self.round_number} results:")
            for team in self.teams:
                print(f"{team.team_color} team score: {team.score}")
            if self.is_game_over():
                self.game_over = True
                print("\nGame Over!")

    def run_round(self):
        """Run a single round of the simulation."""
        start_time = time.time()
        print(f"\nRound {self.round_number} started!")
        while time.time() - start_time < self.time_limit and not self.is_objective_complete():
            self.update_simulation()
            time.sleep(0.5)  # Simulate real-time updates
        self.resolve_objective()

    def assign_initial_objectives(self):
        """Assign initial objectives to each team."""
        for team in self.teams:
            team.objective = random.choice(list(Objective))
            for robot in team.robots:
                robot.objective = team.objective

    def assign_new_objectives(self):
        """Assign new objectives to each team after a round."""
        for team in self.teams:
            team.objective = random.choice(list(Objective))
            for robot in team.robots:
                robot.objective = team.objective
                robot.role = random.choice(list(RobotRole))

    def reset_teams(self):
        """Reset all teams for the next round."""
        for team in self.teams:
            team.reset()

    def update_simulation(self):
        """Update the simulation state."""
        # Update robot positions and actions
        for team in self.teams:
            for robot in team.robots:
                self.handle_robot_action(robot)
                # Check for power-ups and hazards
                self.apply_power_ups(robot)
                self.apply_hazards(robot)

    def handle_robot_action(self, robot):
        """Handle a robot's action based on its objective and role."""
        if robot.health <= 0:
            return

        # Simple AI logic for robot behavior
        if robot.objective == Objective.CAPTURE_FLAG:
            if robot.role == RobotRole.ATTACKER:
        # Use the team's strategy manager for coordinated actions
        if hasattr(robot.team, 'strategy_manager'):
            robot.team.strategy_manager.update_battlefield(robot)
            action = robot.team.strategy_manager.get_robot_action(robot)
            if action:
                action.execute(robot)
                return
                self.handle_capture_flag_attacker(robot)
            elif robot.role == RobotRole.DEFENDER:
                self.handle_capture_flag_defender(robot)
            else:
                self.handle_capture_flag_support(robot)
        elif robot.objective == Objective.DEFEND_BASE:
            if robot.role == RobotRole.ATTACKER:
                self.handle_defend_base_attacker(robot)
            elif robot.role == RobotRole.DEFENDER:
                self.handle_defend_base_defender(robot)
            else:
                self.handle_defend_base_support(robot)
        elif robot.objective == Objective.ESCORT_PAYLOAD:
            if robot.role == RobotRole.ATTACKER:
                self.handle_escort_payload_attacker(robot)
            elif robot.role == RobotRole.DEFENDER:
                self.handle_escort_payload_defender(robot)
            else:
                self.handle_escort_payload_support(robot)
        elif robot.objective == Objective.DESTROY_TURRET:
            if robot.role == RobotRole.ATTACKER:
                self.handle_destroy_turret_attacker(robot)
            elif robot.role == RobotRole.DEFENDER:
                self.handle_destroy_turret_defender(robot)
            else:
                self.handle_destroy_turret_support(robot)

    def handle_capture_flag_attacker(self, robot):
        """Handle an attacker robot in a capture flag objective."""
        other_teams = [t for t in self.teams if t.team_color != robot.team]
        # Find the nearest enemy robot
        nearest_enemy = min([r for t in other_teams for r in t.robots if r.health > 0], 
                            key=lambda r: robot.calculate_distance(r), 
                            default=None)

        # Find the flag position (simplified as a random point in the arena)
        flag_position = (random.randint(0, SCREEN_WIDTH), random.randint(0, SCREEN_HEIGHT))

        # Determine action based on distance to flag and enemies
        if nearest_enemy and robot.calculate_distance(nearest_enemy) <= COMBAT_RADIUS:
            damage = robot.attack(nearest_enemy)
            print(f"{robot.name} attacks {nearest_enemy.name} for {damage} damage!")
        else:
            robot.move_toward(flag_position)
            if robot.calculate_distance(flag_position) < 10:
                print(f"{robot.name} has captured the flag!")

    def handle_capture_flag_defender(self, robot):
        """Handle a defender robot in a capture flag objective."""
        flag_position = (random.randint(0, SCREEN_WIDTH), random.randint(0, SCREEN_HEIGHT))
        enemy_teams = [t for t in self.teams if t.team_color != robot.team]
        enemy_robots = [r for t in enemy_teams for r in t.robots if r.health > 0]

        # Defenders stay near the flag and attack enemies that get too close
        robot.move_toward(flag_position)

        for enemy in enemy_robots:
            if robot.calculate_distance(enemy) <= COMBAT_RADIUS:
                damage = robot.attack(enemy)
                print(f"{robot.name} defends the flag from {enemy.name} for {damage} damage!")

