    def move(self, target_position: Position, delta_time: float):
        """Move the robot towards a target position"""
        if self.state == RobotState.DEAD:
            return

        direction = (target_position.x - self.position.x, target_position.y - self.position.y)
        distance = math.sqrt(direction[0]**2 + direction[1]**2)

        if distance > 0:
            self.position.x += (direction[0]/distance) * self.speed * delta_time
            self.position.y += (direction[1]/distance) * self.speed * delta_time
            self.state = RobotState.MOVING

    def use_weapon(self, target: 'Robot', current_time: float) -> float:
        """Attempt to use the current weapon on a target"""
        if self.state != RobotState.DEAD:
            current_weapon = self.weapons[self.current_weapon_index]
            if current_weapon.is_ready(current_time):
                if self.energy >= current_weapon.energy_cost:
                    damage = current_weapon.use(current_time, self.energy)
                    self.energy -= current_weapon.energy_cost
                    self.state = RobotState.ATTACKING
                    return damage
        return 0

