import json
from typing import Dict, List, Tuple, Optional
import threading
import time
import re

# =====================
# CodeSync Application
# =====================

class User:
    def __init__(self, user_id: str, name: str, role: str = 'developer'):
        self.user_id = user_id
        self.name = name
        self.role = role


class CodeSnippet:
    def __init__(self, snippet_id: str, code: str, language: str):
        self.snippet_id = snippet_id
        self.code = code
        self.language = language
        self.history = [code]  # Version control history

    def edit(self, new_code: str, user: User):
        self.code = new_code
        self.history.append(new_code)  # Add to version control
        print(f"{user.name} edited snippet {self.snippet_id}.")

    def revert(self, version: int):
        if 0 <= version < len(self.history):
            self.code = self.history[version]
            print(f"Reverted to version {version} of snippet {self.snippet_id}.")
        else:
            print("Invalid version number.")

    def get_version(self, version: int):
        if 0 <= version < len(self.history):
            return self.history[version]
        else:
            return "Version not found"


class Notebook:
    def __init__(self, notebook_id: str, title: str, is_private: bool = False, owner: User = None):
        self.notebook_id = notebook_id
        self.title = title
        self.is_private = is_private
        self.owner = owner
        self.users = {}  # user_id: User
        self.snippets = {}  # snippet_id: CodeSnippet
        self.lock = threading.Lock()

    def add_snippet(self, snippet: CodeSnippet):
        self.snippets[snippet.snippet_id] = snippet

    def add_user(self, user: User, access_level: str = 'read'):
        self.users[user.user_id] = {'user': user, 'access': access_level}

    def can_edit(self, user: User) -> bool:
        return self.users.get(user.user_id, {}).get('access') in ['edit', 'owner']

    def real_time_edit(self, snippet_id: str, user: User, new_code: str):
        with self.lock:
            if snippet_id in self.snippets and self.can_edit(user):
                self.snippets[snippet_id].edit(new_code, user)
            else:
                print(f"User {user.name} cannot edit snippet {snippet_id}")


class CodeSync:
    def __init__(self):
        self.users = {}  # user_id: User
        self.notebooks = {}  # notebook_id: Notebook

    def create_user(self, user_id: str, name: str):
        self.users[user_id] = User(user_id, name)

    def create_notebook(self, notebook_id: str, title: str, is_private: bool = False, owner_id: str = None):
        owner = self.users.get(owner_id)
        self.notebooks[notebook_id] = Notebook(notebook_id, title, is_private, owner)
        if owner:
            self.notebooks[notebook_id].add_user(owner, 'owner')

    def add_user_to_notebook(self, notebook_id: str, user_id: str, access_level: str = 'read'):
        if notebook_id in self.notebooks:
            user = self.users.get(user_id)
            if user:
                self.notebooks[notebook_id].add_user(user, access_level)

    def get_notebook(self, notebook_id: str) -> Optional[Notebook]:
        return self.notebooks.get(notebook_id)

    # Syntax Highlighting (simplified)
    SYNTAX_HIGHLIGHTING = {
        'python': r'(?i)\b(def|class|return|if|else|elif|for|while|import|from|as|try|except|finally)\b',
        'javascript': r'(?i)\b(function|var|let|const|if|else|for|while|return|new|class|import|export)\b',
        'java': r'\b(public|private|protected|static|void|int|String|class|interface|extends|implements)\b',
        'cpp': r'\b(int|char|float|double|if|else|for|while|return|class|struct|public|private|protected)\b'
    }

    def highlight_syntax(self, code: str, language: str) -> str:
        pattern = self.SYNTAX_HIGHLIGHTING.get(language.lower(), '')
        if pattern:
            return re.sub(pattern, lambda m: f"**{m.group().upper()}**", code)
        return code

    # Code Completion (simple dictionary-based)
    CODE_COMPLETION = {
        'python': {'print', 'len', 'range', 'input', 'open', 'for', 'while', 'if', 'else', 'elif', 'def', 'class', 'return'},
        'javascript': {'console', 'function', 'if', 'else', 'for', 'while', 'return', 'let', 'const', 'var'},
        'java': {'public', 'private', 'static', 'void', 'main', 'if', 'else', 'for', 'while', 'return', 'class', 'new'},
        'cpp': {'int', 'char', 'float', 'double', 'if', 'else', 'for', 'while', 'return', 'class', 'struct', 'public', 'private'}
    }

    def suggest_completion(self, code: str, language: str) -> List[str]:
        words = code.split()[-1:] or ['']
        prefix = words[0].lower()
        return [kw for kw in self.CODE_COMPLETION.get(language.lower(), []) if kw.startswith(prefix)]

    # Search Functionality
    def search(self, notebook_id: str, query: str) -> List[Tuple[str, str]]:
        results = []
        notebook = self.get_notebook(notebook_id)
        if notebook:
            for snippet_id, snippet in notebook.snippets.items():
                if query.lower() in snippet.code.lower():
                    results.append((snippet_id, snippet.code))
        return results

