class DifficultyManager:
    """
    Manages the adaptive difficulty of the arena.
    """
    def __init__(self, arena: "CyberArena"):
        self.arena = arena
        self.difficulty_level = 1.0  # base difficulty (x1)

    def update(self):
        """Update the difficulty level based on robot performance."""
        # Calculate average team health
        red_health = sum(robot.health for robot in self.arena.robots if robot.team == Team.RED and robot.is_alive()) / \
                    sum(1 for robot in self.arena.robots if robot.team == Team.RED and robot.is_alive())

        blue_health = sum(robot.health for robot in self.arena.robots if robot.team == Team.BLUE and robot.is_alive()) / \
                     sum(1 for robot in self.arena.robots if robot.team == Team.BLUE and robot.is_alive())

        avg_health = (red_health + blue_health) / 2

        # Adjust difficulty based on team performance
        if avg_health < 30:
            # Robots are too strong, increase difficulty
            self.difficulty_level = min(5.0, self.difficulty_level * 1.1)
            print(f"Increasing difficulty level to {self.difficulty_level:.2f}x")
        elif avg_health > 70:
            # Robots are struggling, decrease difficulty
            self.difficulty_level = max(0.5, self.difficulty_level * 0.9)
            print(f"Decreasing difficulty level to {self.difficulty_level:.2f}x")

        # Apply difficulty adjustments to all robots
        for robot in self.arena.robots:
            robot.speed = 2.0 * self.difficulty_level
            robot.armor = 0.5 * self.difficulty_level
            robot.max_health = 100.0 * self.difficulty_level

