        # Calculate team win ratios
        red_wins = sum(robot.wins for robot in self.arena.robots if robot.team == Team.RED)
        blue_wins = sum(robot.wins for robot in self.arena.robots if robot.team == Team.BLUE)

        total_wins = red_wins + blue_wins

        if total_wins > 0:
            red_win_ratio = red_wins / total_wins
            blue_win_ratio = blue_wins / total_wins

            # Adjust learning based on win ratios
            if red_win_ratio > 0.7:
                # Red team is too strong, adjust learning to balance
                for robot in self.arena.robots:
                    if robot.team == Team.BLUE:
                        robot.learning_rate = min(0.5, robot.learning_rate * 1.1)
            elif blue_win_ratio > 0.7:
                # Blue team is too strong, adjust learning to balance
                for robot in self.arena.robots:
                    if robot.team == Team.RED:
                        robot.learning_rate = min(0.5, robot.learning_rate * 1.1)

