"""
CyberArena - A Multi-Agent Simulation of a Futuristic Robot Battle Arena
"""

import random
import time
import threading
from enum import Enum
from abc import ABC, abstractmethod
from typing import List, Dict, Tuple, Optional

# ============ BASE CLASSES ============

class Team(Enum):
    RED = 1
    BLUE = 2

class Position:
    def __init__(self, x: float, y: float):
        self.x = x
        self.y = y

    def move_toward(self, target: "Position", speed: float):
        dx = target.x - self.x
        dy = target.y - self.y
        distance = (dx**2 + dy**2)**0.5

        if distance > 0:
            self.x += dx * speed / distance
            self.y += dy * speed / distance

    def __str__(self):
        return f"({self.x:.2f}, {self.y:.2f})"

class Weapon(ABC):
    """
    Abstract base class for all weapons.
    """
    def __init__(self, name: str, damage: float, attack_speed: float):
        self.name = name
        self.damage = damage
        self.attack_speed = attack_speed  # attacks per second
        self.last_fired = time.time()  # time since last attack

    @abstractmethod
    def attack(self, target: "Robot") -> None:
        """Perform an attack against a target robot."""
        pass

class RangedWeapon(Weapon):
    """A weapon that attacks from a distance."""
    def __init__(self, name: str, damage: float, attack_speed: float, range: float):
        super().__init__(name, damage, attack_speed)
        self.range = range  # attack range in meters

    def attack(self, target: "Robot") -> None:
        """Perform a ranged attack against a target robot."""
        if time.time() - self.last_fired >= 1/self.attack_speed:
            distance = ((self.owner.position.x - target.position.x)**2 + 
                       (self.owner.position.y - target.position.y)**2)**0.5

            if distance <= self.range:
                # Successful hit
                target.take_damage(self.damage)
                self.last_fired = time.time()
                print(f"{self.owner.name} ({self.owner.team}) used {self.name} on {target.name} ({target.team}) " + 
                      f"from distance {distance:.2f}m dealing {self.damage:.1f} damage")

class MeleeWeapon(Weapon):
    """A weapon that requires close combat."""
    def __init__(self, name: str, damage: float, attack_speed: float, reach: float):
        super().__init__(name, damage, attack_speed)
        self.reach = reach  # attack reach in meters

    def attack(self, target: "Robot") -> None:
        """Perform a melee attack against a target robot."""
        if time.time() - self.last_fired >= 1/self.attack_speed:
            distance = ((self.owner.position.x - target.position.x)**2 + 
                       (self.owner.position.y - target.position.y)**2)**0.5

            if distance <= self.reach:
                # Successful hit
                target.take_damage(self.damage)
                self.last_fired = time.time()
                print(f"{self.owner.name} ({self.owner.team}) used {self.name} on {target.name} ({target.team}) " + 
                      f"from distance {distance:.2f}m dealing {self.damage:.1f} damage")

class PowerUp:
    """
    A power-up that provides temporary advantages to robots.
    """
    def __init__(self, name: str, duration: float, effect: Dict):
        self.name = name
        self.duration = duration  # in seconds
        self.effect = effect  # dictionary of effects (e.g., {"speed": 2.0, "armor": 0.5})

    def apply(self, robot: "Robot") -> None:
        """Apply the power-up to a robot."""
        print(f"{robot.name} picked up {self.name} power-up")
        for effect_name, value in self.effect.items():
            if effect_name == "speed":
                robot.speed_multiplier = value
            elif effect_name == "armor":
                robot.armor_multiplier = value
            elif effect_name == "damage":
                robot.damage_multiplier = value
            elif effect_name == "heal":
                robot.heal(value)
        robot.active_power_ups[self.name] = time.time() + self.duration

class Hazard:
    """
    An environmental hazard that affects robots.
    """
    def __init__(self, name: str, radius: float, damage: float):
        self.name = name
        self.radius = radius  # meters
        self.damage = damage  # damage per second
        self.position = Position(random.uniform(0, 100), random.uniform(0, 100))

    def affect(self, robot: "Robot") -> None:
        """Apply the hazard's effect to a robot if they are within range."""
        distance = ((self.position.x - robot.position.x)**2 + 
                   (self.position.y - robot.position.y)**2)**0.5

        if distance <= self.radius:
            robot.take_damage(self.damage * 0.1)  # 0.1 second tick

# ============ ROBOT CLASS ============

class Robot:
    """
    A robot agent in the CyberArena simulation.
    """
    def __init__(self, name: str, team: Team, position: Position):
        self.name = name
        self.team = team
        self.position = position
        self.health = 100.0  # health points
        self.speed = 2.0  # meters per second
        self.speed_multiplier = 1.0  # multiplier for speed
        self.armor = 0.5  # armor value (0 to 1)
        self.armor_multiplier = 1.0  # multiplier for armor
        self.damage_multiplier = 1.0  # multiplier for damage
        self.max_health = 100.0

        # Initialize with default weapons
        self.weapons = [
            RangedWeapon("Plasma Rifle", damage=10.0, attack_speed=2.0, range=20.0),
            MeleeWeapon("Energy Blade", damage=20.0, attack_speed=1.5, reach=1.5)
        ]

        # Set the owner of each weapon to this robot
        for weapon in self.weapons:
            weapon.owner = self

        self.active_power_ups: Dict[str, float] = {}
        self.objective: Optional["Objective"] = None
        self.last_action_time = time.time()

    def take_damage(self, damage: float) -> None:
        """Apply damage to the robot, considering armor."""
        effective_damage = damage * (1 - self.armor) * (1 / self.armor_multiplier)
        self.health -= effective_damage

        if self.health < 0:
            self.health = 0
            print(f"{self.name} ({self.team}) has been destroyed!")

    def heal(self, amount: float) -> None:
        """Heal the robot by a specified amount."""
        self.health = min(self.max_health, self.health + amount)

    def is_alive(self) -> bool:
        """Check if the robot is still alive."""
        return self.health > 0

    def move_toward(self, target_position: Position):
        """Move the robot toward a target position."""
        self.position.move_toward(target_position, self.speed * self.speed_multiplier)

    def attack_closest_enemy(self):
        """Attack the closest enemy robot."""
        closest_enemy = None
        min_distance = float('inf')

        for robot in CyberArena.robots:
            if robot.team != self.team and robot.is_alive():
                distance = ((self.position.x - robot.position.x)**2 + 
                           (self.position.y - robot.position.y)**2)**0.5

                if distance < min_distance:
                    min_distance = distance
                    closest_enemy = robot

        if closest_enemy is not None:
            # Choose a random weapon to attack with
            weapon = random.choice(self.weapons)
            weapon.attack(closest_enemy)

    def check_power_ups(self):
        """Check if any power-ups have expired and remove them."""
        current_time = time.time()
        expired_powers = [name for name, end_time in self.active_power_ups.items() 
                         if current_time >= end_time]

        for name in expired_powers:
            print(f"{self.name}'s {name} power-up has expired")
            del self.active_power_ups[name]

    def update(self):
        """Update the robot's state."""
        self.check_power_ups()
        self.last_action_time = time.time()

# ============ OBJECTIVE SYSTEM ============

class Objective(Enum):
    CAPTURE_FLAG = 1
    DEFEND_BASE = 2
    ESCORT_PAYLOAD = 3

class ObjectiveManager:
    """
