# ============ SCORING SYSTEM ============

class ScoringSystem:
    """
    Manages the scoring and feedback for the arena.
    """
    def __init__(self, arena: "CyberArena"):
        self.arena = arena
        self.scores: Dict[Team, float] = {
            Team.RED: 0.0,
            Team.BLUE: 0.0
        }

    def calculate_team_score(self, team: Team) -> float:
        """Calculate the score for a team based on various factors."""
        team_robots = [robot for robot in self.arena.robots if robot.team == team]

        # Base score for each alive robot
        base_score = sum(1.0 for robot in team_robots if robot.is_alive())

        # Additional score for objective progress
        objective_score = 0.0
        if self.arena.objective_manager.current_objective == Objective.CAPTURE_FLAG:
            if any(robot.team == team for robot in self.arena.robots if robot.is_alive() and 
                   ((robot.position.x - self.arena.objective_manager.objective_position.x)**2 + 
                   (robot.position.y - self.arena.objective_manager.objective_position.y)**2)**0.5 < 5.0):
                objective_score += 2.0
        elif self.arena.objective_manager.current_objective == Objective.DEFEND_BASE:
            if any(robot.team == team for robot in self.arena.robots if robot.is_alive() and 
                   ((robot.position.x - self.arena.objective_manager.objective_position.x)**2 + 
                   (robot.position.y - self.arena.objective_manager.objective_position.y)**2)**0.5 > 10.0):
                objective_score += 2.0
        elif self.arena.objective_manager.current_objective == Objective.ESCORT_PAYLOAD:
            if team == Team.RED:
                if any(robot.team == team and robot.role == "Escort" and robot.is_alive() for robot in team_robots):
                    objective_score += 2.0

        # Damage dealt score
        damage_score = sum(robot.damage_dealt for robot in team_robots if robot.is_alive())

        # Teamwork score (based on number of team robots alive)
        teamwork_score = sum(1.0 for robot in team_robots if robot.is_alive()) / len(team_robots)

        total_score = (base_score * 10) + (objective_score * 5) + (damage_score * 0.1) + (teamwork_score * 50)

        return total_score

    def update(self):
        """Update the scores for both teams and provide feedback."""
        self.scores[Team.RED] = self.calculate_team_score(Team.RED)
        self.scores[Team.BLUE] = self.calculate_team_score(Team.BLUE)

        # Provide visual and audio feedback
        for team in [Team.RED, Team.BLUE]:
            if self.scores[team] > 100:
                print(f"Audio effect: Team {team.name} score alert - {self.scores[team]:.1f} points!")
                print(f"Visual effect: Team {team.name} score indicator glowing!")

# ============ CONTROL SYSTEM ============

class ControlScheme:
    """
    Represents a robot's control scheme.
    """
    def __init__(self):
        self.forward = "W"
        self.backward = "S"
        self.left = "A"
        self.right = "D"
        self.attack = "SPACE"
        self.interact = "E"

    def update(self, new_scheme: Dict):
        """Update the control scheme."""
        for key, value in new_scheme.items():
            if hasattr(self, key):
                setattr(self, key, value)

# ============ MAIN ARENA CLASS ============

class CyberArena:
    """
    The main simulation of the CyberArena.
    """
    def __init__(self):
        self.robots: List[Robot] = []
        self.hazards: List[Hazard] = []
        self.power_ups: List[PowerUp] = []

        # Initialize managers
        self.objective_manager = ObjectiveManager(self)
        self.difficulty_manager = DifficultyManager(self)
        self.learning_manager = LearningManager(self)
        self.visual_manager = VisualManager(self)
        self.scoring_system = ScoringSystem(self)

        # Initialize the arena
        self._initialize_robots()
        self._initialize_hazards()
        self._initialize_power_ups()

    def _initialize_robots(self):
        """Initialize the robots in the arena."""
        red_positions = [Position(random.uniform(0, 40), random.uniform(0, 100)) for _ in range(5)]
        blue_positions = [Position(random.uniform(60, 100), random.uniform(0, 100)) for _ in range(5)]

        # Create red team robots
        for i, position in enumerate(red_positions):
            robot = Robot(f"RedBot-{i+1}", Team.RED, position)
            self.robots.append(robot)

        # Create blue team robots
        for i, position in enumerate(blue_positions):
            robot = Robot(f"BlueBot-{i+1}", Team.BLUE, position)
            self.robots.append(robot)

        # Assign initial objective roles
        self.objective_manager.assign_roles()

    def _initialize_hazards(self):
        """Initialize the hazards in the arena."""
        self.hazards.append(Hazard("Lava Pool", radius=5.0, damage=5.0))
        self.hazards.append(Hazard("Toxic Gas", radius=3.0, damage=2.0))

    def _initialize_power_ups(self):
        """Initialize the power-ups in the arena."""
        self.power_ups.append(PowerUp("Overdrive", duration=10.0, effect={"speed": 2.0, "armor": 0.5}))
        self.power_ups.append(PowerUp("Guardian", duration=15.0, effect={"armor": 0.8}))
        self.power_ups.append(PowerUp("Blitz", duration=8.0, effect={"speed": 1.5}))

    def find_power_up(self, robot: Robot) -> Optional[PowerUp]:
        """Check if a robot is near a power-up and return it."""
        for power_up in self.power_ups:
            distance = ((robot.position.x - power_up.position.x)**2 + 
                       (robot.position.y - power_up.position.y)**2)**0.5
            if distance <= 2.0:  # 2 meters range to pick up power-ups
                return power_up
        return None

    def run_simulation(self, duration: int = 60):
        """Run the simulation for a specified duration in seconds."""
        print("Starting CyberArena simulation...")
        start_time = time.time()

        # Create a real-time combat thread
        combat_thread = threading.Thread(target=self._combat_loop, args=(start_time + duration,))
        combat_thread.start()

        # Wait for the simulation to finish
        combat_thread.join()
        print("Simulation complete!")

        # Print final scores
        print("\nFinal Scores:")
        for team, score in self.scoring_system.scores.items():
            print(f"Team {team.name}: {score:.1f} points")

    def _combat_loop(self, end_time: float):
        """Main combat loop for the simulation."""
        while time.time() < end_time:
            # Update all systems
            self.difficulty_manager.update()
            self.objective_manager.update()
            self.learning_manager.update()
            self.visual_manager.update()
            self.scoring_system.update()

            # Update each robot
            for robot in self.robots:
                if robot.is_alive():
                    robot.update()

                    # Move toward objective position
                    robot.move_toward(self.objective_manager.objective_position)

                    # Check for hazards
                    for hazard in self.hazards:
                        hazard.affect(robot)

                    # Check for power-ups
                    power_up = self.find_power_up(robot)
                    if power_up is not None:
                        power_up.apply(robot)
                        self.power_ups.remove(power_up)

                    # Attack based on role and objective
                    if robot.role == "Attacker":
                        robot.attack_closest_enemy()
                    elif robot.role == "Defender":
                        # Defenders stay near their team's base
                        base_position = Position(0 if robot.team == Team.RED else 100, 50)
                        robot.move_toward(base_position)
                    elif robot.role == "Scout":
                        # Scouts patrol the arena
                        robot.move_toward(Position(random.uniform(0, 100), random.uniform(0, 100)))
                    elif robot.role == "Escort":
                        # Escorts follow the payload
                        robot.move_toward(self.objective_manager.objective_position)

                # Small delay between updates to simulate real-time behavior
                time.sleep(0.1)

