        }

    def calculate_team_score(self, team: Team) -> float:
        """Calculate the score for a team based on various factors."""
        team_robots = [robot for robot in self.arena.robots if robot.team == team]

        # Base score for each alive robot
        base_score = sum(1.0 for robot in team_robots if robot.is_alive())

        # Additional score for objective progress
        objective_score = 0.0
        if self.arena.objective_manager.current_objective == Objective.CAPTURE_FLAG:
            if any(robot.team == team for robot in self.arena.robots if robot.is_alive() and 
                   ((robot.position.x - self.arena.objective_manager.objective_position.x)**2 + 
                   (robot.position.y - self.arena.objective_manager.objective_position.y)**2)**0.5 < 5.0):
                objective_score += 2.0
        elif self.arena.objective_manager.current_objective == Objective.DEFEND_BASE:
            if any(robot.team == team for robot in self.arena.robots if robot.is_alive() and 
                   ((robot.position.x - self.arena.objective_manager.objective_position.x)**2 + 
                   (robot.position.y - self.arena.objective_manager.objective_position.y)**2)**0.5 > 10.0):
                objective_score += 2.0
        elif self.arena.objective_manager.current_objective == Objective.ESCORT_PAYLOAD:
            if team == Team.RED:
                if any(robot.team == team and robot.role == "Escort" and robot.is_alive() for robot in team_robots):
                    objective_score += 2.0

