        damage_score = sum(robot.damage_dealt for robot in team_robots if robot.is_alive())

        # Teamwork score (based on number of team robots alive)
        teamwork_score = sum(1.0 for robot in team_robots if robot.is_alive()) / len(team_robots)

        total_score = (base_score * 10) + (objective_score * 5) + (damage_score * 0.1) + (teamwork_score * 50)

        return total_score

