        self.power_ups.append(PowerUp("Guardian", duration=15.0, effect={"armor": 0.8}))
        self.power_ups.append(PowerUp("Blitz", duration=8.0, effect={"speed": 1.5}))

    def find_power_up(self, robot: Robot) -> Optional[PowerUp]:
        """Check if a robot is near a power-up and return it."""
        for power_up in self.power_ups:
            distance = ((robot.position.x - power_up.position.x)**2 + 
                       (robot.position.y - power_up.position.y)**2)**0.5
            if distance <= 2.0:  # 2 meters range to pick up power-ups
                return power_up
        return None

    def run_simulation(self, duration: int = 60):
        """Run the simulation for a specified duration in seconds."""
        print("Starting CyberArena simulation...")
        start_time = time.time()

        # Create a real-time combat thread
        combat_thread = threading.Thread(target=self._combat_loop, args=(start_time + duration,))
        combat_thread.start()

        # Wait for the simulation to finish
        combat_thread.join()
        print("Simulation complete!")

        # Print final scores
