# ============ BASE CLASSES ============

class Team(Enum):
    RED = 1
    BLUE = 2

class Position:
    def __init__(self, x: float, y: float):
        self.x = x
        self.y = y

    def move_toward(self, target: "Position", speed: float):
        dx = target.x - self.x
        dy = target.y - self.y
        distance = (dx**2 + dy**2)**0.5

        if distance > 0:
            self.x += dx * speed / distance
            self.y += dy * speed / distance

    def __str__(self):
        return f"({self.x:.2f}, {self.y:.2f})"

class Weapon(ABC):
    """
    Abstract base class for all weapons.
    """
    def __init__(self, name: str, damage: float, attack_speed: float):
        self.name = name
        self.damage = damage
        self.attack_speed = attack_speed  # attacks per second
        self.last_fired = time.time()  # time since last attack

    @abstractmethod
    def attack(self, target: "Robot") -> None:
        """Perform an attack against a target robot."""
        pass

class RangedWeapon(Weapon):
    """A weapon that attacks from a distance."""
    def __init__(self, name: str, damage: float, attack_speed: float, range: float):
        super().__init__(name, damage, attack_speed)
        self.range = range  # attack range in meters

    def attack(self, target: "Robot") -> None:
        """Perform a ranged attack against a target robot."""
        if time.time() - self.last_fired >= 1/self.attack_speed:
            distance = ((self.owner.position.x - target.position.x)**2 + 
                       (self.owner.position.y - target.position.y)**2)**0.5

            if distance <= self.range:
                # Successful hit
                target.take_damage(self.damage)
                self.last_fired = time.time()
                print(f"{self.owner.name} ({self.owner.team}) used {self.name} on {target.name} ({target.team}) " + 
                      f"from distance {distance:.2f}m dealing {self.damage:.1f} damage")

class MeleeWeapon(Weapon):
    """A weapon that requires close combat."""
    def __init__(self, name: str, damage: float, attack_speed: float, reach: float):
        super().__init__(name, damage, attack_speed)
        self.reach = reach  # attack reach in meters

    def attack(self, target: "Robot") -> None:
        """Perform a melee attack against a target robot."""
        if time.time() - self.last_fired >= 1/self.attack_speed:
            distance = ((self.owner.position.x - target.position.x)**2 + 
