        self.weekly_plan = self._generate_weekly_plan()

    def _generate_weekly_plan(self):
        valid_recipes = self.recipe_db.get_recipes(self.user.dietary_preference.preferences, 
                                                   self.user.allergies.intolerances)
        meals = self._calculate_meals(valid_recipes)
        return {
