# Define the TravelMate components

class ActivityType(Enum):
    """Enum representing different types of activities users can prefer\"\"
    CULTURAL = "Cultural"
    ADVENTURE = "Adventure"
    RELAXATION = "Relaxation"
    FOOD = "Food"
    NIGHTLIFE = "Nightlife"

@dataclass
class Destination:
    name: str
    description: str
    average_cost: float
    rating: float
    activities: List[ActivityType]

@dataclass
class Activity:
    name: str
    description: str
    cost: float
    duration: int  # in hours
    activity_type: ActivityType
    dietary_info: Optional[str] = None

@dataclass
class Accommodation:
    name: str
    description: str
    cost_per_night: float
    rating: float
    dietary_options: List[str]

@dataclass
class Transportation:
    name: str
    description: str
    cost: float
    duration: int  # in hours

@dataclass
class TravelPreferences:
    budget: float
    start_date: str  # Format: YYYY-MM-DD
    end_date: str  # Format: YYYY-MM-DD
    preferred_activities: List[ActivityType]
    dietary_restrictions: List[str] = None

@dataclass
class ItineraryItem:
    date: str
    activity: Activity
    destination: Optional[Destination] = None
    accommodation: Optional[Accommodation] = None
    transportation: Optional[Transportation] = None

@dataclass
class Itinerary:
    user_id: str
    preferences: TravelPreferences
    items: List[ItineraryItem] = None

    def __post_init__(self):
        self.items = self.items or []

    def add_item(self, item: ItineraryItem):
        self.items.append(item)

    def remove_item(self, index: int):
        if 0 <= index < len(self.items):
            self.items.pop(index)

    def save(self):
        # In a real system, this would save to a DB or file
        print(f"Itinerary for user {self.user_id} saved.")

    def display(self):
        print(f"\nTravel Itinerary for {self.user_id}:")
        for item in self.items:
            print(f"- Date: {item.date}")
            print(f"  Activity: {item.activity.name} ({item.activity.activity_type.value})")
            print(f"  Description: {item.activity.description}")
            print(f"  Cost: ${item.activity.cost:.2f}
")
            if item.destination:
                print(f"  Destination: {item.destination.name}")
                print(f"    Avg Cost: ${item.destination.average_cost:.2f}")
                print(f"    Rating: {item.destination.rating}\n")
            if item.accommodation:
                print(f"  Accommodation: {item.accommodation.name}")
                print(f"    Cost/night: ${item.accommodation.cost_per_night:.2f}")
                print(f"    Rating: {item.accommodation.rating}")
                if item.accommodation.dietary_options:
                    print(f"    Dietary Options: {', '.join(item.accommodation.dietary_options)}\n")
            if item.transportation:
                print(f"  Transportation: {item.transportation.name}")
                print(f"    Cost: ${item.transportation.cost:.2f}")
                print(f"    Duration: {item.transportation.duration} hours\n")

    def get_total_cost(self):
