# Generate itinerary based on user preferences
def generate_itinerary(preferences: TravelPreferences, destinations, activities, accommodations, transportation):
    itinerary = Itinerary(user_id="12345", preferences=preferences)
    total_budget = 0

    for destination in destinations:
        if any(activity in destination.activities for activity in preferences.preferred_activities):
            if total_budget + destination.average_cost < preferences.budget:
                itinerary.add_item(ItineraryItem(
