        if activity.activity_type in preferences.preferred_activities:
            if total_budget + activity.cost < preferences.budget:
                itinerary.add_item(ItineraryItem(
                    date=preferences.start_date,
                    activity=activity
                ))

    for accommodation in accommodations:
        if any(activity in accommodation.description for activity in preferences.preferred_activities):
            if total_budget + accommodation.cost_per_night < preferences.budget:
                itinerary.add_item(ItineraryItem(
                    date=preferences.start_date,
                    accommodation=accommodation
                ))

    for transport in transportation:
        if total_budget + transport.cost < preferences.budget:
            itinerary.add_item(ItineraryItem(
                date=preferences.start_date,
                transportation=transport
            ))

