class Arena:
    def __init__(self, name, size, spawn_points, objectives, power_ups, hazards):
        self.name = name
        self.size = size
        self.spawn_points = spawn_points
        self.objectives = objectives
        self.power_ups = power_ups
        self.hazards = hazards
        self.teams = defaultdict(list)
        self.robots = []
        self.spectators = []

    def add_robot(self, robot):
        self.teams[robot.team].append(robot)
        self.robots.append(robot)

    def add_spectator(self, spectator):
        self.spectators.append(spectator)

    def remove_robot(self, robot):
        if robot in self.robots:
            self.robots.remove(robot)
            if robot in self.teams[robot.team]:
                self.teams[robot.team].remove(robot)

    def update(self, dt):
        for robot in self.robots:
            robot.update(dt)
        for hazard in self.hazards:
            hazard.remaining_time -= dt
            if hazard.remaining_time <= 0:
                self.hazards.remove(hazard)

    def check_hazards(self, robot):
        for hazard in self.hazards:
            if np.linalg.norm(np.array(robot.position) - np.array(hazard.position)) <= hazard.radius:
                hazard.apply_effect(robot)

    def spawn_power_up(self, power_up_type):
        power_up = PowerUp(power_up_type)
        self.power_ups.append(power_up)
        return power_up

    def respawn_robot(self, robot):
        robot.health = robot.max_health
        robot.shield = 0
        robot.position = random.choice(self.spawn_points)
        robot.stun = 0
        if robot.strategy:
            robot.strategy.reset(robot)

