class Objective:
    def __init__(self, objective_type, position, target_team, reward=10):
        self.type = objective_type
        self.position = position
        self.target_team = target_team
        self.reward = reward
        self.completed = False

    def is_complete(self, arena):
        if self.type == ObjectiveType.CAPTURE_FLAG:
            return any(robot.position == self.position and robot.team == self.target_team for robot in arena.robots)
        elif self.type == ObjectiveType.DEFEND_BASE:
            return all(robot.team != self.target_team or robot.position != self.position for robot in arena.robots)
        elif self.type == ObjectiveType.ESCORT_PAYLOAD:
            return any(robot.position == self.position and robot.team == self.target_team for robot in arena.robots)
        elif self.type == ObjectiveType.DESTROY_ENEMY:
            return all(robot.team != self.target_team for robot in arena.robots)

class Strategy:
    def __init__(self, name):
