class AggressiveStrategy(Strategy):
    def __init__(self):
        super().__init__("Aggressive")

    def execute(self, robot, dt):
        if robot.stun > 0:
            return
        if robot.targets:
            target = robot.targets[0]
            if robot.position == target.position:
                robot.use_weapon(target)
            else:
                direction = np.array(target.position) - np.array(robot.position)
                direction = direction / np.linalg.norm(direction)
                robot.position = tuple(np.array(robot.position) + direction * robot.speed * dt)
        else:
            robot.targets = [r for r in robot.arena.robots if r.team != robot.team and r.health > 0]
            if robot.targets:
                self.execute(robot, dt)

class DefensiveStrategy(Strategy):
    def __init__(self):
        super().__init__("Defensive")

    def execute(self, robot, dt):
        if robot.stun > 0:
            return
        objective = robot.arena.objectives[0]
        if robot.position != objective.position:
            direction = np.array(objective.position) - np.array(robot.position)
            direction = direction / np.linalg.norm(direction)
            robot.position = tuple(np.array(robot.position) + direction * robot.speed * dt)
        else:
            for r in robot.arena.robots:
                if r.team != robot.team and r.health > 0 and robot.position == r.position:
                    robot.use_weapon(r)
                    break

