class ScoringSystem:
    def __init__(self, arena):
        self.arena = arena
        self.scores = defaultdict(int)
        self.teams = defaultdict(int)

    def update(self, dt):
        for robot in self.arena.robots:
            if robot.health <= 0:
                robot.score += 5
            if robot.weapon.type == WeaponType.SHIELD and robot.weapon.last_used > 0:
                robot.score += 1
            if robot.position in [obj.position for obj in self.arena.objectives if obj.is_complete(self.arena)]:
                robot.score += 10

    def get_scores(self):
        return self.scores

class AdaptiveDifficulty:
    def __init__(self, arena):
        self.arena = arena
        self.difficulty = 1.0
        self.difficulty_factor = 0.1
        self.max_difficulty = 3.0
        self.min_difficulty = 0.5

    def update(self, dt):
        total_health = 0
        for robot in self.arena.robots:
            total_health += robot.health
        average_health = total_health / len(self.arena.robots) if self.arena.robots else 0

        if average_health > 80:
            self.difficulty = max(self.difficulty - self.difficulty_factor, self.min_difficulty)
        elif average_health < 20:
            self.difficulty = min(self.difficulty + self.difficulty_factor, self.max_difficulty)

        for robot in self.arena.robots:
            robot.weapon_damage_multiplier = self.difficulty
            robot.speed = max(robot.speed * self.difficulty, 0.1)

