# PhotoCollabEditor - A real-time collaborative photo editing web application

import socketio
import json
from flask import Flask, render_template, request
from PIL import Image, ImageEnhance, ImageFilter, ImageOps
import os
import datetime
import uuid

# Socket.IO initialization for real-time communication
sio = socketio.Server(cors_allowed_origins='*')

# Flask app for the web server
app = Flask(__name__)
sio.attach(app)

# Dictionary to save current photo state for a session
photos = {}

# Dictionary to store version history
version_history = {}

# Dictionary to store filters and frames for reuse
shared_filters = {}
shared_frames = {}

# Dictionary for storing user feedback and edits
feedback = {}

# Helper function to save current version of the photo
def save_version(photo_id, user_id, photo_data):
    if photo_id not in version_history:
        version_history[photo_id] = []
    version = {
        'id': str(uuid.uuid4()),
        'timestamp': datetime.datetime.now().isoformat(),
        'user_id': user_id,
        'photo': photo_data
    }
    version_history[photo_id].append(version)
    return version['id']

# Helper function to apply brightness adjustment
def apply_brightness(photo, brightness):
    enhancer = ImageEnhance.Brightness(photo)
    return enhancer.enhance(brightness)

# Helper function to apply contrast adjustment
def apply_contrast(photo, contrast):
    enhancer = ImageEnhance.Contrast(photo)
    return enhancer.enhance(contrast)

# Helper function to apply filter
def apply_filter(photo, filter_type):
    if filter_type == 'BLUR':
        return photo.filter(ImageFilter.BLUR)
    elif filter_type == 'SHARPEN':
        return photo.filter(ImageFilter.SHARPEN)
    elif filter_type == 'CONTOUR':
        return photo.filter(ImageFilter.CONTOUR)
    return photo

# Helper function to apply frame
def apply_frame(photo, frame):
    # Here we assume the frame is a PIL image of the same size as the photo
    return Image.composite(photo, frame, photo)

# Socket.IO event: When a client connects
@sio.event
async def connect(sid, environ):
    print(f'Client {sid} connected')

# Socket.IO event: When a client disconnects
@sio.event
async def disconnect(sid):
    print(f'Client {sid} disconnected')

# Socket.IO event: Load photo into the session
@sio.event
async def load_photo(sid, data):
    photo_id = data.get('photo_id')
    file_path = data.get('file_path')

    if not os.path.exists(file_path):
        await sio.emit('error', {'message': 'File not found!'}, room=sid)
        return

    # Load the photo
    photo = Image.open(file_path).convert('RGB')
    photo.save(f'temp/{photo_id}.jpg')
    photos[photo_id] = photo
    version_id = save_version(photo_id, sid, f'temp/{photo_id}.jpg')

    # Broadcast to all clients the new photo is loaded
    await sio.emit('photo_loaded', {
        'photo_id': photo_id,
        'version_id': version_id
    })

# Socket.IO event: Apply an edit to the photo
@sio.event
async def apply_edit(sid, data):
    photo_id = data['photo_id']
    edit_type = data['edit_type']
    parameters = data['parameters']

    if photo_id not in photos:
        await sio.emit('error', {'message': 'Photo not found!'}, room=sid)
        return

    photo = photos[photo_id]

    if edit_type == 'BRIGHTNESS':
        photo = apply_brightness(photo, parameters['brightness'])
    elif edit_type == 'CONTRAST':
        photo = apply_contrast(photo, parameters['contrast'])
    elif edit_type == 'FILTER':
        photo = apply_filter(photo, parameters['filter_type'])
    elif edit_type == 'FRAME':
        frame_id = parameters['frame_id']
        if frame_id in shared_frames:
            frame = shared_frames[frame_id]
            photo = apply_frame(photo, frame)
        else:
            await sio.emit('error', {'message': 'Frame not found!'}, room=sid)
            return

    # Save new version of the photo
    photo.save(f'temp/{photo_id}.jpg')
    photos[photo_id] = photo
    version_id = save_version(photo_id, sid, f'temp/{photo_id}.jpg')

    # Broadcast the updated photo to all clients
    await sio.emit('photo_updated', {
        'photo_id': photo_id,
        'version_id': version_id
    })

# Socket.IO event: Submit feedback on an edit
@sio.event
async def submit_feedback(sid, data):
    photo_id = data['photo_id']
    version_id = data['version_id']
    feedback_text = data['feedback']

    if photo_id not in feedback:
        feedback[photo_id] = []

    feedback_id = str(uuid.uuid4())
    feedback[photo_id].append({
        'id': feedback_id,
        'version_id': version_id,
        'user_id': sid,
        'feedback': feedback_text
    })

    await sio.emit('feedback_received', {
        'photo_id': photo_id,
        'feedback': feedback[photo_id]
    })

# Socket.IO event: Revert to a previous version
@sio.event
async def revert_version(sid, data):
    photo_id = data['photo_id']
    version_id = data['version_id']

    if photo_id not in version_history:
        await sio.emit('error', {'message': 'No version history found!'}, room=sid)
        return

    for v in version_history[photo_id]:
        if v['id'] == version_id:
            photo_path = v['photo']
            photo = Image.open(photo_path).convert('RGB')
            photo.save(f'temp/{photo_id}.jpg')
            photos[photo_id] = photo
            new_version_id = save_version(photo_id, sid, f'temp/{photo_id}.jpg')

            await sio.emit('photo_reverted', {
                'photo_id': photo_id,
                'version_id': new_version_id
            })
            return

    await sio.emit('error', {'message': 'Version not found!'}, room=sid)

# Socket.IO event: Save a custom filter
@sio.event
async def save_custom_filter(sid, data):
    filter_id = str(uuid.uuid4())
    filter_data = data['filter_data']
    shared_filters[filter_id] = filter_data

    await sio.emit('filter_saved', {
        'filter_id': filter_id,
        'filter_data': filter_data
    })

# Socket.IO event: Save a custom frame
@sio.event
async def save_custom_frame(sid, data):
    frame_id = str(uuid.uuid4())
    frame_data = data['frame_data']
    shared_frames[frame_id] = frame_data

    await sio.emit('frame_saved', {
        'frame_id': frame_id,
        'frame_data': frame_data
    })

# Flask route to serve the main application page
@app.route('/editor')
def editor():
    return render_template('editor.html')

# Flask route to get version history for a photo
@app.route('/get_version_history')
def get_version_history():
    photo_id = request.args.get('photo_id')
    if photo_id in version_history:
        return json.dumps(version_history[photo_id])
    return json.dumps([])

# Flask route to get shared filters
@app.route('/get_shared_filters')
def get_shared_filters():
