    'photo': None,  # PIL Image object
    'history': [],   # List of version snapshots
    'comments': {},  # {comment_id: {user, position, timestamp, message, resolved}}
    'filters': {},   # {filter_id: {name, data, user}}
    'frames': {},    # {frame_id: {name, data, user}}
    'current_version': 0
}

# Static content routing
@app.route('/<path:filename>')
def static_files(filename):
    return send_from_directory('static', filename)

# Main route
@app.route('/')
def index():
    return render_template('index.html')

# Load photo from client
@app.route('/upload', methods=['POST'])
def upload_photo():
    file = request.files['photo']
    if file:
        workspace['photo'] = Image.open(file.stream)
        workspace['history'].append({
            'version': workspace['current_version'],
            'user': 'system',
            'timestamp': datetime.datetime.now().isoformat(),
            'data': base64.b64encode(file.read()).decode()
        })
        workspace['current_version'] += 1
        return jsonify({'status': 'success', 'message': 'Photo uploaded successfully.'})
    return jsonify({'status': 'error', 'message': 'No file uploaded.'})

# SocketIO event handlers
@sio.on('connect')
def handle_connect():
    print('Client connected')
    emit('photo_update', get_photo_data())
    emit('history', workspace['history'])
    emit('comments', workspace['comments'])
    emit('filters', workspace['filters'])
    emit('frames', workspace['frames'])

@sio.on('disconnect')
def handle_disconnect():
    print('Client disconnected')

# Real-time editing events
@sio.on('edit_photo')
def handle_edit_photo(edit_data):
    try:
        # Apply edits to photo (simplified example)
        photo = workspace['photo']
        operation = edit_data['operation']

        if operation == 'brightness':
            enhancer = ImageEnhance.Brightness(photo)
            photo = enhancer.enhance(edit_data['value'])
        elif operation == 'contrast':
            enhancer = ImageEnhance.Contrast(photo)
            photo = enhancer.enhance(edit_data['value'])
        elif operation == 'filter':
            photo = photo.filter(ImageFilter.GaussianBlur(radius=edit_data['value']))
        elif operation == 'frame':
            # Simplified frame application
            photo = photo.resize((photo.width + 20, photo.height + 20),
                                 resample=Image.BILINEAR)

        workspace['photo'] = photo
        workspace['history'].append({
            'version': workspace['current_version'],
            'user': request.sid,
            'timestamp': datetime.datetime.now().isoformat(),
            'operation': operation,
            'value': edit_data['value']
        })
        workspace['current_version'] += 1

        emit('photo_update', get_photo_data(), broadcast=True)
    except Exception as e:
        emit('error', {'message': str(e)})

# Comment handling
@sio.on('add_comment')
def handle_add_comment(comment_data):
    comment_id = str(uuid.uuid4())
    workspace['comments'][comment_id] = {
        'id': comment_id,
        'user': request.sid,
        'position': comment_data['position'],
        'timestamp': datetime.datetime.now().isoformat(),
        'message': comment_data['message'],
        'resolved': False
    }
    emit('comment_added', workspace['comments'][comment_id], broadcast=True)

@sio.on('resolve_comment')
def handle_resolve_comment(comment_id):
    if comment_id in workspace['comments']:
        workspace['comments'][comment_id]['resolved'] = True
        emit('comment_resolved', {'id': comment_id}, broadcast=True)

# Custom filters and frames
@sio.on('save_filter')
def handle_save_filter(filter_data):
    filter_id = str(uuid.uuid4())
    workspace['filters'][filter_id] = {
        'id': filter_id,
        'name': filter_data['name'],
        'data': filter_data['data'],
        'user': request.sid
    }
    emit('filters', workspace['filters'], broadcast=True)

@sio.on('save_frame')
def handle_save_frame(frame_data):
    frame_id = str(uuid.uuid4())
    workspace['frames'][frame_id] = {
        'id': frame_id,
        'name': frame_data['name'],
        'data': frame_data['data'],
        'user': request.sid
    }
    emit('frames', workspace['frames'], broadcast=True)

# Version control
@sio.on('revert_version')
def handle_revert_version(version):
    if int(version) < workspace['current_version']:
        workspace['current_version'] = int(version)
        workspace['photo'] = Image.open(io.BytesIO(base64.b64decode(workspace['history'][int(version)]['data'])))
        emit('photo_update', get_photo_data(), broadcast=True)

# Helper functions
def get_photo_data():
    if workspace['photo']:
        buffer = io.BytesIO()
        workspace['photo'].save(buffer, format='PNG')
        return base64.b64encode(buffer.getvalue()).decode()
    return None

# Run the application
if __name__ == '__main__':
    sio.run(app, host='0.0.0.0', port=5000)"
