        total_robots = len(self.robots)
        if total_robots == 0:
            return

        # Assign roles: attackers, defenders, and support
        attackers = max(1, int(total_robots * 0.4))
        defenders = max(1, int(total_robots * 0.3))
        support = total_robots - attackers - defenders

        for i in range(attackers):
            self.robots[i].role = "attacker"
        for i in range(attackers, attackers + defenders):
            self.robots[i].role = "defender"
        for i in range(attackers + defenders, total_robots):
            self.robots[i].role = "support"

        print(f"Roles assigned for Team {self.team.name}: {attackers} attackers, {defenders} defenders, {support} support units.")

