        # Create robots
        for i in range(5):  # 5 robots per team
            red_robot = Robot(f"Red_Bot_{i}", Team.RED)
            self.robots.append(red_robot)
            blue_robot = Robot(f"Blue_Bot_{i}", Team.BLUE)
            self.robots.append(blue_robot)

        # Assign robots to team strategies
        for robot in self.robots:
            for strategy in self.team_strategies:
                if robot.team == strategy.team:
                    strategy.robots.append(robot)

        # Create objectives
        self.objectives.append(Objective(ObjectiveType.CAPTURE_FLAG, Position(50, 50)))
        self.objectives.append(Objective(ObjectiveType.DEFEND_BASE, Position(30, 30)))
        self.objectives.append(Objective(ObjectiveType.ESCORT_PAYLOAD, Position(70, 70)))

        # Create power-ups
        for _ in range(10):
            self.power_ups.append(PowerUp(Position(random.randint(0, 100), random.randint(0, 100))))

        # Assign roles and adapt strategies
        for strategy in self.team_strategies:
            strategy.assign_roles()
            strategy.adapt_strategy()

        # Update performance tracking
        for strategy in self.team_strategies:
            strategy.update_performance({"win": False})

        print("Game setup completed.")
        self.describe_game()

    def describe_game(self):
