        battle_thread = threading.Thread(target=self.run_battle)
        battle_thread.start()

    def run_battle(self):
        """Runs the main battle loop for the CyberArena."""
        battle_duration = 60  # seconds
        start_time = time.time()

        while time.time() - start_time < battle_duration and self.battle_active:
            if self.game_paused:
                time.sleep(0.5)
                continue

            # Update robot positions and actions
            for robot in self.robots:
                if robot.health <= 0:
                    continue

                # Move towards objective or target
                if robot.role == "attacker":
                    # Attack nearest enemy
                    enemy = self.find_nearest_enemy(robot)
                    if enemy:
                        robot.move_to(enemy.position)
                        if random.random() < 0.1:  # 10% chance to attack
                            robot.attack(enemy)
                    else:
