                        objective = self.find_objective(robot)
                        if objective:
                            robot.move_to(objective.position)
                elif robot.role == "defender":
                    # Defend base or objective
                    objective = self.find_objective(robot)
                    if objective:
                        robot.move_to(objective.position)
                elif robot.role == "support":
                    # Support by collecting power-ups and healing teammates
                    power_up = self.find_nearest_power_up(robot)
                    if power_up and not power_up.collected:
                        robot.move_to(power_up.position)
                        if robot.position.distance_to(power_up.position) < 2:
                            power_up.apply_effect(robot)
                    else:
                        teammate = self.find_injured_teammate(robot)
                        if teammate:
                            robot.move_to(teammate.position)
                            if robot.position.distance_to(teammate.position) < 5:
