            # Small delay to simulate real-time execution
            time.sleep(0.5)

        # Battle ended
        self.battle_active = False
        self.end_battle()

    def find_nearest_enemy(self, robot):
        """Finds the nearest enemy robot to the given robot."""
        enemies = [r for r in self.robots if r.team != robot.team]
        if not enemies:
            return None
        return min(enemies, key=lambda r: robot.position.distance_to(r.position))

    def find_objective(self, robot):
        """Finds an objective of interest to the robot based on its role."""
        if robot.role == "attacker":
            return min(self.objectives, key=lambda o: robot.position.distance_to(o.position))
        elif robot.role == "defender":
            for objective in self.objectives:
                if objective.objective_type in [ObjectiveType.DEFEND_BASE, ObjectiveType.ESCORT_PAYLOAD]:
                    return objective
            return self.objectives[0]  # Default to first objective
        else:
            return None

    def find_nearest_power_up(self, robot):
        """Finds the nearest uncollected power-up to the robot."""
        uncollected_powers = [pu for pu in self.power_ups if not pu.collected]
        if not uncollected_powers:
            return None
        return min(uncollected_powers, key=lambda pu: robot.position.distance_to(pu.position))

    def find_injured_teammate(self, robot):
        """Finds an injured teammate in need of healing."""
        teammates = [r for r in self.robots if r.team == robot.team and r.health < 100]
        if not teammates:
            return None
        return min(teammates, key=lambda t: robot.position.distance_to(t.position))

    def check_victory(self, team):
        """Checks if the given team has won the battle based on objectives."""
        # Victory condition: all objectives are completed by the team
        for objective in self.objectives:
            if objective.team != team:
                continue
            if objective.objective_type == ObjectiveType.ESCORT_PAYLOAD:
                # For escort missions, the payload must reach the destination
                if objective.position.x < 90:
                    return False
            elif not objective.completed:
                return False
        return True

    def update_scores(self):
        """Updates the scores for all robots based on objectives and actions."""
        # Score for completing objectives
        for objective in self.objectives:
            if objective.completed:
                for robot in self.robots:
                    if robot.team == objective.team:
                        robot.score += 50
                        print(f"{robot.name} earned 50 points for contributing to {objective.objective_type.name} objective.")

        # Score for dealing damage
        for robot in self.robots:
            if robot.health <= 0:
                continue
            nearby_enemies = [r for r in self.robots if r.team != robot.team and robot.position.distance_to(r.position) < 20]
            if nearby_enemies:
                robot.score += 10 * len(nearby_enemies)
                print(f"{robot.name} earned 10 points for being near {len(nearby_enemies)} enemies.")

        # Score for collecting power-ups
        for power_up in self.power_ups:
            if power_up.collected:
                for robot in self.robots:
                    if robot.team == power_up.team:
                        robot.score += 20
                        print(f"{robot.name} earned 20 points for collecting a power-up.")

        # Score for surviving
        for robot in self.robots:
            if robot.health > 0:
                robot.score += robot.health // 10
                print(f"{robot.name} earned {robot.health // 10} points for surviving.")

    def play_battle_sounds(self):
        """Plays appropriate sound effects during the battle."""
        # Play combat sounds if robots are attacking or injured
        for robot in self.robots:
            if robot.health <= 0:
                self.environment.play_sound("combat")
        # Play objective sounds if an objective is completed
        for objective in self.objectives:
            if objective.completed and not hasattr(objective, "sound_played"):
                self.environment.play_sound("objective")
                objective.sound_played = True
        # Play power-up sounds for collected power-ups
        for power_up in self.power_ups:
            if power_up.collected and not hasattr(power_up, "sound_played"):
                self.environment.play_sound("power_up")
                power_up.sound_played = True

    def end_battle(self):
        """Ends the battle and displays the results."""
        print("Battle ended!")

        # Determine the winner
        red_victory = self.check_victory(Team.RED)
        blue_victory = self.check_victory(Team.BLUE)
        if red_victory and blue_victory:
            winner = "Draw"
        elif red_victory:
            winner = "Team RED"
        elif blue_victory:
            winner = "Team BLUE"
        else:
            winner = "No clear winner"

