class TeamStrategy:
    """Handles the strategy and roles for a team of robots."""
    def __init__(self, team):
        self.team = team
        self.robots = []  # Will be populated with Robot objects
        self.objective = None  # Will be assigned with Objective objects
        self.victory_streak = 0
        self.loss_streak = 0

    def assign_roles(self):
        """Assigns roles to robots based on team strategy."""
        total_robots = len(self.robots)
        if total_robots == 0:
            return

        # Assign roles: attackers, defenders, and support
        attackers = max(1, int(total_robots * 0.4))
        defenders = max(1, int(total_robots * 0.3))
        support = total_robots - attackers - defenders

        for i in range(attackers):
            self.robots[i].role = "attacker"
        for i in range(attackers, attackers + defenders):
            self.robots[i].role = "defender"
        for i in range(attackers + defenders, total_robots):
            self.robots[i].role = "support"

        print(f"Roles assigned for Team {self.team.name}: {attackers} attackers, {defenders} defenders, {support} support units.")

    def update_performance(self, battle_results):
        """Updates team performance based on battle results."""
        if battle_results["win"]:
            self.victory_streak += 1
            self.loss_streak = 0
        else:
            self.victory_streak = 0
            self.loss_streak += 1
        print(f"Team {self.team.name} has a {self.victory_streak} win streak and {self.loss_streak} loss streak.")

    def adapt_strategy(self):
        """Adapts the team strategy based on performance and environment."""
        # Simple adaptation based on performance
        if self.victory_streak > 2:
            # If the team is winning, become more aggressive
            for robot in self.robots:
                robot.strategy = {"aggressive": True, "defensive": False, "support": False}
        elif self.loss_streak > 1:
            # If the team is losing, focus on defense
            for robot in self.robots:
                robot.strategy = {"aggressive": False, "defensive": True, "support": False}
        else:
            # Balanced strategy
            for robot in self.robots:
                robot.strategy = {"aggressive": False, "defensive": False, "support": True}

    def __str__(self):
        return f"Team {self.team.name} Strategy with {len(self.robots)} robots"

