    def find_nearest_enemy(self, robot):
        """Finds the nearest enemy robot to the given robot."""
        enemies = [r for r in self.robots if r.team != robot.team]
        if not enemies:
            return None
        return min(enemies, key=lambda r: robot.position.distance_to(r.position))

    def find_objective(self, robot):
        """Finds an objective of interest to the robot based on its role."""
        if robot.role == "attacker":
            return min(self.objectives, key=lambda o: robot.position.distance_to(o.position))
        elif robot.role == "defender":
            for objective in self.objectives:
                if objective.objective_type in [ObjectiveType.DEFEND_BASE, ObjectiveType.ESCORT_PAYLOAD]:
