        red_victory = self.check_victory(Team.RED)
        blue_victory = self.check_victory(Team.BLUE)
        if red_victory and blue_victory:
            winner = "Draw"
        elif red_victory:
            winner = "Team RED"
        elif blue_victory:
            winner = "Team BLUE"
        else:
            winner = "No clear winner"

        print(f"Battle Result: {winner}")

        # Display final scores
        print("Final Scores:")
        for robot in self.robots:
            print(f"{robot.name} (Team {robot.team.name}): {robot.score} points")

        # Reset game state for next battle
        self.reset_game()

    def reset_game(self):
        """Resets the game state for a new battle."""
        self.robots = []
        self.objectives = []
        self.power_ups = []
        self.team_strategies = [TeamStrategy(Team.RED), TeamStrategy(Team.BLUE)]
        self.battle_active = False
        self.game_paused = False
        print("Game reset. Ready for next battle.")

    def pause_game(self):
        """Pauses the game."""
        self.game_paused = True
        print("Game paused.")

    def resume_game(self):
        """Resumes the game."""
        self.game_paused = False
        print("Game resumed.")

    def stop_game(self):
        """Stops the battle and ends the game."""
        self.battle_active = False
        print("Game stopped.")

    def run(self):
        """Runs the CyberArena simulation."""
        self.setup_game()
        self.start_battle()

