import uuid
from enum import Enum
from datetime import datetime
from typing import List, Dict

# Enums for system status
class OrderStatus(Enum):
    PENDING = 'Pending'
    PROCESSING = 'Processing'
    READY = 'Ready for Pickup'
    DELIVERING = 'Out for Delivery'
    DELIVERED = 'Delivered'
    CANCELED = 'Canceled'

class DeliveryStatus(Enum):
    ASSIGNED = 'Assigned'
    ACCEPTED = 'Accepted'
    REJECTED = 'Rejected'
    IN_TRANSIT = 'In Transit'
    COMPLETED = 'Completed'

# User class
class User:
    def __init__(self, user_id: str, name: str, address: str):
        self.user_id = user_id
        self.name = name
        self.address = address

# Restaurant class
class Restaurant:
    def __init__(self, restaurant_id: str, name: str, location: str):
        self.restaurant_id = restaurant_id
        self.name = name
        self.location = location
        self.menu = {}

    def add_to_menu(self, item_id: str, item_name: str, price: float, is_available: bool):
        self.menu[item_id] = {
            'name': item_name,
            'price': price,
            'available': is_available
        }

# Cart class
class Cart:
    def __init__(self, user_id: str):
        self.user_id = user_id
        self.items = {}  # {restaurant_id: {item_id: quantity}}

    def add_item(self, restaurant_id: str, item_id: str, quantity: int):
        if restaurant_id not in self.items:
            self.items[restaurant_id] = {}
        self.items[restaurant_id][item_id] = self.items[restaurant_id].get(item_id, 0) + quantity

    def remove_item(self, restaurant_id: str, item_id: str, quantity: int):
        if restaurant_id in self.items and item_id in self.items[restaurant_id]:
            self.items[restaurant_id][item_id] -= quantity
            if self.items[restaurant_id][item_id] <= 0:
                del self.items[restaurant_id][item_id]

    def is_valid(self, restaurants: Dict[str, Restaurant]) -> bool:
        for restaurant_id, items in self.items.items():
            if restaurant_id not in restaurants:
                return False
            restaurant = restaurants[restaurant_id]
            for item_id in items:
                if item_id not in restaurant.menu or not restaurant.menu[item_id]['available']:
                    return False
        return True

# Order class
class Order:
    def __init__(self, user_id: str, restaurants: Dict[str, Restaurant]) -> None:
        self.order_id = str(uuid.uuid4())
        self.user_id = user_id
        self.restaurants = restaurants
        self.cart = Cart(user_id)
        self.status = OrderStatus.PENDING
        self.created_at = datetime.now()
        self.restaurant_orders = {}  # {restaurant_id: order_details}

    def place_order(self) -> bool:
        if not self.cart.is_valid(self.restaurants):
            return False

        for restaurant_id, items in self.cart.items.items():
            restaurant = self.restaurants[restaurant_id]
            order_details = {
                'restaurant_id': restaurant_id,
                'items': items,
                'total': self._calculate_total(restaurant, items),
                'status': OrderStatus.PROCESSING
            }
            self.restaurant_orders[restaurant_id] = order_details

        self.status = OrderStatus.PROCESSING
        return True

    def _calculate_total(self, restaurant: Restaurant, items: Dict[str, int]) -> float:
        total = 0.0
        for item_id, quantity in items.items():
            if item_id in restaurant.menu:
                total += restaurant.menu[item_id]['price'] * quantity
        return total

# DeliveryAgent class
class DeliveryAgent:
    def __init__(self, agent_id: str, name: str, location: str):
        self.agent_id = agent_id
        self.name = name
        self.location = location
        self.status = DeliveryStatus.ASSIGNED

    def assign_delivery(self, delivery_id: str, order_id: str, destination: str):
        self.delivery_id = delivery_id
        self.order_id = order_id
        self.destination = destination
        self.status = DeliveryStatus.ASSIGNED

    def accept_delivery(self):
        self.status = DeliveryStatus.ACCEPTED

    def reject_delivery(self):
        self.status = DeliveryStatus.REJECTED

    def start_delivery(self):
        self.status = DeliveryStatus.IN_TRANSIT

    def complete_delivery(self):
        self.status = DeliveryStatus.COMPLETED

# OrderDelivery class
class OrderDelivery:
    def __init__(self, order_id: str, user_address: str):
        self.order_id = order_id
        self.user_address = user_address
        self.deliveries = []  # List of delivery agent assignments

    def assign_agents(self, agents: List[DeliveryAgent], restaurant_locations: List[str]):
        for i, agent in enumerate(agents):
            delivery_id = f"{self.order_id}_D{i+1}"
            restaurant_location = restaurant_locations[i]
            agent.assign_delivery(delivery_id, self.order_id, self.user_address)
            self.deliveries.append({
                'delivery_id': delivery_id,
                'agent': agent,
                'restaurant_location': restaurant_location
            })

    def update_status(self):
        for delivery in self.deliveries:
            # Simulate status update by agent
            if delivery['agent'].status == DeliveryStatus.ACCEPTED:
                delivery['agent'].start_delivery()
            elif delivery['agent'].status == DeliveryStatus.COMPLETED:
                # Update order status if all deliveries are completed
                all_completed = all(d['agent'].status == DeliveryStatus.COMPLETED for d in self.deliveries)
                if all_completed:
                    # Update original order status
                    for restaurant_order in self.original_order.restaurant_orders.values():
                        restaurant_order['status'] = OrderStatus.DELIVERED
                    self.original_order.status = OrderStatus.DELIVERED

# MultiServe system class
class MultiServe:
    def __init__(self):
        self.users = {}
        self.restaurants = {}
        self.agents = {}
        self.active_orders = {}
        self.active_deliveries = {}

    def add_user(self, user_id: str, name: str, address: str) -> bool:
        if user_id in self.users:
            return False
        self.users[user_id] = User(user_id, name, address)
        return True

    def add_restaurant(self, restaurant_id: str, name: str, location: str) -> bool:
        if restaurant_id in self.restaurants:
            return False
        self.restaurants[restaurant_id] = Restaurant(restaurant_id, name, location)
        return True

    def add_menu_item(self, restaurant_id: str, item_id: str, item_name: str, price: float, is_available: bool) -> bool:
        if restaurant_id not in self.restaurants:
            return False
        self.restaurants[restaurant_id].add_to_menu(item_id, item_name, price, is_available)
        return True

    def add_delivery_agent(self, agent_id: str, name: str, location: str) -> bool:
        if agent_id in self.agents:
            return False
        self.agents[agent_id] = DeliveryAgent(agent_id, name, location)
        return True

    def create_order(self, user_id: str) -> Order:
        if user_id not in self.users:
            return None
        return Order(user_id, self.restaurants)

    def process_order(self, order: Order) -> bool:
        if not order.place_order():
            return False
        self.active_orders[order.order_id] = order
        # Create delivery for the order
        delivery = OrderDelivery(order.order_id, self.users[order.user_id].address)
        delivery.original_order = order

        # Assign deliveries to agents
        restaurant_ids = list(order.cart.items.keys())
        available_agents = [self.agents[agent_id] for agent_id in self.agents]
        if len(available_agents) >= len(restaurant_ids):
            delivery.assign_agents(available_agents[:len(restaurant_ids)], 
                                  [self.restaurants[rid].location for rid in restaurant_ids])
            self.active_deliveries[order.order_id] = delivery
        return True

    def cancel_order(self, order_id: str) -> bool:
        if order_id not in self.active_orders:
            return False
        order = self.active_orders[order_id]
        for restaurant_order in order.restaurant_orders.values():
            if restaurant_order['status'] == OrderStatus.PROCESSING:
                restaurant_order['status'] = OrderStatus.CANCELED

