        move_x = self.location[0] + (dx / distance) * speed
        move_y = self.location[1] + (dy / distance) * speed

        return (move_x, move_y)

    def _move_away_from(self, target_location, speed):
        dx = self.location[0] - target_location[0]
        dy = self.location[1] - target_location[1]
        distance = (dx**2 + dy**2)**0.5

        if distance == 0:
            return self.location

        move_x = self.location[0] + (dx / distance) * speed
        move_y = self.location[1] + (dy / distance) * speed

        return (move_x, move_y)

    def _find_path_to_objective(self, arena, current_time):
        # Simple pathfinding: check if the direct path is clear
        path = []
        current_pos = self.location
        objective_pos = self.objective.location

        steps = int(self._distance_to(objective_pos) / self.speed)

        for i in range(1, steps + 1):
            x = self.location[0] + (objective_pos[0] - self.location[0]) * (i / steps)
            y = self.location[1] + (objective_pos[1] - self.location[1]) * (i / steps)
            path.append((x, y))

        # Check if the path is blocked by hazards
        for hazard in arena.hazards:
            if hazard.is_active(current_time):
                for point in path:
                    if self._distance_to((hazard.location[0], hazard.location[1])) < hazard.radius + 1:
                        return []  # Path is blocked

        return path

    def _find_alternative_path(self, arena, current_time):
        # Find alternative path by checking surrounding areas
        alternatives = [
            (self.location[0] + 1, self.location[1]),
            (self.location[0] - 1, self.location[1]),
            (self.location[0], self.location[1] + 1),
            (self.location[0], self.location[1] - 1)
        ]

        for alternative in alternatives:
            # Check if this alternative path is clear
            for hazard in arena.hazards:
                if hazard.is_active(current_time) and self._distance_to(alternative) < hazard.radius + 2:
                    continue  # Skip this alternative if it's in a hazard

            # Check if this alternative path is closer to the objective
            if self._distance_to(alternative) < self._distance_to(self.objective.location):
                return alternative

        # If no good alternative found, just move randomly
        return (self.location[0] + random.randint(-1, 1), self.location[1] + random.randint(-1, 1))

# Class for the CyberArena environment
class CyberArena:
    def __init__(self, width, height, teams, objectives, hazards, powerups):
        self.width = width
        self.height = height
        self.teams = teams
        self.robots = []
        self.objectives = objectives
        self.hazards = hazards
        self.powerups = powerups
        self.rounds = 0
