        # Initialize powerup activation times
        for powerup in self.powerups:
            powerup.activation_time = random.uniform(60, 120)  # Powerups appear between 1-2 minutes

    def add_robot(self, robot):
        if robot.team in self.teams:
            self.robots.append(robot)
            self.team_robots[robot.team].append(robot)
            # Assign an objective to the robot
            robot.objective = random.choice(self.team_objectives[robot.team])
        else:
            raise ValueError(f"Team {robot.team} is not a valid team in this arena.")

    def update(self, current_time):
        # Check if the arena has reached its time limit
        if (current_time - self.start_time) >= self.total_time:
            self._determine_winner()
            return True

        # Update robot positions and actions
        for robot in self.robots:
            if robot.is_alive():
                robot.move(self, current_time)
                if random.random() < 0.2:  # 20% chance to attack
                    target = self._find_attack_target(robot)
                    if target:
                        robot.attack(target, current_time)
                if random.random() < 0.1 and robot.health < 100:  # 10% chance to use healing powerup
                    robot.use_powerup(PowerupType.HEAL, current_time)

        # Check for objective completions
        for objective in self.objectives:
            if not objective.completed:
                if objective.check_completion(self.robots):
                    # Award points to the team that completed the objective
                    self.score[objective.team] += 10
                    # Reset the objective for the next round
                    # (In a real game, this would be replaced with a new objective)
                    objective.completed = False

