        return False

    def _distance_to(self, robot_1, robot_2):
        return ((robot_1.location[0] - robot_2.location[0])**2 + 
               (robot_1.location[1] - robot_2.location[1])**2)**0.5

    def _find_attack_target(self, robot):
        # Find a suitable attack target based on AI behavior
        if robot.behavior_level == AI_Behavior.BASIC:
            # Basic AI: attack the nearest enemy
            nearest_enemy = self._find_nearest_enemy(robot)
            if nearest_enemy and nearest_enemy.is_alive():
                return nearest_enemy
        elif robot.behavior_level == AI_Behavior.ADVANCED:
            # Advanced AI: attack the most vulnerable enemy
            most_vulnerable = None
            for enemy in self._find_enemies(robot):
                if enemy.is_alive() and (most_vulnerable is None or enemy.health < most_vulnerable.health):
                    most_vulnerable = enemy
            return most_vulnerable
        elif robot.behavior_level == AI_Behavior.EXPERT:
            # Expert AI: choose the best target based on position and strategy
            best_target = None
            for enemy in self._find_enemies(robot):
                if enemy.is_alive():
                    # Consider distance, enemy health, and potential for damage
                    distance = self._distance_to(robot, enemy)
                    if (best_target is None or 
                        (distance < 5 and enemy.health < 50) or 
                        (distance < 3 and enemy.health < 30)):
                        best_target = enemy
            return best_target

        return None

    def _find_nearest_enemy(self, robot):
        nearest_enemy = None
        min_distance = float('inf')

        for enemy in self._find_enemies(robot):
            if enemy.is_alive():
                distance = self._distance_to(robot, enemy)
                if distance < min_distance:
                    min_distance = distance
                    nearest_enemy = enemy
        return nearest_enemy

    def _find_enemies(self, robot):
        return [r for r in self.robots if r.team != robot.team and r.is_alive()]

    def _determine_winner(self):
        # Determine the winning team based on score
        max_score = max(self.score.values())
        winners = [team for team, score in self.score.items() if score == max_score]

        if len(winners) == 1:
            self.winning_team = winners[0]
            print(f"Winner: Team {self.winning_team} with {max_score} points!")
        else:
            print(f"Tie game! Teams {', '.join(winners)} all have {max_score} points.")
            # For a tie, randomly choose a winner
            self.winning_team = random.choice(winners)

    def get_status(self):
        return {
            "time_remaining": self.total_time - (time.time() - self.start_time),
            "score": self.score,
            "winning_team": self.winning_team,
            "alive_robots": sum([1 for r in self.robots if r.is_alive()]),
            "objectives_completed": sum([1 for o in self.objectives if o.completed])
        }

