# ================== Arena Class ==================
class Arena:
    """Class representing the CyberArena environment"""
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.robots = []
        self.power_ups = []
        self.objective = None
        self.teams = {
            Team.ALIENS: [],
            Team.MECHS: [],
            Team.DRONES: []
        }
        self.scoreboard = {Team.ALIENS: 0, Team.MECHS: 0, Team.DRONES: 0}
        self.difficulty = 1.0  # Base difficulty
        self.time_elapsed = 0.0  # In seconds

    def add_robot(self, robot):
        """Add a robot to the arena"""
        self.robots.append(robot)
        self.teams[robot.team].append(robot)

    def add_power_up(self, power_up):
        """Add a power-up to the arena"""
        self.power_ups.append(power_up)

    def set_objective(self, objective):
        """Set the current objective for the battle"""
        self.objective = objective

    def update(self):
        """Update all robots in the arena"""
        self.time_elapsed += 0.1  # Assuming 10 FPS update
        for robot in self.robots:
            robot.update(self)

        # Check for objective completion
        if self.objective and self.objective.is_complete(self):
            print(f"Objective '{self.objective.name}' completed!")
            self.objective.complete()

        # Handle difficulty adaptation
        self.update_difficulty()

    def update_difficulty(self):
        """Adjust difficulty based on robot performance"""
        alive_robots = sum(len(team) for team in self.teams.values())
        if alive_robots < 5:  # If fewer robots are alive, increase difficulty
            self.difficulty += 0.1
            print(f"Difficulty increased to {self.difficulty:.2f}")
        elif alive_robots > 10:  # If more robots are alive, decrease difficulty
            self.difficulty = max(0.5, self.difficulty - 0.05)
            print(f"Difficulty decreased to {self.difficulty:.2f}")

    def get_score(self, team):
        """Get the score for a team"""
        return self.scoreboard.get(team, 0)

    def add_score(self, team, amount):
        """Add points to a team's score"""
        self.scoreboard[team] = self.scoreboard.get(team, 0) + amount

    def display_scoreboard(self):
        """Display the current scoreboard"""
        print("Scoreboard:")
        for team, score in self.scoreboard.items():
            print(f"{team.name}: {score} points")

    def check_team_victory(self):
        """Check if a team has won the match"""
        for team, members in self.teams.items():
            if all(not robot.is_alive for robot in members):
                print(f"{team.name} team has been eliminated!")
                return True
        return False

