    """Objective where a team must capture an enemy flag"""
    def __init__(self, name, flag_position):
        super().__init__(name, "Capture the enemy flag and return it to your base")
        self.flag_position = flag_position
        self.return_position = None  # Position where the flag should be returned

    def is_complete(self, arena):
        """Check if the objective is complete"""
        for robot in arena.robots:
            if (robot.position.x, robot.position.y) == (self.return_position.x, self.return_position.y):
                return True
        return False

    def complete(self):
        """Handle objective completion"""
        print("Flag captured and returned! Objective completed!")

class DefendBaseObjective(Objective):
