class CelestialBody:
    """Class representing a celestial body"""
    def __init__(self, name: str, mass: float, radius: float, position: Position, velocity: Position):
        self.name = name
        self.mass = mass
        self.radius = radius
        self.position = position
        self.velocity = velocity

    def update_position(self, dt: float):
        self.position = Position(self.position.x + self.velocity.x * dt,
                                 self.position.y + self.velocity.y * dt)

    def gravitational_force(self, other) -> Position:
        G = 6.67430e-11  # gravitational constant
        r = self.position.distance_to(other.position)
        if r == 0:
            return Position(0, 0)
        fx = G * self.mass * other.mass * (other.position.x - self.position.x) / r**3
        fy = G * self.mass * other.mass * (other.position.y - self.position.y) / r**3
        return Position(fx, fy)

class SimulationEngine:
    """Handles physics and simulation of celestial mechanics"""
    def __init__(self):
        self.bodies: List[CelestialBody] = []

    def add_body(self, body: CelestialBody):
        self.bodies.append(body)

    def update(self, dt: float):
        # Apply gravitational forces
        forces = {body: Position(0, 0) for body in self.bodies}
        for i, body in enumerate(self.bodies):
            for j, other in enumerate(self.bodies):
                if i != j:
                    force = body.gravitational_force(other)
                    forces[body] = forces[body] + force

