class Arena:
    def __init__(self, width: float, height: float):
        self.width = width
        self.height = height
        self.robots = []
        self.power_ups = []
        self.hazards = []
        self.objectives = []
        self.teams_score = {team: 0 for team in Team}
        self.current_time = 0.0
        self.round_time = 120.0  # 2 minutes per round
        self.difficulty_level = 1  # 1 is easiest, 5 is hardest
        self.round_winning_team = None

    def add_robot(self, robot: Robot):
        """Add a robot to the arena"""
        self.robots.append(robot)

    def add_power_up(self, power_up: "PowerUp"):
        """Add a power-up to the arena"""
        self.power_ups.append(power_up)

    def add_hazard(self, hazard: "Hazard"):
        """Add a hazard to the arena"""
        self.hazards.append(hazard)

    def add_objective(self, objective: "Objective"):
        """Add an objective to the arena"""
        self.objectives.append(objective)

    def update(self, dt: float):
        """Update the arena and all its elements"""
        self.current_time += dt
        if self.current_time >= self.round_time:
            self.end_round()

        # Update all robots
        for robot in self.robots:
            robot.update(dt, self)

        # Update all power-ups
        for power_up in self.power_ups:
            power_up.update(dt)

        # Update all hazards
        for hazard in self.hazards:
            hazard.update(dt)

        # Update all objectives
        for objective in self.objectives:
            objective.update(dt)

        # Check if any objective is completed
        for objective in self.objectives:
            if objective.is_complete:
                self.complete_objective(objective)

    def end_round(self):
        """End the current round and determine the winning team"""
        winning_team = self.determine_winning_team()
        if winning_team:
            self.teams_score[winning_team] += 1
            self.round_winning_team = winning_team
            self.broadcast_message(f"Team {winning_team.name} wins the round!")
        else:
            self.broadcast_message("Round ended in a draw!")
        # Reset the arena for the next round
        self.reset_round()

    def determine_winning_team(self) -> Optional[Team]:
        """Determine the winning team based on objectives and scores"""
        # Example: The team with the most points wins
        scores = {team: self.teams_score[team] for team in Team}
        max_score = max(scores.values())
        winners = [team for team in Team if scores[team] == max_score]
        return winners[0] if len(winners) == 1 else None

    def complete_objective(self, objective: "Objective"):
        """Handle the completion of an objective"""
        if objective.team:
            self.teams_score[objective.team] += objective.points
            self.broadcast_message(f"Team {objective.team.name} completed objective: {objective.name} (+{objective.points} points)")
        else:
            self.broadcast_message(f"Objective completed: {objective.name}")
        # Remove the objective from the arena
        self.objectives.remove(objective)

    def reset_round(self):
        """Reset the arena for a new round"""
        self.current_time = 0.0
        self.round_winning_team = None
        # In a real game, we would reset robot positions, health, etc.
        for robot in self.robots:
            robot.health = robot.max_health
            robot.position = self.get_spawn_position(robot.team)
        # Re-spawn power-ups and hazards
        for power_up in self.power_ups:
            power_up.respawn()
        for hazard in self.hazards:
            hazard.respawn()
        # In a real game, we would also reset objectives and adjust difficulty

    def get_spawn_position(self, team: Team) -> Position:
        """Get a spawn position for a team"""
        # This is a placeholder implementation
        # In a real game, we would have defined spawn points for each team
        if team == Team.RED:
            return Position(-10, -10)
        elif team == Team.BLUE:
            return Position(10, -10)
        elif team == Team.GREEN:
            return Position(-10, 10)
        elif team == Team.YELLOW:
            return Position(10, 10)
        return Position(0, 0)

    def broadcast_message(self, message: str):
        """Broadcast a message to all players (simulated)"""
        print(f"[ANNOUNCEMENT] {message}")

    def adjust_difficulty(self):
        """Adjust the difficulty based on team performance"""
        # In a real game, this would consider various factors like
        # number of kills, objectives completed, time taken, etc.
        # For this example, we'll just increase difficulty if one team is leading
        scores = [self.teams_score[team] for team in Team]
        max_score = max(scores)
        if max_score >= len(scores) - 1:
            self.difficulty_level = min(5, self.difficulty_level + 1)
            self.broadcast_message(f"Difficulty increased to level {self.difficulty_level}")
        elif max_score <= 1:
            self.difficulty_level = max(1, self.difficulty_level - 1)
            self.broadcast_message(f"Difficulty decreased to level {self.difficulty_level}")
        else:
            self.difficulty_level = max(1, self.difficulty_level - 1)
            self.broadcast_message(f"Difficulty adjusted to level {self.difficulty_level}")

    def get_team_score(self, team: Team) -> int:
        """Get the score for a team"""
        return self.teams_score[team]

    def get_all_scores(self) -> Dict[Team, int]:
        """Get the scores for all teams"""
        return self.teams_score

    def get_robot_by_name(self, name: str) -> Optional[Robot]:
        """Get a robot by name"""
        for robot in self.robots:
            if robot.name == name:
                return robot
        return None

