class PowerUp:
    def __init__(self, name: str, position: Position, duration: float, effect: callable):
        self.name = name
        self.position = position
        self.duration = duration
        self.effect = effect
        self.is_active = True
        self.activation_time = 0.0

    def update(self, dt: float):
        """Update the power-up state"""
        if not self.is_active:
            return
        if self.activation_time > 0 and self.activation_time <= time.time():
            self.deactivate()

    def activate(self):
        """Activate the power-up effect"""
        if self.is_active:
            return
        self.activation_time = time.time() + self.duration
        self.is_active = True

    def deactivate(self):
        """Deactivate the power-up effect"""
        self.is_active = False

    def respawn(self):
        """Respawn the power-up"""
        self.deactivate()
        self.activation_time = time.time() + random.uniform(10, 30)
        self.is_active = False

    def use(self, robot: Robot):
        """Apply the power-up to a robot"""
        if not self.is_active:
            return False
        self.effect(robot)
        return True

    def __str__(self):
        return f"{self.name} at {self.position}, Duration: {self.duration:.2f}s"

class SpeedBoost(PowerUp):
    def __init__(self, position: Position):
        super().__init__("Speed Boost", position, 10.0, self.apply_speed_boost)

