class Hazard:
    def __init__(self, name: str, position: Position, radius: float, damage: float):
        self.name = name
        self.position = position
        self.radius = radius
        self.damage = damage
        self.is_active = True
        self.activation_time = 0.0

    def update(self, dt: float, arena: Arena):
        """Update the hazard state"""
        if not self.is_active:
            return
        if self.activation_time > 0 and self.activation_time <= time.time():
            self.deactivate()
            # Re-activate after a random time
            self.activation_time = time.time() + random.uniform(30, 60)
            self.is_active = True

        # Check for robots in the hazard area
        for robot in arena.robots:
            if robot.position.distance_to(self.position) <= self.radius:
                # Apply damage to the robot
                robot.take_damage(self.damage * dt)

    def deactivate(self):
        """Deactivate the hazard"""
        self.is_active = False

    def respawn(self):
        """Respawn the hazard"""
        self.deactivate()
        self.activation_time = time.time() + random.uniform(10, 30)
        self.is_active = False

    def __str__(self):
        return f"{self.name} at {self.position}, Radius: {self.radius:.2f}, Damage: {self.damage:.2f}"

class LaserTurret(Hazard):
    def __init__(self, position: Position):
        super().__init__("Laser Turret", position, 1.0, 10.0)
        self.fire_rate = 1.0  # shots per second
        self.last_shot_time = 0.0

    def update(self, dt: float, arena: Arena):
        """Update the laser turret behavior"""
        super().update(dt, arena)

        # Fire at the nearest robot
        if time.time() - self.last_shot_time >= 1.0 / self.fire_rate:
            nearest_robot = self.find_nearest_robot(arena)
            if nearest_robot:
                distance = self.position.distance_to(nearest_robot.position)
                if distance <= 10.0:
                    # Calculate the direction to the robot
                    direction = self.calculate_direction(self.position, nearest_robot.position)
                    # Apply damage to the robot
                    nearest_robot.take_damage(self.damage)
                    self.last_shot_time = time.time()
                    print(f"Laser Turret at {self.position} fired at {nearest_robot.name}!")

    def find_nearest_robot(self, arena: Arena) -> Optional[Robot]:
        """Find the nearest robot to the hazard"""
        if not arena.robots:
            return None
        return min(arena.robots, key=lambda robot: self.position.distance_to(robot.position))

    def calculate_direction(self, current: Position, target: Position) -> Direction:
        """Calculate the direction from current position to target position"""
        dx = target.x - current.x
        dy = target.y - current.y

        if abs(dx) > abs(dy):
            return Direction.EAST if dx > 0 else Direction.WEST
        else:
            return Direction.NORTH if dy > 0 else Direction.SOUTH

