class Objective:
    def __init__(self, name: str, position: Position, points: int, team: Optional[Team] = None):
        self.name = name
        self.position = position
        self.points = points
        self.team = team  # Optional team association
        self.is_complete = False
        self.completion_time = 0.0

    def update(self, dt: float, arena: Arena):
        """Update the objective state"""
        if self.is_complete:
            return

        # In a real game, this would check if the objective is complete
        # For this example, we'll just randomize completion
        if random.random() < 0.001:  # 0.1% chance per update
            self.is_complete = True
            self.completion_time = time.time()
            print(f"Objective '{self.name}' completed!")

    def __str__(self):
        return f"{self.name} at {self.position}, Points: {self.points}"

class FlagCapture(Objective):
    def __init__(self, name: str, position: Position, target_position: Position, points: int, team: Team):
        super().__init__(name, position, points, team)
        self.target_position = target_position
        self.carried_by = None

    def update(self, dt: float, arena: Arena):
        """Update the flag capture objective"""
        if self.is_complete:
            return

        # Check if a robot is carrying the flag
        flag_carriers = [robot for robot in arena.robots if self.carried_by and robot == self.carried_by]

        if flag_carriers:
            # Move the flag with the carrier
            self.position = self.carried_by.position

            # Check if the carrier reached the target position
            if self.carried_by.position.distance_to(self.target_position) < 1.0:
                self.is_complete = True
                self.completion_time = time.time()
                arena.teams_score[self.team] += self.points
                print(f"Team {self.team.name} captured the flag at {self.target_position}!")
                arena.broadcast_message(f"Team {self.team.name} captured the flag!")
        else:
            # If no carrier, return the flag to its base position
            self.position = self.position.move_towards(self.target_position, dt)
            if self.position.distance_to(self.target_position) < 1.0:
                self.position = self.target_position

    def pickup(self, robot: Robot):
        """Allow a robot to pickup the flag"""
        if not self.is_complete and not self.carried_by:
            self.carried_by = robot
            print(f"{robot.name} picked up the flag!")

    def drop(self, robot: Robot):
        """Allow a robot to drop the flag"""
        if self.carried_by == robot:
            self.carried_by = None
            print(f"{robot.name} dropped the flag!")

class BaseDefense(Objective):
    def __init__(self, name: str, position: Position, team: Team, points: int, radius: float):
        super().__init__(name, position, points, team)
        self.radius = radius
        self.is_under_attack = False

    def update(self, dt: float, arena: Arena):
        """Update the base defense objective"""
        if self.is_complete:
            return

        # Check if the base is under attack
        if not self.is_under_attack:
            for robot in arena.robots:
                if not self.is_teammate(robot) and self.position.distance_to(robot.position) < self.radius:
                    self.is_under_attack = True
                    print(f"Team {self.team.name} base is under attack!")
                    arena.broadcast_message(f"Team {self.team.name} base is under attack!")
                    break
        else:
            # Check if the threat has passed
            under_attack = False
            for robot in arena.robots:
                if not self.is_teammate(robot) and self.position.distance_to(robot.position) < self.radius:
                    under_attack = True
                    break
            if not under_attack:
                self.is_under_attack = False
                print(f"Team {self.team.name} base is no longer under attack!")
                arena.broadcast_message(f"Team {self.team.name} base is no longer under attack!")

    def is_teammate(self, robot: Robot) -> bool:
        """Check if a robot is a teammate of the base"""
        return self.team == robot.team

