import random
import time
import threading
from dataclasses import dataclass
from enum import Enum
from typing import Dict, List, Optional, Tuple

# Define constants for the game
SCREEN_WIDTH = 800
SCREEN_HEIGHT = 600
ARENA_SIZE = (SCREEN_WIDTH, SCREEN_HEIGHT)
MAX_ROBOTS = 10
MAX_TEAMS = 2
MAX_WEAPON_TYPES = 3
MAX_POWER_UP_TYPES = 5
MAX_HAZARD_TYPES = 3

# Enum for different types of weapons
class WeaponType(Enum):
    LASER = 1
    PLASMA = 2
    MELEE = 3

# Enum for different types of power-ups
class PowerUpType(Enum):
    SHIELD = 1
    SPEED_BOOST = 2
    DAMAGE_BOOST = 3
    TELEPORT = 4
    TEAM_SHIELD = 5

# Enum for different types of hazards
class HazardType(Enum):
    LAVA = 1
    ELECTRICITY = 2
    FREEZE = 3

# Enum for robot status
class RobotStatus(Enum):
    ALIVE = 1
    DEAD = 2
    DISABLED = 3

# Enum for robot roles in team
class RobotRole(Enum):
    COMMANDER = 1
    TANK = 2
    SUPPORT = 3
    SCOUT = 4

# Enum for team objectives
class Objective(Enum):
    CAPTURE_FLAG = 1
    DEFEND_BASE = 2
    ESCORT_PAYLOAD = 3

# Data class for position and velocity
@dataclass
class Position:
    x: float
    y: float

# Base class for all game entities
class Entity:
    def __init__(self, position: Position):
        self.position = position
        self.is_active = True

# Class for weapons
class Weapon:
    def __init__(self, weapon_type: WeaponType, damage: float, range: float, cooldown: float):
        self.type = weapon_type
        self.damage = damage
        self.range = range
        self.cooldown = cooldown
        self.last_used = 0.0

    def can_use(self) -> bool:
        return time.time() - self.last_used >= self.cooldown

    def use(self):
        self.last_used = time.time()

# Class for power-ups
class PowerUp(Entity):
    def __init__(self, position: Position, power_up_type: PowerUpType, duration: float):
        super().__init__(position)
        self.type = power_up_type
        self.duration = duration
        self.activation_time = 0.0

    def apply_effect(self, robot):
        if not self.is_active:
            return
        self.activation_time = time.time()
        if self.type == PowerUpType.SHIELD:
            robot.shield = min(robot.max_shield, robot.shield + 50)
        elif self.type == PowerUpType.SPEED_BOOST:
            robot.speed = min(robot.max_speed * 1.5, robot.speed + 10)
        elif self.type == PowerUpType.DAMAGE_BOOST:
            robot.attack_power = min(robot.base_attack_power * 1.5, robot.attack_power + 20)
        elif self.type == PowerUpType.TELEPORT:
            robot.position = Position(random.randint(0, ARENA_SIZE[0]), random.randint(0, ARENA_SIZE[1]))
        self.is_active = False

    def is_effect_active(self) -> bool:
        return time.time() - self.activation_time < self.duration if self.is_active else False

# Class for hazards
class Hazard(Entity):
    def __init__(self, position: Position, hazard_type: HazardType, damage_rate: float):
        super().__init__(position)
        self.type = hazard_type
        self.damage_rate = damage_rate
        self.last_damage = 0.0

    def apply_damage(self, robot):
        if time.time() - self.last_damage >= 1.0:
            if self.type == HazardType.LAVA:
                robot.take_damage(self.damage_rate * 1.5)
            elif self.type == HazardType.ELECTRICITY:
                robot.take_damage(self.damage_rate)
                robot.shock(robot, 1.0)
            elif self.type == HazardType.FREEZE:
                robot.freeze(2.0)
            self.last_damage = time.time()

# Class for robots
class Robot(Entity):
    def __init__(self, position: Position, team: str, role: RobotRole):
        super().__init__(position)
        self.team = team
        self.role = role
        self.status = RobotStatus.ALIVE
        self.health = 100.0
        self.max_health = 100.0
        self.shield = 0.0
        self.max_shield = 50.0
        self.speed = 5.0
        self.max_speed = 5.0
        self.attack_power = 10.0
        self.base_attack_power = 10.0
        self.weapon = self._initialize_weapon()
        self.power_ups = []
        self.active_buffs = []

    def _initialize_weapon(self) -> Weapon:
        # Initialize a random weapon for the robot
        weapon_type = random.choice(list(WeaponType))
        return Weapon(weapon_type, 
                     damage=random.uniform(5, 15), 
                     range=random.uniform(20, 100), 
                     cooldown=random.uniform(1, 3))

    def move(self, direction: Position, arena_size: Tuple[float, float]):
        # Move the robot in the specified direction
        self.position.x += direction.x * self.speed
        self.position.y += direction.y * self.speed

        # Keep robot within arena boundaries
        self.position.x = max(0, min(self.position.x, arena_size[0]))
        self.position.y = max(0, min(self.position.y, arena_size[1]))

    def take_damage(self, amount: float):
        if self.shield > 0:
            if amount <= self.shield:
                self.shield -= amount
                amount = 0
            else:
                amount -= self.shield
                self.shield = 0

        self.health -= amount
        if self.health <= 0:
            self.status = RobotStatus.DEAD
            self.health = 0

    def heal(self, amount: float):
        self.health = min(self.max_health, self.health + amount)

    def recharge_shield(self):
        if self.shield < self.max_shield:
            self.shield = min(self.max_shield, self.shield + 5)

    def use_weapon(self, target: 'Robot'):
        if self.weapon.can_use():
            distance = ((self.position.x - target.position.x)**2 + (self.position.y - target.position.y)**2)**0.5
            if distance <= self.weapon.range:
                target.take_damage(self.attack_power)
                self.weapon.use()
                return True
        return False

    def activate_power_up(self, power_up: PowerUp):
        if power_up not in self.power_ups:
            return False
        power_up.apply_effect(self)
        self.active_buffs.append(power_up)
        return True

    def update(self):
        # Update robot state (recharge shield, check active buffs, etc.)
        self.recharge_shield()
        for buff in self.active_buffs:
            if not buff.is_effect_active():
                self.active_buffs.remove(buff)

    def shock(self, duration: float):
        # Apply shock effect (slow movement)
        self.speed = max(0.5, self.speed * 0.5)
        threading.Timer(duration, self.reset_speed).start()

    def reset_speed(self):
        self.speed = self.max_speed

    def freeze(self, duration: float):
        # Apply freeze effect (stop movement)
        self.speed = 0
        threading.Timer(duration, self.unfreeze).start()

    def unfreeze(self):
        self.speed = self.max_speed

# Class for teams
class Team:
    def __init__(self, name: str, team_color: str, objective: Objective):
        self.name = name
        self.color = team_color
        self.objective = objective
        self.members = []
        self.score = 0
        self.base_position = Position(random.randint(0, ARENA_SIZE[0]), random.randint(0, ARENA_SIZE[1]))

    def add_robot(self, robot: Robot):
        self.members.append(robot)
        robot.team = self

    def assign_roles(self):
        # Randomly assign roles to team members
        roles = list(RobotRole)
        random.shuffle(roles)
        for i, robot in enumerate(self.members):
            robot.role = roles[i % len(roles)]

    def update_score(self, points: float):
        self.score += points

    def is_objective_complete(self) -> bool:
        # Check if the team has completed its objective
        if self.objective == Objective.CAPTURE_FLAG:
            # Check if flag is in our base
            return any(flag.owner == self for flag in arena.flags if flag.is_captured)
        elif self.objective == Objective.DEFEND_BASE:
            # Check if our base is intact
            return not any(hazard.type == HazardType.EXPLOSIVE for hazard in arena.hazards if hazard.position == self.base_position)
        elif self.objective == Objective.ESCORT_PAYLOAD:
            # Check if payload has reached destination
            return any(payload.destination == self.base_position for payload in arena.payloads)
        return False

# Class for the game arena
class Arena:
    def __init__(self):
        self.entities = []
        self.robots = []
        self.teams = []
        self.power_ups = []
        self.hazards = []
        self.flags = []
        self.payloads = []
        self.spawn_zones = []
        self.ambient_light = 0.8
        self.particle_effects = []
        self.sound_effects = []
        self.environment_music = "cyber_arena_theme.mp3"
        self.difficulty_level = 1.0
        self.battle_history = []
        self.learning_rate = 0.1

    def initialize_game(self):
        # Create teams and robots
        for i in range(MAX_TEAMS):
            team = Team(f"Team {i+1}", ["Red", "Blue"][i], random.choice(list(Objective)))
            self.teams.append(team)
            for _ in range(MAX_ROBOTS // MAX_TEAMS):
                robot = Robot(Position(random.randint(0, ARENA_SIZE[0]), random.randint(0, ARENA_SIZE[1])), 
                             team.name, 
                             RobotRole.COMMANDER)
                team.add_robot(robot)
                self.robots.append(robot)
                self.entities.append(robot)

        # Create power-ups
        for _ in range(MAX_POWER_UP_TYPES * 2):
            power_up_type = random.choice(list(PowerUpType))
            position = Position(random.randint(0, ARENA_SIZE[0]), random.randint(0, ARENA_SIZE[1]))
            power_up = PowerUp(position, power_up_type, random.uniform(5, 15))
            self.power_ups.append(power_up)
            self.entities.append(power_up)

        # Create hazards
        for _ in range(MAX_HAZARD_TYPES * 2):
            hazard_type = random.choice(list(HazardType))
            position = Position(random.randint(0, ARENA_SIZE[0]), random.randint(0, ARENA_SIZE[1]))
            hazard = Hazard(position, hazard_type, random.uniform(2, 5))
            self.hazards.append(hazard)
            self.entities.append(hazard)

        # Create flags for capture objective
        if any(team.objective == Objective.CAPTURE_FLAG for team in self.teams):
            for team in self.teams:
                flag = Flag(team.base_position, team)
                self.flags.append(flag)
                self.entities.append(flag)

        # Create payloads for escort objective
        if any(team.objective == Objective.ESCORT_PAYLOAD for team in self.teams):
            for team in self.teams:
                payload = Payload(team.base_position, 
                                 Position(random.randint(0, ARENA_SIZE[0]), random.randint(0, ARENA_SIZE[1])))
                self.payloads.append(payload)
                self.entities.append(payload)

        # Assign spawn zones
        for team in self.teams:
            spawn_zone = SpawnZone(Position(team.base_position.x - 50, team.base_position.y - 50), 
                                  Position(team.base_position.x + 50, team.base_position.y + 50))
            self.spawn_zones.append(spawn_zone)

        # Assign roles to robots
        for team in self.teams:
            team.assign_roles()

    def update(self):
        # Update all entities
        for entity in self.entities:
            if isinstance(entity, Robot):
                entity.update()
            elif isinstance(entity, PowerUp):
                if not entity.is_active:
                    # Respawn power-up after some time
                    if time.time() - entity.activation_time > 10.0:
                        entity.is_active = True
                        entity.activation_time = 0.0
            elif isinstance(entity, Hazard):
                pass  # Hazards are static but affect other entities

        # Check for collisions and interactions
        self.process_combat()
        self.process_power_ups()
        self.process_hazards()
        self.process_objectives()

        # Update difficulty based on robot performance
        self.update_difficulty()

        # Apply learning to robots
        self.apply_learning()

    def process_combat(self):
        # Process combat between robots
        for robot in self.robots:
            if robot.status != RobotStatus.ALIVE:
                continue
            # Find nearby enemies
            for enemy in self.robots:
                if robot == enemy or enemy.status != RobotStatus.ALIVE or enemy.team == robot.team:
                    continue

                distance = ((robot.position.x - enemy.position.x)**2 + (robot.position.y - enemy.position.y)**2)**0.5
                if distance < 50.0:
                    # Try to attack
                    if robot.use_weapon(enemy):
                        # Add combat event to history
                        self.battle_history.append({
                            "attacker": robot,
                            "target": enemy,
                            "damage": robot.attack_power,
                            "timestamp": time.time()
                        })

    def process_power_ups(self):
        # Process power-up interactions
        for robot in self.robots:
            if robot.status != RobotStatus.ALIVE:
                continue
            for power_up in self.power_ups:
                if not power_up.is_active:
                    continue
                distance = ((robot.position.x - power_up.position.x)**2 + 
                           (robot.position.y - power_up.position.y)**2)**0.5
                if distance < 20.0:
                    robot.activate_power_up(power_up)

    def process_hazards(self):
        # Process hazard effects
        for robot in self.robots:
            if robot.status != RobotStatus.ALIVE:
                continue
            for hazard in self.hazards:
                distance = ((robot.position.x - hazard.position.x)**2 + 
                           (robot.position.y - hazard.position.y)**2)**0.5
                if distance < 25.0:
