    def update_difficulty(self):
        # Adjust difficulty based on robot performance
        alive_robots = [robot for robot in self.robots if robot.status == RobotStatus.ALIVE]
        if not alive_robots:
            return

        avg_health = sum(robot.health for robot in alive_robots) / len(alive_robots)
        avg_speed = sum(robot.speed for robot in alive_robots) / len(alive_robots)
        avg_attack = sum(robot.attack_power for robot in alive_robots) / len(alive_robots)

        # Adjust difficulty based on performance
        if avg_health > 85 and avg_speed > 4.5 and avg_attack > 12:
            # Robots are too strong, increase difficulty
            self.difficulty_level = min(2.0, self.difficulty_level + 0.1)
        elif avg_health < 40 or avg_speed < 2.5 or avg_attack < 8:
