        return True

# Class for payloads
class Payload(Entity):
    def __init__(self, position: Position, destination: Position):
        super().__init__(position)
        self.destination = destination
        self.reached_destination = False
        self.speed = 2.0  # Speed at which the payload moves
        self.owner = None  # The robot currently carrying the payload

    def move(self):
        # Move the payload towards its destination
        if self.reached_destination:
            return
        # Calculate direction to destination
        dx = self.destination.x - self.position.x
        dy = self.destination.y - self.position.y
        distance = (dx**2 + dy**2)**0.5

        if distance > 0:
            # Move in direction of destination
            self.position.x += self.speed * (dx / distance)
            self.position.y += self.speed * (dy / distance)

            # Check if reached destination
            if (dx**2 + dy**2)**0.5 < 5:  # Within 5 units of destination
                self.reached_destination = True

# Class for spawn zones
class SpawnZone:
    def __init__(self, top_left: Position, bottom_right: Position):
        self.top_left = top_left
        self.bottom_right = bottom_right

    def is_in_spawn_zone(self, position: Position) -> bool:
        return (self.top_left.x <= position.x <= self.bottom_right.x and
