import random
import time
import threading
from dataclasses import dataclass
from enum import Enum
from typing import Dict, List, Optional, Tuple
import json

# Science_Collaboratory System for AI Agents and Human Researchers

# Enum for agent capabilities
class AgentCapability(Enum):
    DATA_ANALYSIS = 1
    SIMULATION = 2
    HYPOTHESIS_GENERATION = 3

# Enum for task status
class TaskStatus(Enum):
    PENDING = 1
    IN_PROGRESS = 2
    COMPLETED = 3
    FAILED = 4

# Dataclass for representing an AI agent
@dataclass
class Agent:
    id: str
    capability: AgentCapability
    performance: float  # Performance score from 0.0 to 1.0

# Dataclass for representing a scientific task
@dataclass
class Task:
    id: str
    description: str
    required_capability: AgentCapability
    status: TaskStatus = TaskStatus.PENDING
    assigned_to: Optional[str] = None

# Dataclass for representing project progress
@dataclass
class ProjectProgress:
    tasks: List[Task]
    agents: List[Agent]
    feedback: Dict[str, str]  # Feedback for the system from agents

# Dynamic task allocation mechanism
class TaskAllocator:
    def __init__(self):
        self.task_queue: List[Task] = []
        self.agent_pool: List[Agent] = []

    def add_task(self, task: Task):
        self.task_queue.append(task)

    def add_agent(self, agent: Agent):
        self.agent_pool.append(agent)

    def allocate_tasks(self):
        # Sort agents by performance and capability match
        sorted_agents = sorted(
            self.agent_pool,
            key=lambda a: (a.performance, a.capability)
        )

        # Sort tasks by priority (e.g., based on deadline or importance)
        sorted_tasks = sorted(
            self.task_queue,
            key=lambda t: t.required_capability
        )

        # Assign each task to the most suitable agent
        for task in sorted_tasks:
            for agent in sorted_agents:
                if agent.capability == task.required_capability and task.status == TaskStatus.PENDING: 
                    task.assigned_to = agent.id
                    task.status = TaskStatus.IN_PROGRESS
                    break

    def reassign_tasks(self):
        # Reassign tasks if agent performance drops or task requirements change
        for task in self.task_queue:
            if task.status == TaskStatus.FAILED:
                # Reassign failed tasks to a different agent
                for agent in self.agent_pool:
                    if agent.capability == task.required_capability and agent.id != task.assigned_to:
                        task.assigned_to = agent.id
                        task.status = TaskStatus.IN_PROGRESS
                        break

    def update_performance(self, agent_feedback: Dict[str, float]):
        # Update agent performance based on feedback
        for agent in self.agent_pool:
            if agent.id in agent_feedback:
                agent.performance = agent_feedback[agent.id]

# Feedback system for agent communication and system adaptation
class FeedbackSystem:
    def __init__(self):
        self.feedback_data: Dict[str, Dict] = {}

    def collect_feedback(self, agent_id: str, report: Dict):
        if agent_id not in self.feedback_data:
            self.feedback_data[agent_id] = {}
        self.feedback_data[agent_id].update(report)

    def analyze_feedback(self):
        # Analyze feedback data to identify trends and areas for improvement
        suggestions = {
            'task_reallocation': [],
            'performance_adjustments': {},
            'system_optimization': []
        }

        for agent_id, feedback in self.feedback_data.items():
            if 'task_progress' in feedback and feedback['task_progress'] < 0.5:
                # Suggest reassigning underperforming tasks
                suggestions['task_reallocation'].append(agent_id)
            if 'performance' in feedback:
