    filename='networkguard.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Constants
timeout = 10  # seconds for socket timeout

# Mock threat database for demonstration purposes
class ThreatDatabase:
    def __init__(self):
        self.signatures = {
            'malware_signature_1': 'known_malware_1',
            'malware_signature_2': 'known_malware_2',
            'suspicious_pattern_1': 'unusual_data_pattern_1',
            'unauthorized_access': 'unauthorized_IP_pattern'
        }

    def check_threat(self, data):
        for signature, threat in self.signatures.items():
            if signature in data:
                return threat
        return None

# Network monitoring component
class TrafficMonitor:
    def __init__(self):
        self.threat_db = ThreatDatabase()
        self.running = False
        self.interface = 'lo'  # Use 'lo' for localhost in demo, change to network interface in production
        self.port = 80  # Port to monitor

    def start_monitoring(self):
        self.running = True
        print("[+] NetworkGuard is monitoring traffic...")

        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.bind((self.interface, self.port))
        self.server_socket.listen(5)
        self.server_socket.settimeout(timeout)

        logging.info("Traffic monitoring started on interface: {} port: {}".format(self.interface, self.port))

        while self.running:
            try:
                client_socket, addr = self.server_socket.accept()
                client_socket.settimeout(timeout)

                data = client_socket.recv(4096).decode('utf-8', errors='ignore')
                if data:
                    threat = self.threat_db.check_threat(data)
                    if threat:
                        self.log_alert(threat, data, addr)

                client_socket.close()
            except socket.timeout:
                continue
            except Exception as e:
                logging.error(f"Error processing traffic: {e}")
                continue

    def stop_monitoring(self):
        self.running = False
        self.server_socket.close()
        print("[+] NetworkGuard has stopped monitoring.")
        logging.info("Traffic monitoring stopped.")

    def log_alert(self, threat, data, source):
        alert_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        log_entry = {
            "timestamp": alert_time,
            "threat": threat,
            "data": data,
            "source": source
        }

        with open('alerts.json', 'a') as f:
            f.write(json.dumps(log_entry) + '\n')

        print(f"[!] Alert: {threat} detected from {source}")
        logging.warning(f"Threat: {threat} detected from {source}")

# User interface for administrators
class AdminInterface:
    def __init__(self):
        self.monitor = TrafficMonitor()

    def show_menu(self):
        print("\n--- NetworkGuard Admin Console ---")
        print("1. Start Monitoring")
        print("2. Stop Monitoring")
        print("3. View Alerts")
        print("4. Exit")

