        elif len(alive_robots) > len(self.robots) * 0.75 and self.difficulty_level > self.MIN_DIFFICULTY:
            self.difficulty_level -= 1
            # Remove some hazards or reduce enemy strength
            if self.hazards:
                self.hazards.pop()

    def end_round(self):
