        # Score calculation
        for robot in self.robots:
            if robot.is_alive():
                robot.score += 50  # Base score for surviving
                if self.current_objective and self.current_objective.status == ObjectiveStatus.COMPLETE:
                    if self.current_objective.team == robot.team:
                        robot.score += 200  # Bonus for capturing objective

        # Reset all entities
        for robot in self.robots:
            robot.health = 100
            robot.status = HealthStatus.ALIVE
            robot.score = 0
            robot.experience += 1  # Simple learning mechanism

        for objective in self.objectives:
            objective.reset()

        self.round_timer = 120.0
        self.time_elapsed = 0.0
        self.team_to_capture = Team.RED if self.team_to_capture == Team.BLUE else Team.BLUE
        self.current_objective = random.choice(self.objectives)
        self.team_to_capture = self.current_objective.team

    def check_objective_complete(self):
        if self.current_objective.status == ObjectiveStatus.COMPLETE:
            self.end_round()

    def get_closest_robot(self, position: Position, team: Team) -> Optional[Robot]:
        closest_robot = None
        min_distance = float('inf')
        for robot in self.robots:
            if robot.team == team and robot.is_alive():
                distance = math.sqrt((robot.position.x - position.x)**2 + (robot.position.y - position.y)**2)
                if distance < min_distance:
                    min_distance = distance
                    closest_robot = robot
        return closest_robot

    def get_closest_enemy(self, robot: Robot) -> Optional[Robot]:
        closest_enemy = None
        min_distance = float('inf')
        for other in self.robots:
            if other.team != robot.team and other.is_alive():
                distance = math.sqrt((other.position.x - robot.position.x)**2 + (other.position.y - robot.position.y)**2)
                if distance < min_distance:
                    min_distance = distance
                    closest_enemy = other
