        # Set the first objective as current
        if not self.current_objective:
            self.current_objective = objective
            self.team_to_capture = objective.team

    def update(self, delta_time):
        self.time_elapsed += delta_time
        self.round_timer -= delta_time

        # Update all game entities
        for robot in self.robots:
            if robot.is_alive():
                robot.update(self, delta_time)

        for weapon in self.weapons:
            weapon.update(delta_time)

        for power_up in self.power_ups:
            power_up.update(power_up, delta_time)

        for hazard in self.hazards:
            if not hazard.update(delta_time):
                self.hazards.remove(hazard)

        for objective in self.objectives:
            if self.current_objective == objective:
                objective.update(self, delta_time)

        # Check if the round should end
        if self.round_timer <= 0 or all(robot.status != HealthStatus.ALIVE for robot in self.robots):
            self.end_round()

        # Adjust difficulty based on performance
        self.adjust_difficulty()

    def adjust_difficulty(self):
        # Simple difficulty adjustment based on remaining robots
        alive_robots = [r for r in self.robots if r.is_alive()]
