                if self.current_objective and self.current_objective.status == ObjectiveStatus.COMPLETE:
                    if self.current_objective.team == robot.team:
                        robot.score += 200  # Bonus for capturing objective

        # Reset all entities
        for robot in self.robots:
            robot.health = 100
            robot.status = HealthStatus.ALIVE
            robot.score = 0
            robot.experience += 1  # Simple learning mechanism

        for objective in self.objectives:
