def run_simulation(arena: Arena, rounds: int = 3):
    for round_num in range(1, rounds + 1):
        print(f"\n--- Starting Round {round_num} ---")
        print(f"Difficulty Level: {arena.difficulty_level}")
        print(f"Current Objective: {arena.current_objective.description}")
        print(f"Team to Capture: {arena.team_to_capture.name}")

        # Reset the round
        for robot in arena.robots:
            robot.health = 100
            robot.status = HealthStatus.ALIVE
            robot.score = 0

        arena.time_elapsed = 0.0
        arena.round_timer = 120.0

        # Simulate the round
        while arena.round_timer > 0 and any(robot.is_alive() for robot in arena.robots):
            # Simple simulation step with 0.5 seconds per update
            arena.update(0.5)

            # Display some info
            alive_robots = [robot for robot in arena.robots if robot.is_alive()]
            if alive_robots:
                print(f"Alive Robots: {len(alive_robots)}")
                for robot in alive_robots:
                    print(f"Robot at ({robot.position.x}, {robot.position.y}) - Team: {robot.team.name}")

            if arena.current_objective.status == ObjectiveStatus.COMPLETE:
                print(f"Objective '{arena.current_objective.description}' completed by team {arena.current_objective.team.name}")
                break

        # Print round summary
        print("\nRound Summary:")
        for robot in arena.robots:
            print(f"Robot - Team: {robot.team.name}, Score: {robot.score}, Experience: {robot.experience}")
        print(f"Difficulty Level after round: {arena.difficulty_level}")

    print("\n--- Simulation Complete ---")
    print("Final Robot Scores:")
    for robot in arena.robots:
        print(f"Robot - Team: {robot.team.name}, Final Score: {robot.score}, Experience: {robot.experience}")

