class Weapon:
    def __init__(self, stats: WeaponStats):
        self.stats = stats
        self.cooldown_timer: float = 0.0

    def is_ready(self) -> bool:
        return self.cooldown_timer <= 0

    def use(self, user: Entity, target: Entity, arena):
        if self.is_ready():
            if self.stats.type == WeaponType.RANGED:
                distance = math.sqrt((user.position.x - target.position.x)**2 + (user.position.y - target.position.y)**2)
                if distance <= self.stats.range:
                    target.take_damage(self.stats.damage)
                    self.cooldown_timer = self.stats.cooldown
            elif self.stats.type == WeaponType.MELEE:
                if user.position.x == target.position.x and user.position.y == target.position.y:
                    target.take_damage(self.stats.damage)
                    self.cooldown_timer = self.stats.cooldown

    def update(self, delta_time):
        if self.cooldown_timer > 0:
            self.cooldown_timer -= delta_time
            if self.cooldown_timer < 0:
                self.cooldown_timer = 0

class PowerUp:
    def __init__(self, stats: PowerUpStats, duration: float):
        self.stats = stats
        self.duration = duration
        self.timer: float = 0.0

    def activate(self, user: Entity):
        if self.stats.effect == "speed_boost":
            user.velocity.x *= 2
            user.velocity.y *= 2
            self.timer = self.duration
        elif self.stats.effect == "health_restore":
            user.health = min(user.health + 50, 100)
        elif self.stats.effect == "shield":
            user.health += 25
        self.timer = self.duration

    def update(self, user: Entity, delta_time):
        if self.timer > 0:
            self.timer -= delta_time
            if self.timer <= 0:
                if self.stats.effect == "speed_boost":
                    user.velocity.x /= 2
                    user.velocity.y /= 2

class Hazard:
    def __init__(self, position: Position, stats: HazardStats, duration: float):
        self.position = position
        self.stats = stats
        self.timer = duration

    def update(self, delta_time):
        self.timer -= delta_time
        if self.timer <= 0:
            return False  # Hazard is gone
        return True

