class Objective:
    def __init__(self, position: Position, description: str, team: Team):
        self.position = position
        self.status: ObjectiveStatus = ObjectiveStatus.ACTIVE
        self.description = description
        self.team = team
        self.capture_timer: float = 0.0
        self.CAPTURE_TIME = 5.0

    def update(self, arena, delta_time):
        if self.status == ObjectiveStatus.ACTIVE and self.team == arena.team_to_capture:
            self.capture_timer += delta_time
            if self.capture_timer >= self.CAPTURE_TIME:
                self.status = ObjectiveStatus.COMPLETE
                arena.check_objective_complete()

    def reset(self):
        self.status = ObjectiveStatus.ACTIVE
        self.capture_timer = 0.0

class Arena:
    def __init__(self, width: int, height: int):
        self.width = width
        self.height = height
        self.robots: List[Robot] = []
        self.weapons: List[Weapon] = []
        self.power_ups: List[PowerUp] = []
        self.hazards: List[Hazard] = []
        self.objectives: List[Objective] = []
        self.current_objective: Optional[Objective] = None
        self.team_to_capture: Team = Team.RED
        self.difficulty_level: int = 1
        self.round_timer: float = 120.0
        self.MAX_DIFFICULTY = 5
        self.MIN_DIFFICULTY = 1
        self.time_elapsed: float = 0.0

    def is_position_valid(self, position: Position):
        return (0 <= position.x < self.width) and (0 <= position.y < self.height)

    def add_robot(self, robot: Robot):
        if self.is_position_valid(robot.position):
            self.robots.append(robot)
            # Assign a weapon to the robot
            if self.weapons:
                robot.select_weapon(random.choice(self.weapons))

    def add_weapon(self, weapon: Weapon):
        self.weapons.append(weapon)

    def add_power_up(self, power_up: PowerUp):
        self.power_ups.append(power_up)

    def add_hazard(self, hazard: Hazard):
        self.hazards.append(hazard)

    def add_objective(self, objective: Objective):
        self.objectives.append(objective)
        # Set the first objective as current
        if not self.current_objective:
            self.current_objective = objective
            self.team_to_capture = objective.team

    def update(self, delta_time):
        self.time_elapsed += delta_time
        self.round_timer -= delta_time

        # Update all game entities
        for robot in self.robots:
            if robot.is_alive():
                robot.update(self, delta_time)

        for weapon in self.weapons:
            weapon.update(delta_time)

        for power_up in self.power_ups:
            power_up.update(power_up, delta_time)

        for hazard in self.hazards:
            if not hazard.update(delta_time):
                self.hazards.remove(hazard)

        for objective in self.objectives:
            if self.current_objective == objective:
                objective.update(self, delta_time)

        # Check if the round should end
        if self.round_timer <= 0 or all(robot.status != HealthStatus.ALIVE for robot in self.robots):
            self.end_round()

        # Adjust difficulty based on performance
        self.adjust_difficulty()

    def adjust_difficulty(self):
        # Simple difficulty adjustment based on remaining robots
        alive_robots = [r for r in self.robots if r.is_alive()]
        if len(alive_robots) < len(self.robots) * 0.25 and self.difficulty_level < self.MAX_DIFFICULTY:
            self.difficulty_level += 1
            # Add more hazards or stronger enemies
            self.add_hazard(Hazard(
                Position(random.randint(0, self.width), random.randint(0, self.height)),
                HazardStats("Toxic Zone", 10, 30.0, "Deals periodic damage to robots"),
                30.0
            ))
        elif len(alive_robots) > len(self.robots) * 0.75 and self.difficulty_level > self.MIN_DIFFICULTY:
            self.difficulty_level -= 1
            # Remove some hazards or reduce enemy strength
            if self.hazards:
                self.hazards.pop()

    def end_round(self):
        # End the round and reset
        # Score calculation
        for robot in self.robots:
            if robot.is_alive():
                robot.score += 50  # Base score for surviving
                if self.current_objective and self.current_objective.status == ObjectiveStatus.COMPLETE:
                    if self.current_objective.team == robot.team:
                        robot.score += 200  # Bonus for capturing objective

        # Reset all entities
        for robot in self.robots:
            robot.health = 100
            robot.status = HealthStatus.ALIVE
            robot.score = 0
            robot.experience += 1  # Simple learning mechanism

        for objective in self.objectives:
            objective.reset()

        self.round_timer = 120.0
        self.time_elapsed = 0.0
        self.team_to_capture = Team.RED if self.team_to_capture == Team.BLUE else Team.BLUE
        self.current_objective = random.choice(self.objectives)
        self.team_to_capture = self.current_objective.team

    def check_objective_complete(self):
        if self.current_objective.status == ObjectiveStatus.COMPLETE:
            self.end_round()

    def get_closest_robot(self, position: Position, team: Team) -> Optional[Robot]:
        closest_robot = None
        min_distance = float('inf')
        for robot in self.robots:
            if robot.team == team and robot.is_alive():
                distance = math.sqrt((robot.position.x - position.x)**2 + (robot.position.y - position.y)**2)
                if distance < min_distance:
                    min_distance = distance
                    closest_robot = robot
        return closest_robot

    def get_closest_enemy(self, robot: Robot) -> Optional[Robot]:
        closest_enemy = None
        min_distance = float('inf')
        for other in self.robots:
            if other.team != robot.team and other.is_alive():
                distance = math.sqrt((other.position.x - robot.position.x)**2 + (other.position.y - robot.position.y)**2)
                if distance < min_distance:
                    min_distance = distance
                    closest_enemy = other
        return closest_enemy

    def get_power_up_at(self, position: Position) -> Optional[PowerUp]:
        for power_up in self.power_ups:
            if power_up.position.x == position.x and power_up.position.y == position.y:
                return power_up
        return None

    def remove_power_up(self, power_up: PowerUp):
        if power_up in self.power_ups:
            self.power_ups.remove(power_up)

    def spawn_power_up(self, position: Position, stats: PowerUpStats):
        self.power_ups.append(PowerUp(stats, 30.0))

    def spawn_hazard(self, position: Position, stats: HazardStats):
        self.hazards.append(Hazard(position, stats, 30.0))

# --------------------------
# Game Simulation
# --------------------------

def run_simulation(arena: Arena, rounds: int = 3):
    for round_num in range(1, rounds + 1):
        print(f"\n--- Starting Round {round_num} ---")
        print(f"Difficulty Level: {arena.difficulty_level}")
        print(f"Current Objective: {arena.current_objective.description}")
        print(f"Team to Capture: {arena.team_to_capture.name}")

        # Reset the round
        for robot in arena.robots:
            robot.health = 100
            robot.status = HealthStatus.ALIVE
            robot.score = 0

        arena.time_elapsed = 0.0
        arena.round_timer = 120.0

        # Simulate the round
        while arena.round_timer > 0 and any(robot.is_alive() for robot in arena.robots):
            # Simple simulation step with 0.5 seconds per update
            arena.update(0.5)

            # Display some info
            alive_robots = [robot for robot in arena.robots if robot.is_alive()]
            if alive_robots:
                print(f"Alive Robots: {len(alive_robots)}")
                for robot in alive_robots:
                    print(f"Robot at ({robot.position.x}, {robot.position.y}) - Team: {robot.team.name}")

            if arena.current_objective.status == ObjectiveStatus.COMPLETE:
                print(f"Objective '{arena.current_objective.description}' completed by team {arena.current_objective.team.name}")
                break

        # Print round summary
        print("\nRound Summary:")
        for robot in arena.robots:
            print(f"Robot - Team: {robot.team.name}, Score: {robot.score}, Experience: {robot.experience}")
        print(f"Difficulty Level after round: {arena.difficulty_level}")

    print("\n--- Simulation Complete ---")
    print("Final Robot Scores:")
    for robot in arena.robots:
        print(f"Robot - Team: {robot.team.name}, Final Score: {robot.score}, Experience: {robot.experience}")

# --------------------------
# Main Execution
# --------------------------

def main():
    # Initialize the arena
    arena = Arena(width=10, height=10)

    # Add predefined weapons
    arena.add_weapon(Weapon(WeaponStats("Laser Rifle", 20, 5, 1.0, "A semi-automatic laser weapon with moderate range")))
    arena.add_weapon(Weapon(WeaponStats("Plasma Sword", 30, 0, 2.0, WeaponType.MELEE, "A close-range energy sword with high damage")))
    arena.add_weapon(Weapon(WeaponStats("Shield Generator", 0, 0, 5.0, WeaponType.SUPPORT, "Generates a temporary shield for the user")))

    # Add power-ups
    arena.spawn_power_up(Position(3, 4), PowerUpStats("Speed Boost", "Increases movement speed", 10.0, "Gives a speed boost for a short duration"))
    arena.spawn_power_up(Position(6, 7), PowerUpStats("Health Restore", "Restores health", 5.0, "Restores a portion of your health"))

    # Add objectives
    arena.add_objective(Objective(Position(5, 5), "Capture the Core", Team.RED))
    arena.add_objective(Objective(Position(2, 2), "Defend the Base", Team.BLUE))
    arena.add_objective(Objective(Position(8, 8), "Escort the Payload", Team.RED))

    # Add robots
    # Red team
    for i in range(3):
        arena.add_robot(Robot(Position(i, 0), Team.RED, 100))

    # Blue team
    for i in range(3):
        arena.add_robot(Robot(Position(0, i), Team.BLUE, 100))

    # Run the simulation
    run_simulation(arena, rounds=3)

