        with self.lock:
            if len(self.items) < MAX_ITEMS_PER_LIST:
                self.items.append(item)
                return True
            return False

    def remove_item(self, item_id):
        with self.lock:
            for item in self.items:
                if item.item_id == item_id:
                    self.items.remove(item)
                    return True
            return False

    def update_item_status(self, item_id, new_status):
        with self.lock:
            for item in self.items:
                if item.item_id == item_id:
