            PowerUpType.SHIELD: 0,
            PowerUpType.SPEED_BOOST: 0,
            PowerUpType.DAMAGE_AMPLIFIER: 0,
            PowerUpType.TEAM_BUFF: 0
        }
        self.skills = self._initialize_skills()
        self.role = self._determine_role()
        self.experience = 0
        self.score = 0
        self.power_ups = []

    def _initialize_skills(self):
        """Initialize skills based on robot's specialization."""
        return {
            "melee_attack": random.uniform(30, 50),
            "ranged_attack": random.uniform(20, 40),
            "healing": random.uniform(10, 30),
            "speed": random.uniform(1.5, 2.5)
        }

    def _determine_role(self):
        """Determine the robot's role based on skills."""
        if self.skills["healing"] > 30:
            return "Support"
        elif self.skills["melee_attack"] > 40:
            return "Offense"
        else:
            return "Assassin"

    @abstractmethod
