        """Update the robot's experience."""
        self.experience += amount
        if self.experience >= 100:
            self.level_up()

    def level_up(self):
        """Level up the robot and improve skills."""
        self.experience = 0
        self.max_health += 10
        self.health = self.max_health
        for skill in self.skills:
            self.skills[skill] *= 1.2  # 20% improvement

    def calculate_damage(self, weapon_type):
        """Calculate potential damage based on weapon and skills."""
        if weapon_type == WeaponType.MELEE:
