# Base class for all weapons
class Weapon:
    def __init__(self, weapon_type, damage, cooldown):
        self.weapon_type = weapon_type
        self.damage = damage
        self.cooldown = cooldown

    def use(self, user, target):
        # Apply the weapon's effect to the target
        if self.weapon_type == WeaponType.SHIELD:
            # Shield absorbs damage
            shield_amount = self.damage
            target.defense += shield_amount
            return 0  # No damage dealt
        else:
            # All other weapons deal damage
            return target.take_damage(self.damage)

# Class representing the battle arena
class CyberArena:
    def __init__(self, size=(100, 100)):
        self.size = size  # Width and height of the arena
        self.robots = []
        self.power_ups = []
        self.hazards = []
        self.objective = None
        self.score = {Team.RED: 0, Team.BLUE: 0}
        self.round_number = 1
        self.difficulty = "Normal"
        self.is_battle_active = False

    def add_robot(self, robot):
        # Add a robot to the arena
        self.robots.append(robot)

    def add_power_up(self, power_up):
        # Add a power-up to the arena
        self.power_ups.append(power_up)

    def add_hazard(self, hazard):
        # Add a hazard to the arena
        self.hazards.append(hazard)

    def set_objective(self, objective):
        # Set the current objective for the battle
        self.objective = objective

    def start_battle(self):
        # Start a new battle
        self.is_battle_active = True
        self.display_battle_start()
        self.run_battle()

    def run_battle(self):
        # Run the battle until all robots of one team are eliminated
        while self.is_battle_active:
            self.update_robots()
            self.update_power_ups()
            self.update_hazards()
            self.check_objective_completion()
            self.check_battle_end()
            time.sleep(0.1)  # Simulate real-time with a small delay

    def update_robots(self):
        # Update all robots in the arena
        for robot in self.robots:
            if robot.is_alive:
                robot.update_cooldowns()
                robot.update_position(self)
                self.resolve_combat(robot)

    def resolve_combat(self, robot):
        # Resolve combat for a robot
        # Find the closest enemy
        closest_enemy = self.find_closest_enemy(robot)
        if closest_enemy and self.is_in_attack_range(robot, closest_enemy):
            # Attack the closest enemy
            damage = robot.use_weapon(closest_enemy)
            print(f"{robot.name} ({robot.robot_type.value}) attacks {closest_enemy.name} for {damage} damage!")
        elif closest_enemy:
            # Move closer to the enemy if they're out of attack range
            robot.move(self.calculate_midpoint(robot.position, closest_enemy.position))

    def find_closest_enemy(self, robot):
        # Find the closest enemy robot
        closest_distance = float('inf')
        closest_enemy = None
        for other_robot in self.robots:
            if other_robot.is_alive and other_robot.team != robot.team:
                distance = self.calculate_distance(robot.position, other_robot.position)
                if distance < closest_distance:
                    closest_distance = distance
                    closest_enemy = other_robot
        return closest_enemy

    def is_in_attack_range(self, robot, target):
        # Check if the robot is in attack range of the target
        distance = self.calculate_distance(robot.position, target.position)
        return distance <= self.get_weapon_attack_range(robot.weapon)

    def get_weapon_attack_range(self, weapon):
        # Return the attack range of a weapon
        if weapon.weapon_type == WeaponType.SWORD:
            return 5  # Melee weapon has short range
        else:
            return 20  # Ranged weapons have longer range

    def calculate_distance(self, pos1, pos2):
        # Calculate the Euclidean distance between two positions
        return ((pos1[0] - pos2[0])**2 + (pos1[1] - pos2[1])**2)**0.5

    def calculate_midpoint(self, pos1, pos2):
        # Calculate the midpoint between two positions
        return [(pos1[0] + pos2[0])/2, (pos1[1] + pos2[1])/2]

    def update_power_ups(self):
        # Update all power-ups in the arena
        for power_up in self.power_ups:
            if power_up.is_active:
                power_up.apply_effect()

    def update_hazards(self):
        # Update all hazards in the arena
        for hazard in self.hazards:
            if hazard.is_active:
                hazard.apply_effect()

    def check_objective_completion(self):
        # Check if the current objective has been completed
        if self.objective:
            if self.objective.is_complete:
                print(f"Objective '{self.objective.name}' completed!")
                self.score[self.objective.completing_team] += self.objective.value
                self.objective = None  # Reset the objective

    def check_battle_end(self):
        # Check if the battle should end (e.g., one team eliminated)
        red_robots_alive = any(robot.is_alive and robot.team == Team.RED for robot in self.robots)
        blue_robots_alive = any(robot.is_alive and robot.team == Team.BLUE for robot in self.robots)

        if not red_robots_alive or not blue_robots_alive:
            self.is_battle_active = False
            winner = Team.RED if red_robots_alive else Team.BLUE
            print(f"Battle {self.round_number} complete! Winner: {winner.value}")
            self.handle_battle_end()

    def handle_battle_end(self):
        # Handle the end of a battle
        # Calculate battle results for each robot
        battle_results = self.calculate_battle_results()
        # Let robots learn from the battle
        for robot in self.robots:
            robot.learn_from_battle(battle_results)
        # Reset arena for next battle
        self.reset_arena()
        # Update difficulty based on performance
        self.update_difficulty(battle_results)
        # Start next battle if desired
        if self.round_number < 5:  # Example: 5 rounds per match
            self.round_number += 1
            self.start_battle()
        else:
            print("Match complete!")
            self.display_final_scores()

    def calculate_battle_results(self):
        # Calculate performance metrics for the battle
        red_kills = 0
        blue_kills = 0
        red_damage = 0
        blue_damage = 0
        red_healing = 0
        blue_healing = 0

        for robot in self.robots:
            if robot.team == Team.RED:
                red_kills += robot.kills
                red_damage += robot.damage_dealt
                red_healing += robot.healing_done
            else:
                blue_kills += robot.kills
                blue_damage += robot.damage_dealt
                blue_healing += robot.healing_done

        return {
            "red_kills": red_kills,
            "blue_kills": blue_kills,
            "red_damage": red_damage,
            "blue_damage": blue_damage,
            "red_healing": red_healing,
            "blue_healing": blue_healing
        }

    def update_difficulty(self, battle_results):
        # Adjust game difficulty based on team performance
        red_performance = (battle_results["red_kills"] + battle_results["red_damage"] + battle_results["red_healing"])
        blue_performance = (battle_results["blue_kills"] + battle_results["blue_damage"] + battle_results["blue_healing"])

        if red_performance > blue_performance * 1.5:
            # Red team is much stronger, increase difficulty for them
            self.difficulty = "Hard"
        elif blue_performance > red_performance * 1.5:
            # Blue team is much stronger, increase difficulty for them
            self.difficulty = "Hard"
        else:
            # Teams are balanced, keep or reduce difficulty
            self.difficulty = "Normal"

    def random_position(self, area):
        # Generate a random position within a specific area
        x = random.randint(area[0][0], area[1][0])
        y = random.randint(area[0][1], area[1][1])
        return [x, y]

    def display_battle_start(self):
        # Display battle start information
        print(f"\n=== Battle {self.round_number} Start ===")
        print(f"Team Red: {sum(robot.is_alive for robot in self.robots if robot.team == Team.RED)} robots")
        print(f"Team Blue: {sum(robot.is_alive for robot in self.robots if robot.team == Team.BLUE)} robots")
        print(f"Difficulty: {self.difficulty}")
        print(f"Current Objective: {self.objective.name if self.objective else 'None'}")

    def display_final_scores(self):
        # Display final scores for the match
        print("\n=== Final Scores ===")
        print(f"Team Red: {self.score[Team.RED]} points")
        print(f"Team Blue: {self.score[Team.BLUE]} points")
        if self.score[Team.RED] > self.score[Team.BLUE]:
            print("Team Red wins the match!")
        elif self.score[Team.BLUE] > self.score[Team.RED]:
            print("Team Blue wins the match!")
        else:
            print("The match is a draw!")

    def reset_arena(self):
        # Reset the arena for the next battle
        # Respawn robots with full health
        for robot in self.robots:
            robot.health = robot.max_health
            robot.is_alive = True
            robot.position = [0, 0]
            robot.weapon_cooldown = 0
            robot.kills = 0
            robot.damage_dealt = 0
            robot.healing_done = 0

        # Reset power-ups and hazards
        for power_up in self.power_ups:
            power_up.is_active = True
            power_up.respawn()

        for hazard in self.hazards:
            hazard.is_active = True
            hazard.respawn()

# Class representing a power-up
class PowerUp:
    def __init__(self, power_up_type, position, duration=10):
        self.type = power_up_type
        self.position = position
        self.is_active = True
        self.duration = duration
        self.timer = duration

    def apply_effect(self):
        # Apply the power-up's effect to robots in the area
        for robot in arena.robots:
            if self.is_robot_in_range(robot):
                self.apply_power_up(robot)
                self.timer -= 1
                if self.timer <= 0:
                    self.is_active = False

    def is_robot_in_range(self, robot):
        # Check if a robot is within the power-up's range
        distance = arena.calculate_distance(robot.position, self.position)
        return distance <= 5  # Power-up range

    def apply_power_up(self, robot):
        # Apply the specific power-up effect
        if self.type == PowerUpType.HEAL:
            robot.heal(20)
            print(f"{robot.name} uses a Heal power-up and regains 20 health!")
        elif self.type == PowerUpType.SPEED_BOOST:
            robot.speed = min(2.0, robot.speed * 1.5)
            print(f"{robot.name} uses a Speed Boost power-up and increases speed!")
        elif self.type == PowerUpType.DAMAGE_BOOST:
            robot.damage = min(30, robot.damage * 1.5)
            print(f"{robot.name} uses a Damage Boost power-up and increases attack power!")
        elif self.type == PowerUpType.SHIELD_BOOST:
            robot.defense += 10
            print(f"{robot.name} uses a Shield Boost power-up and gains 10 defense!")

    def respawn(self):
        # Respawn the power-up at a random position
        self.position = arena.random_position(arena.play_area)
        self.is_active = True
        self.timer = self.duration

