    CONSTRUCTION_SUPERVISOR = "Construction Supervisor"  # Oversees building and infrastructure
    PUBLIC_SERVICE_COORDINATOR = "Public Service Coordinator"  # Handles public services like health and safety

# Communication protocol
class Message:
    def __init__(self, sender, receiver, content):
        self.sender = sender
        self.receiver = receiver
        self.content = content

    def __str__(self):
        return f"From {self.sender} to {self.receiver}: {self.content}"

# City Simulation Environment
class City:
    def __init__(self, name):
        self.name = name
        self.population = 1000
        self.resources = {
            'water': 10000,
            'energy': 5000,
            'food': 10000,
            'construction_material': 2000
        }
        self.buildings = []
        self.traffic = 0
        self.message_bus = []

    def update_resources(self, resource_key, change):
        self.resources[resource_key] += change
        if self.resources[resource_key] < 0:
            self.resources[resource_key] = 0
            self.send_message(f"Warning: {resource_key} is in short supply!")

    def add_building(self, building):
        self.buildings.append(building)
        self.traffic += building.traffic_impact

        # Update resource consumption
        for resource, amount in building.resource_consumption.items():
            self.update_resources(resource, -amount)

    def send_message(self, content):
        message = Message("CitySimulation", "AllAgents", content)
        self.message_bus.append(message)

    def visualize(self):
        print(f"\n--- {self.name} City Status ---")
        print(f"Population: {self.population}")
        print(f"Resources: {self.resources}")
        print(f"Traffic Level: {self.traffic}")
        print(f"Buildings: {len(self.buildings)}")
        print("---\n")

# Building types
class BuildingType(Enum):
    RESIDENTIAL = "Residential"
    COMMERCIAL = "Commercial"
    INDUSTRIAL = "Industrial"
    GOVERNMENT = "Government"
    HEALTH = "Health"
    EDUCATION = "Education"

# Building class
class Building:
    def __init__(self, building_type, size):
        self.building_type = building_type
        self.size = size
        self.traffic_impact = size * 5
        self.resource_consumption = {
            'construction_material': size * 10,
            'energy': size * 2
        }

# Agent base class
class Agent:
    def __init__(self, name, agent_type, city):
        self.name = name
        self.agent_type = agent_type
        self.city = city

    def send_message(self, content, receiver):
        message = Message(self.name, receiver, content)
        self.city.message_bus.append(message)

    def receive_message(self):
        for message in self.city.message_bus:
            if message.receiver == self.name:
                print(f"{self.name} received: {message}")

# Urban Planner class
class UrbanPlanner(Agent):
    def __init__(self, name, city):
        super().__init__(name, AgentType.URBAN_PLANNER, city)

    def plan_city_layout(self):
        self.send_message("Start planning city layout with zoning and infrastructure.", "ResourceManager")
        self.send_message("Coordinate with construction supervisor for building placements.", "ConstructionSupervisor")

# Resource Manager class
class ResourceManager(Agent):
    def __init__(self, name, city):
        super().__init__(name, AgentType.RESOURCE_MANAGER, city)

    def manage_resources(self):
        self.receive_message()
        self.send_message("Allocate resources for residential and commercial zones.", "ConstructionSupervisor")

        # Simulate resource shortage scenario
        if self.city.resources['construction_material'] < 500:
            self.send_message("Warning: Construction material is running low!", "AllAgents")

# Construction Supervisor class
class ConstructionSupervisor(Agent):
    def __init__(self, name, city):
        super().__init__(name, AgentType.CONSTRUCTION_SUPERVISOR, city)

    def manage_construction(self):
        self.receive_message()
        self.send_message("Starting construction of residential building.", "AllAgents")

        # Simulate actual construction
        new_building = Building(BuildingType.RESIDENTIAL, 50)
        self.city.add_building(new_building)

        self.send_message(f"Completed construction of a {new_building.building_type} building of size {new_building.size}.", "AllAgents")

# Public Service Coordinator class
class PublicServiceCoordinator(Agent):
    def __init__(self, name, city):
        super().__init__(name, AgentType.PUBLIC_SERVICE_COORDINATOR, city)

    def manage_public_services(self):
        self.receive_message()
        self.send_message("Ensure hospitals and schools are built to support population.", "UrbanPlanner")
        self.send_message("Establish emergency services for disaster response.", "AllAgents")

# Simulation driver
class SimulationDriver:
    def __init__(self):
        self.city = City("Futuristic City")
        self.agents = [
            UrbanPlanner("Agent1", self.city),
            ResourceManager("Agent2", self.city),
            ConstructionSupervisor("Agent3", self.city),
            PublicServiceCoordinator("Agent4", self.city)
        ]

    def run_simulation(self):
        print("Starting simulation of Multi-Agent City Planner...")

        # Run agent tasks
        for agent in self.agents:
            if agent.agent_type == AgentType.URBAN_PLANNER:
                agent.plan_city_layout()
            elif agent.agent_type == AgentType.RESOURCE_MANAGER:
                agent.manage_resources()
            elif agent.agent_type == AgentType.CONSTRUCTION_SUPERVISOR:
                agent.manage_construction()
            elif agent.agent_type == AgentType.PUBLIC_SERVICE_COORDINATOR:
                agent.manage_public_services()

        # Simulate a natural disaster event
        if random.random() < 0.2:
            self.city.send_message("A natural disaster has occurred! Evacuation and emergency services are activated.")

        # Visualize city state
        self.city.visualize()

        print("Simulation completed.")

# Run the simulation
def main():
    driver = SimulationDriver()
    driver.run_simulation()

if __name__ == "__main__":
    main()"
}
