        super().__init__("Capture the enemy flag and return to base")
        self.flag_position = flag_position
        self.base_position = base_position
        self.flag_captured = False

    def calculate_progress(self, robot):
        """Calculate progress towards capturing the flag"""
        if not self.completed:
            if not self.flag_captured:
                # Progress is based on distance to the flag
                distance = robot.position.distance_to(self.flag_position)
                max_distance = 100.0  # Assume maximum possible distance
                return 1 - (distance / max_distance)
            else:
                # Progress is based on distance to base with the flag
                distance = robot.position.distance_to(self.base_position)
                max_distance = 100.0
                return 1 - (distance / max_distance)
        return 1.0

    def complete(self):
