class PowerUp:
    """Base class for power-ups that robots can collect"""
    def __init__(self, name, duration, effects):
        self.name = name
        self.duration = duration
        self.effects = effects

    def apply(self, robot):
        """Apply the power-up effects to a robot"""
        for effect, value in self.effects.items():
            if hasattr(robot, effect):
                original_value = getattr(robot, effect)
                robot.power_up_effects[effect] = (original_value, value)

    def remove(self, robot):
        """Remove the power-up effects from a robot"""
        for effect in self.effects:
            if effect in robot.power_up_effects:
                del robot.power_up_effects[effect]

