from dataclasses import dataclass
from enum import Enum
from typing import List, Tuple, Optional, Dict, Any

# -----------------------------
# ENUMS AND DATA CLASSES
# -----------------------------

class Team(Enum):
    RED = "Red Team"
    BLUE = "Blue Team"

class WeaponType(Enum):
    RANGED = "Ranged"
    MELEE = "Melee"

class Weapon(Enum):
    LASER_RIFLE = ("Laser Rifle", WeaponType.RANGED, 50, 10)
    SHOTGUN = ("Particle Shotgun", WeaponType.RANGED, 80, 5)
    ENERGY_SWORD = ("Energy Sword", WeaponType.MELEE, 150, 1)
    CLAW_BLADES = ("Claw Blades", WeaponType.MELEE, 120, 2)

    def __init__(self, name: str, weapon_type: WeaponType, damage: int, ammo: int):
        self.name = name
        self.type = weapon_type
        self.damage = damage
        self.ammo = ammo

class Role(Enum):
    ATTACKER = "Attacker"
    DEFENDER = "Defender"
    SUPPORT = "Support"
    SCOUT = "Scout"

class StatusEffect(Enum):
    SHIELD = "Shield"
    STUN = "Stun"
    SLOW = "Slow"

@dataclass
class Position:
    x: float
    y: float

    def distance_to(self, other: "Position") -> float:
        return math.hypot(self.x - other.x, self.y - other.y)

@dataclass
class WeaponStats:
    name: str
    weapon_type: WeaponType
    damage: int
    ammo: int
    remaining_ammo: int

    def use(self):
        if self.remaining_ammo > 0:
            self.remaining_ammo -= 1

@dataclass
class PowerUp:
    name: str
    effect: StatusEffect
    duration: float  # in seconds

    def apply_effect(self, robot):
        if self.effect == StatusEffect.SHIELD:
            robot.shield = True
        elif self.effect == StatusEffect.STUN:
            robot.stunned_until = time.time() + self.duration
        elif self.effect == StatusEffect.SLOW:
            robot.movement_speed = max(robot.movement_speed * 0.5, 1)

# -----------------------------
# ROBOT CLASS
# -----------------------------

class Robot:
    def __init__(self, name: str, team: Team, role: Role, position: Position):
        self.name = name
        self.team = team
        self.role = role
        self.position = position
        self.health = 100
        self.max_health = 100
        self.movement_speed = 5.0
        self.weapon = self._select_initial_weapon()
        self.inventory: List[PowerUp] = []
        self.shield = False
        self.stunned_until = 0
        self.strategy = {}

    def _select_initial_weapon(self) -> WeaponStats:
        # Attacking robots get ranged weapons
        if self.role == Role.ATTACKER:
            return WeaponStats(*Weapon.LASER_RIFLE.value, Weapon.LASER_RIFLE.value[2])
        # Defenders get melee weapons for defense
        elif self.role == Role.DEFENDER:
            return WeaponStats(*Weapon.ENERGY_SWORD.value, Weapon.ENERGY_SWORD.value[2])
        else:
            # Default to a basic ranged weapon
            return WeaponStats(*Weapon.LASER_RIFLE.value, Weapon.LASER_RIFLE.value[2])

    def move_towards(self, target_position: Position, speed: float = None):
        if time.time() < self.stunned_until:
            print(f"{self.name} is stunned and cannot move.")
            return

        if speed is None:
            speed = self.movement_speed

        dx = target_position.x - self.position.x
        dy = target_position.y - self.position.y
        distance = math.hypot(dx, dy)

        if distance > 0:
            self.position.x += (dx / distance) * speed
            self.position.y += (dy / distance) * speed

    def use_weapon(self, target: "Robot"):
        if not self.weapon.remaining_ammo:
            print(f"{self.name} has no ammo left for {self.weapon.name}.")
            return

        # Check if target is in range
        if self.weapon.type == WeaponType.RANGED:
            if self.position.distance_to(target.position) > 10:
                print(f"{self.name} is out of range to use {self.weapon.name}.")
                return
        else:  # MELEE weapon
            if self.position.distance_to(target.position) > 3:
                print(f"{self.name} is too far to use {self.weapon.name}.")
                return

        # Apply damage
        damage = self.weapon.damage
        if target.shield:
            damage = int(damage * 0.5)
            target.shield = False

        target.health -= damage
        self.weapon.use()
        print(f"{self.name} attacked {target.name} for {damage} damage! {target.name} now has {target.health} HP.")

    def apply_power_up(self, power_up: PowerUp):
        self.inventory.append(power_up)
        power_up.apply_effect(self)
        print(f"{self.name} picked up {power_up.name} with effect {power_up.effect} for {power_up.duration} seconds.")

    def _apply_status_effects(self):
        if self.stunned_until > time.time():
            print(f"{self.name} is still stunned.")

    def update_strategy(self, strategy_data: Dict[str, Any]):
        """Learn and adapt from previous battles."""
        for key, value in strategy_data.items():
            self.strategy[key] = value

    def report_status(self):
        status = f"Robot {self.name} ({self.team.value}, {self.role.value}) at ({self.position.x}, {self.position.y})"
        status += f" - Health: {self.health} | Weapon: {self.weapon.name} (Ammo: {self.weapon.remaining_ammo})"
        if self.shield:
            status += " | Shield Active"
        if time.time() < self.stunned_until:
            status += f" | Stunned until {self.stunned_until - time.time():.1f}s"
        return status

