    def get_teammates(self, robot: Robot) -> List[Robot]:
        return [r for r in self.teams[robot.team] if r != robot]

    def get_opponents(self, robot: Robot) -> List[Robot]:
        return self.teams[self.get_opponent_team(robot.team)]

    def report_objective_status(self):
        print(f"Current objective: {self.objective.value}")
        print(f"Round timer: {self.round_timer} seconds")

