# solution.py
import json
from typing import List, Dict, Optional, Tuple
from datetime import datetime

# Constants for data structure
MAX_UPLOAD_SIZE = 10 * 1024 * 1024  # 10 MB
VALID_CATEGORIES = ["knitting", "woodworking", "painting", "sewing", "crocheting", "paper crafts", "jewelry"]

# User class to manage user profiles
class User:
    def __init__(self, user_id: int, username: str, bio: str, profile_picture: Optional[str] = None):
        self.user_id = user_id
        self.username = username
        self.bio = bio
        self.profile_picture = profile_picture
        self.projects = []
        self.comments = []
        self.messages = []

    def to_dict(self):
        return {
            "user_id": self.user_id,
            "username": self.username,
            "bio": self.bio,
            "profile_picture": self.profile_picture,
            "projects": self.projects,
            "comments": self.comments,
            "messages": self.messages
        }

# Project class for individual crafting projects
class Project:
    def __init__(self, project_id: int, user_id: int, title: str, media: List[str], description: str, category: str):
        self.project_id = project_id
        self.user_id = user_id
        self.title = title
        self.media = media
        self.description = description
        self.category = category
        self.comments = []

    def to_dict(self):
        return {
            "project_id": self.project_id,
            "user_id": self.user_id,
            "title": self.title,
            "media": self.media,
            "description": self.description,
            "category": self.category,
            "comments": self.comments
        }

# GroupProject class for collaborative projects
class GroupProject:
    def __init__(self, project_id: int, leader_id: int, title: str, description: str, members: List[int] = None):
        self.project_id = project_id
        self.leader_id = leader_id
        self.title = title
        self.description = description
        self.members = members if members else [leader_id]
        self.tasks = {}
        self.comments = []

    def add_member(self, user_id: int):
        if user_id not in self.members:
            self.members.append(user_id)
            return True
        return False

    def remove_member(self, user_id: int):
        if user_id in self.members:
            self.members.remove(user_id)
            return True
        return False

    def assign_task(self, task_id: str, user_id: int, description: str, due_date: datetime):
        self.tasks[task_id] = {
            "user_id": user_id,
            "description": description,
            "due_date": due_date.isoformat(),
            "completed": False
        }

    def mark_task_complete(self, task_id: str):
        if task_id in self.tasks:
            self.tasks[task_id]["completed"] = True

    def to_dict(self):
        return {
            "project_id": self.project_id,
            "leader_id": self.leader_id,
            "title": self.title,
            "description": self.description,
            "members": self.members,
            "tasks": self.tasks,
            "comments": self.comments
        }

# Comment class to support feedback on projects
class Comment:
    def __init__(self, comment_id: int, user_id: int, content: str, upvotes: int = 0, downvotes: int = 0):
        self.comment_id = comment_id
        self.user_id = user_id
        self.content = content
        self.upvotes = upvotes
        self.downvotes = downvotes

    def to_dict(self):
        return {
            "comment_id": self.comment_id,
            "user_id": self.user_id,
            "content": self.content,
            "upvotes": self.upvotes,
            "downvotes": self.downvotes
        }

# Message class for private and group messaging
class Message:
    def __init__(self, message_id: int, sender_id: int, receiver_ids: List[int], content: str, timestamp: datetime):
        self.message_id = message_id
        self.sender_id = sender_id
        self.receiver_ids = receiver_ids
        self.content = content
        self.timestamp = timestamp

    def to_dict(self):
        return {
            "message_id": self.message_id,
            "sender_id": self.sender_id,
            "receiver_ids": self.receiver_ids,
            "content": self.content,
            "timestamp": self.timestamp.isoformat()
        }

# Main application class to handle all operations
class CollaborateCraft:
    def __init__(self):
        self.users: Dict[int, User] = {}
        self.projects: Dict[int, Project] = {}
        self.group_projects: Dict[int, GroupProject] = {}
        self.comments: Dict[int, Comment] = {}
        self.messages: Dict[int, Message] = {}
        self.next_id = 1

    def create_user(self, username: str, bio: str, profile_picture: Optional[str] = None) -> Dict:
        if not username or not bio:
            return {"success": False, "error": "Username and bio are required."}
        if profile_picture and len(profile_picture) > MAX_UPLOAD_SIZE:
            return {"success": False, "error": "Profile picture exceeds size limit."}
        user = User(self.next_id, username, bio, profile_picture)
        self.users[self.next_id] = user
        self.next_id += 1
        return {"success": True, "user_id": user.user_id}

    def post_project(self, user_id: int, title: str, media: List[str], description: str, category: str) -> Dict:
        if user_id not in self.users:
            return {"success": False, "error": "User not found."}
        if not title or not description or category not in VALID_CATEGORIES:
            return {"success": False, "error": "Invalid input for project."}
        if any(len(item) > MAX_UPLOAD_SIZE for item in media):
            return {"success": False, "error": "Media files exceed size limit."}
        project = Project(self.next_id, user_id, title, media, description, category)
        self.projects[self.next_id] = project
        self.next_id += 1
        return {"success": True, "project_id": project.project_id}

    def create_group_project(self, leader_id: int, title: str, description: str) -> Dict:
        if leader_id not in self.users:
            return {"success": False, "error": "Leader not found."}
        if not title or not description:
            return {"success": False, "error": "Title and description are required."}
        group_project = GroupProject(self.next_id, leader_id, title, description)
        self.group_projects[self.next_id] = group_project
        self.next_id += 1
        return {"success": True, "project_id": group_project.project_id}

    def add_comment(self, user_id: int, project_id: int, content: str) -> Dict:
        if user_id not in self.users or (project_id not in self.projects and project_id not in self.group_projects):
            return {"success": False, "error": "User or project not found."}
        comment = Comment(self.next_id, user_id, content)
        if project_id in self.projects:
            self.projects[project_id].comments.append(comment.to_dict())
        else:
            self.group_projects[project_id].comments.append(comment.to_dict())
        self.comments[self.next_id] = comment
        self.next_id += 1
        return {"success": True, "comment_id": comment.comment_id}

    def send_message(self, sender_id: int, receiver_ids: List[int], content: str) -> Dict:
        if sender_id not in self.users or any(uid not in self.users for uid in receiver_ids):
            return {"success": False, "error": "Invalid user(s)."}
        message = Message(self.next_id, sender_id, receiver_ids, content, datetime.now())
        self.messages[self.next_id] = message
        self.next_id += 1
        return {"success": True, "message_id": message.message_id}

    def search(self, query: str, search_type: str = "user") -> List[Dict]:
        if search_type not in ["user", "project", "group_project"]:
            return

