class User:
    def __init__(self, username: str, bio: str, profile_pic: str = None):
        self.user_id = str(uuid.uuid4())
        self.username = username
        self.bio = bio
        self.profile_pic = profile_pic
        self.posts = []
        self.group_projects = []
        self.messages = []

    def to_dict(self):
        return {
            "user_id": self.user_id,
            "username": self.username,
            "bio": self.bio,
            "profile_pic": self.profile_pic,
        }


class Post:
    def __init__(self, user_id: str, media: List[str], description: str, tags: List[str]):
        self.post_id = str(uuid.uuid4())
        self.user_id = user_id
        self.media = media
        self.description = description
        self.tags = tags
        self.comments = []
        self.upvotes = 0
        self.downvotes = 0
        self.timestamp = time.time()

    def to_dict(self):
        return {
            "post_id": self.post_id,
            "user_id": self.user_id,
            "media": self.media,
            "description": self.description,
            "tags": self.tags,
            "comments": [c.to_dict() for c in self.comments],
            "upvotes": self.upvotes,
            "downvotes": self.downvotes,
            "timestamp": self.timestamp,
        }


class Comment:
    def __init__(self, user_id: str, text: str):
        self.comment_id = str(uuid.uuid4())
        self.user_id = user_id
        self.text = text
        self.upvotes = 0
        self.downvotes = 0
        self.timestamp = time.time()

    def to_dict(self):
        return {
            "comment_id": self.comment_id,
            "user_id": self.user_id,
            "text": self.text,
            "upvotes": self.upvotes,
            "downvotes": self.downvotes,
            "timestamp": self.timestamp,
        }


class GroupProject:
    def __init__(self, leader_id: str, name: str, description: str, category: str):
        self.project_id = str(uuid.uuid4())
        self.leader_id = leader_id
        self.name = name
        self.description = description
        self.category = category
        self.members = [leader_id]
        self.tasks = {}
        self.comments = []
        self.upvotes = 0
        self.downvotes = 0

    def add_member(self, user_id: str):
        if user_id not in self.members:
            self.members.append(user_id)

    def assign_task(self, task_id: str, user_id: str, description: str):
        self.tasks[task_id] = {
            "user_id": user_id,
            "description": description,
            "status": "pending",
            "assigned_at": time.time(),
        }

    def complete_task(self, task_id: str):
        if task_id in self.tasks:
            self.tasks[task_id]["status"] = "completed"
            self.tasks[task_id]["completed_at"] = time.time()

    def to_dict(self):
        return {
            "project_id": self.project_id,
            "leader_id": self.leader_id,
            "name": self.name,
            "description": self.description,
            "category": self.category,
            "members": self.members,
            "tasks": self.tasks,
            "comments": [c.to_dict() for c in self.comments],
            "upvotes": self.upvotes,
            "downvotes": self.downvotes,
        }


