            "receiver_id": self.receiver_id,
            "content": self.content,
            "group_project_id": self.group_project_id,
            "timestamp": self.timestamp,
        }


class CollaborateCraftApp:
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.posts: Dict[str, Post] = {}
        self.group_projects: Dict[str, GroupProject] = {}
        self.messages: Dict[str, Message] = {}

    def create_user_profile(self, username: str, bio: str, profile_pic: Optional[str] = None):
        if username in [u.username for u in self.users.values()]:
            return {"error": "Username already exists."}
        user = User(username, bio, profile_pic)
        self.users[user.user_id] = user
        return {"user": user.to_dict(), "success": True}

    def post_project(self, user_id: str, media: List[str], description: str, tags: List[str]):
        if user_id not in self.users:
