        self.memory = []  # Stores past actions and outcomes

    def move(self, direction):
        """Move the robot in the specified direction."""
        x, y = self.position
        if direction == Direction.UP:
            y -= self.speed
        elif direction == Direction.DOWN:
            y += self.speed
        elif direction == Direction.LEFT:
            x -= self.speed
        elif direction == Direction.RIGHT:
            x += self.speed
        self.position = (x, y)

    def attack(self, target):
        """Attack another robot with current weapon."""
        if self.weapon and self.weapon.weapon_type == WeaponType.RANGED:
            if self.is_in_range(target):
                damage = max(0, self.attack_power - target.defense)
                target.take_damage(damage)
                self.memory.append({"action": "attack", "target": target.name, "damage": damage, "success": True})
                return True
        elif self.weapon and self.weapon.weapon_type == WeaponType.MELEE:
            if self.is_in_melee_range(target):
                damage = max(0, self.attack_power - target.defense)
                target.take_damage(damage)
                self.memory.append({"action": "attack", "target": target.name, "damage": damage, "success": True})
                return True
        self.memory.append({"action": "attack", "target": target.name, "damage": 0, "success": False})
        return False

    def use_ability(self, ability_name, target=None):
        """Use a special ability."""
        for ability in self.abilities:
            if ability.name == ability_name:
                if ability.is_usable():
                    if ability.use(self, target):
                        self.memory.append({"action": "use_ability", "ability": ability_name, "target": target.name if target else None, "success": True})
                        return True
        self.memory.append({"action": "use_ability", "ability": ability_name, "target": target.name if target else None, "success": False})
        return False

    def take_damage(self, damage):
        """Take damage and reduce health."""
        self.health = max(0, self.health - damage)
        if self.health <= 0:
            self.die()

    def die(self):
        """Handle robot death."""
        self.health = 0
        self.memory.append({"action": "death", "success": False})
        print(f"{self.name} has died.")

    def is_in_range(self, target):
        """Check if target is in range for ranged attack."""
        distance = math.sqrt((self.position[0] - target.position[0])**2 + (self.position[1] - target.position[1])**2)
        return distance <= self.weapon.range

    def is_in_melee_range(self, target):
        """Check if target is in melee range."""
        distance = math.sqrt((self.position[0] - target.position[0])**2 + (self.position[1] - target.position[1])**2)
        return distance <= 10  # Melee range is 10 units

