from enum import Enum

class Direction(Enum):
    UP = 1
    DOWN = 2
    LEFT = 3
    RIGHT = 4
    IDLE = 5

class ActionType(Enum):
    ATTACK = 1
    MOVE = 2
    USE_ABILITY = 3
    GATHER_INFO = 4

class WeaponType(Enum):
    RANGED = 1
    MELEE = 2
    SUPPORT = 3

class Team(Enum):
    RED = 1
    BLUE = 2
