class HazardType(Enum):
    """Types of environmental hazards in the arena."""
    LAND_MINE = 0
    POISON_CLOUD = 1
    LASER_GRID = 2
    FIRE_FIELD = 3

class Hazard:
    """Base class for environmental hazards."""

    def __init__(self, hazard_type, position, radius, damage, duration):
        self.hazard_type = hazard_type
        self.position = position
        self.radius = radius
        self.damage = damage
        self.duration = duration
        self.active = True
        self.timer = time.time()

    def is_active(self):
        """Check if the hazard is still active based on duration."""
        return self.active and (time.time() - self.timer < self.duration)

    def check_collision(self, robot):
        """Check if a robot is affected by the hazard."""
        distance = self.position.distance(robot.position)
        if distance < self.radius and self.is_active():
            robot.take_damage(self.damage)
            return True
        return False

    def __repr__(self):
        return f"Hazard(type={self.hazard_type}, position={self.position}, radius={self.radius}, damage={self.damage}, duration={self.duration})"

class RobotState(Enum):
    """Possible states for a robot in the arena."""
    IDLE = 0
    MOVING = 1
    ATTACKING = 2
