        self.inventory = []
        self.target = None
        self.memory = []  # For learning from previous battles
        self.role = None  # Dynamic role assignment based on team needs
        self.score = 0

    def move(self, direction):
        """Move the robot in the specified direction."""
        if self.state == RobotState.DEAD:
            return
        self.state = RobotState.MOVING
        self.position = self.position + (direction * self.speed * self.speed_multiplier)

    def attack(self, target):
        """Attempt to attack a target with the robot's current weapon."""
        if self.state == RobotState.DEAD:
            return
        self.target = target
        self.state = RobotState.ATTACKING
        if self.weapon.weapon_type in [WeaponType.RIFLE, WeaponType.SHOTGUN, WeaponType.LASER]:
            distance = self.position.distance(target.position)
            if distance <= self.weapon.range:
                if self.weapon.shoot(target.position):
