        print(f"Maintaining difficulty at level {self.difficulty_level}")

class LearningSystem:
    """Enables robots to learn and adapt from previous battles."""
    def __init__(self):
        self.robot_memory = {}

    def record_battle_outcome(self, robots):
        """Record the outcome of a battle for each robot."""
        for robot in robots:
            self.robot_memory[robot.name] = {
                "wins": robot.wins,
                "losses": robot.losses,
                "combat_stats": robot.combat_stats,
                "team_performance": robot.team_performance
            }

    def analyze_battle(self, robots):
        """Analyze the battle and provide insights for adaptation."""
        for robot in robots:
            if robot.name in self.robot_memory:
                memory = self.robot_memory[robot.name]
                if robot.wins > memory["wins"]:
                    robot._adapt_winning_strategy()
                elif robot.losses > memory["losses"]:
                    robot._adapt_losing_strategy()

    def _adapt_winning_strategy(self, robot):
        """Adapt the robot's strategy based on successful outcomes."""
        if robot.role == RobotRole.ASSAULT:
            robot.movement_speed += 0.5
            robot.attack_power += 5
        elif robot.role == RobotRole.SUPPORT:
            robot.heal_amount += 10
            robot.heal_speed += 1.0

    def _adapt_losing_strategy(self, robot):
        """Adapt the robot's strategy based on failed outcomes."""
        if robot.role == RobotRole.ASSAULT:
