class Weapon:
    """Base class for all weapons in the game."""
    def __init__(self, weapon_type, damage, range, cooldown):
        self.weapon_type = weapon_type
        self.damage = damage
        self.range = range
        self.cooldown = cooldown
        self.last_used = 0

    def is_ready(self):
        """Check if the weapon is ready to be used."""
        return time.time() - self.last_used >= self.cooldown

    def use(self, target_pos, current_time):
        """Simulate using the weapon against a target."""
        self.last_used = current_time
        return f"{self.weapon_type.value} fired at {target_pos.x}, {target_pos.y}"

