class HazardType(Enum):
    """Types of environmental hazards in the arena."""
    LAVA = "Lava"
    EXPLOSIVE = "Explosive"
    ELECTRICITY = "Electricity"

class Hazard:
    """Base class for environmental hazards that can damage robots."""
    def __init__(self, hazard_type, damage_per_second):
        self.hazard_type = hazard_type
        self.damage_per_second = damage_per_second
        self.position = Vector2(0, 0)
        self.radius = 5

    def check_collision(self, robot):
        """Check if a robot is affected by this hazard."""
        distance = (robot.position - self.position).magnitude()
        if distance <= self.radius:
            robot.health -= self.damage_per_second * 0.1
            return True
        return False

class LavaHazard(Hazard):
    """Implementation of a lava hazard."""
    def __init__(self):
        super().__init__(HazardType.LAVA, damage_per_second=10)

class ExplosiveHazard(Hazard):
    """Implementation of an explosive hazard that detonates after a delay."""
    def __init__(self):
        super().__init__(HazardType.EXPLOSIVE, damage_per_second=50)
        self.detonation_time = time.time() + 5  # Detonates after 5 seconds

    def check_collision(self, robot):
        distance = (robot.position - self.position).magnitude()
        if distance <= self.radius:
            if time.time() >= self.detonation_time:
                robot.health -= self.damage_per_second * 0.1
                return True
        return False

class ElectricityHazard(Hazard):
    """Implementation of an electricity hazard that stuns robots."""
    def __init__(self):
        super().__init__(HazardType.ELECTRICITY, damage_per_second=5)
        self.stun_duration = 3

    def check_collision(self, robot):
        distance = (robot.position - self.position).magnitude()
        if distance <= self.radius:
            robot.health -= self.damage_per_second * 0.05
            robot.movement_speed = 0  # Stun the robot
            robot.stunned_until = time.time() + self.stun_duration
            return True
        return False

