class AdaptiveDifficultySystem:
    """Adjusts difficulty based on robot performance."""
    def __init__(self):
        self.difficulty_level = 1
        self.max_difficulty = 5
        self.performance_metrics = defaultdict(float)

    def evaluate_performance(self, robots):
        """Evaluate the performance of robots and adjust difficulty."""
        total_damage_dealt = 0
        total_damage_received = 0
        alive_robots = sum(1 for robot in robots if robot.is_alive)

        for robot in robots:
            total_damage_dealt += robot.combat_stats["damage_dealt"]
            total_damage_received += robot.combat_stats["damage_received"]

        if alive_robots == 0:
            return  # No one is alive, no need to adjust

        average_damage_ratio = total_damage_received / total_damage_dealt if total_damage_dealt > 0 else 0

        if average_damage_ratio > 1.5:  # Robots are taking more damage than they deal
            self._increase_difficulty()
        elif average_damage_ratio < 0.5:  # Robots are dealing more damage than they take
            self._decrease_difficulty()
        else:
            self._maintain_difficulty()

    def _increase_difficulty(self):
        """Increase the difficulty level and AI aggression."""
        if self.difficulty_level < self.max_difficulty:
            self.difficulty_level += 1
            print(f"Difficulty increased to level {self.difficulty_level}")

    def _decrease_difficulty(self):
        """Decrease the difficulty level and AI aggression."""
        if self.difficulty_level > 1:
            self.difficulty_level -= 1
            print(f"Difficulty decreased to level {self.difficulty_level}")

