class TeamManager:
    """Manages teams and their compositions."""
    def __init__(self):
        self.teams = {
            Team.RED: [],
            Team.BLUE: [],
            Team.NEUTRAL: []
        }

    def add_robot(self, team, robot):
        """Add a robot to a team."""
        self.teams[team].append(robot)

    def get_team(self, team):
        """Get all robots in a team."""
        return self.teams[team]

    def balance_teams(self):
        """Balance the teams by adjusting the number of robots in each."""
        red_count = len(self.teams[Team.RED])
        blue_count = len(self.teams[Team.BLUE])
        if abs(red_count - blue_count) > 1:
            # Move a robot from the larger team to the smaller one
            if red_count > blue_count:
                moved_robot = self.teams[Team.RED].pop()
                self.teams[Team.BLUE].append(moved_robot)
            else:
                moved_robot = self.teams[Team.BLUE].pop()
                self.teams[Team.RED].append(moved_robot)

class CombatSystem:
    """Handles all combat-related logic in the arena."""
    def __init__(self):
        self.battle_logs = []

    def calculate_damage(self, attacker, target):
        """Calculate the damage dealt by an attacker to a target."""
        best_weapon = attacker.select_best_weapon(target.position)
        if best_weapon:
            return best_weapon.damage
        return 0

    def process_combat(self, robots):
        """Process all combat actions between robots."""
        for i, robot in enumerate(robots):
            if not robot.is_alive:
                continue
            closest_enemy = self._find_closest_enemy(robot, robots)
            if closest_enemy:
                attack_result = robot.attack(closest_enemy.position)
                damage = self.calculate_damage(robot, closest_enemy)
                closest_enemy.receive_damage(damage)
                self.battle_logs.append(f"{robot.name} attacked {closest_enemy.name} for {damage} damage. {attack_result}")
            else:
                self.battle_logs.append(f"{robot.name} has no target to attack.")

    def _find_closest_enemy(self, robot, robots):
        """Find the closest enemy robot to the given robot."""
        enemies = [r for r in robots if r.team != robot.team and r.is_alive]
        if not enemies:
            return None
        return min(enemies, key=lambda e: (e.position - robot.position).magnitude())

class ObjectiveSystem:
    """Manages game objectives and tracks progress."""
    def __init__(self):
        self.objectives = []
        self.completed_objectives = []

    def add_objective(self, objective):
        """Add an objective to the system."""
        self.objectives.append(objective)

    def update(self, robots):
        """Update the status of all objectives."""
        for objective in self.objectives:
            if not objective.completed and objective.check_completion(robots):
                self.completed_objectives.append(objective)
                self.objectives.remove(objective)
                self._award_objective_completion_bonuses(robots, objective)

    def _award_objective_completion_bonuses(self, robots, objective):
        """Award bonuses to robots for completing an objective."""
        for robot in robots:
            if robot.team == objective.team:
                robot.update_score(100)  # Example bonus score
                print(f"{robot.name} received 100 points for completing {objective.description}.")

class AdaptiveDifficultySystem:
    """Adjusts difficulty based on robot performance."""
    def __init__(self):
        self.difficulty_level = 1
        self.max_difficulty = 5
        self.performance_metrics = defaultdict(float)

    def evaluate_performance(self, robots):
        """Evaluate the performance of robots and adjust difficulty."""
        total_damage_dealt = 0
        total_damage_received = 0
        alive_robots = sum(1 for robot in robots if robot.is_alive)

        for robot in robots:
            total_damage_dealt += robot.combat_stats["damage_dealt"]
            total_damage_received += robot.combat_stats["damage_received"]

        if alive_robots == 0:
            return  # No one is alive, no need to adjust

        average_damage_ratio = total_damage_received / total_damage_dealt if total_damage_dealt > 0 else 0

        if average_damage_ratio > 1.5:  # Robots are taking more damage than they deal
            self._increase_difficulty()
        elif average_damage_ratio < 0.5:  # Robots are dealing more damage than they take
            self._decrease_difficulty()
        else:
            self._maintain_difficulty()

    def _increase_difficulty(self):
        """Increase the difficulty level and AI aggression."""
        if self.difficulty_level < self.max_difficulty:
            self.difficulty_level += 1
            print(f"Difficulty increased to level {self.difficulty_level}")

    def _decrease_difficulty(self):
        """Decrease the difficulty level and AI aggression."""
        if self.difficulty_level > 1:
            self.difficulty_level -= 1
            print(f"Difficulty decreased to level {self.difficulty_level}")

    def _maintain_difficulty(self):
        """Maintain the current difficulty level."""
        print(f"Maintaining difficulty at level {self.difficulty_level}")

class LearningSystem:
    """Enables robots to learn and adapt from previous battles."""
    def __init__(self):
        self.robot_memory = {}

    def record_battle_outcome(self, robots):
        """Record the outcome of a battle for each robot."""
        for robot in robots:
            self.robot_memory[robot.name] = {
                "wins": robot.wins,
                "losses": robot.losses,
                "combat_stats": robot.combat_stats,
                "team_performance": robot.team_performance
            }

    def analyze_battle(self, robots):
        """Analyze the battle and provide insights for adaptation."""
        for robot in robots:
            if robot.name in self.robot_memory:
                memory = self.robot_memory[robot.name]
                if robot.wins > memory["wins"]:
                    robot._adapt_winning_strategy()
                elif robot.losses > memory["losses"]:
                    robot._adapt_losing_strategy()

    def _adapt_winning_strategy(self, robot):
        """Adapt the robot's strategy based on successful outcomes."""
        if robot.role == RobotRole.ASSAULT:
            robot.movement_speed += 0.5
            robot.attack_power += 5
        elif robot.role == RobotRole.SUPPORT:
            robot.heal_amount += 10
            robot.heal_speed += 1.0

    def _adapt_losing_strategy(self, robot):
        """Adapt the robot's strategy based on failed outcomes."""
        if robot.role == RobotRole.ASSAULT:
            robot.defense += 5
            robot.shield_duration += 2
        elif robot.role == RobotRole.SUPPORT:
            robot.heal_range += 5
            robot.heal_cooldown -= 0.5

