    def __init__(self, name, team, starting_position):
        self.name = name
        self.team = team
        self.position = starting_position
        self.direction = Direction.RIGHT
        self.health = 100
        self.max_health = 100
        self.movement_speed = 3.0
        self.weapons = []
        self.power_ups = []
        self.role = RobotRole.SUPPORT
        self.skills = []
        self.score = 0
        self.is_alive = True
        self.weapon_cooldowns = {}
        self.last_action_time = 0
        self.movement_thread = threading.Thread(target=self.move_ai)

    def assign_role(self, role):
        """Assign a specific role to the robot."""
        self.role = role
        self._initialize_skills_for_role(role)

    @abstractmethod
    def _initialize_skills_for_role(self, role):
        """Initialize skills based on the assigned role."""
        pass

    def move(self, direction, duration):
        """Move the robot in a direction for a specified duration."""
        start_time = time.time()
        while time.time() - start_time < duration and self.is_alive:
            if self.direction != direction:
                self.direction = direction
            self.position = self.position + (direction.value * self.movement_speed)
            time.sleep(0.1)

    def move_ai(self):
        """AI-controlled movement logic for the robot."""
        while self.is_alive:
            # Decide on a movement direction based on AI logic
        # Simple behavior tree logic for goal-oriented movement
        if self.role == RobotRole.SCOUT:
            # Scouts prioritize finding the closest power-up
            closest_powerup = self._find_closest_powerup()
            if closest_powerup:
                direction = self._calculate_direction_towards(closest_powerup.position)
            else:
                direction = random.choice(list(Direction))
        elif self.role == RobotRole.ASSAULT:
            # Attackers prioritize chasing enemies or objectives
            target = self._find_closest_enemy()
            if target:
                direction = self._calculate_direction_towards(target.position)
            else:
                direction = random.choice(list(Direction))
        elif self.role == RobotRole.TANK:
            # Tanks move closer to objectives or hazards to protect teammates
            objective = self._find_closest_objective()
            if objective:
                direction = self._calculate_direction_towards(objective.position)
            else:
                direction = random.choice(list(Direction))
        else:
            # Default random movement for other roles
            direction = random.choice(list(Direction))            self.move(direction, duration=1.0)
            time.sleep(0.5)
    def _calculate_direction_towards(self, target_position):
        """Calculate the direction to head toward a target."""
        direction_vector = (target_position - self.position).normalize()
        if direction_vector.x > 0.7:
            return Direction.RIGHT
        elif direction_vector.x < -0.7:
            return Direction.LEFT
        elif direction_vector.y > 0.7:
            return Direction.DOWN
        else:
            return Direction.UP

    def _find_closest_powerup(self):
        """Find the closest power-up in the arena."""
        if hasattr(self, 'arena') and hasattr(self.arena, 'power_ups'):
            return min(self.arena.power_ups, key=lambda pu: (pu.position - self.position).magnitude(), default=None)
        return None

    def _find_closest_enemy(self):
        """Find the closest enemy robot."""
        if hasattr(self, 'arena') and hasattr(self.arena, 'robots'):
            enemies = [robot for robot in self.arena.robots if robot.team != self.team and robot.is_alive]
            return min(enemies, key=lambda robot: (robot.position - self.position).magnitude(), default=None)
        return None

    def _find_closest_objective(self):
        """Find the closest objective in the arena."""
        if hasattr(self, 'arena') and hasattr(self.arena, 'objectives'):
            return min(self.arena.objectives, key=lambda obj: (obj.position - self.position).magnitude(), default=None)
        return None

    def attack(self, target_position):
        """Attack a target at a specific position."""
        for weapon in self.weapons:
            if weapon.is_ready():
                return weapon.use(target_position, time.time())
        return "No weapon ready to attack."

    def receive_damage(self, amount):
        """Apply damage to the robot, considering shields and health."""
        if self.shield > 0:
            if self.shield >= amount:
                self.shield -= amount
            else:
                remaining = amount - self.shield
                self.shield = 0
                self.health -= remaining
        else:
            self.health -= amount
            if self.health <= 0:
                self.is_alive = False
                self.health = 0

    def update(self, arena):
        """Update the robot's state in the arena."""
        # Check for hazards
        for hazard in arena.hazards:
            if hazard.check_collision(self):
                print(f"{self.name} is affected by {hazard.hazard_type.value} at {hazard.position.x}, {hazard.position.y}")

        # Check for power-ups
        for power_up in arena.power_ups:
            if (self.position - power_up.position).magnitude() < 2:
                power_up.activate(self)
                arena.power_ups.remove(power_up)
                print(f"{self.name} activated {power_up.powerup_type.value} power-up.")

    def select_best_weapon(self, target_position):
        """Select the best weapon to use based on distance to the target."""
        best_weapon = None
        best_distance_ratio = 0
        for weapon in self.weapons:
            distance = (self.position - target_position).magnitude()
            distance_ratio = distance / weapon.range
            if 0.5 <= distance_ratio <= 1.5:
                if best_weapon is None or distance_ratio < best_distance_ratio:
                    best_weapon = weapon
                    best_distance_ratio = distance_ratio
        return best_weapon

    def update_score(self, points):
        """Update the robot's score with the specified points."""
        self.score += points

