class Vector3:
    """Represents a 3D vector for position, velocity, and direction."""
    def __init__(self, x=0, y=0, z=0):
        self.x = x
        self.y = y
        self.z = z

    def __add__(self, other):
        return Vector3(self.x + other.x, self.y + other.y, self.z + other.z)

    def __sub__(self, other):
        return Vector3(self.x - other.x, self.y - other.y, self.z - other.z)

    def __mul__(self, scalar):
        return Vector3(self.x * scalar, self.y * scalar, self.z * scalar)

    def magnitude(self):
        return (self.x**2 + self.y**2 + self.z**2)**0.5

    def normalize(self):
        mag = self.magnitude()
        if mag > 0:
            return Vector3(self.x/mag, self.y/mag, self.z/mag)
        return self

class Weapon:
    """Base class for different types of weapons."""
    def __init__(self, name, damage, range, fire_rate, ammo_capacity):
        self.name = name
        self.damage = damage
        self.range = range
        self.fire_rate = fire_rate  # Rounds per second
        self.ammo_capacity = ammo_capacity
        self.current_ammo = ammo_capacity

    def reload(self):
        """Reload the weapon to full capacity."""
        self.current_ammo = self.ammo_capacity
        print(f"{self.name} reloaded with {self.current_ammo} rounds.")

    def fire(self, target):
        """Fire the weapon at a target within range."""
        if self.current_ammo > 0:
