        """Fire the weapon at a target within range."""
        if self.current_ammo > 0:
            distance = (self.owner.position - target.position).magnitude()
            if distance <= self.range:
                self.current_ammo -= 1
                print(f"{self.owner.name} fires {self.name} at {target.name} for {self.damage} damage.")
                return self.damage
            else:
                print(f"{self.owner.name} is out of range to fire {self.name}.")
