class EnvironmentalHazard:
    """Represents an environmental hazard that affects robots."""
    def __init__(self, name, damage_per_tick, radius, position, duration):
        self.name = name
        self.damage_per_tick = damage_per_tick
        self.radius = radius
        self.position = position
        self.duration = duration
        self.active = True

    def tick(self, arena):
        """Apply the hazard's effect to nearby robots."""
        if self.active:
            for robot in arena.robots:
                distance = (robot.position - self.position).magnitude()
                if distance <= self.radius:
                    robot.take_damage(self.damage_per_tick)
                    print(f"{robot.name} is damaged by {self.name} hazard for {self.damage_per_tick} damage.")
            self.duration -= 1
            if self.duration <= 0:
                self.active = False

