class CaptureFlagObjective(Objective):
    """Objective to capture the opponent's flag."""
    def __init__(self, target_position):
        super().__init__(target_position)
        self.carried = False

    def update(self, robot, arena):
        """Update the capture flag objective."""
        if self.completed:
            return

        # Move towards the flag
        robot.move(self.target, arena)

        # Check if flag is reached
        distance = (robot.position - self.target).magnitude()
        if distance <= 5:
            if not self.carried:
                print(f"{robot.name} has captured the flag!")
                self.carried = True
                robot.score += 20  # Reward for capturing
            else:
                # Try to return to base
                if (robot.position - robot.team.base_position).magnitude() <= 5:
                    print(f"{robot.name} has returned the flag to base!")
                    robot.team.score += 50  # Team score for success
                    robot.score += 30  # Personal score for success
                    self.completed = True
                else:
                    robot.move(robot.team.base_position, arena)

class DefendBaseObjective(Objective):
    """Objective to defend the team's base."""
