                                  Vector3(50, 90, 1)))

        # Add hazards
        self.add_hazard(EnvironmentalHazard("Lava", 5, 10, Vector3(50, 50, 0.5), 100))
        self.add_hazard(EnvironmentalHazard("Toxic Gas", 3, 15, Vector3(25, 25, 0.5), 100))

        # Set up the objective
        if self.objective_type == "capture_the_flag":
            self.flags.append(Vector3(90, 10, 1))  # Red team's flag
