                robot.objective = EscortObjective(payload_position, destination)

    def run_game(self):
        """Start and run the game loop."""
        self.running = True
        while self.running and self.game_time < self.max_game_time:
            self.update_game()
            time.sleep(0.01)  # 10 ms per frame
            self.game_time += 0.01

        # End of game
        self.running = False
        self.end_game()

    def update_game(self):
        """Update the game state for each frame."""
        # Update all robots
        for robot in self.robots:
            robot.update_objective(self)
            # Check for power-ups
            for power_up in self.power_ups:
                if power_up.active and (robot.position - power_up.position).magnitude() <= 5:
                    power_up.apply(robot)
            # Check for hazards
            for hazard in self.hazards:
                hazard.tick(self)

