    def adjust_difficulty(self):
        """Adjust the game difficulty based on robot performance."""
        total_health = sum(robot.health for robot in self.robots)
        if total_health > 800:  # If robots are too powerful
            for robot in self.robots:
                if robot.health > 100:
                    robot.health = 100  # Cap health
                    robot.speed -= 0.5  # Reduce speed
        elif total_health < 500:  # If robots are too weak
