class Effect:
    """Base class for visual and audio effects."""
    def __init__(self, position, duration):
        self.position = position
        self.duration = duration
        self.active = True

    def update(self):
        """Update the effect over time."""
        if self.active:
            self.duration -= 0.01
            if self.duration <= 0:
                self.active = False

class ExplosionEffect(Effect):
    """Visual effect for an explosion."""
    def __init__(self, position):
