class MultiAgentTaskScheduler:
    def __init__(self):
        self.tasks = []
        self.agents = []
        self.task_history = []
        self.chat_history = []

    def add_task(self, task):
        self.tasks.append(task)
        self._reassign_tasks()

    def add_agent(self, agent):
        self.agents.append(agent)
        self._reassign_tasks()

    def remove_agent(self, agent_name):
        self.agents = [a for a in self.agents if a.name != agent_name]
        self._reassign_tasks()

    def _reassign_tasks(self):
        pending_tasks = [task for task in self.tasks if task.status == TaskStatus.PENDING]
        available_agents = [agent for agent in self.agents if agent.status == AgentStatus.IDLE]

        for task in sorted(pending_tasks, key=lambda x: x.priority, reverse=True):
            for agent in available_agents:
                if agent.is_capable(task):
                    agent.assign_task(task)
                    available_agents.remove(agent)
                    break

    def complete_task(self, task):
        for agent in self.agents:
            if task in agent.assigned_tasks:
                agent.complete_task(task)
                break
        task_entry = {
            "task": task.name,
            "assigned_agent": task.assigned_agent,
            "start_time": task.start_time,
            "end_time": task.end_time,
            "feedback": task.feedback
        }
        self.task_history.append(task_entry)

    def fail_task(self, task, reason):
        for agent in self.agents:
            if task in agent.assigned_tasks:
                agent.fail_task(task, reason)
                break

    def get_task_progress(self):
        progress = {
            "total_tasks": len(self.tasks),
            "pending": len([t for t in self.tasks if t.status == TaskStatus.PENDING]),
            "in_progress": len([t for t in self.tasks if t.status == TaskStatus.IN_PROGRESS]),
            "completed": len([t for t in self.tasks if t.status == TaskStatus.COMPLETED]),
            "failed": len([t for t in self.tasks if t.status == TaskStatus.FAILED])
        }
        return progress

    def get_agent_status(self):
        status = {
            "total_agents": len(self.agents),
            "idle": len([a for a in self.agents if a.status == AgentStatus.IDLE]),
            "busy": len([a for a in self.agents if a.status == AgentStatus.BUSY]),
            "offline": len([a for a in self.agents if a.status == AgentStatus.OFFLINE])
        }
        return status

    def agent_offline(self, agent_name):
        for agent in self.agents:
            if agent.name == agent_name:
                agent.update_status(AgentStatus.OFFLINE)
        self._reassign_tasks()

    def agent_online(self, agent_name):
        for agent in self.agents:
            if agent.name == agent_name:
                agent.update_status(AgentStatus.IDLE)
        self._reassign_tasks()

