class Position:
    """Represents a position in the arena with x and y coordinates"""
    def __init__(self, x: float, y: float):
        self.x = x
        self.y = y

    def distance_to(self, other: "Position") -> float:
        """Calculate the Euclidean distance between two positions"""
        return math.hypot(self.x - other.x, self.y - other.y)

    def move_towards(self, target: "Position", speed: float) -> "Position":
        """Move in the direction of the target position at the given speed"""
        if self.distance_to(target) < speed:
            return target
        angle = math.atan2(target.y - self.y, target.x - self.x)
        return Position(self.x + speed * math.cos(angle), 
                      self.y + speed * math.sin(angle))

