            delta_time = current_time - start_time
            start_time = current_time

            self.update(delta_time)

            # Simple AI for robots to move towards the objective
            for robot in self.robots:
                if robot.is_alive() and self.objective:
                    robot.move(self.objective.position)

            # Simple AI for robots to use weapons
            for robot in self.robots:
                if random.random() < 0.05:  # 5% chance to use a weapon each frame
                    if robot.is_alive():
                        # Pick a random weapon
                        weapon_type = random.choice(list(WeaponType))
                        # Find a target robot from the opposing team
                        target = self._find_opponent(robot)
                        if target:
                            robot.use_weapon(weapon_type, target)

            # Print status update
            if self.time_elapsed % 5 < delta_time:
                self._print_status()

            time.sleep(0.1)  # Simulate real-time processing delay

        print("Round complete!")
        print(f"Final score: Red {self.score[Team.RED]}, Blue {self.score[Team.BLUE]}")

        # Reset the arena for the next round
