class NotificationType(Enum):
    ASSIGNMENT = 1
    DEPENDENCY_MET = 2
    COMPLETION = 3


class Notification:
    def __init__(self, user, notification_type, task, message):
        self.user = user
        self.notification_type = notification_type
        self.task = task
        self.message = message
        self.timestamp = datetime.datetime.now()


class User:
    def __init__(self, user_id, name, role):
        self.user_id = user_id
        self.name = name
        self.role = role
        self.notifications = []

    def add_notification(self, notification):
        self.notifications.append(notification)


class Task:
    def __init__(self, task_id, name, description, deadline, dependencies=[], assigned_to=None):
        self.task_id = task_id
        self.name = name
        self.description = description
        self.deadline = deadline
        self.dependencies = dependencies
        self.assigned_to = assigned_to
        self.status = TaskStatus.PENDING
        self.history = []

    def start(self):
        if self.status == TaskStatus.PENDING and all(task.status == TaskStatus.COMPLETED for task in self.dependencies):
            self.status = TaskStatus.IN_PROGRESS
            timestamp = datetime.datetime.now().isoformat()
            self.history.append(
                {
                    'action': 'started',
                    'timestamp': timestamp
                }
            )
            self._notify(NotificationType.ASSIGNMENT)
        else:
            raise Exception(f"Cannot start task. Task {self.name} has dependencies that are not completed.")

    def complete(self):
        if self.status == TaskStatus.IN_PROGRESS:
            self.status = TaskStatus.COMPLETED
            timestamp = datetime.datetime.now().isoformat()
            self.history.append(
                {
                    'action': 'completed',
                    'timestamp': timestamp
                }
            )
            self._notify(NotificationType.COMPLETION)
            self._check_and_notify_dependencies()
        else:
            raise Exception(f"Cannot complete task. Task {self.name} is not in progress.")

    def delay(self):
        if self.status in [TaskStatus.PENDING, TaskStatus.IN_PROGRESS]:
            self.status = TaskStatus.DELAYED
            timestamp = datetime.datetime.now().isoformat()
            self.history.append(
                {
                    'action': 'delayed',
                    'timestamp': timestamp
                }
            )
            self._notify(NotificationType.DELAYED)
        else:
            raise Exception(f"Task {self.name} cannot be delayed at this stage.")

    def assign(self, user):
        self.assigned_to = user
        timestamp = datetime.datetime.now().isoformat()
        self.history.append(
            {
                'action': 'assigned',
                'user': user.name,
                'timestamp': timestamp
            }
        )
        user.add_notification(Notification(user.name, NotificationType.ASSIGNMENT, self, f"You have been assigned task {self.name}."))

    def _check_and_notify_dependencies(self):
        for dependent_task in self.dependent_tasks:
            dependent_task._check_dependency()

    def _check_dependency(self):
        completed_deps = all(task.status == TaskStatus.COMPLETED for task in self.dependencies)
        if completed_deps and self.status == TaskStatus.PENDING:
            self.status = TaskStatus.READY
            self._notify(NotificationType.DEPENDENCY_MET)

    def _notify(self, notification_type):
        if self.assigned_to:
            self.assigned_to.add_notification(Notification(self.assigned_to.name, notification_type, self, f"Task {self.name} is now in {self.status.name} state."))

    def __repr__(self):
        return f"Task({self.task_id}, {self.name}, {self.status.name})"

class Project:
