from typing import List, Dict, Optional


class Priority(Enum):
    """Priority levels for tasks"""
    LOW = 1
    MEDIUM = 2
    HIGH = 3


@dataclass
class Task:
    """Represents a project task"""
    task_id: int
    description: str
    due_date: str
    priority: Priority
    assigned_to: List[str]
    status: str = 'Pending'


class TaskManager:
    """Handles task creation, editing, and deletion"""
    def __init__(self):
        self.tasks: Dict[int, Task] = {}
        self.next_id = 1

    def create_task(self, description: str, due_date: str, priority: Priority, assigned_to: List[str]) -> Task:
        task = Task(self.next_id, description, due_date, priority, assigned_to)
        self.tasks[self.next_id] = task
        self.next_id += 1
        return task

    def delete_task(self, task_id: int):
        if task_id in self.tasks:
            del self.tasks[task_id]

    def update_task(self, task_id: int, new_description: Optional[str] = None, 
                   new_due_date: Optional[str] = None, new_priority: Optional[Priority] = None, 
                   new_assigned_to: Optional[List[str]] = None):
        if task_id in self.tasks:
            task = self.tasks[task_id]
            if new_description:
                task.description = new_description
            if new_due_date:
                task.due_date = new_due_date
            if new_priority:
                task.priority = new_priority
            if new_assigned_to:
                task.assigned_to = new_assigned_to

    def get_task(self, task_id: int) -> Optional[Task]:
        return self.tasks.get(task_id)

    def get_all_tasks(self) -> List[Task]:
        return list(self.tasks.values())


class TaskScheduler:
    """Handles task scheduling based on dependencies and priorities"""
    def __init__(self, task_manager: TaskManager):
        self.task_manager = task_manager
        self.task_dependencies: Dict[int, List[int]] = {}

    def set_dependency(self, task_id: int, depends_on: List[int]):
        self.task_dependencies[task_id] = depends_on

    def schedule_tasks(self):
        tasks = self.task_manager.get_all_tasks()
        # Sort tasks by priority and due date for scheduling
        sorted_tasks = sorted(tasks, key=lambda t: (t.priority.value, t.due_date))
        for task in sorted_tasks:
            if self._can_start_task(task):
                print(f"Scheduling task {task.task_id}: {task.description}")

    def _can_start_task(self, task: Task) -> bool:
        if task.task_id in self.task_dependencies:
            for dep in self.task_dependencies[task.task_id]:
                dep_task = self.task_manager.get_task(dep)
                if dep_task.status != 'Completed':
                    return False
        return True


