# solution.py
import json
from dataclasses import dataclass
from enum import Enum
from typing import List, Dict, Optional, Set
import time
import uuid
import datetime

# Module 1: Task Creation and Management
class Priority(Enum):
    LOW = 1
    MEDIUM = 2
    HIGH = 3

@dataclass
class Task:
    task_id: str
    description: str
    due_date: datetime.date
    priority: Priority
    assigned_team_members: List[str]
    status: str = "Pending"
    dependencies: List[str] = None

    def __post_init__(self):
        if self.dependencies is None:
            self.dependencies = []

class TaskManager:
    def __init__(self):
        self.tasks: Dict[str, Task] = {}

    def create_task(self, description: str, due_date: datetime.date, priority: Priority, assigned_team_members: List[str], dependencies: Optional[List[str]] = None) -> str:
        task_id = str(uuid.uuid4())
        task = Task(
            task_id=task_id,
            description=description,
            due_date=due_date,
            priority=priority,
            assigned_team_members=assigned_team_members,
            dependencies=dependencies or []
        )
        self.tasks[task_id] = task
        return task_id

    def edit_task(self, task_id: str, **kwargs):
        if task_id not in self.tasks:
            raise ValueError(f"Task {task_id} does not exist.")
        task = self.tasks[task_id]
        for key, value in kwargs.items():
            if hasattr(task, key):
                setattr(task, key, value)
        self.tasks[task_id] = task

    def delete_task(self, task_id: str):
        if task_id in self.tasks:
            del self.tasks[task_id]

    def get_task(self, task_id: str) -> Optional[Task]:
        return self.tasks.get(task_id)

    def list_all_tasks(self) -> List[Task]:
        return list(self.tasks.values())

# Module 2: Task Scheduling
class TaskScheduler:
    def __init__(self, task_manager: TaskManager):
        self.task_manager = task_manager

    def schedule_tasks(self):
        tasks = self.task_manager.list_all_tasks()
        # Sort by priority and due date
        tasks.sort(key=lambda t: (t.priority.value, t.due_date))
        for task in tasks:
            print(f"Scheduled Task: {task.task_id} - {task.description}")

    def update_schedule_on_completion(self, task_id: str):
        task = self.task_manager.get_task(task_id)
        if task.status == "Completed":
            print(f"Updating schedule due to completion of task {task_id}")
            self.schedule_tasks()

# Module 3: Resource Allocation
class Resource:
    def __init__(self, resource_id: str, name: str, capacity: int):
        self.resource_id = resource_id
        self.name = name
        self.capacity = capacity
        self.allocated = 0

class ResourceAllocator:
    def __init__(self):
        self.resources: Dict[str, Resource] = {}

    def add_resource(self, resource_id: str, name: str, capacity: int):
        self.resources[resource_id] = Resource(resource_id, name, capacity)

    def allocate_resource(self, task: Task, resource_id: str, amount: int):
        resource = self.resources.get(resource_id)
        if not resource:
            raise ValueError(f"Resource {resource_id} does not exist.")
        if resource.allocated + amount > resource.capacity:
            raise ValueError(f"Resource {resource_id} is over-allocated.")
        resource.allocated += amount
        task.assigned_resources = {resource_id: amount}

    def check_overallocation(self) -> List[str]:
        overallocated = []
        for resource in self.resources.values():
            if resource.allocated > resource.capacity * 0.8:  # Threshold for warning
                overallocated.append(resource.resource_id)
        return overallocated

# Module 4: Real-Time Updates and Notifications
class NotificationSystem:
    def __init__(self, task_manager: TaskManager, resource_allocator: ResourceAllocator):
        self.task_manager = task_manager
        self.resource_allocator = resource_allocator
        self.subscribers = []

    def subscribe(self, subscriber):
        self.subscribers.append(subscriber)

    def notify(self, message: str):
        for subscriber in self.subscribers:
            subscriber.receive_notification(message)

    def check_and_notify(self):
        # Check for task completions
        for task in self.task_manager.list_all_tasks():
            if task.status == "Completed":
                self.notify(f"Task {task.task_id} has been completed.")
        # Check for over-allocated resources
        overallocated = self.resource_allocator.check_overallocation()
        for resource_id in overallocated:
            self.notify(f"Resource {resource_id} is over-allocated.")
        # Check for tasks approaching due date
        today = datetime.date.today()
        for task in self.task_manager.list_all_tasks():
            if task.status == "Pending" and (task.due_date - today).days <= 3:
                self.notify(f"Task {task.task_id} is approaching its due date.")

# Module 5: User Interface (Text-based for simplicity)
class TextUI:
    def __init__(self, task_manager: TaskManager, scheduler: TaskScheduler, resource_allocator: ResourceAllocator, notification_system: NotificationSystem):
        self.task_manager = task_manager
