    def run(self):
        while True:
            choice = self.display_menu()
            if choice == "1":
                description = input("Enter task description: ")
                due_date = datetime.datetime.strptime(input("Enter due date (YYYY-MM-DD): "), "%Y-%m-%d").date()
                priority = Priority[input("Enter priority (LOW, MEDIUM, HIGH): ")]
                members = input("Enter assigned team members (comma-separated): ").split(",")
                task_id = self.task_manager.create_task(description, due_date, priority, [m.strip() for m in members])
                print(f"Task created with ID: {task_id}")
            elif choice == "2":
                for task in self.task_manager.list_all_tasks():
                    print(f"\nTask ID: {task.task_id}")
                    print(f"Description: {task.description}")
                    print(f"Due Date: {task.due_date}")
                    print(f"Priority: {task.priority}")
                    print(f"Assigned Members: {task.assigned_team_members}")
                    print(f"Status: {task.status}")
            elif choice == "3":
                task_id = input("Enter task ID to edit: ")
                field = input("Enter field to edit (description, due_date, priority, assigned_team_members): ")
                value = input("Enter new value: ")
                self.task_manager.edit_task(task_id, **{field: value})
