            "deaths": self.combat_stats.deaths,
            "objectives_completed": self.team.get_objectives_completed(),
            "time_alive": time.time() - self.combat_stats.time_start
        })

        # Simple learning - adjust role based on performance
        if self.combat_stats.total_damage > self.combat_stats.total_received * 2:
            self.role = Role.FRONTLINE
