class CyberArena:
    def __init__(self):
        self.teams = []
        self.robots = []
        self.power_ups = []
        self.hazards = []
        self.current_battle = None
        self.difficulty_level = 1  # 1=Easy, 2=Medium, 3=Hard
        self.combat_log = []
        self.game_over = False

    def add_team(self, team):
        self.teams.append(team)
        for robot in team.robots:
            self.robots.append(robot)

    def add_power_up(self, power_up):
        self.power_ups.append(power_up)

    def add_hazard(self, hazard):
        self.hazards.append(hazard)

    def start_battle(self, rounds=3):
        self.current_battle = Battle(self, rounds)
        self.current_battle.start()
        self.run_game_loop()

    def run_game_loop(self):
        # Main game loop - runs in a thread to allow for real-time action
        game_thread = threading.Thread(target=self.update_game_state)
        game_thread.start()

    def update_game_state(self):
        while not self.game_over:
            self.handle_combat()
            self.handle_power_ups()
            self.handle_hazards()
            self.update_objectives()
            self.update_difficulty()
            time.sleep(0.1)  # 10 FPS

    def handle_combat(self):
        for robot in self.robots:
            if robot.health <= 0:
                continue

            # AI decision making
            target = self.find_enemy(robot)
            if target:
                damage = robot.use_weapon(target)
                if damage > 0:
                    self.combat_log.append(f"{robot.name} attacked {target.name} for {damage} damage")
                    target.take_damage(damage)
            else:
                # No enemy in sight, move randomly
                direction = random.choice(list(Direction))
                robot.move(direction, 1)

            # Learning after each action
            robot.learn_from_combat()

    def find_enemy(self, robot):
        enemies = [r for r in self.robots if r.team != robot.team and r.health > 0]
        if not enemies:
            return None

        # Find closest enemy
        enemies.sort(key=lambda r: robot.position.distance_to(r.position))
        return enemies[0]

    def handle_power_ups(self):
        for power_up in self.power_ups:
            if power_up.active:
                for robot in self.robots:
                    if robot.position.distance_to(power_up.position) <= 0.5:
                        power_up.use(robot)
                        break

    def handle_hazards(self):
        for hazard in self.hazards:
            if hazard.active:
                for robot in self.robots:
                    hazard.check_collision(robot)

    def update_objectives(self):
        for team in self.teams:
            for objective in team.objectives:
                objective.check_completion(team.robots)

    def update_difficulty(self):
        # Simple adaptive difficulty based on team performance
        if self.difficulty_level < 3:
            avg_damage = sum(r.combat_stats.total_damage for r in self.robots) / len(self.robots)
            avg_damage_received = sum(r.combat_stats.total_received for r in self.robots) / len(self.robots)

            if avg_damage > avg_damage_received * 2:
                # Robots are too strong, increase difficulty
                self.difficulty_level += 1
                self.increase_difficulty()
            elif avg_damage_received > avg_damage * 2:
                # Robots are struggling, decrease difficulty
                self.difficulty_level = max(1, self.difficulty_level - 1)
                self.decrease_difficulty()

    def increase_difficulty(self):
        print(f"Difficulty increased to level {self.difficulty_level}")
        # Add more hazards
        for _ in range(2):
            self.add_hazard(Hazard(
                Position(random.randint(0, 100), random.randint(0, 100)),
                damage=10 + self.difficulty_level * 5,
                radius=1 + self.difficulty_level
            ))

