class Robot:
    def __init__(self, name, team, position, weapon):
        self.name = name
        self.team = team
        self.position = position
        self.health = 100
        self.speed = 2
        self.weapon = weapon
        self.power_ups = []
        self.role = Role.SOLDIER  # Default role
        self.combat_stats = CombatStats()
        self.learning_data = []

    def take_damage(self, damage):
        shield_effect = sum(pu.value for pu in self.power_ups if pu.type == PowerUpType.SHIELD)
        actual_damage = max(0, damage - shield_effect)
        self.health -= actual_damage

        if self.health <= 0:
            self.on_death()

        return actual_damage

    def on_death(self):
        self.health = 0
        print(f"{self.name} has been destroyed!")
        self.team.robots.remove(self)
        self.combat_stats.add_death()

    def move(self, direction, distance):
        self.position.move(direction, distance * self.speed)

    def use_weapon(self, target):
        if self.weapon.is_ready():
            damage = self.weapon.fire(self, target)
            self.combat_stats.add_damage(damage)
            return damage
        return 0

    def pick_up_power_up(self, power_up):
        self.power_ups.append(power_up)
        if power_up.type == PowerUpType.SHIELD:
            self.combat_stats.add_shield(power_up.value)
        elif power_up.type == PowerUpType.SPEED_BOOST:
            self.speed += power_up.value
        elif power_up.type == PowerUpType.DAMAGE_BOOST:
            self.weapon.damage += power_up.value
        elif power_up.type == PowerUpType.REPAIR_KIT:
            self.health = min(100, self.health + power_up.value)
        elif power_up.type == PowerUpType.TEAM_BUFF:
            for robot in self.team.robots:
                robot.speed += power_up.value
                robot.weapon.damage += power_up.value

    def learn_from_combat(self):
        # Store combat data for learning
        self.learning_data.append({
            "position": self.position,
            "weapon": self.weapon.type,
            "power_ups": [pu.type for pu in self.power_ups],
            "damage_dealt": self.combat_stats.total_damage,
            "damage_received": self.combat_stats.total_received,
            "deaths": self.combat_stats.deaths,
            "objectives_completed": self.team.get_objectives_completed(),
            "time_alive": time.time() - self.combat_stats.time_start
        })

        # Simple learning - adjust role based on performance
        if self.combat_stats.total_damage > self.combat_stats.total_received * 2:
            self.role = Role.FRONTLINE
        elif self.combat_stats.total_received > self.combat_stats.total_damage * 2:
            self.role = Role.SUPPORT

    def __str__(self):
