class Weapon:
    def __init__(self, name, weapon_type, damage, range_distance, cooldown):
        self.name = name
        self.type = weapon_type
        self.damage = damage
        self.range = range_distance
        self.cooldown = cooldown
        self.last_shot_time = 0

    def is_ready(self):
        return time.time() - self.last_shot_time >= self.cooldown

    def fire(self, robot, target):
        if self.is_ready():
            self.last_shot_time = time.time()

            if self.type == WeaponType.RANGED:
                if robot.position.distance_to(target.position) <= self.range:
                    return self.damage
                else:
                    return 0  # Out of range
            elif self.type == WeaponType.MELEE:
                if robot.position.distance_to(target.position) <= 1:
                    return self.damage
                else:
                    return 0  # Out of melee range
            elif self.type == WeaponType.SUPPORT:
                # Support weapons have special effects, not direct damage
                return 0
        return 0

    def __str__(self):
        return f"Weapon(name={self.name}, type={self.type}, damage={self.damage}, range={self.range}, cooldown={self.cooldown})"


