class Position:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def move(self, direction, distance):
        dx, dy = direction.value
        self.x += dx * distance
        self.y += dy * distance

    def distance_to(self, other):
        return math.hypot(self.x - other.x, self.y - other.y)

    def __str__(self):
