    def add_death(self):
        self.deaths += 1

    def get_kd_ratio(self):
        if self.deaths == 0:
            return float('inf')
        return self.total_damage / self.deaths

    def __str__(self):
        return f"CombatStats(damage={self.total_damage}, received={self.total_received}, deaths={self.deaths}, kd={self.get_kd_ratio():.2f})"


