        for i, robot in enumerate(self.robots):
            if robot.health <= 0:
                continue
            for j, other in enumerate(self.robots):
                if i == j or other.health <= 0:
                    continue
                if robot.position.distance_to(other.position) <= 1.5:
                    # Handle collision logic here
                    # For example, robots push each other back
                    dx = robot.position.x - other.position.x
                    dy = robot.position.y - other.position.y
                    distance = math.hypot(dx, dy)
                    if distance > 0:
                        robot.move(Direction.LEFT if dx < 0 else Direction.RIGHT, 0.5)
                        other.move(Direction.LEFT if dx > 0 else Direction.RIGHT, 0.5)

            # AI decision making
            target = self.find_enemy(robot)
            if target:
                damage = robot.use_weapon(target)
                if damage > 0:
                    self.combat_log.append(f"{robot.name} attacked {target.name} for {damage} damage")
                    target.take_damage(damage)
            else:
                # No enemy in sight, move randomly
                direction = random.choice(list(Direction))
                robot.move(direction, 1)

            # Learning after each action
            robot.learn_from_combat()

    def find_enemy(self, robot):
        enemies = [r for r in self.robots if r.team != robot.team and r.health > 0]
        if not enemies:
            return None

        # Find closest enemy
        enemies.sort(key=lambda r: robot.position.distance_to(r.position))
        return enemies[0]

