class Battle:
    def __init__(self, arena, rounds):
        self.arena = arena
        self.rounds = rounds
        self.current_round = 0

    def start(self):
        print("Starting CyberArena battle!")
        print(f"Difficulty level: {self.arena.difficulty_level}")

        for team in self.arena.teams:
            print(f"{team.name} Team: {len(team.robots)} robots")
            for robot in team.robots:
                print(f"  {robot.name} - {robot.weapon}")

        for power_up in self.arena.power_ups:
            print(f"Available power-up: {power_up.type} at {power_up.position}")

        for hazard in self.arena.hazards:
            print(f"Hazard: {hazard.damage} damage in {hazard.radius} radius at {hazard.position}")

    def run_round(self):
        print(f"\n--- Round {self.current_round + 1} Start ---")
        self.current_round += 1

        # Reset combat stats for this round
        for robot in self.arena.robots:
            robot.combat_stats = CombatStats()

        # Wait for the round to complete
        time.sleep(2)

        # Check if any team has won
        if self.check_victory():
            return True  # Battle ends

        return False  # Continue to next round

    def check_victory(self):
        # Check if any team has won
        for team in self.arena.teams:
            if hasattr(team, "base_health") and team.base_health <= 0:
                print(f"{team.name} team has lost because their base was destroyed!")
                self.arena.end_game()
                return True
            if len(team.robots) == 0:
                print(f"{team.name} team has lost because all their robots are destroyed!")
                self.arena.end_game()
                return True

        # Check if any team has completed all objectives
        for team in self.arena.teams:
            if len(team.objectives) > 0 and team.get_objectives_completed() == len(team.objectives):
                print(f"{team.name} team has won by completing all objectives!")
                self.arena.end_game()
                return True

        return False

    def run(self):
        for _ in range(self.rounds):
            if self.run_round():
                break  # Battle ended early
            time.sleep(2)  # Pause between rounds

        self.arena.end_game()


