        shield_effect = sum(pu.value for pu in self.power_ups if pu.type == PowerUpType.SHIELD)
        actual_damage = max(0, damage - shield_effect)
        self.health -= actual_damage

        if self.health <= 0:
            self.on_death()

        return actual_damage

    def on_death(self):
        self.health = 0
        print(f"{self.name} has been destroyed!")
