class Robot:
    """Base class for all AI-controlled robots in CyberArena"""
    def __init__(self, name, team, position):
        self.name = name
        self.team = team
        self.position = position
        self.health = 100
        self.speed = random.uniform(2.0, 4.0)
        self.weapon = self._choose_weapon()
        self.state = RobotState.IDLE
        self.experience = 0
        self.skills = {"attack": 0.5, "defense": 0.5, "speed": 0.5}

    def _choose_weapon(self):
        """Randomly select a weapon for the robot"""
        weapons = [LaserCannon(), PlasmaCannon(), EnergySword(), FragGrenade()]
        return random.choice(weapons)

    def move(self, destination):
        """Move the robot towards a destination"""
        self.state = RobotState.MOVING
        distance = ((self.position[0] - destination[0])**2 + (self.position[1] - destination[1])**2)**0.5
        if distance < 10:
            return True
        self.position = ((self.position[0] + (destination[0] - self.position[0]) * 0.1),
                         (self.position[1] + (destination[1] - self.position[1]) * 0.1))
        return False

    def attack(self, target):
        """Attack a target with current weapon if possible"""
        if self.weapon.can_fire(time.time()):
            distance = ((self.position[0] - target.position[0])**2 + (self.position[1] - target.position[1])**2)**0.5
            if distance <= self.weapon.range:
                self.state = RobotState.ATTACKING
                damage = self.weapon.fire()
                target.health -= self.weapon.damage
                return True, damage
        return False, "Weapon on cooldown"

    def defend(self):
        """Enter defensive stance"""
        self.state = RobotState.DEFENDING
        self.skills["defense"] += 0.05
        return f"{self.name} is now in defensive stance"

    def retreat(self):
        """Retreat to safe position"""
        self.state = RobotState.RETREATING
        self.health -= 5  # Take damage while retreating
        return f"{self.name} is retreating"

    def learn(self, battle_results):
        """Learn from battle outcomes to improve performance"""
        if battle_results["success"]:
            self.experience += 10
            self._improve_skills(battle_results["stats"])
        else:
            self.experience += 5
            self._adapt_strategy(battle_results["stats"])

    def _improve_skills(self, stats):
        """Improve specific skills based on battle statistics"""
        if stats["damage_dealt"] > stats["damage_received"]:
            self.skills["attack"] += 0.05
        if stats["survival_time"] > 10:
            self.skills["defense"] += 0.03
        if stats["distance_covered"] > 50:
            self.skills["speed"] += 0.02

    def _adapt_strategy(self, stats):
        """Adapt strategy based on battle performance"""
        if stats["damage_received"] > stats["damage_dealt"]:
            self._switch_weapon()
        if stats["survival_time"] < 5:
            self.skills["defense"] += 0.07
            self.skills["speed"] += 0.03

    def _switch_weapon(self):
        """Switch to a different weapon based on battle needs"""
        available_weapons = [LaserCannon(), PlasmaCannon(), EnergySword(), FragGrenade()]
        current_weapon_type = self.weapon.type
        new_weapons = [w for w in available_weapons if w.type != current_weapon_type]
        if new_weapons:
