        objective_positions = [self.arena.size // 3, 2 * self.arena.size // 3]
        for i, team in enumerate(self.teams):
            if team == Team.RED:
                # Red team objective is to capture the blue flag
                self.arena.add_objective(TeamObjective(Objective.CAPTURE_FLAG, team, objective_positions[1]))
                # Blue team objective is to defend their base
                self.arena.add_objective(TeamObjective(Objective.DEFEND_BASE, self.teams[1], objective_positions[1]))
            elif team == Team.BLUE:
                # Blue team objective is to capture the red flag
                self.arena.add_objective(TeamObjective(Objective.CAPTURE_FLAG, team, objective_positions[0]))
                # Red team objective is to defend their base
                self.arena.add_objective(TeamObjective(Objective.DEFEND_BASE, self.teams[0], objective_positions[0]))

        # Add some power-ups
        power_ups = [
            PowerUp("Shield Generator", "Increases armor", 10),
            PowerUp("Speed Boost", "Increases movement speed", 15),
            PowerUp("Damage Amplifier", "Increases weapon damage", 20)
        ]
        for power_up in power_ups:
            self.arena.add_power_up(power_up)

        # Add some hazards
        hazards = [
            Hazard("Lava Trap", 15, 30),
            Hazard("Electric Storm", 10, 60),
            Hazard("Toxic Gas", 8, 80)
        ]
        for hazard in hazards:
            self.arena.add_hazard(hazard)

    def run_round(self):
        print(f"\nStarting Round {self.arena.round_number}...")
        # Simulate the round
        for i in range(10):  # 10 time steps per round
            print(f"\nTime Step {i+1}:")
            for robot in self.arena.robots:
                # Simple AI - move towards objective
                robot.move(random.choice([-1, 1]))
                # Randomly use weapon
                if random.random() < 0.2:
                    if self.arena.robots:
                        robot.use_weapon(random.choice(self.arena.robots))
            self.arena.update()
