            time.sleep(0.5)  # Small delay for visualization

        # Check if we have a winner
        winner = self.arena.determine_winner()
        if winner:
            self.score[winner] += 1
            print(f"Score: {self.score}")
            print("Teams have a chance to learn from this round...")
            for robot in self.arena.robots:
                if robot.team == winner:
                    robot.strategy.analyze_battle_stats()
            # Reset for next round
            self.arena.reset()
        else:
            print("No winner in this round. Resetting...")
            self.arena.reset()

    def print_arena_status(self):
        # Print current status of robots
        for robot in self.arena.robots:
            print(f"{robot.robot_id} - Position: {robot.position}, Health: {robot.health}, Invisible: {robot.invisible}")

    def run(self):
        print("Welcome to CyberArena!")
        print("Robot teams will battle to complete objectives and win!")
        self.setup_arena()
        for _ in range(self.rounds):
            self.run_round()
            if self.arena.round_number > self.rounds:
                break
        print("\nGame Over!")
        print(f"Final Score: {self.score}")
        winning_team = max(self.score, key=self.score.get)
        print(f"Winning Team: {winning_team.value} with {self.score[winning_team]} wins!")

