# Define User Roles
class UserRole(Enum):
    OWNER = "Owner"
    EDITOR = "Editor"
    REVIEWER = "Reviewer"


# User Class to Represent Users
class User:
    def __init__(self, user_id: str, name: str, role: UserRole):
