        self.name = name
        self.role = role

    def can_edit(self) -> bool:
        return self.role in [UserRole.OWNER, UserRole.EDITOR]

    def can_review(self) -> bool:
        return self.role in [UserRole.OWNER, UserRole.REVIEWER]

    def __str__(self):
        return f"{self.name} ({self.role.value})"


# Base Class for Video Editing Actions
class VideoAction(ABC):
    @abstractmethod
    def apply(self, video: "VideoProject") -> None:
        pass

    @abstractmethod
    def undo(self, video: "VideoProject") -> None:
        pass

    @abstractmethod
    def to_dict(self) -> Dict:
        pass

    @staticmethod
    def from_dict(data: Dict) -> "VideoAction":
        if data["action_type"] == "cut":
            return CutAction.from_dict(data)
        elif data["action_type"] == "crop":
            return CropAction.from_dict(data)
        elif data["action_type"] == "apply_filter":
            return ApplyFilterAction.from_dict(data)
        elif data["action_type"] == "add_comment":
            return AddCommentAction.from_dict(data)
        raise ValueError("Unknown action type")


# Cut Action Implementation
class CutAction(VideoAction):
    def __init__(self, start: float, end: float):
        self.start = start
        self.end = end

    def apply(self, video: "VideoProject") -> None:
        video.content = video.content[self.start:self.end]

    def undo(self, video: "VideoProject") -> None:
        # In a real implementation, we would store the original content
        pass

    def to_dict(self) -> Dict:
        return {
            "action_type": "cut",
            "start": self.start,
            "end": self.end
        }

    @staticmethod
    def from_dict(data: Dict) -> "CutAction":
        return CutAction(data["start"], data["end"])


# Crop Action Implementation
class CropAction(VideoAction):
    def __init__(self, x1: float, y1: float, x2: float, y2: float):
        self.x1 = x1
        self.y1 = y1
