            "action_type": "add_comment",
            "timestamp": self.timestamp,
            "comment": self.comment,
            "user": self.user.name
        }

    @staticmethod
    def from_dict(data: Dict) -> "AddCommentAction":
        user = User(data["user"], data["user"], UserRole.REVIEWER)
        return AddCommentAction(data["timestamp"], data["comment"], user)


# Video Project Class to Represent a Video Being Edited
class VideoProject:
    def __init__(self, video_id: str, content: str, users: List[User]):
        self.video_id = video_id
        self.content = content
        self.comments: List[Dict] = []
        self.actions: List[VideoAction] = []
        self.undos: List[VideoAction] = []
        self.users = users
        self.history = []

    def add_action(self, action: VideoAction) -> None:
        action.apply(self)
        self.actions.append(action)
        self.history.append(self.content)  # Store a copy of the content as state

    def undo(self) -> None:
        if self.actions:
            action = self.actions.pop()
            action.undo(self)
            self.undos.append(action)

    def redo(self) -> None:
        if self.undos:
            action = self.undos.pop()
            action.apply(self)
            self.actions.append(action)

    def export(self, format: str) -> str:
        # Simulate exporting the video in the specified format
        return f"Exported video in format: {format}"

    def get_history(self) -> List[str]:
        return self.history

    def apply_changes_from_other_client(self, action: VideoAction) -> None:
        # Apply changes from another client
        self.add_action(action)

    def __str__(self):
        return f"Video ID: {self.video_id}, Current Content Size: {len(self.content)}"


# Collaboration Manager Class to Handle Real-Time Synchronization
class CollaborativeManager:
    def __init__(self):
        self.projects: Dict[str, VideoProject] = {}
        self.user_sessions: Dict[str, User] = {}
        self.lock = threading.Lock()

    def create_project(self, video_id: str, content: str, users: List[User]) -> VideoProject:
        with self.lock:
            project = VideoProject(video_id, content, users)
            self.projects[video_id] = project
            return project

    def add_user_to_project(self, video_id: str, user: User) -> bool:
        with self.lock:
            if video_id in self.projects:
                self.projects[video_id].users.append(user)
                self.user_sessions[user.user_id] = user
                return True
            return False

    def apply_user_action(self, video_id: str, action: VideoAction, user_id: str) -> bool:
        with self.lock:
            if video_id in self.projects and self.user_sessions.get(user_id):
                user = self.user_sessions[user_id]
                if user.can_edit():
                    self.projects[video_id].apply_changes_from_other_client(action)
                    return True
        return False

    def get_project(self, video_id: str) -> Optional[VideoProject]:
        with self.lock:
            return self.projects.get(video_id)


# JSON Serialization/Deserialization
def serialize_project(project: VideoProject) -> str:
    return json.dumps({
        "video_id": project.video_id,
        "content": project.content,
        "comments": project.comments,
        "actions": [action.to_dict() for action in project.actions],
        "undos": [action.to_dict() for action in project.undos],
        "users": [f"{user.name} ({user.role.value})" for user in project.users]
    })


def deserialize_project(data: str) -> VideoProject:
    data_dict = json.loads(data)
    users = [User(uuid.uuid4().hex[:8], name.split(" (")[0], UserRole(name.split(" (")[1][:-1])) for name in data_dict["users"]]
    project = VideoProject(data_dict["video_id"], data_dict["content"], users)
    for action_data in data_dict["actions"]:
        action = VideoAction.from_dict(action_data)
        project.add_action(action)
    for action_data in data_dict["undos"]:
        action = VideoAction.from_dict(action_data)
        project.undos.append(action)
    project.comments = data_dict["comments"]
    return project


