# User class to represent system users
class User:
    def __init__(self, user_id, username, role):
        self.user_id = user_id
        self.username = username
        self.role = role

# Video class to represent a video being edited
class Video:
    def __init__(self, video_id, file_path):
        self.video_id = video_id
        self.file_path = file_path
        self.changes_history = []
        self.comments = []
        self.current_version = 1

    def apply_change(self, change, user):
        # Apply a video editing change to the video
        self.changes_history.append({
            'change': change,
            'user': user.username,
            'version': self.current_version
        })
        self.current_version += 1

    def add_comment(self, comment):
        # Add a comment on a specific segment of the video
        self.comments.append(comment)

# Change class to represent an editing action
class Change:
    def __init__(self, action, start_time, end_time, parameters=None):
        self.action = action  # e.g., 'cut', 'crop', 'add_filter'
        self.start_time = start_time
        self.end_time = end_time
        self.parameters = parameters or {}

# Comment class to represent user feedback
class Comment:
    def __init__(self, user, timestamp, message):
        self.user = user
        self.timestamp = timestamp
        self.message = message

# Collaborative Editor System
class VideoCollabEditor:
    def __init__(self):
        self.users = {}
        self.videos = {}

    def add_user(self, user_id, username, role):
        self.users[user_id] = User(user_id, username, role)

    def add_video(self, video_id, file_path):
        self.videos[video_id] = Video(video_id, file_path)

    def get_user(self, user_id):
        return self.users.get(user_id)

    def get_video(self, video_id):
        return self.videos.get(video_id)

    def apply_edit(self, user_id, video_id, change):
        user = self.get_user(user_id)
        video = self.get_video(video_id)
        if video and user:
            video.apply_change(change, user)

    def add_feedback(self, user_id, video_id, timestamp, message):
        user = self.get_user(user_id)
        video = self.get_video(video_id)
        if video and user:
