class Subtitle:
    def __init__(self, text: str, start_time: Timestamp, end_time: Timestamp):
        self.text = text
        self.start_time = start_time
        self.end_time = end_time

    def adjust_synchronization(self, delta: float):
        self.start_time.seconds += delta
        self.end_time.seconds += delta

    def to_dict(self):
        return {
            'text': self.text,
            'start_time': self.start_time.seconds,
            'end_time': self.end_time.seconds
        }

class VideoEditor:
    def __init__(self, user_id: str, role: UserRole):
        self.user_id = user_id
