        print(f'User {self.user_id} is trimming video from {start.seconds} to {end.seconds}')

    def adjust_playback_speed(self, speed: float):
        if not (MIN_PLAYBACK_SPEED <= speed <= MAX_PLAYBACK_SPEED):
            raise ValueError(f'Speed must be between {MIN_PLAYBACK_SPEED} and {MAX_PLAYBACK_SPEED}')
        print(f'Playback speed adjusted to {speed}x')

    def add_subtitle(self, subtitle: Subtitle):
