class RealTimeSynchronizationService:
    def __init__(self):
        self.subscribers = []
        self.lock = threading.Lock()

    def subscribe(self, user: VideoEditor):
        with self.lock:
            self.subscribers.append(user)

    def notify_all(self, message: str):
        for user in self.subscribers:
